INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m1', 'ai101', 1, 'What is AI?', 'A working mental model: what an LLM actually does, the vocabulary, why data decides everything, and a delegation heuristic you can carry under pressure.', 'open', 30, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m2', 'ai101', 2, 'Choosing the tool for the task', 'Chat assistants, copilots, and the AI already embedded in your HR stack — what each is actually for, and how to tell a language model from a scoring engine before you rely on either.', 'open', 25, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m3', 'ai101', 3, 'What it costs and how it scales', 'Tokens, context windows, and pricing — enough of the economics to size a use case, read a vendor quote, and know when a bigger model is worth it.', 'open', 25, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m4', 'ai101', 4, 'Working with your documents and data', 'Attachments, long documents, and sensitive material: getting your world into the model''s view without crowding out the question — or crossing a line your legal team hasn''t cleared.', 'open', 30, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m5', 'ai101', 5, 'Prompting as briefing', 'Role, task, context, format. Prompting as briefing a capable stranger — and iteration as the keystone behavior that separates fluent users from frustrated ones.', 'open', 35, '["ai101-m1"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m6', 'ai101', 6, 'When it''s confidently wrong', 'Hallucination in depth: why fluent output deserves more scrutiny, not less, and the verification habits that keep a fabricated citation out of a document with someone''s name on it.', 'open', 30, '["ai101-m1"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m7', 'ai101', 7, 'The lines that don''t move', 'Bias, adverse impact, and decisions about people. Where AI assists, where it must stop, and how to say so in a way your organization will actually follow.', 'open', 30, '["ai101-m6"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai101-m8', 'ai101', 8, 'What you own', 'Data agreements, disclosure, and accountability. What you''re responsible for when AI touched the work — and the policy questions to settle before someone asks.', 'open', 25, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m1', 'ai201', 1, 'From one-offs to workflows', 'The workflow lens: five parts every repeatable workflow has, the audit that finds your candidates, the selection rules — and the capstone''s first stage: pick your build and spec it.', 'open', 30, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m2', 'ai201', 2, 'Context that keeps', 'The artisan tax and its refund: context packs — what''s durable, what arrives fresh, what never becomes infrastructure — built hands-on in your organization''s tools.', 'open', 30, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m3', 'ai201', 3, 'Document pipelines', 'Chains with checkpoints: structure forward, prose last, and the lossy middle where detail dies. Your workflow becomes a pipeline and runs on real material.', 'open', 35, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m4', 'ai201', 4, 'Verification by design', 'The verification budget: sized to stakes, matched to failure mode, cheap enough to survive week six — plus the sign-off that means something and the path for when something ships wrong anyway.', 'open', 30, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m5', 'ai201', 5, 'Handing it to an agent', 'The autonomy ladder, priced in evidence: draft-only, propose-then-approve, act-with-audit-trail. Guardrails as permissions, the decision-laundering test, and the refusal as a senior artifact.', 'open', 35, '["ai201-m4"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m6', 'ai201', 6, 'People data in production', 'Four tiers, the person-test, redaction as a pipeline step, the agreement layer, and a blame-safe escalation path. The boundary sheet that makes your workflow deployable.', 'open', 30, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m7', 'ai201', 7, 'The operating rhythm', 'Seconds per run, ten a week, twenty a month. Four honest numbers with a baseline, retirement criteria written in advance — and the reckoning against your Module 1 prediction.', 'open', 25, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai201-m8', 'ai201', 8, 'Ship it and prove it', 'The capstone lands: the consistency pass, the handoff test with a cold reader, and the executive sentence with receipts. Completes the jump to Practitioner.', 'open', 40, '["ai201-m4","ai201-m6"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai301-hrbp-m1', 'ai301-hrbp', 1, 'Where you actually are', 'Most of the urgency was manufactured: what the adoption data actually says, and the difference between a peer gap and an expectations gap.', 'open', 20, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai301-hrbp-m2', 'ai301-hrbp', 2, 'Sort your own job', 'Two questions — presence, contested judgment — and the four quadrants they produce. Least penetrated is not protected.', 'open', 40, '["ai301-hrbp-m1"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai301-hrbp-m3', 'ai301-hrbp', 3, 'The honest arithmetic', 'Botsitting, the four-question workflow audit, the volume trap, and tearing down a claim on evidence, sample, and falsifier.', 'open', 45, '["ai301-hrbp-m2"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai301-hrbp-m4', 'ai301-hrbp', 4, 'Adversarial rehearsal', 'Five adversaries, five sting moves, and the model''s job is to attack your work rather than make it. The tutor is the surface.', 'open', 45, '["ai301-hrbp-m2"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai301-hrbp-m5', 'ai301-hrbp', 5, 'Arguing with finance', 'A story loses to a model. Three you can build, the ways your HR data lies, and why small numbers demand the n in the sentence.', 'open', 40, '["ai301-hrbp-m3"]');
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai301-hrbp-m6', 'ai301-hrbp', 6, 'The line', 'The law about systems and the law about your documents: the patchwork, the agent theory, and ER documentation that survives discovery.', 'open', 45, NULL);
INSERT INTO fd_module (id, course_id, ordinal, title, blurb, status, est_minutes, prereq_json) VALUES ('ai301-hrbp-m7', 'ai301-hrbp', 7, 'Manager capability as product', 'Catching misuse without driving it underground, what the coaching evidence really says, and why allocating human support is an equity call.', 'open', 40, '["ai301-hrbp-m4"]');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-brief', 'ai101-m1', 10, 'prose', 'stable', '## Why this module exists

You almost certainly already use AI. You''ve probably asked something to tidy up a job description, turn a page of interview scrawl into a debrief a hiring manager can read, soften a rejection email, or explain a benefits provision in language an employee will actually understand. So opening a course with "what is AI?" is a strange move. The answer is on your screen already.

But there is a difference between using this technology and understanding what happens when you use it, and most people skip the second part. That skip is where the Risk-stage problems come from. People without a working mental model tend to land in one of two places. Some treat it as a search engine that returns true facts — it is not, and it does not. Others treat it as a colleague with intentions, judgment, and a stake in the outcome — it has none of those, not in the way you mean. Both framings will get you in trouble, in different ways and on different timelines.

There''s a reason to care about this more in People work than in most functions. In sales, using AI carelessly produces a weak email. In People, it can produce a document that shapes someone''s livelihood — a performance write-up, a policy interpretation, a screening decision, an investigation summary — and it can produce that document fluently, confidently, and wrong. The gap between how good the output *sounds* and how good it *is* is exactly the gap this module exists to close.

This module gives you a third framing: accurate enough to be useful, simple enough to carry around under pressure. No mathematics, no philosophy, no diagrams of neural networks. Just a working account of what these systems do, where they come from, and what that means for how you use them.

**A note on your two roles.** As a People leader you will be asked to do two different things with AI: use it well in your own work, and eventually help other functions adopt it. Those are different jobs and they need different preparation. You cannot credibly lead a change you can''t perform, so this course is about the first one. The second gets its own course, later.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-objectives', 'ai101-m1', 20, 'callout', 'stable', '### Learning objectives

By the end of this module you should be able to:

1. Explain, in plain language, what people mean by "AI" today — and what they don''t.
2. Describe what a large language model actually does when you send it a message.
3. Recognize and use the working vocabulary: model, prompt, context window, token, knowledge cutoff, hallucination, agent.
4. Articulate why data — both what the model was trained on and what you hand it — determines the quality of what you get back.
5. Predict, before you begin a task, whether AI is likely to do it well.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l1-intro', 'ai101-m1', 30, 'prose', 'stable', '## Lesson 1 · What we mean when we say "AI"

The word is doing far too much work. People use it for the résumé screener in the ATS, the sentiment scoring on your engagement survey, ChatGPT, the anomaly flag in payroll, and the menacing robot from a film — often in the same meeting. That''s part of why two reasonable people can have wildly different reactions to "we should use more AI." They''re not discussing the same thing.

Here''s the cut that clears it up. **"AI" is a category, not a technology.** Inside that category sit many different systems built in different ways for different purposes. The kind currently reshaping knowledge work — and the kind this course is mostly about — is a specific type called a **large language model**, or LLM. When a colleague says "I used AI to write this," they almost always mean they used an LLM.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l1-lineup', 'ai101-m1', 40, 'prose', 'volatile', 'The LLMs you''ll encounter most: Claude, from Anthropic. ChatGPT, from OpenAI, built on the GPT family. Gemini, from Google. Those are the consumer-facing names; underneath, they''re the same general kind of system — software trained on an enormous quantity of text that reads and produces human-like language.', '["model-lineup"]', '2026-08-04', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l1-hrstack', 'ai101-m1', 50, 'prose', 'stable', '### The part that matters specifically for People work

Much of the "AI" already sitting in your HR technology stack is **not** an LLM. Résumé matching and ranking, candidate scoring, attrition risk models, engagement sentiment classification, payroll anomaly detection, scheduling optimization — most of these are older machine-learning techniques doing statistical classification or scoring. Some vendors have since layered an LLM on top for the chat interface while the underlying scoring engine remains what it always was.

This distinction is not pedantry, for three reasons:

- **It changes what questions to ask a vendor.** "Is this a language model or a scoring model?" gets you further than "is this AI?", which every vendor now answers yes to.
- **It changes the failure mode.** A scoring model fails by being systematically biased against a group. A language model fails by fabricating. Those need different controls.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l1-regulatory', 'ai101-m1', 60, 'prose', 'volatile', '- **It changes your regulatory exposure.** Regulation in this area tends to attach to *automated decision-making about people* rather than to a technology label. A scoring model that ranks candidates is squarely in scope under rules like NYC''s Local Law 144 and the EU AI Act''s treatment of employment as high-risk. An LLM you use to redraft a job posting generally isn''t. Confusing the two means you either over-comply on harmless uses or under-comply on the ones that count. *Verify current specifics with counsel — this area moves.*', '["employment-regulation","eu-ai-act"]', '2026-08-04', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l1-close', 'ai101-m1', 65, 'prose', 'stable', 'So: when this course says "AI" without qualification, it means a large language model. Software that takes text in and produces text out, using patterns learned from a very large quantity of text it was trained on.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l1-try', 'ai101-m1', 70, 'try_this', 'stable', '### Try this — 2 minutes

1. List every place you used AI at work last week. Be specific: not "ChatGPT," but "I had it rewrite the internal comms note about the benefits change."
2. For each one, ask: was that an LLM, or was it a scoring or matching feature inside a tool I already use?
3. Then look at your ATS or HRIS. Find one feature marketed as AI and decide which kind it is.

You won''t be certain on all of them. That uncertainty is useful information — it tells you where you''d have to ask a vendor a direct question.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l1-sort', 'ai101-m1', 80, 'exercise', 'stable', '{"type":"sorting","title":"Calibration exercise — Where does AI actually help?","intro":"Ten minutes. This is the most important exercise in the module.\n\nBelow are fifteen tasks a People team might plausibly hand to an LLM. Sort each into **does this well**, **does this partly — needs verification**, or **does this badly — don''t**.\n\nNothing reveals until all fifteen are committed — an unscored guess teaches nothing."}', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l2-mechanism', 'ai101-m1', 90, 'prose', 'stable', '## Lesson 2 · What an LLM actually does, in plain English

The mechanism reduces to one sentence:

> **A large language model is software that, given some text, predicts what text should come next — one small piece at a time.**

Everything else is detail. But the detail is where the practical consequences live, so it''s worth two minutes.

### The training step

Before you type anything, the model has been trained. Training means it was shown an enormous quantity of text — books, articles, websites, code, transcripts, forums — and learned the statistical patterns of how language works. Not memorized. Learned. It picked up that "we regret to inform you that your application" is very likely followed by something other than "congratulations." It picked up grammar, register, tone, structure, factual associations, and a few thousand other regularities, all from patterns in text.

That training happened before you arrived. When you open the tool, the model is already finished. You are not teaching it anything during your conversation, and Lesson 4 explains why that matters more than it sounds like it should.

### The prediction step

Now you type. The model takes your message plus everything else in the conversation and asks one narrow question: *given everything I''ve seen so far, what''s the most likely next piece of text?* It picks a piece, appends it, and asks again. And again, until it stops.

It is not drafting a complete answer and then writing it out. It is not retrieving an answer from a database. It is generating text one fragment at a time, where each fragment is the most probable continuation of everything before it.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l2-try', 'ai101-m1', 100, 'try_this', 'stable', '### Try this — 3 minutes

1. Open your AI tool.
2. Send exactly: *"Tell me a short, surprising fact about octopuses, then explain how you know it."*
3. Read the answer.
4. Follow up: *"How did you generate that? Walk me through what actually happened, step by step."*

You''ll get the model''s own account of itself. Notice the vocabulary — probability, training data, patterns. Notice what it never says: *"I looked it up."* *"I checked a source."* Because neither happened.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l2-frustrations', 'ai101-m1', 110, 'prose', 'stable', '### Why this explains almost everything that will frustrate you

**Why it sounds confident about wrong things.** The model isn''t checking facts as it writes; it''s producing statistically likely text. Sometimes statistically likely text is also true. Sometimes it isn''t. In human writing, confidence and correctness are loosely coupled — someone who sounds certain usually has reason to be. That coupling does not exist here. M6 is entirely about this.

**Why the same prompt gives different answers.** There''s a small amount of randomness in how each next piece gets chosen. Without it, every response would be identical and mechanical. With it, asking twice gives you two drafts. That''s not a malfunction — it''s why re-running a prompt is a legitimate technique rather than a sign something broke.

**Why context changes everything.** Because prediction runs on everything the model has been given, more relevant material means better predictions. A vague prompt leaves the model predicting from almost nothing. A prompt carrying role, task, context, and format narrows the prediction toward what you actually wanted. M5 covers this properly.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l2-memory', 'ai101-m1', 120, 'prose', 'volatile', '**Why it doesn''t remember you.** Each conversation typically starts fresh. The model has no memory across sessions unless something was specifically built to give it one. Memory features have become common across the major tools, but they vary in what they retain and for how long, and the default is often off. Never assume; check what your specific tool does.', '["memory-features"]', '2026-08-04', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l2-honest', 'ai101-m1', 130, 'prose', 'stable', '### The honest part: nobody fully understands the inside

Even the people who build these systems don''t fully understand how they work internally. Training produces a model with billions of parameters that encode the learned patterns, and those parameters aren''t human-readable. Anthropic has published interpretability research — techniques for tracing what happens inside a model as it responds — precisely because the internals aren''t otherwise visible, including to them.

What that research has surfaced is genuinely interesting. There''s evidence models do more than blind word-by-word prediction in some cases: planning ahead toward a rhyming word before starting a line, for instance, or representing concepts in a shared space that spans languages. There''s also evidence that when a model explains its reasoning, the explanation doesn''t always match what actually happened internally.

You don''t need to retain any of that. It''s here because it pushes back on both of the confident positions you''ll hear in meetings — *"it''s just autocomplete"* (mechanically defensible, underestimates what falls out of the mechanism) and *"it genuinely thinks"* (wrong in a different direction). The useful stance sits between: a powerful pattern-matcher trained on a vast amount of human text, which often produces startlingly good output and has failure modes worth building habits around.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l3-vocab-a', 'ai101-m1', 140, 'prose', 'stable', '## Lesson 3 · The vocabulary, demystified

You''ll keep hearing these. Don''t memorize them — read through once and notice the shape of each. They recur throughout the course.

**Model.** The trained system itself. When someone says "the model did something strange," they mean the underlying AI, not the website they used to reach it. Models come in different sizes; larger ones are generally more capable, slower, and more expensive to run.

**Prompt.** What you send — your text, plus any instructions, context, or attached material. Your prompt is the single largest lever you have on output quality. M5 is entirely about this.

**Context window.** How much text the model can hold in view at once when responding: your message, the conversation so far, and anything attached. It''s finite. When it fills, earlier material effectively drops out of view — which is why long conversations start to feel like the model forgot something, and why pasting in a 90-page handbook can crowd out your actual question.

**Token.** The unit models process text in — roughly a word or word-fragment. Mostly this matters for two reasons: context windows are measured in tokens, and pricing is usually per token. M3 covers the economics.

**Training data.** The text the model learned from. It shapes everything: what the model handles well, what it fumbles, what registers it can write in, and what biases it carries.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l3-cutoff', 'ai101-m1', 150, 'prose', 'volatile', '**Knowledge cutoff.** The date past which the model wasn''t trained on new information. Most current tools pair the model with web search to compensate, but the underlying model still has a cutoff. It''s why asking about yesterday''s news, without search enabled, produces something fluent and useless.', '["knowledge-cutoff","search-features"]', '2026-08-04', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l3-vocab-b', 'ai101-m1', 160, 'prose', 'stable', '**Hallucination.** When a model produces something confident, plausible, and wrong or invented. The single most important failure mode to understand, and the one with the sharpest consequences in People work. M6 is devoted to it.

**Agent.** A model configured to take actions rather than only respond — browsing, sending, updating a record, running code — within whatever permissions it''s been given. You don''t need to work with agents at this level. Just know the word means *an AI system that does things*, not one that only talks.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l3-multimodal', 'ai101-m1', 170, 'prose', 'volatile', '**Multimodal.** Models that handle more than text — images, audio, documents. Current frontier models are multimodal; you can paste a screenshot of an org chart or attach a PDF policy and ask questions about it. Same mechanics underneath, wider set of inputs.', '["multimodal-capabilities"]', '2026-08-04', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l3-try', 'ai101-m1', 180, 'try_this', 'stable', '### Try this — 3 minutes

Open the product page of one HR tool your team uses that advertises AI features. Read the claims and answer three questions:

1. Is this a language model, a scoring or matching model, or both?
2. What data was it trained on — theirs, yours, or unstated?
3. Does it make or influence a decision about a person?

If you can''t answer all three from the page, you''ve just written your first three vendor questions. That''s the exercise working.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l4-training', 'ai101-m1', 190, 'prose', 'stable', '## Lesson 4 · Why data is the whole game

If one thing survives from this module, make it this: **AI is a data problem before it is anything else.** What you get out is determined, almost entirely, by two things — what the model was trained on, and what you hand it in the moment.

### Training data shapes the model

The model only handles well what it saw patterns for. Well-represented topics get handled well. Sparse ones get hedging, vagueness, or invention.

Practical consequences:

- A model trained mostly on English performs better in English, even when it produces other languages competently.
- A model trained on public text has never seen your handbook, your HRIS, your comp bands, your Slack, your investigation files, or your board deck. It cannot draw on what it never saw.
- **All training data carries bias, and models reproduce it.** In most functions that''s an abstract concern. In People work it is not. A model asked to evaluate, rank, or characterize people can reproduce patterns present in its training text — and in an employment context, that is the mechanism by which adverse impact happens. This is why the delegation heuristic ends with *"it must not make decisions about people."*

The habit to build: before asking, form a rough view of whether this is the kind of thing the model would have seen a great deal of. *"Rewrite this clunky paragraph"* — enormous quantities of training data. *"What''s our policy on carryover PTO"* — none whatsoever. The first is squarely in the model''s competence. The second, asked cold, produces something fluent, confident, and made up.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l4-recency', 'ai101-m1', 200, 'prose', 'volatile', 'One more practical consequence: a model trained through a given date is unreliable about anything after it, unless you supply fresh information or search is enabled.', '["knowledge-cutoff"]', '2026-08-04', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l4-supply', 'ai101-m1', 210, 'prose', 'stable', '### The data you supply

The second kind is what you give it — your prompt, your attachments, the context you establish. Because the model knows only its training plus what''s in the current conversation, the material you supply is your only channel for getting your specific world into the picture.

Ask for a summary of your engagement survey results without pasting the results, and the model will produce a survey summary. A generic, plausible, entirely fictional one. Paste the actual comments and you get real analysis. Same model, same prompt structure, completely different output — because the data changed.

This is why prompting is far more about **information** than about clever phrasing. The wording matters, and M5 will make you better at it, but wording is downstream of whether the model has what it needs.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l4-paste', 'ai101-m1', 220, 'prose', 'stable', '### A note on what you paste

People data is the most sensitive material in most organizations, which makes "what can I put in here" a sharper question for you than for almost any other function. Employee records, health information, investigation notes, compensation data, and anything identifying a named individual sit at the top of that gradient.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l4-agreements', 'ai101-m1', 230, 'prose', 'volatile', 'The answer depends entirely on which tool you''re using and under what agreement — an enterprise deployment with a data processing agreement is a different situation from a personal account on a consumer tier. Find out which one you''re in before you paste, not after. Your security or legal team has this answer. If nobody does, that gap is itself worth raising.', '["data-agreements"]', '2026-08-04', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l4-close', 'ai101-m1', 240, 'prose', 'stable', 'M8 returns to this when we discuss what you own. For now: data is what makes the system work, and the data you supply is the part you control.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-l4-try', 'ai101-m1', 250, 'try_this', 'stable', '### Try this — 3 minutes

1. Pick one thing you did last week that involved AI, or could have.
2. Ask: what did the model need to know that it couldn''t have known on its own?
3. If you didn''t supply that, what did it fill the gap with?

The question *"what does this model not know that I''d have to give it?"* is the single most useful habit in this course. It''s the seed of good prompting and the seed of good judgment about when not to bother.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-takeaways', 'ai101-m1', 260, 'takeaways', 'stable', '## Key takeaways

- **"AI" is a category.** The kind reshaping your work is a large language model. Much of the AI already in your HR stack is something else — usually a scoring or matching model — and the distinction changes the failure mode, the vendor questions, and the regulatory exposure.
- **An LLM predicts the next piece of text, one piece at a time,** based on everything it''s seen. It is not retrieving, not verifying, and not reasoning the way a person does — even when the output looks like reasoning.
- **Confidence and correctness are decoupled** in a way they aren''t in human writing. This is the root of hallucination and the reason fluent output deserves more scrutiny, not less.
- **The model has never seen your organization.** Not your handbook, your data, your history, or your decisions. Anything requiring that knowledge must be supplied by you or it will be invented.
- **All training data carries bias, and in People work that''s not abstract** — it''s the mechanism behind adverse impact.
- **The delegation heuristic:** AI does well when you supply the material and ask for transformation; badly when the task needs organizational knowledge it was never given; and it must not make decisions about people.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1-activity-link', 'ai101-m1', 270, 'exercise', 'stable', '{"type":"activity_link","title":"Applied activity — Testing the Edges","blurb":"Three short conversations with your AI tool, each built to expose a different property of the system, then a 250–350 word reflection. Graded against a four-dimension rubric with per-dimension feedback. Free unlimited resubmission.","estMinutes":"20–25"}', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1a-intro', 'ai101-m1-activity', 10, 'prose', 'stable', '## Applied activity — "Testing the Edges"

**Time:** 20–25 minutes · **Submit:** a record of three conversations plus a 250–350 word reflection · **Graded against the rubric below.** Score doesn''t matter. Doing the work is where the learning lands.

Have three short conversations with your AI tool. Each is built to expose a different property of the system. Then write a short reflection on what you noticed.

This is not about getting good answers. It''s about watching the thing behave so you build real intuition for what it is.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1a-conv1', 'ai101-m1-activity', 20, 'prose', 'stable', '### Conversation 1 — Where it''s strong

Pick a subject you know well: an area of People practice you''ve worked in for years, a policy you wrote, a process you own. Ask a substantive question. Read the answer critically — you''re one of the few people who can actually judge it. Then ask one follow-up that pushes deeper.

*Notice:* What does it handle well? Where does it sound like it genuinely understands? Where does it produce something that reads correctly but that you know is thin?', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1a-conv2', 'ai101-m1-activity', 30, 'prose', 'stable', '### Conversation 2 — Where it might fabricate

**Predict first.** Before you send anything, write down: *how likely is it that this answer contains something invented?* Give a percentage — there''s a field for it below.

Then ask for something specific and hard to verify. Options that work:

- A statistic about employment practice with a source citation
- What a specific named regulation requires in a specific jurisdiction
- Details about a small organization you know well
- A quotation from a specific page of a specific book

Now check it. Actually check it — follow the citation, look up the regulation, verify the number.

*Record:* your prediction, what actually happened, and how far off you were.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1a-conv3', 'ai101-m1-activity', 40, 'prose', 'stable', '### Conversation 3 — Where it can''t know

Ask something about your own organization that the model was never given. Your parental leave provision. Why your last engagement survey moved. Which of your roles takes longest to fill.

Watch carefully. Does it refuse? Hedge? Ask you for context? Or does it produce something fluent, specific, and fabricated? Then paste in the actual material and ask again.

*Notice:* the difference between the two answers is the entire lesson of Lesson 4.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1a-reflection', 'ai101-m1-activity', 50, 'prose', 'stable', '### The reflection — 250–350 words

Address all of:

- One thing the model did better than you expected
- One thing it did worse
- Your calibration: what you predicted in Conversation 2, what happened, and which direction you were wrong in
- One habit you''ll change on Monday, stated concretely enough that someone could check whether you did it', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1a-rubric', 'ai101-m1-activity', 60, 'table', 'stable', '### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Engagement with all three conversations** | All three run, with actual transcripts or faithful accounts. Follow-ups asked. Real subject matter, not placeholder queries. |
| **Observation of mechanics** | The reflection connects what was observed to how the system works — prediction, training data, context — rather than only reporting what it said. |
| **Calibration** | A prediction was made *before* Conversation 2, compared honestly afterward, and the direction of error is named. Accuracy isn''t scored; honesty and specificity are. |
| **Practical insight** | The habit named is concrete, tied to actual work, and checkable. Not "I''ll be more careful." |', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1micro-core', 'ai101-m1-micro', 10, 'prose', 'stable', '## Module 1 in two minutes

**"AI" is a category, not a technology.** The kind reshaping your work is a large language model (LLM): software that, given some text, predicts what should come next — one small piece at a time. It is not searching, not looking things up, and not reasoning like a colleague, even when it sounds like one. Much of the "AI" already in your HR stack is something else entirely — a scoring or matching model — and the distinction changes the failure mode, the vendor questions, and the regulatory exposure.

**Confidence and correctness are decoupled.** The model produces statistically likely text. Sometimes likely is also true; sometimes it isn''t. In human writing, someone who sounds certain usually has reason to be — that coupling does not exist here. Fluent output deserves more scrutiny, not less, and in People work a fluent, wrong document can shape someone''s livelihood.

**The model has never seen your organization.** Not your handbook, your comp bands, your survey data, your investigation files. Anything that requires that knowledge must be supplied by you in the conversation — or it will be invented, fluently, with no signal that it''s invented.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1micro-heuristic', 'ai101-m1-micro', 20, 'callout', 'stable', '### The delegation heuristic

AI does well when you supply the material and ask for transformation. It does badly when the task needs organizational knowledge it was never given. And it must not make decisions about people — regardless of how good the output looks.', NULL, '2026-07-28', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('m1micro-habit', 'ai101-m1-micro', 30, 'prose', 'stable', '**The one habit to build:** before any task, ask *"what does the model not know that I''d have to give it?"* That single question is the seed of good prompting and of good judgment about what to hand over at all.', NULL, '2026-07-28', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m1-sorting', 'ai101-m1', 'sorting', '{"buckets":[{"id":"well","label":"Does this well","hint":"Hand it over","rank":2,"pct":85},{"id":"partly","label":"Does this partly","hint":"Needs verification","rank":1,"pct":50},{"id":"badly","label":"Does this badly","hint":"Don''t","rank":0,"pct":15}],"tasks":[{"id":"t1","text":"Rewrite a job description to strip out jargon and inflated requirements","key":"well","reasoning":"You supply the JD; the model transforms it. Language transformation on material you provide is the center of its competence."},{"id":"t2","text":"Turn a page of your messy interview notes into a structured debrief","key":"well","reasoning":"Your notes in, structure out. The model never needs to know anything you didn''t hand it."},{"id":"t3","text":"Explain what happened to attrition in your Denver office last quarter","key":"badly","reasoning":"The model never saw your attrition data. It will answer anyway — fluently, and invented."},{"id":"t4","text":"Draft three versions of a candidate rejection email at different levels of warmth","key":"well","reasoning":"Tone variation on a well-understood format. It has seen thousands of these."},{"id":"t5","text":"Summarize the themes across 200 engagement survey free-text comments you paste in","key":"partly","reasoning":"Good at surfacing patterns, but it flattens minority views and will present a confident summary of the comments it weighted most. Read the raw comments too."},{"id":"t6","text":"Tell you which section of your employee handbook covers bereavement leave","key":"badly","reasoning":"It has never seen your handbook. It has seen thousands of others, so what it produces will read exactly like yours — and won''t be."},{"id":"t7","text":"Generate interview questions for a competency you describe in detail","key":"well","reasoning":"You describe the competency; it generates against your description. Supply the material, ask for transformation."},{"id":"t8","text":"Recommend the comp band for a new role","key":"badly","reasoning":"Your comp philosophy, your bands, your market data — none of it was in training. Any number it gives is a fabrication wearing a confident face."},{"id":"t9","text":"Rewrite a policy paragraph so a non-native English speaker can follow it","key":"well","reasoning":"Plain-language rewriting of supplied text. Squarely in competence."},{"id":"t10","text":"Explain, in general terms, what a statutory leave entitlement typically covers","key":"partly","reasoning":"Reasonable in the abstract, unreliable on your jurisdiction, your plan, or current specifics. Verify anything you''d act on."},{"id":"t11","text":"Decide whether an employee''s conduct warrants termination","key":"badly","reasoning":"This one isn''t about capability. It''s a decision about a person''s livelihood and it stays with a human, however good the output looks."},{"id":"t12","text":"Draft a performance improvement plan from notes you supply","key":"partly","reasoning":"Structure and language, yes; the judgment about whether a PIP is warranted, never."},{"id":"t13","text":"Tell you what your CEO said at last month''s all-hands","key":"badly","reasoning":"It wasn''t in the room and the transcript wasn''t in its training. It will produce plausible executive remarks that nobody gave."},{"id":"t14","text":"Produce a plain-language FAQ from a benefits summary you paste in","key":"well","reasoning":"Pasted source, transformed format. The model has everything it needs because you gave it everything it needs."},{"id":"t15","text":"Identify which of your open roles is hardest to fill","key":"badly","reasoning":"Your requisition data never reached it. Same failure as the attrition question: a confident answer built on nothing."}],"pattern":"AI does well when you supply the material and ask for transformation. It does badly when the task needs organizational knowledge it was never given. And it must not make decisions about people.","postscript":"If you missed several, look at which kind you missed. Over-assigning to \"does this well\" means you''re likely to ship something fabricated. Over-assigning to \"does this badly\" means you''re leaving real leverage on the table. Both are calibration errors. Neither is a character flaw. Both are fixable, and the next seven modules are how."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m1-rubric', 'ai101-m1', 'rubric', '{"promptVersion":"m1-testing-the-edges-v1","moduleId":"ai101-m1","minWords":250,"maxWords":350,"dimensions":[{"name":"Engagement with all three conversations","criteria":"All three run, with actual transcripts or faithful accounts. Follow-ups asked. Real subject matter, not placeholder queries."},{"name":"Observation of mechanics","criteria":"The reflection connects what was observed to how the system works — prediction, training data, context — rather than only reporting what it said."},{"name":"Calibration","criteria":"A prediction was made before Conversation 2, compared honestly afterward, and the direction of error is named. Accuracy isn''t scored; honesty and specificity are."},{"name":"Practical insight","criteria":"The habit named is concrete, tied to actual work, and checkable. Not \"I''ll be more careful.\""}],"minChars":700,"calibration":[{"key":"conversation2","label":"Conversation 2 prediction — % chance it invented something","hint":"Recorded before you check — honesty is what''s scored, not accuracy.","placeholder":"e.g. 60","min":0,"max":100}],"submitLabel":"Three conversations + reflection","intro":"Paste your three conversation accounts and the reflection below. Resubmission is free and unlimited — the score is a mirror, not a gate."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m1-knowledge_check', 'ai101-m1', 'knowledge_check', '{"title":"Knowledge check — 10 questions","note":"Retakes are free and unlimited; previous answers are cleared.","reviewedAt":"2026-07-28","questions":[{"id":"q1","prompt":"Which is the most accurate working definition of \"AI\" as the term is used in your day-to-day work?","options":["A category covering many technologies, most prominently large language models","Software built to replace human workers across knowledge-work roles","Any program that automates a task, including spreadsheet macros and scheduling rules","A system that has achieved human-like general awareness"],"correctIndex":0,"explanation":"AI is best understood as a broad category, with LLMs the kind most directly reshaping knowledge work. The others miss differently: human-like awareness is science fiction rather than anything the field has produced; calling all automation AI is so broad it stops being useful (a calculator isn''t AI); and \"built to replace workers\" is a claim about intent, not a definition.","study":{"blockId":"m1-l1-intro","label":"Lesson 1 · What we mean when we say \"AI\""}},{"id":"q2","prompt":"What does a large language model actually do when you send it a prompt?","options":["Looks up an answer in a database of pre-written responses","Searches the internet and summarizes the top results","Predicts what text should come next, one small piece at a time, from patterns learned in training","Reasons through the problem as a human expert would, then writes out the solution"],"correctIndex":2,"explanation":"The core mechanic is next-piece prediction. Some tools layer search on top, which changes what''s available in the prompt, but the model underneath is a statistical text predictor — not a lookup, not a search engine, and not human-style reasoning, even when the output resembles it.","study":{"blockId":"m1-l2-mechanism","label":"Lesson 2 · What an LLM actually does"}},{"id":"q3","prompt":"Your ATS advertises \"AI-powered candidate matching.\" Based on this module, what''s the most useful first question to ask the vendor?","options":["Which large language model does it use?","Is this a language model or a scoring/matching model, and does it influence a decision about a person?","How large is the context window?","What was the knowledge cutoff date?"],"correctIndex":1,"explanation":"Candidate matching is usually a scoring model, not a language model — and scoring models that influence employment decisions are where regulatory obligations and adverse-impact risk concentrate. The other three questions are only meaningful once you know it''s a language model, and asking them first signals you haven''t made the distinction.","study":{"blockId":"m1-l1-hrstack","label":"Lesson 1 · The AI in your HR stack"}},{"id":"q4","prompt":"You ask the same question twice and get two slightly different answers. Most likely explanation?","options":["One of the two is a malfunction","The provider updated the model between your questions","A bug worth reporting to support","There''s a small amount of randomness in how each next piece is chosen, which is normal"],"correctIndex":3,"explanation":"Small variation is built into how these systems generate output. The same input rarely produces byte-identical results, and sometimes the second attempt is better — which is why re-running a prompt is a legitimate technique rather than a workaround.","study":{"blockId":"m1-l2-mechanism","label":"Lesson 2 · What an LLM actually does"}},{"id":"q5","prompt":"What is the context window?","options":["The hours during which the tool is available","Your organization''s list of approved use cases","How much text the model can hold in view at once: your message, the conversation, and attachments","The interface around the chat box"],"correctIndex":2,"explanation":"It''s the model''s working memory for a given response, and it''s finite. Understanding it explains why very long conversations feel like the model forgot something, and why pasting in a 90-page handbook can crowd out the question you actually asked.","study":{"blockId":"m1-l3-vocab-a","label":"Lesson 3 · The vocabulary, demystified"}},{"id":"q6","prompt":"You ask an AI what your organization''s bereavement leave policy says. You paste nothing. What''s most likely?","options":["It produces a fluent, specific, plausible policy that isn''t yours","It refuses and explains it has no access to your systems","It asks a series of clarifying questions before answering","It accurately describes typical policy and clearly labels it as generic"],"correctIndex":0,"explanation":"This is the highest-stakes pattern in the module. The model never saw your handbook, but it has seen thousands of bereavement policies, so it can generate something that reads exactly like one. Some tools will hedge — the other outcomes happen sometimes — but you cannot rely on it, and the failure is quiet. You get a real-looking answer with no signal that it''s invented.","study":{"blockId":"m1-l4-supply","label":"Lesson 4 · The data you supply"}},{"id":"q7","prompt":"Which of these is NOT shaped by a model''s training data?","options":["Which languages it''s strongest in","Which topics it handles well","Whether it knows about something that happened this morning","The exact wording you choose to put in your prompt"],"correctIndex":3,"explanation":"Your prompt is the data *you* contribute, in the moment. It''s the part you control and the part not inherited from training. The other three — topic strength, language strength, recency — all follow directly from what was in the training corpus and when it was assembled.","study":{"blockId":"m1-l4-training","label":"Lesson 4 · Why data is the whole game"}},{"id":"q8","prompt":"Why does the bias question carry more weight in People work than in most functions?","options":["HR teams use AI more heavily than other functions","Models are trained on more HR data than other kinds","Outputs can influence decisions about people, which is the mechanism by which adverse impact occurs","Employment law prohibits using AI in HR contexts"],"correctIndex":2,"explanation":"All training data carries bias and all models can reproduce it. What changes in People work is the consequence: when a biased output shapes screening, evaluation, or advancement, the harm attaches to a person and creates real legal exposure. The last option is simply false — AI isn''t prohibited in HR, it''s regulated in specific decision contexts.","study":{"blockId":"m1-l4-training","label":"Lesson 4 · Why data is the whole game"}},{"id":"q9","prompt":"What''s the most accurate description of a hallucination?","options":["The model deliberately misleading you","The model producing something confident and plausible that is wrong or invented","The model flagging uncertainty in its response","The model crashing or returning nothing"],"correctIndex":1,"explanation":"Note what''s absent: intent. The model isn''t lying, because lying requires knowing the truth and choosing otherwise. It''s generating statistically likely text, and sometimes likely text is false. That''s precisely why it''s hard to catch — there''s no tell.","study":{"blockId":"m1-l3-vocab-b","label":"Lesson 3 · Hallucination, demystified"}},{"id":"q10","prompt":"You want to start using AI well. Based on this module, which habit is most important to build first?","options":["Asking, before any task: what does the model not know that I''d need to give it?","Always writing the longest, most detailed prompt possible","Using AI for as many tasks as you can each day to build reps","Keeping track of which model versions each provider has released"],"correctIndex":0,"explanation":"That single question is the seed of good prompting and of good delegation judgment. It forces you to think about the data the model needs — the single largest lever on output quality — and it surfaces the tasks you shouldn''t hand over at all. The others are counterproductive (longer isn''t better), unfocused (reps without judgment build confident bad habits), or performative (version numbers are trivia).","study":{"blockId":"m1-takeaways","label":"Key takeaways · the habit to build"}}]}', '2026-07-28');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-calibration-prompt-before-you-start-10', 'ai101-m2', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. You''ll score it during the applied activity.*

By the end of this module you''ll audit the systems your People function actually runs — the ATS,
the HRIS, the survey platform, the docs suite, the chat tools — and find the AI already inside
them.

**How many distinct systems in your stack have AI in them right now?** Count anything you or
your team touches in a normal month. Write the number down before you look.

Almost everyone guesses low. The gap between your number and the real one is the point: it
measures how much AI is already making or shaping calls around you without ever having been
chosen.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-module-brief-20', 'ai101-m2', 20, 'prose', 'stable', '## Module brief

In M1 you built a working model of one thing: the large language model. This module is about a
harder, more practical problem — the word "AI" is currently stuck to at least three genuinely
different technologies, and a People leader meets all three in a single week, usually without
labels.

Here''s the week. Monday, someone on your team asks whether they can use a chat assistant to
draft interview questions. Wednesday, your HRIS vendor demos a new "AI-powered" panel that
answers employees'' benefits questions. Friday, a different vendor shows you a dashboard that
scores your open reqs'' candidate pipelines and flags "high-potential applicants." All three got
called AI. Two of them are the technology you studied in M1. One is something else entirely —
and it''s the one that can quietly make decisions about people.

Confusing them costs you in both directions. Treat a scoring engine like a chat assistant and
you''ll under-scrutinize something with real adverse-impact exposure. Treat a drafting copilot
like a scoring engine and you''ll wrap a harmless writing aid in three layers of approval nobody
needed. Over-trust and over-compliance are the same mistake — reasoning about the label instead
of the thing.

By the end of this module you''ll be able to look at any "AI-powered" product from the outside —
in a demo, in your existing stack, in a teammate''s excited Slack message — and answer the only
question that matters: *what shape of thing is this, and what does that shape make it good for,
bad at, and accountable to?*', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-learning-objectives-30', 'ai101-m2', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Sketch the broad arc of AI as a field — the rule-based era, the shift to machine learning,
   and what changed in 2017 — well enough to talk with a skeptical colleague without
   overclaiming or dismissing.
2. Distinguish the three shapes AI takes in a People leader''s stack — assistants, copilots, and
   decision engines — by what goes in, what comes out, and where the context lives.
3. Identify which shape any product is from the outside, using four questions that need no
   technical access.
4. Explain why the failure modes differ by shape — and why the scoring shape carries the
   regulatory exposure.
5. Match a real task to the right shape, and name the one question you''d put to a vendor before
   trusting their label.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-lesson-1-the-long-arc-briefly-40', 'ai101-m2', 40, 'prose', 'stable', '## Lesson 1 · The long arc, briefly

The term "artificial intelligence" was coined in 1956, at a summer workshop at Dartmouth
College. The researchers there genuinely believed they could crack most of the problem within a
generation. They were wrong — but their ambition set the field''s agenda for decades, and the
field''s history since is the fastest way to understand why this moment is different.

The first several decades were dominated by one approach: encode human knowledge as explicit
rules, then write programs that reason over those rules. It worked in narrow domains and
collapsed everywhere else — the world holds more edge cases than any rulebook can. Twice the
gap between promise and delivery grew wide enough that funding and attention drained away.
The field calls these the **AI winters**, and they''re why some of your most experienced
colleagues reflexively file AI under "hype cycle." They watched it happen before. Their
skepticism is earned, and arguing with it head-on is both rude and ineffective.

The shift that ended the rules era was **machine learning**: instead of writing rules, show the
system enormous numbers of examples and let it find the patterns itself. That''s the lineage the
M1 material comes from — and it''s why *all training data carries bias* is a structural fact
rather than a scandal. A system that learns from examples learns what the examples contain.

The breakthrough that produced the current moment came in 2017, when researchers published the
**transformer** architecture — the design that made it practical to train language models at
enormous scale. Combined with a stubborn empirical finding — bigger models trained on more data
kept getting better, past every point where experts predicted the gains would flatten — it
produced the LLMs from M1. The "GPT" in ChatGPT stands for generative pre-trained *transformer*;
Claude and Gemini are built on the same family of architecture.

So when the skeptic on your leadership team says "we''ve seen AI hype before," the honest answer
is: *yes, twice, and the pattern was real — and this wave is built on a different mechanism than
the ones that stalled.* The previous eras tried to hand-encode intelligence; this one grew a
general language capability from data at scale. That doesn''t mean every product demo is real —
most of what you''ll be pitched is thin wrapping around someone else''s model. It means the
underlying capability is not going to un-happen. Holding both of those at once — no
overclaiming, no dismissing — is the posture this whole course tries to build. You''ll practice
saying it out loud in M8.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-try-50', 'ai101-m2', 50, 'try_this', 'stable', '### Try this — 2 minutes
Think of the most AI-skeptical person you work with. In two sentences — write them down —
explain what changed in 2017 without using the words "transformer" or "architecture."
If your sentences survive their eye-roll, you''ve got the arc.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-lesson-2-the-three-shapes-60', 'ai101-m2', 60, 'prose', 'volatile', '## Lesson 2 · The three shapes [V]

Every "AI" a People leader meets is one of three shapes. The technology overlaps; the shape —
what goes in, what comes out, where the context lives — is what determines how to treat it.

**Shape 1: Assistants.** Claude, ChatGPT, Gemini, Copilot as a standalone chat. A general-purpose
LLM in a conversation window. *You* supply the material and the briefing; it transforms,
drafts, summarizes, critiques. Its defining property is breadth with zero built-in knowledge of
your organization — everything M1 taught. It is the most capable shape and the most dependent
on how well you drive it. When this course says "your AI tool," it means this shape.

**Shape 2: Copilots.** The same LLM technology, embedded inside software you already use — the
drafting panel in your ATS that writes job descriptions, the summarizer in your docs suite, the
benefits-question bot inside the HRIS, the meeting notes in your video tool. The host
application supplies the context automatically, which is the convenience — and the constraint.
A copilot sees what its host shows it and nothing else, does the narrow set of tasks the vendor
built, and quietly inherits every property of LLMs from M1: same fluency, same hallucination
risk, same decoupling of confidence from correctness. The danger with copilots isn''t the
technology — it''s the packaging. Output that appears inside a trusted system of record borrows
that system''s credibility without earning it.

**Shape 3: Decision engines.** Resume screeners and rankers, "candidate match" scores,
attrition-risk predictors, engagement-driver models, comp benchmarking. Mostly not language
models at all — these are scoring and matching systems, often older than the current wave,
rebranded "AI" because the label sells. Structured data about people goes in; a number, rank,
or flag about a person comes out. This is the shape M1 warned about: it doesn''t assist a
decision about a person, it *makes* one and hands you the output. It''s also where regulatory
frameworks concentrate — employment-related scoring is the canonical high-risk category **[V]**
— and where adverse impact stops being abstract. You''ll spend M7 on this shape. For now, one
rule: when the output is a number attached to a person, everything in this course about
"drafts" stops applying. A draft can be edited. A score has already decided something.

> **In your stack [V]:** Your organization''s provisioned tools slot into these shapes — the
> assistants you''ve been given, the copilots already embedded in your HR systems, and any
> scoring features switched on inside them. If you don''t know which of the three shapes a given
> system is, that''s not a gap in your technical knowledge — it''s the audit this module''s
> activity has you run.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-lesson-3-telling-them-apart-from-the-out-70', 'ai101-m2', 70, 'prose', 'stable', '## Lesson 3 · Telling them apart from the outside

You will never be shown a product''s architecture, and you don''t need it. Four questions,
answerable from a demo or a settings page, identify the shape of anything.

**1. What goes in?** Material you choose to give it, per use (assistant). Whatever the host
application already holds (copilot). Structured records about people — resumes, performance
data, survey responses — flowing in automatically (decision engine).

**2. What comes out?** Language you''ll edit — a draft, a summary, an answer (assistant or
copilot). Or a number, rank, score, match percentage, or flag (decision engine). This is the
single sharpest tell: **does it produce language, or a number about a person?** Language can be
read, judged, and rewritten before it touches anyone. A number invites sorting, and sorted
lists become decisions the moment someone is busy.

**3. Where would an error land?** A bad draft lands on *your* desk, caught or not by your
review. A bad copilot answer lands on an employee who asked the benefits bot and believed it. A
bad score lands on a candidate who never knows they were filtered. The further the output lands
from your desk, the less "human review" describes anything real.

**4. Who''s accountable for the output?** If the honest answer is "whoever edits and ships it,"
you''re looking at a drafting tool and M1''s rules apply. If the honest answer is "nobody edits
it — it just routes people," you''re looking at a decision engine, whatever the marketing says —
and it''s carrying accountability no one has consciously accepted.

Ask these four in that vendor demo and watch what happens. A good vendor answers cleanly. A
telling vendor answers the language question with the score question''s answer — "our AI
surfaces the best candidates" — and that blur is your cue to slow the meeting down.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-try-80', 'ai101-m2', 80, 'try_this', 'stable', '### Try this — 3 minutes
Pick one system in your stack with an AI feature you''ve never examined. Answer the four
questions from what you already know. If you can''t answer #3 — where an error would land —
you''ve found this week''s most useful email to send.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-exercise-embed-85', 'ai101-m2', 85, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-lesson-4-choosing-without-getting-paraly-90', 'ai101-m2', 90, 'prose', 'stable', '## Lesson 4 · Choosing without getting paralyzed

"Which AI tool is best?" is the question everyone asks, and it''s the wrong one — it assumes the
tools compete on one axis. The right question is older and calmer: **what is this task actually
asking for?** Run the task, not the tool, through the shapes.

**Transformation of material you have** — rewrite this policy in plain language, structure these
interview notes, draft three versions of this announcement — wants an assistant. This is the
delegation heuristic''s home ground: you supply everything it needs, and your review is the
quality gate. When people ask "which assistant," the honest answer **[V]** is that the leading
ones are close enough that *the one your organization has provisioned, used well,* beats the
marginally better one used through a personal account — because the provisioned one comes with
an agreement about your data, and M8 will show you why that dwarfs any capability difference.

**Work that lives inside a system** — JD drafting in the ATS, summaries in the docs suite —
wants the copilot that''s already there, with one habit attached: read its output with exactly
the M1 skepticism you''d give a chat window. The system of record it appears in vouches for
nothing.

**Anything that scores, ranks, or filters people** doesn''t get a tool recommendation. It gets
M7''s question first: should any system be doing this at all — and under whose sign-off? That
one is never answered in a product demo.

And a counterweight, because tool-shopping is a genuine failure mode: for the tasks in this
course, the capability differences between major assistants are smaller than the difference
between a thin brief and a good one. M5 — prompting as briefing — will move your results more
than any tool switch. If you''re spending more time comparing tools than briefing them, the
comparison has become the procrastination.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-key-takeaways-100', 'ai101-m2', 100, 'takeaways', 'stable', '## Key takeaways

- **"AI" currently names three different shapes** in a People leader''s stack: assistants (you
  supply material, it drafts), copilots (embedded in a host app, context comes along), and
  decision engines (data about people in, scores about people out).
- **The field''s history explains the skeptics.** Two AI winters made "hype cycle" a reasonable
  prior. What changed in 2017 — learned language capability at scale, not hand-coded rules — is
  a different mechanism, which is the honest, non-dismissive answer.
- **The sharpest tell is the output: language, or a number about a person?** Language gets
  edited before it touches anyone. A number attached to a person has already decided something.
- **Copilots borrow credibility from their host system without earning it.** Same LLM, same
  failure modes, more trusted wrapper. Read them with chat-window skepticism.
- **Errors land in different places by shape** — your desk, an employee''s inbox, a candidate''s
  silent rejection. "Human review" only describes the first.
- **Choose by task, not by leaderboard.** The provisioned assistant used well beats the
  marginally better one used outside your data agreement — and briefing quality moves results
  more than tool choice ever will.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-activity-link-105', 'ai101-m2', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 The Stack Audit", "blurb": "Inventory the systems your People function actually runs, classify every AI feature you find by shape, write the vendor question each one deserves \u2014 and score the prediction you made at the top of the module. Graded against a four-dimension rubric with per-dimension feedback. Free unlimited resubmission.", "estMinutes": "20\u201325"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-sources-and-attribution-110', 'ai101-m2', 110, 'prose', 'stable', '## Sources and attribution

This module draws on the following material:

- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with Anthropic,
  CC BY-NC-SA 4.0) — the historical arc in Lesson 1 and the overclaiming/dismissing framing
  adapt its treatment of AI''s history and of calibrated judgment about AI capability.
- **"Attention Is All You Need"** (Vaswani et al., 2017) — the transformer paper behind
  Lesson 1''s account of what changed. **[V]**
- The three-shapes taxonomy and the four outside questions are original to this course,
  developed for the People-leader context.
- Regulatory framing (employment as a high-risk category) follows the EU AI Act''s treatment of
  employment-related AI systems — introduced in M1, deepened in M7. *Verify current specifics
  with counsel; this area moves.* **[V]**', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-activity-applied-activity-the-stack-audit-10', 'ai101-m2-activity', 10, 'prose', 'stable', '## Applied activity — "The Stack Audit"

**Time:** 20–25 minutes · **Submit:** your audit table plus a 250–350 word write-up · **Graded
against the rubric below.** Score doesn''t matter. Doing the work is where the learning lands.

Before you started this module, you predicted how many systems in your People stack have AI in
them. Now go count.

**Step 1 — Inventory (10 min).** List the systems you or your team touch in a normal month:
ATS, HRIS, payroll, survey platform, LMS, docs suite, meeting tools, chat tools, scheduling
tools. For each, note whether it has an AI feature — announced, embedded, or switched on
without ceremony in the last two years. Vendor release notes and settings pages are fair game.
Three systems minimum; most people find more.

**Step 2 — Classify (5 min).** For each AI feature you found, name its shape — assistant,
copilot, or decision engine — using the four questions from Lesson 3. Where a system contains
more than one shape (many do), say so: "HRIS: benefits-answer copilot + attrition-risk decision
engine" is exactly the kind of precision this exercise is after.

**Step 3 — One question each (5 min).** For each decision engine you found — and at least one
copilot — write the single question you''d put to the vendor. Make it concrete enough that a
vendor could actually answer it, and revealing enough that the answer would change what you do.

**Step 4 — Score your prediction (5 min).** Compare the count you predicted against what you
found. Name the direction of your miss and your best one-sentence theory of why.

Then write the reflection: what you found, what surprised you, which single system most needs a
closer look, and why.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-micro-core', 'ai101-m2-micro', 10, 'prose', 'stable', '## Module 2 in two minutes

**"AI" is currently three different things in your stack,** and the label hides which one you''re looking at. **Assistants** (Claude, ChatGPT, Gemini): you supply the material, it drafts, your review is the gate. **Copilots**: the same LLM technology embedded in your ATS, HRIS, or docs suite — context comes from the host app, and the output borrows the host''s credibility without earning it. **Decision engines**: scoring and matching systems — resume rankers, attrition predictors — where data about people goes in and a number about a person comes out.

**The sharpest tell:** does it produce language, or a number attached to a person? Language gets edited before it touches anyone. A number invites sorting, and sorted lists become decisions the moment someone is busy — with the errors landing on people nobody reviewed.

**And the history in one line:** the field stalled twice trying to hand-code intelligence; the 2017 transformer breakthrough grew language capability from data at scale instead. That''s the honest answer to a skeptic — the winters were real, and this mechanism is different.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-micro-rule', 'ai101-m2-micro', 20, 'callout', 'stable', '### The rule to carry

Choose by task, not by leaderboard. Transformation of your material → assistant. Work inside a system → its copilot, read with chat-window skepticism. Anything that scores, ranks, or filters people → stop; that''s not a tool choice, it''s M7''s sign-off question.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m2-micro-close', 'ai101-m2-micro', 30, 'prose', 'stable', '**The full module adds** the four outside questions that identify any product''s shape from a demo, the vendor-demo exercise (find the claim that can''t be true), and the Stack Audit — counting the AI already inside your own systems against the number you predicted.', NULL, '2026-08-11', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m2-choice', 'ai101-m2', 'choice', '{"reviewedAt":"2026-08-11","title":"The demo that blurred","intro":"*Five minutes. Commit before you look.*\n\nYou''re forty minutes into a vendor demo of **TalentFlow**, an \"AI-powered talent intelligence platform\" your TA lead is excited about. Below are four claims the account executive made, verbatim. Three are ordinary vendor talk — optimistic, but consistent with the shape of thing being sold. **One cannot be true as stated**, because it quietly promises the properties of one shape while selling another.\n\nUse the four questions from Lesson 3. Which claim can''t be true?","artifacts":[{"label":"Claim 1 · the drafting panel","body":"\"Our JD Composer drafts job descriptions in your company voice — your recruiters edit and approve every word before anything posts.\""},{"label":"Claim 2 · the ranking dashboard","body":"\"Our Fit Score ranks every applicant against the role profile automatically, so your team spends their time on the top of the list, not the pile.\""},{"label":"Claim 3 · the assurance","body":"\"And because a human recruiter always makes the final hiring decision, the Fit Score is purely assistive — there''s no automated decision-making anywhere in the product.\""},{"label":"Claim 4 · the integration","body":"\"It all lives inside the ATS you already use — your team never has to leave their workflow or learn a new tool.\""}],"options":[{"id":"c1","label":"Claim 1 — the drafting panel"},{"id":"c2","label":"Claim 2 — the ranking dashboard"},{"id":"c3","label":"Claim 3 — the assurance"},{"id":"c4","label":"Claim 4 — the integration"}],"key":"c3","reasoning":"**Claim 3 can''t be true as stated.** Claim 2 already told you the shape: applicants are ranked automatically, and the team works \"the top of the list, not the pile.\" That means the sorting has happened before any human looks — the people at the bottom are filtered by the score, reviewed by no one. A system can be a decision engine *and* have a human sign the final offer; what it can''t be is \"purely assistive\" while deciding who never gets seen. This is the exact blur from Lesson 3: answering the accountability question with the drafting shape''s answer while selling the scoring shape.\n\nThe other three claims are consistent with their shapes. Claim 1 describes a copilot doing what copilots do — draft for a human who edits and ships (your M1 skepticism still applies to the drafts). Claim 4 is packaging, not capability — true of many products, good and bad. Claim 2 is honest, even blunt, about being a decision engine — which is precisely why Claim 3 contradicts it.\n\nThe practitioner''s move when you hear this blur in a live demo: slow the meeting down and ask question 3 — *where would an error land?* For the Fit Score, it lands on a candidate nobody reviewed. What happens next is M7''s territory."}', '2026-08-11');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m2-rubric', 'ai101-m2', 'rubric', '{"promptVersion":"ai101-m2-stack-audit-v1","moduleId":"ai101-m2","minWords":250,"maxWords":350,"submitLabel":"Your audit table and reflection","intro":"Paste your audit table (any readable format) followed by the 250–350 word reflection. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 101, The Foundation). Module 2 applied activity, ''The Stack Audit'': an inventory of the systems their People function runs (three minimum), each AI feature classified by shape (assistant / copilot / decision engine), a concrete vendor question for each decision engine found plus at least one copilot, and a comparison against the count they predicted before the module. A numeric prediction may have been captured by the module''s opening calibration prompt; grade the calibration dimension on whether the prediction is stated and honestly compared, never on its accuracy.","opening":[{"key":"systems","label":"Predicted — systems in your stack with AI in them","hint":"Count anything you or your team touches in a normal month.","placeholder":"e.g. 4","min":0,"max":40}],"calibration":[{"key":"systemsActual","label":"Found — systems that actually have AI in them","hint":"Your audit''s real count. The miss is the lesson.","placeholder":"e.g. 7","min":0,"max":40,"actualFor":"systems"}],"dimensions":[{"name":"Coverage honesty","criteria":"At least three real systems from their actual stack, named specifically enough to be recognizable (vendor or category). An admitted ''I couldn''t find out'' for a system outscores a confident guess."},{"name":"Classification reasoning","criteria":"Shapes assigned using the four questions — what goes in, what comes out, where errors land, who''s accountable — not vendor labels. Systems containing more than one shape are split rather than averaged. A defended borderline call outscores an undefended correct one."},{"name":"The vendor questions","criteria":"Each question is concrete enough for a vendor to answer and revealing enough that the answer would change something. ''Is your AI ethical?'' scores low; ''what share of applicants does the Fit Score filter before a human sees them?'' scores high."},{"name":"Calibration","criteria":"The predicted count is stated, compared against what the audit found, the direction of the miss named, and a one-sentence theory offered. Accuracy isn''t graded; honesty and specificity are."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m2-knowledge_check', 'ai101-m2', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-11","questions":[{"id":"q1","prompt":"A colleague says \"AI is just another hype cycle — I''ve seen this before.\" What''s the most honest and accurate response?","options":["They''re wrong — this technology has no precedent and the old pattern doesn''t apply","They''re right — the field has overpromised before and this wave will fade the same way","The skepticism is earned — the field stalled twice — but this wave runs on a different mechanism: learned capability from data at scale, not hand-coded rules","It doesn''t matter either way, because the tools change too fast for the history to be relevant"],"correctIndex":2,"explanation":"Both winters were real, which is why the skepticism deserves respect rather than rebuttal — and the mechanism shift is why the pattern doesn''t simply repeat. A overclaims, B dismisses, and D dodges the question the skeptic actually asked."},{"id":"q2","prompt":"What changed in 2017 that made the current generation of AI tools possible?","options":["Computers finally became fast enough to run the rule-based systems designed in the 1980s","The transformer architecture made it practical to train language models at enormous scale","Governments began funding AI research again after the second AI winter","Companies started collecting employee data in large enough volumes to train on"],"correctIndex":1,"explanation":"The transformer is the architecture behind the \"T\" in GPT — and behind Claude and Gemini. Combined with the finding that bigger models kept improving, it produced modern LLMs. A describes the era that failed; C and D aren''t the mechanism."},{"id":"q3","prompt":"Your HRIS vendor announces an \"AI-powered\" panel that answers employees'' benefits questions inside the HRIS. Which shape is this, and what''s its defining property?","options":["An assistant — the employee supplies all the context it uses","A decision engine — it processes structured employee records","A copilot — LLM technology embedded in a host system, drawing context from that system and borrowing its credibility","Not AI at all — question answering is a search feature"],"correctIndex":2,"explanation":"Embedded in a host app, context supplied by the host, narrow task set — and output that appears inside a trusted system of record, which is exactly why its errors are dangerous: an employee who asked the official HRIS believes the answer."},{"id":"q4","prompt":"Of the four outside questions, which single tell most sharply separates a decision engine from the other two shapes?","options":["Whether the product uses a large language model internally","Whether the output is language you''ll edit, or a number, rank, or flag attached to a person","Whether the vendor calls the feature \"AI-powered\" in their marketing","Whether the tool requires a separate login from your other systems"],"correctIndex":1,"explanation":"Language gets read, judged, and rewritten before it touches anyone; a number about a person invites sorting, and sorted lists become decisions. A is invisible from the outside, C is marketing, D is IT trivia."},{"id":"q5","prompt":"Why does a copilot''s output deserve the same skepticism as a chat assistant''s, even though it appears inside your system of record?","options":["It doesn''t — the host system''s data makes copilot output more reliable","Copilots run on older, weaker models than standalone assistants","It''s the same LLM technology with the same failure modes — the trusted wrapper adds credibility without adding correctness","Copilot output is unreliable because host systems restrict what the model can see"],"correctIndex":2,"explanation":"Same fluency, same hallucination risk, same confidence–correctness decoupling from M1. The packaging is the hazard: output inside the official HRIS *looks* vouched for. B isn''t reliably true, and D describes a constraint, not the reason for skepticism."},{"id":"q6","prompt":"A vendor demo shows a dashboard that ranks your candidate pipeline and flags \"high-potential applicants.\" Where would this system''s errors land?","options":["On your desk, caught by your normal review before anything ships","On the vendor, who is accountable for their model''s outputs","Nowhere serious — a ranking is only a suggestion until a human acts on it","On candidates who get filtered or deprioritized without anyone ever reviewing the call"],"correctIndex":3,"explanation":"A ranked list does its damage upstream of review: the people it sorts to the bottom silently fall out of a busy pipeline. That''s why \"human review\" describes drafting tools, not scoring tools — the human reviews the survivors, not the decision."},{"id":"q7","prompt":"Your team wants to turn messy panel-interview notes into structured debriefs. Which shape fits, and why?","options":["An assistant — you supply the notes, it transforms them, and your review is the quality gate","A decision engine — interview evaluation is fundamentally a scoring task","A copilot only — notes should never leave the system they were taken in","None — interview material is too sensitive for any AI shape to touch"],"correctIndex":0,"explanation":"Transformation of material you supply is the assistant''s home ground and the delegation heuristic''s center. B would convert your notes into scores about people — exactly the shape shift M7 exists to stop. C and D confuse the shape question with the data question, which M4 handles on its own terms."},{"id":"q8","prompt":"What''s the strongest argument for using the assistant your organization has provisioned rather than a marginally better one through a personal account?","options":["The provisioned one is always the most capable option available","The provisioned one comes with an agreement about your data — and that outweighs capability differences that briefing quality dwarfs anyway","IT departments block personal accounts, so the question never arises","Using multiple assistants confuses the models and degrades their output"],"correctIndex":1,"explanation":"The data agreement is the real difference — M8 makes this concrete — and M5 will show that briefing quality moves results more than tool choice. A isn''t guaranteed, C isn''t reliably true, and D isn''t a thing."}]}', '2026-08-11');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-calibration-prompt-before-you-start-10', 'ai101-m3', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. You''ll score it during the applied activity.*

At the end of this module you''ll take one recurring task from your own function — say,
summarizing your engagement survey''s free-text comments twice a year, or drafting every job
description your team posts — and estimate what it would cost per month to run through an AI
tool.

**Pick your task now, and predict its monthly cost in dollars.** Gut number, no arithmetic.
Write it down.

Most people miss by an order of magnitude — and the *direction* of the miss is what''s
interesting. Guessing high usually means pricing the hype; guessing low usually means
forgetting the reviewing human. Either way, the miss is the lesson.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-module-brief-20', 'ai101-m3', 20, 'prose', 'stable', '## Module brief

You don''t need to understand AI economics to use a chat assistant. You need it the moment the
conversation stops being about *you* using a tool and starts being about *scale*: a vendor
quote lands on your desk, someone proposes running every exit interview through a summarizer,
or Finance asks why the AI line item doubled. In those conversations, the person who
understands what the meter is actually counting has a structural advantage over the person
nodding along.

The good news: the entire subject rests on one unit you already met in M1 — the token — and
three pricing structures built on top of it. Learn those and vendor quotes stop being
mysterious documents. You can size a use case on a napkin, spot the pricing model that goes
wrong at your volume, and ask the question that makes a thin product wrapper visibly thin.

The honest framing before we start: **the numbers in this module are illustrative, and the
structure is the lesson.** Per-token prices have moved constantly since these tools launched
— mostly down, sometimes by a lot **[V]** — and any specific figure printed here would be stale
in months. What doesn''t move is the shape: everything is metered in tokens, tokens map to
volume of text, and every pricing plan is a bet about your usage that someone — you or the
vendor — is on the wrong side of.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-learning-objectives-30', 'ai101-m3', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain what a token is and why every AI cost, limit, and price traces back to counting
   them.
2. Reason about the context window as a budget — why long documents and long conversations
   cost more, degrade, or both.
3. Decide when a more capable model is worth its price, and recognize the People-work tasks
   where the cheaper tier is the right call.
4. Read a vendor quote: identify which of the three pricing structures you''re looking at, and
   what usage pattern makes each one go wrong.
5. Produce a defensible order-of-magnitude cost estimate for one real use case — the applied
   activity.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-lesson-1-the-token-economy-40', 'ai101-m3', 40, 'prose', 'volatile', '## Lesson 1 · The token economy [V]

M1 told you a language model reads and writes in **tokens** — fragments of words, roughly
three-quarters of an English word each. What M1 didn''t say is that the token is also the
industry''s billing unit. Every price you will ever see, whatever it''s dressed as, is
ultimately a price for tokens in and tokens out.

Rough sizes, to build intuition **[V]**: a one-page memo runs several hundred tokens. A
ten-page policy, a few thousand. Two hundred engagement-survey comments, maybe ten to twenty
thousand. Your whole employee handbook, likely into the hundreds of thousands. When you paste
a document into a chat window, you are spending tokens; when the model answers, it spends
more. A "conversation" is a running token bill that both sides are adding to.

Two consequences follow immediately.

**Input and output are priced separately, and output usually costs more per token** **[V]**.
This is why "summarize this long document" (huge input, small output) and "write me a long
report from these notes" (small input, huge output) have very different cost shapes even
though both are one prompt.

**"Unlimited" plans are a bet, not a description.** A flat per-seat subscription doesn''t make
tokens free — it means the vendor predicted your usage and priced above it. Push usage far
enough past the prediction and you meet the fine print: rate limits, throttling, "fair use"
caps **[V]**. This isn''t vendor malice; it''s the token meter reasserting itself. The practical
habit: whenever a price looks flat, ask what happens at ten times your expected volume. The
answer tells you where the meter actually is.

For a casual user none of this matters — the subscription is genuinely simpler and usually
cheaper than metered pricing at low volume. It starts to matter exactly when *you* start to
matter: the moment a task runs on a schedule rather than on a whim, tokens stop being an
abstraction and become a line item. That moment is the subject of the rest of this module.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-try-50', 'ai101-m3', 50, 'try_this', 'stable', '### Try this — 2 minutes
Take the last substantial thing you pasted into an AI tool — or would paste. Estimate its
tokens: word count × 1.3, roughly. Now imagine the task running weekly for a year, for
everyone on your team. You''ve just done real AI cost analysis — that multiplication is the
whole method, and Lesson 4''s vendors are hoping you never do it.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-lesson-2-the-context-window-as-a-budget-60', 'ai101-m3', 60, 'prose', 'volatile', '## Lesson 2 · The context window as a budget [V]

M1 introduced the **context window** — everything the model can see at once: your instructions,
the documents you''ve supplied, and the conversation so far. This lesson makes it economic: the
window is a *budget*, and treating it as unlimited is the most common way careful people get
bad results at scale.

Three budget behaviors are worth internalizing.

**Filling it costs money.** Everything in the window is input tokens, re-sent with every turn
of the conversation. A long chat with a large document attached re-reads that document, in
token terms, every time you follow up **[V]** — which is why a rambling twenty-turn
conversation over your handbook can cost more than twenty clean one-shot questions, and why
the practitioners'' habit of starting fresh conversations per task (which you''ll build in 201)
is a cost habit as much as a quality habit.

**Filling it degrades attention.** The window is bigger than it used to be — current models
advertise room for hundreds of pages **[V]** — but *fits* is not *attends*. M1''s mechanism
explains why: every fragment is predicted from everything in view, and the more you put in
view, the more everything competes. Material buried in the middle of a very long context is
where details quietly stop influencing the output. The symptom to watch for: confident,
fluent summaries of a long document that are strangely thin on its middle sections. (M4 gives
this failure a full lesson; here it''s enough to know the budget has a quality dimension, not
just a cost one.)

**Overflowing it silently truncates.** When a conversation outgrows the window, the oldest
material drops out of view — the model doesn''t announce this, and its fluency doesn''t dip.
Your instructions from the start of a long session may simply no longer exist as far as the
model is concerned. If a long conversation seems to have "forgotten" its brief, it likely
has — literally.

The budget mindset, in one line: **decide what the model needs to see for *this* question, and
supply that** — not everything you have. It''s cheaper, and it''s better. The instinct to paste
more context is usually right in direction (M1: the model knows nothing about your org) and
wrong in indiscriminateness; M5 will turn that instinct into technique.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-lesson-3-when-the-bigger-model-is-worth--70', 'ai101-m3', 70, 'prose', 'volatile', '## Lesson 3 · When the bigger model is worth it [V]

Every provider sells a range: a frontier model — the most capable, priced accordingly — and
one or more cheaper, faster tiers that are a fraction of the cost per token **[V]**. The gap
matters at scale: at meaningful volume, tier choice can move a project''s cost by multiples.
So the question "which tier?" is a real budgeting decision, and it has a calmer answer than
the marketing suggests.

**Where the cheap tier wins** — which, for People work, is most of the time: transformation
tasks with clear instructions and supplied material. Reformatting notes into a debrief.
Extracting themes from comments *you provide*. Drafting routine communications from a solid
brief. First-pass summaries a human will review anyway. These sit at the delegation
heuristic''s center — you supplied everything, the shape of the output is known — and the
cheaper tier does them roughly as well as the frontier model, several times cheaper and
faster.

**Where the frontier model earns its price:** long or subtle judgment over lots of material at
once — the tasks where quality failures are expensive and hard to spot. Nuanced synthesis
across many documents, careful reasoning about an ambiguous situation, drafting where tone
misfires carry real cost. And note the pattern in that list: as tasks climb toward requiring
organizational judgment, they climb toward the heuristic''s *boundary* — the tasks where the
question stops being "which tier" and becomes "should the model be doing this without heavy
human involvement at all." **If a task seems to need the smartest possible model, treat that
as a flag to increase your review, not just your spend.**

Two practical corollaries. First, *start cheap and escalate on evidence*: run the task on the
cheaper tier, look at the output, and pay up only where you can articulate what was missing —
that articulation is itself the review skill M6 builds. Second, *latency is a price too*:
frontier models are slower, and for interactive drafting work, a fast good-enough model often
beats a slow brilliant one because you iterate more. M5 will show that iteration count drives
quality more than model choice does.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-try-80', 'ai101-m3', 80, 'try_this', 'stable', '### Try this — 3 minutes
Take three AI-suitable tasks from your own week (steal them from M1''s sorting exercise if
you did it). For each, one-line verdict: cheap tier, frontier, or "the tier question is the
wrong question — this one needs a human." If everything landed in the frontier column,
re-read the flag above: you may be describing tasks that need review, not horsepower.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-lesson-4-reading-a-vendor-quote-90', 'ai101-m3', 90, 'prose', 'volatile', '## Lesson 4 · Reading a vendor quote [V]

Every AI price you''ll ever be quoted is one of three structures — or a bundle hiding one
inside another. Each is a bet about usage, each goes wrong at a predictable place, and your
job in a procurement conversation is to find where.

**Per-seat subscription.** Flat monthly price per user **[V]**. The vendor''s bet: average
usage stays modest. Goes wrong at the edges: heavy automated usage hits the fine-print caps
(Lesson 1), while a sea of licensed-but-inactive seats means you''re paying retail for shelf
space. The question to ask: *what does the fine print say at 10× typical usage — and what
share of our seats were active last month?* For the second half, demand the usage report;
every vendor has one.

**Metered (per-use) pricing.** Pay per token, per document, per "credit" **[V]**. The bet
runs the other way: the vendor wins when you use more. Predictable at steady volume, goes
wrong at spikes — the surge you didn''t forecast (survey season, annual review cycle, a
reorg''s worth of documents) arrives as an invoice. The questions: *what exactly is metered —
tokens, documents, or something the vendor invented* (a "credit" is a markup wearing a
costume) — *and what does our peak month look like, priced out?*

**Enterprise agreement.** Negotiated flat rate for an organization **[V]**, typically bundling
capability with the things M8 cares about — data terms, admin controls, retention promises.
Goes wrong through mismatch: paying for an org-wide capability that fifty people use, or —
the reverse and more common failure — buying the cheap thing and discovering the data terms
you actually needed were in the tier you skipped. The question: *which parts of this price
are capability and which are the data agreement?* — because (M8 will argue) the second part
is the part you can''t do without.

And one structural question that cuts across all three, for any product that isn''t from a
model provider directly: **"which model does this run on, and what happens to our price when
your model costs change?"** Most AI products are a workflow layer over someone else''s model —
often a genuinely valuable layer, sometimes a thin one. A vendor with a real product answers
cleanly. A vendor selling tokens at retail with a logo on top gets vague — and per-token
prices'' historical direction of travel **[V]** means their margin is a melting asset you''d be
locking in at today''s rate. Thin isn''t automatically bad; *unpriceable* is. If they can''t
answer, you can''t size the deal, and that — not any single number — is what "being the person
who understands the meter" buys you in the room.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-exercise-embed-95', 'ai101-m3', 95, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-key-takeaways-100', 'ai101-m3', 100, 'takeaways', 'stable', '## Key takeaways

- **The token is the billing unit of everything.** Word count × 1.3, in and out, forever.
  Every plan — subscription, metered, enterprise — is a structure built on that meter, and
  every flat price is a bet someone placed on your volume.
- **The context window is a budget with a quality dimension.** Filling it costs tokens on
  every turn; overfilling it degrades attention in the lossy middle; overflowing it silently
  drops your earliest instructions. Supply what the question needs, not everything you have.
- **The cheap tier is the right call for most People work** — supplied material, clear
  instructions, human review. Pay for the frontier model on evidence, not vibes — and treat
  "this needs the smartest model" as a flag for more review, not just more spend.
- **Every pricing structure has a predictable failure point:** per-seat fails at heavy use and
  idle seats; metered fails at spikes; enterprise fails at mismatch. Price your peak month
  and your idle seats before signing anything.
- **Ask any non-provider vendor which model they run on** and what happens to your price when
  their costs change. Clean answer: real product. Vague answer: you''re buying tokens at
  retail, at a locked-in markup on a falling price.
- **Numbers here are illustrative; the structure is the lesson.** Prices move monthly. The
  napkin math — volume × tokens × rate, plus the human review time — is what transfers.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-activity-link-105', 'ai101-m3', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 Size One Use Case", "blurb": "Take one recurring task from your own function, count its tokens, price it two ways, add the human review line \u2014 and score the gut prediction you made at the top of the module. Graded against a four-dimension rubric with per-dimension feedback. Free unlimited resubmission.", "estMinutes": "20\u201325"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-sources-and-attribution-110', 'ai101-m3', 110, 'prose', 'stable', '## Sources and attribution

This module draws on the following material:

- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with Anthropic,
  CC BY-NC-SA 4.0) — the treatment of tokens and context as practical constraints adapts its
  framing of how model mechanics surface in everyday use.
- Provider pricing and documentation pages — current per-token prices, tier names, context
  window sizes, and plan terms move constantly; verify against the provider''s published
  pricing at time of use. **[V]**
- The three-pricing-structures taxonomy, the failure-point analysis, and the napkin method
  are original to this course, developed for the People-leader procurement context.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-activity-applied-activity-size-one-use-case-10', 'ai101-m3-activity', 10, 'prose', 'stable', '## Applied activity — "Size One Use Case"

**Time:** 20–25 minutes · **Submit:** your estimate table plus a 250–350 word write-up ·
**Graded against the rubric below.** Score doesn''t matter. Doing the work is where the
learning lands.

At the top of this module you picked one recurring task and predicted its monthly cost. Now
do the arithmetic and score yourself.

**Step 1 — Define the unit (5 min).** What is one "run" of this task? (One survey cycle
summarized, one JD drafted, one week''s exit interviews processed.) Describe the input and
output of a single run concretely.

**Step 2 — Count the tokens (5 min).** Estimate the input size (word count × 1.3, include
*everything* the model must see — instructions, documents, examples) and the output size.
Multiply by runs per month. Show the arithmetic; round numbers are fine, reasoning is the
point.

**Step 3 — Price it two ways (5 min).** (a) As metered usage, using a current published
per-token price for a mid-tier model — note which one and the date **[V]**. (b) As a slice of
a per-seat subscription: whose seat, and what share of that seat''s monthly price does this
task plausibly represent? One sentence on which structure fits this task better and why.

**Step 4 — Add the human (3 min).** Estimate the review time per run, in minutes, and note
who does it. This number is usually the real cost. If your task''s review time rivals doing
the task by hand, say so — that''s a finding, not a failure.

**Step 5 — Score the prediction (2 min).** Predicted vs. computed: direction of miss, size
of miss, one-sentence theory of why.

Then the write-up: your table, the comparison, and one decision this estimate would actually
change — a tool you''d adopt or skip, a quote you''d push back on, a task you''d leave manual.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-micro-core', 'ai101-m3-micro', 10, 'prose', 'stable', '## Module 3 in two minutes

**Everything is metered in tokens** — roughly word count × 1.3, priced in and out — and every plan you''ll ever see is a structure built on that meter. A flat "unlimited" price is a bet on your volume, with fine print standing where the meter reasserts itself. The napkin method is the whole skill: volume × tokens × rate, plus the human review time — which is usually the real cost.

**The context window is a budget.** Everything in it is re-sent every turn (long conversations over big documents quietly cost multiples), overfilling it degrades attention in the middle of long material, and overflowing it silently drops your earliest instructions. Supply what the question needs, not everything you have.

**Three pricing structures, three failure points.** Per-seat fails at heavy use and idle seats. Metered fails at the spike you didn''t forecast — survey season arriving as an invoice. Enterprise fails at mismatch, though its premium often buys the data terms that matter more than capability. Price your peak month, not your average one.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-micro-rule', 'ai101-m3-micro', 20, 'callout', 'stable', '### The rule to carry

Start on the cheap tier and escalate on evidence — most People work is supplied-material transformation where tier differences barely show. And if a task seems to need the smartest possible model, treat that as a flag to increase your review, not just your spend.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m3-micro-close', 'ai101-m3-micro', 30, 'prose', 'stable', '**The full module adds** the vendor-quote lesson (including the one question that exposes a thin wrapper: "which model does this run on, and what happens to our price when your costs change?"), the price-the-mismatch exercise, and Size One Use Case — real napkin math on a task from your own week, scored against your gut prediction.', NULL, '2026-08-11', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m3-choice', 'ai101-m3', 'choice', '{"reviewedAt":"2026-08-11","title":"Price the mismatch","intro":"*Five minutes. Commit before you look.*\n\nFour People teams, four pricing structures — each pairing plausible enough that somebody signed it. Three of them are reasonable fits: not perfect, but the kind of deal that works out fine. **One goes badly wrong at scale**, predictably, for structural reasons from Lesson 4.\n\nRead the four pairings. Which one blows up?","artifacts":[{"label":"Pairing A · the TA team","body":"A 6-person talent acquisition team drafts 25–30 job descriptions and offer letters a month, spread evenly across the year. They sign a per-seat subscription: flat monthly price per recruiter, everything included."},{"label":"Pairing B · the survey program","body":"A People-analytics lead runs the engagement survey twice a year — 4,000 free-text comments per cycle, processed over two intense weeks, near-zero AI usage in between. She signs a metered plan priced per token, which was by far the cheapest option in the months she compared."},{"label":"Pairing C · the HRBP group","body":"Twelve HRBPs use an assistant a few times a week each — drafting, summarizing meeting notes, tightening documents. They''re on the org''s enterprise agreement, which bundles admin controls and data-processing terms. Per head, it costs more than a consumer subscription would."},{"label":"Pairing D · the L&D experiment","body":"An L&D manager pilots AI-generated first drafts of course outlines — a handful of documents a month for one quarter. He uses a metered plan and expenses roughly the price of a nice lunch each month."}],"options":[{"id":"a","label":"Pairing A — TA on per-seat"},{"id":"b","label":"Pairing B — surveys on metered"},{"id":"c","label":"Pairing C — HRBPs on enterprise"},{"id":"d","label":"Pairing D — L&D on metered"}],"key":"b","reasoning":"**Pairing B blows up.** Metered pricing fails at spikes, and her usage is *only* spikes: months of near-zero (when metered looked unbeatable in the comparison) punctuated by two weeks of processing 4,000 comments — tens of thousands of tokens per batch, re-supplied across every follow-up pass. The plan looked cheapest precisely because she compared it during the quiet months; survey season arrives as an invoice nobody forecast. The fix isn''t necessarily a different plan — it''s pricing the *peak* month before signing, which is the one month that matters.\n\nThe other three hold. **A** is per-seat''s home ground: steady, modest, predictable usage across a stable team — the vendor''s bet and the team''s reality agree. **C** costs more per head *and that''s the point*: the premium buys the data-processing terms and admin controls, which is the part of the price M8 argues you can''t do without — HRBP work touches exactly the material that needs them. **D** is what metered is for: small, exploratory, honestly temporary — a subscription would be shelf space by month two.\n\nThe pattern to carry into any quote: match the structure to the *shape* of your usage — steady, spiky, or sensitive — and price the edge case, not the average month."}', '2026-08-11');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m3-rubric', 'ai101-m3', 'rubric', '{"promptVersion":"ai101-m3-size-one-use-case-v1","moduleId":"ai101-m3","minWords":250,"maxWords":350,"submitLabel":"Your estimate table and write-up","intro":"Paste your estimate table (any readable format) followed by the 250–350 word write-up. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 101, The Foundation). Module 3 applied activity, ''Size One Use Case'': one recurring task from their own function, sized end to end — the unit of work defined, tokens estimated with visible arithmetic (word count × 1.3, input and output, runs per month), priced two ways (metered at a named current per-token price with date, and as a share of a per-seat subscription), a human review-time line with a named reviewer, and a comparison against the gut prediction made before the module. A numeric prediction may have been captured by the module''s opening calibration prompt; grade the calibration dimension on whether the prediction is stated and honestly compared, never on its accuracy. Order-of-magnitude reasoning with round numbers is the goal; false precision is not.","opening":[{"key":"monthlyCost","label":"Predicted — this task''s monthly cost in dollars","hint":"Gut number, no arithmetic. Whole dollars.","placeholder":"e.g. 150","min":0,"max":100000}],"calibration":[{"key":"monthlyCostActual","label":"Computed — what the arithmetic actually says","hint":"Your step-3 estimate, in whole dollars. The direction of the miss is the lesson.","placeholder":"e.g. 12","min":0,"max":100000,"actualFor":"monthlyCost"}],"dimensions":[{"name":"The unit is real","criteria":"A genuine recurring task from their own function, with one run defined concretely — input and output described specifically enough that someone else could recognize a run. Invented or generic tasks score low."},{"name":"Arithmetic shown","criteria":"Token estimates built from visible reasoning (word counts, the ×1.3 rule, runs per month), input and output both counted, and everything the model must see included — instructions and examples, not just the document. Round numbers with reasoning outscore precise numbers without it."},{"name":"Both pricings, compared","criteria":"Metered pricing uses a named model and a dated price; the per-seat framing names whose seat and a plausible share. One sentence commits to which structure fits this task''s usage shape and why — steady, spiky, or sensitive."},{"name":"The human line and the verdict","criteria":"Review time per run estimated with a named reviewer, and the write-up names one decision this estimate would actually change. An honest ''leave it manual'' or ''the review is the real cost'' verdict outscores an enthusiastic case for automation. Calibration: prediction stated, miss direction named, one-sentence theory offered."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m3-knowledge_check', 'ai101-m3', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-11","questions":[{"id":"q1","prompt":"Why does a long back-and-forth conversation over an attached document cost substantially more than the same questions asked as clean, separate one-shot prompts?","options":["Conversations are billed at a premium rate compared to single prompts","The full context — document included — is re-sent as input tokens on every turn","The model writes longer answers in conversations than in one-shot prompts","It doesn''t — conversation turns after the first are free on most plans"],"correctIndex":1,"explanation":"The window is re-supplied each turn, so the document''s tokens are effectively re-read every time you follow up. That''s the economic half of the fresh-conversation habit; the quality half is attention. A and D describe billing structures that don''t exist, and C isn''t the mechanism."},{"id":"q2","prompt":"A vendor''s plan is \"unlimited AI drafting, $30 per seat per month.\" What is this price, structurally?","options":["Evidence that the vendor has found a way to make tokens genuinely free at scale","A loss-leader that must disappear once the vendor''s investors demand profitability","A bet that average usage stays modest — with fine print (rate limits, fair-use caps) standing where the token meter reasserts itself","Proof the product doesn''t use a large language model, since LLM costs are always metered"],"correctIndex":2,"explanation":"Flat prices don''t remove the meter; they hide it behind a usage prediction. The practical habit: ask what happens at ten times your expected volume — the answer locates the real limit. B might even prove true for a given vendor, but it''s a guess about one company, not the structure of the price."},{"id":"q3","prompt":"Your team runs a 40-page report through an assistant and gets a fluent summary that''s strangely thin on the report''s middle sections. What most likely happened?","options":["The middle sections exceeded the model''s knowledge cutoff","The document filled a large share of the context window, and material in the middle of a long context received the least attention","The model''s safety filters removed the middle content","The subscription''s fair-use cap truncated the output"],"correctIndex":1,"explanation":"Fits is not attends: everything in the window competes for influence, and the middle of a long context is where details stop mattering first — while fluency stays perfect, which is what makes it dangerous. A confuses the cutoff (training time) with the window (right now); C and D aren''t this mechanism."},{"id":"q4","prompt":"For which task is the cheaper model tier most clearly the right choice?","options":["Reformatting your own interview notes into the team''s standard debrief template","Synthesizing an ambiguous ER situation across a year of scattered documentation","Drafting a sensitive org-change announcement where tone missteps carry real cost","Any task involving employee data, since cheaper models are safer with sensitive inputs"],"correctIndex":0,"explanation":"Supplied material, clear instructions, known output shape, human review — the delegation heuristic''s center, where tier differences barely show. B and C are the judgment-heavy profile where the frontier model earns its price — and where the real flag is more review, not just more spend. D confuses the tier question with the data question; model size has nothing to do with data terms."},{"id":"q5","prompt":"A team that runs heavy, predictable daily volume is choosing between per-seat and metered pricing. What''s the structural trade?","options":["Metered pricing is always cheaper at high volume","Per-seat absorbs their heavy steady usage until fine-print caps bite; metered prices it accurately but punishes unforecast spikes","There is no real difference — both bill the same tokens underneath","Per-seat is only available in enterprise agreements"],"correctIndex":1,"explanation":"Each structure fails at its own edge: flat plans at sustained heavy use (that''s what the fine print is for), metered at the surge you didn''t forecast — survey season arriving as an invoice. C is true of the underlying meter but false about who carries the risk, which is the entire question."},{"id":"q6","prompt":"During procurement, which single question most directly exposes whether an \"AI-powered\" product is a thin wrapper around someone else''s model?","options":["\"Is your product SOC 2 compliant?\"","\"How many engineers are on your AI team?\"","\"Which model does this run on, and what happens to our price when your model costs change?\"","\"Does your product use the latest generation of models?\""],"correctIndex":2,"explanation":"A vendor with a real workflow layer answers cleanly; a reseller of tokens at retail gets vague, because their margin is the gap between your locked-in price and a falling cost they don''t control. A matters for M8''s reasons but doesn''t locate thinness; B and D invite theater."},{"id":"q7","prompt":"Why should \"this task seems to need the most capable model available\" prompt a second look rather than just a bigger budget?","options":["Frontier models are usually too slow to be usable for any real work","Tasks that seem to need maximum capability are usually climbing toward judgment calls — where the right response is more human review, not just more model","Capability differences between tiers are pure marketing with no real effect","Cheaper models produce more reliable outputs than frontier models"],"correctIndex":1,"explanation":"The pattern from the lesson: as tasks climb toward organizational judgment, they approach the delegation heuristic''s boundary, where \"which tier\" becomes \"how much human.\" A overstates a real latency trade; C and D are both false."},{"id":"q8","prompt":"In the Size One Use Case activity, why does the estimate require a line for human review time?","options":["Because review time is usually the dominant real cost, and a task whose review rivals doing it by hand may not be worth automating","Because regulators require documented human oversight of all AI usage","To calculate how many tokens the reviewer will consume re-reading the output","To determine which employees need training on the tool"],"correctIndex":0,"explanation":"Token costs are usually the small number; the reviewing human is the big one. An estimate without that line flatters every use case and hides the honest finding — sometimes the verdict is \"leave it manual,\" and the activity treats that as a result, not a failure. B overstates current requirements (M7 covers what actually applies); C and D aren''t what the line is for."}]}', '2026-08-11');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-calibration-prompt-before-you-start-10', 'ai101-m4', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. You''ll score it during the applied activity.*

At the end of this module you''ll take one real document you''d genuinely like AI''s help with —
an ER summary, survey verbatims, interview notes — and produce the version you''d actually
paste, redacting what shouldn''t travel.

**What percentage of the document do you predict survives redaction?** Meaning: after you
remove what shouldn''t be pasted under your current agreement, how much of the original text is
left? Write the number down.

Both directions of miss are instructive. Much survives that people expect to lose — most
redaction is precise, not wholesale. And what''s lost is rarely what they guessed — names are
easy; it''s the office, the role, and the date that carry identity out the door.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-module-brief-20', 'ai101-m4', 20, 'prose', 'stable', '## Module brief

M1 left you with a clean principle: the model has never seen your organization, so quality
depends on the material you supply. This module is about the collision between that principle
and another one: **the material a People leader holds is the most sensitive material in the
building.**

Here''s the collision in one scene. An HRBP has forty pages of exit-interview notes and a
Thursday deadline for a themes summary. The right move *capability-wise* is obvious — M1
taught it: supply the material, ask for transformation. The right move *stewardship-wise* is
not obvious at all: those notes contain names, grievances, a mention of a medical
accommodation, and a quote so distinctive that anyone in the department could identify its
author. Pasting them raw into a personal chat account is a data incident with extra steps.
Refusing to use AI at all hands back the Thursday problem. The skill this module builds is
the middle path: knowing exactly what may travel, making the rest travel-safe, and being able
to defend the call afterward.

Two ideas do most of the work. A **four-tier classification** you can run on any document in
seconds, and a single test that catches what the tiers miss: **could this run be shown to the
person it concerns?** Around them: what actually happens to a long document inside the model
(M3''s budget, now with failure modes), and what real redaction looks like — as opposed to the
theater of deleting names and calling it done.

One promise: nothing here requires a policy your organization hasn''t written yet. This is the
judgment you can exercise *today*, under whatever agreement you currently have — and it''s the
foundation M8 builds the policy skeleton on.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-learning-objectives-30', 'ai101-m4', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain why supplying material beats describing it — and route any real task through
   attach-and-transform rather than describe-and-hope.
2. Predict how a long document degrades in the window — the lossy middle, silent truncation —
   and know the working habits that defend against both.
3. Tier any People-work artifact in under a minute — public / internal / person-identifying /
   protected — and say what each tier permits under your current agreement. **[V]**
4. Apply the shown-to-the-person test to catch what tiering misses.
5. Redact a real document so it actually de-identifies — not just de-names — and say out loud
   what was removed and why.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-lesson-1-supplying-material-beats-descri-40', 'ai101-m4', 40, 'prose', 'stable', '## Lesson 1 · Supplying material beats describing it

Run the same task both ways and the principle teaches itself.

*Describing:* "Summarize our PTO policy for new managers." The model has never seen your PTO
policy. M1 told you what happens next: it generates a fluent summary of *a* PTO policy — a
plausible average of the thousands in its training data. Accrual rates you don''t offer,
carryover rules you don''t have, delivered in confident prose. Nothing about it looks wrong,
and all of it is invented.

*Supplying:* paste the policy, then ask. Now every sentence has source material to draw on,
and — just as important — **you have something to check against.** When the summary says
"unused days lapse in March," you can look at the policy and verify it. Supplied material
doesn''t just improve the output; it converts an unverifiable claim into a checkable one.
That''s the difference M6 will lean on hard.

The habit, stated once and bluntly: **for any task touching your organization''s specifics,
attach the source or expect invention.** The model fills gaps silently — that''s its mechanism,
not a defect — so the only question is whether you filled them first.

And the immediate objection — *"but can I paste this?"* — is the right one. It''s the rest of
this module. The answer is almost never "no, nothing"; it''s "these parts, under these
conditions, in this form." Hold the objection for two lessons and you''ll have the tools to
answer it precisely instead of nervously.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-try-50', 'ai101-m4', 50, 'try_this', 'stable', '### Try this — 2 minutes
Ask your AI tool to summarize a policy your organization actually has — by name, without
attaching it. Read the confident result. Count the invented specifics. You''ve just watched
the gap that every supplied document closes — and you''ll never again wonder whether
attaching the source matters.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-lesson-2-what-happens-to-a-long-document-60', 'ai101-m4', 60, 'prose', 'volatile', '## Lesson 2 · What happens to a long document [V]

M3 called the context window a budget. Here''s what spending it on a big document actually
looks like — and the two failure modes that matter for People work.

**The lossy middle.** Current models advertise windows that hold hundreds of pages **[V]**,
and the marketing is technically true: the pages fit. But *fits is not attends* — every
fragment of output is predicted from everything in view, and the more there is in view, the
more it all competes. Empirically, material at the start and end of a long context holds the
model''s attention best; the middle is where details go quiet. For a 60-page handbook, that
means a summary can be sharp on sections 1–3, sharp on the appendix, and strangely vague
about the grievance procedure buried in the middle — while sounding equally confident
throughout. The tell is *asymmetric thinness*: if a summary''s detail level varies by section
for no editorial reason, suspect the middle, and probe it directly ("what does section 7 say
about escalation timelines?").

**Silent truncation.** A conversation that outgrows the window drops its oldest content
without announcement — including, eventually, the document you attached and the instructions
you opened with. A long working session that starts giving generic answers hasn''t gotten
lazy; it has literally lost sight of your material.

The working habits that defend against both, cheap and boring by design: **ask for what you
need section by section** rather than one heroic full-document request; **put the thing that
matters most at the start or end** of what you supply, never the middle; **start fresh
conversations per task** instead of nursing one endless thread; and **spot-check the middle**
of anything long before you trust its summary. (201 M3 turns these habits into designed
pipelines; here they''re just hygiene.)', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-lesson-3-the-paste-question-answered-70', 'ai101-m4', 70, 'prose', 'volatile', '## Lesson 3 · The paste question, answered [V]

"Can I paste this?" has a real answer, and it isn''t a vibe. It''s a tier and an agreement.

**The four tiers** — run any artifact through them in seconds:

**Tier 1 · Public.** Already published or intended to be: job postings, your careers page,
publicly filed policies. No new exposure — it''s already out there.

**Tier 2 · Internal.** Organizational but not about a person: policy drafts, org design
notes, process docs, aggregate statistics, template language. Sensitive to the *organization*
(confidentiality, competitive), not to an individual.

**Tier 3 · Person-identifying.** About someone, or traceable to someone: interview notes,
performance narratives, survey verbatims, exit interviews, anything with a name — or with the
combination of details that works like a name. This is the tier people mis-sort most, in both
directions.

**Tier 4 · Protected.** The categories with legal weight of their own **[V]**: medical and
accommodation information, protected-class data, active investigation and legal-hold
material, compensation at the individual level. Not "be careful" — *stop*: this tier moves
only inside systems and processes your counsel has explicitly blessed, which a chat window
almost never is.

**What tiers permit depends on the agreement** — the M2 lesson about provisioned tools, now
with teeth. Under a consumer account, the safe assumption **[V]** is that anything pasted
may be retained and possibly used to improve the service: fine for Tier 1, defensible for
sanitized Tier 2, wrong for Tier 3. Under an enterprise agreement with negotiated
data-processing terms **[V]** — no training on your inputs, defined retention — Tier 2 is
ordinary work and Tier 3 becomes possible *in redacted form* (next lesson). Tier 4 stays
stop-and-ask under every agreement, because the constraint isn''t the vendor''s terms — it''s
your own obligations. If you don''t know which agreement covers the tool in front of you,
that''s not a reason to guess; it''s the single most useful question you can ask IT this week,
and M8 gives you the follow-ups.

**And the test that catches what tiering misses: could this run be shown to the person it
concerns?** Imagine the employee in your Tier 3 document reading the transcript — your
prompt, their information, the output. If your reaction is discomfort, the discomfort is
information: something traveled that shouldn''t have, or the task itself is one M7 wants a
harder look at. The test works because it swaps an abstract compliance question for a
concrete loyalty one — *am I handling this person''s information the way I''d defend to their
face?* — and People leaders'' instincts on that question are already well trained.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-try-80', 'ai101-m4', 80, 'try_this', 'stable', '### Try this — 3 minutes
Tier the last five things you (or your team) put into an AI tool — or would have. Fast,
gut-level, honest. Most people find four easy calls and one that makes them stop. The
stopper is the point: write one sentence on *why* it''s hard to place, and you''ve found
either a redaction candidate (Lesson 4) or a question for M7.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-exercise-embed-85', 'ai101-m4', 85, 'exercise', 'stable', '{"type": "sorting", "title": "Calibration exercise \u2014 Tier the artifacts", "intro": "Ten minutes, twelve artifacts from a People leader''s week. Sort each into the tier it belongs to. Commit every card before the reveal \u2014 the pattern in your misses matters more than the count.\n\nAssume nothing has been redacted yet: tier each artifact as it sits."}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-lesson-4-redaction-that-isn-t-theater-90', 'ai101-m4', 90, 'prose', 'stable', '## Lesson 4 · Redaction that isn''t theater

Deleting names and calling a document safe is the most common redaction mistake in People
work, and it fails for a reason worth understanding: **identity lives in combinations, not
names.** "A senior engineer in the Denver office who raised concerns after the March reorg"
contains zero names and identifies one person to everyone who works there. Re-identification
is a *join* — each detail narrows the set of people it could be, and three or four details
in, the set has one member.

Real redaction is three moves, applied with the reader in mind — not a hypothetical stranger,
but the most-informed insider who could plausibly see the output:

**Generalize the quasi-identifiers.** Role, location, tenure, dates, team names — replace
each with the least specific version that still serves the task. "Senior engineer, Denver,
post-reorg" becomes "an experienced employee in a technical function." If the task genuinely
needs the specific — say, you''re analyzing *Denver''s* results — that''s a sign the task wants
a more controlled setting than a chat window, not a sign to leave the detail in.

**Break the joins.** One distinctive detail is a flag; the *combination* is the identifier.
Ask which details, together, shrink the candidate set to one, and cut or blur until the set
is comfortably large. Distinctive phrasing counts: a verbatim quote with an unusual turn of
phrase identifies its author to colleagues as surely as a name — paraphrase it.

**Then run the shown-to-the-person test on what''s left.** If the redacted version would still
make its subject flinch — because the *situation* is identifiable even with every detail
blurred — the document wasn''t over-sensitive; the task was. Some analyses shouldn''t run on a
small population at all, in any tool. Finding that out during redaction is the discipline
working, not failing.

Two habits complete the practice. **Redact before the material enters the tool**, not in the
prompt ("ignore the names" is an instruction to a system that has already received the
names). And **say what you removed** — a one-line note on the redacted version ("names,
office, dates generalized; two quotes paraphrased") turns your judgment into something a
colleague can review and M8 can call accountable. Silent redaction protects the data;
*narrated* redaction protects you.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-key-takeaways-100', 'ai101-m4', 100, 'takeaways', 'stable', '## Key takeaways

- **Attach the source or expect invention.** Describing your organization''s documents
  produces fluent averages of other people''s; supplying them produces checkable output.
  The gap never closes on its own.
- **Long documents degrade predictably:** the lossy middle (fits ≠ attends — probe for
  asymmetric thinness) and silent truncation (long threads drop their oldest material without
  telling you). Section-by-section requests and fresh conversations are cheap insurance.
- **Four tiers, run in seconds:** public / internal / person-identifying / protected. The
  agreement determines what each permits **[V]** — and if you don''t know which agreement
  covers your tool, that''s this week''s most useful question for IT.
- **Tier 4 is stop, not caution** — medical, protected-class, investigation, individual comp.
  The constraint is your obligations, not the vendor''s terms, so no agreement upgrade
  unlocks it.
- **The shown-to-the-person test catches what tiers miss:** could this run — prompt, data,
  output — be shown to the person it concerns? Discomfort is information.
- **Identity lives in combinations, not names.** Real redaction generalizes
  quasi-identifiers, breaks the joins, paraphrases distinctive quotes — before the material
  enters the tool — and narrates what it removed so the judgment is reviewable.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-activity-link-105', 'ai101-m4', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 The Redaction Pass", "blurb": "One real document you''d want AI''s help with: tier it, produce the version you''d actually paste, map what you removed and why \u2014 and score your prediction of how much survives. Graded against a four-dimension rubric with per-dimension feedback. Free unlimited resubmission.", "estMinutes": "20\u201325"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-sources-and-attribution-110', 'ai101-m4', 110, 'prose', 'stable', '## Sources and attribution

This module draws on the following material:

- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with Anthropic,
  CC BY-NC-SA 4.0) — the supply-don''t-describe framing extends its treatment of context as
  the lever on output quality.
- Provider documentation on data handling, retention, and training-use defaults across
  consumer and enterprise tiers — verify against your vendor''s current published terms and
  your own agreement; both move. **[V]**
- The four-tier classification, the shown-to-the-person test, and the three-move redaction
  discipline are original to this course, developed for the People-leader context. The
  re-identification-by-combination principle reflects the long-standing privacy research
  consensus on quasi-identifiers.
- Regulatory treatment of employee data varies by jurisdiction and moves quickly — this
  module teaches judgment, not compliance advice. *Verify specifics with counsel.* **[V]**', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-activity-applied-activity-the-redaction-pass-10', 'ai101-m4-activity', 10, 'prose', 'stable', '## Applied activity — "The Redaction Pass"

**Time:** 20–25 minutes · **Submit:** the before/after redaction map plus a 250–350 word
reflection · **Graded against the rubric below.** Score doesn''t matter. Doing the work is
where the learning lands. **Do not paste the original document into this submission** — the
map describes; it doesn''t reproduce.

Take one real document you''d genuinely like AI''s help with — interview notes, survey
verbatims, an ER summary, exit-interview material. Something Tier 3: honestly sensitive,
honestly useful.

**Step 1 — Tier it (3 min).** Name the document type and its tier. If parts land in
different tiers — a mostly-internal doc with one person-identifying section — map the parts.
Anything Tier 4 inside it: mark it *out of scope for any chat tool* and proceed with the
rest. That marking is itself a graded judgment.

**Step 2 — The redaction pass (10 min).** Produce the version you''d actually paste, using
the three moves: generalize quasi-identifiers, break the joins, paraphrase distinctive
quotes. Work against the most-informed insider, not a stranger.

**Step 3 — The map (5 min).** List what you changed, category by category — not the
sensitive originals, the *categories*: "4 names → roles · 2 offices → ''a regional office'' ·
3 dates → quarters · 1 distinctive quote paraphrased · accommodation mention removed
entirely (Tier 4)." Then the one-line narration you''d attach for a colleague.

**Step 4 — Score the prediction (2 min).** Estimate what percentage of the original
survived. Compare with your opening prediction: direction of the miss, and whether what you
*lost* was what you expected to lose.

Then the reflection: which move did the real work; what the shown-to-the-person test flagged,
if anything; and the sentence you''d now say to a teammate who asks "can I paste exit
interviews?"', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-micro-core', 'ai101-m4-micro', 10, 'prose', 'stable', '## Module 4 in two minutes

**Attach the source or expect invention.** The model has never seen your organization''s documents; describe them and it generates fluent averages of other people''s. Supplying the material improves the output *and* makes it checkable — every claim can now be verified against something you hold.

**The paste question has a real answer: a tier and an agreement.** Public / internal / person-identifying / protected, run in seconds. What the first three permit depends on your tool''s agreement; Tier 4 — medical, protected-class, investigations, individual comp — is *stop* under every agreement, because the obligations attach to the data itself. The test that catches what tiers miss: **could this run be shown to the person it concerns?** Discomfort is information.

**Redaction that isn''t theater:** identity lives in combinations, not names. ''A senior engineer in the Denver office who raised concerns after the reorg'' names nobody and identifies one person. Generalize the quasi-identifiers, break the joins, paraphrase distinctive quotes — before the material enters the tool — and narrate what you removed so the judgment is reviewable.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-micro-rule', 'ai101-m4-micro', 20, 'callout', 'stable', '### The rule to carry

Tier it, redact to the most-informed insider, run the shown-to-the-person test — and when unsure, round the tier up. If the redacted version would still make its subject flinch, the task is the problem, not the document.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m4-micro-close', 'ai101-m4-micro', 30, 'prose', 'stable', '**The full module adds** the long-document failure modes (the lossy middle and silent truncation, with the working habits that defend against both), the twelve-artifact tier sort, and the Redaction Pass — the full discipline run on a real document of yours, scored against your prediction of how much survives.', NULL, '2026-08-11', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m4-sorting', 'ai101-m4', 'sorting', '{"reviewedAt":"2026-08-11","buckets":[{"id":"public","label":"Tier 1 · Public","hint":"Already out there","rank":0,"pct":5},{"id":"internal","label":"Tier 2 · Internal","hint":"Org-sensitive, not person-sensitive","rank":1,"pct":35},{"id":"person","label":"Tier 3 · Person-identifying","hint":"Traceable to someone","rank":2,"pct":70},{"id":"protected","label":"Tier 4 · Protected","hint":"Stop — counsel-blessed systems only","rank":3,"pct":95}],"tasks":[{"id":"t1","text":"The job posting for an open Marketing Manager role, as it appears on your careers page","key":"public","reasoning":"Published and intended to be. Pasting it creates no exposure that hitting the careers page doesn''t."},{"id":"t2","text":"A draft of the new hybrid-work policy, two weeks before announcement","key":"internal","reasoning":"Organizationally sensitive — you wouldn''t want it leaked — but about rules, not people. Classic Tier 2: sanitized org material, defensible under a proper agreement."},{"id":"t3","text":"Interview notes on a named finalist, including your panel''s concerns about their management style","key":"person","reasoning":"Named person plus evaluative judgment — Tier 3''s center. It can travel only in redacted form, and the evaluative content is exactly what redaction has to be most careful with."},{"id":"t4","text":"An employee''s request for a reduced schedule, which mentions their ongoing chemotherapy","key":"protected","reasoning":"Medical information. Not ''redact carefully'' — Tier 4: it moves only inside systems counsel has blessed, under obligations that attach to the data itself. No agreement upgrade changes this."},{"id":"t5","text":"Aggregate engagement scores by division — no division smaller than 150 people","key":"internal","reasoning":"Aggregated past individual traceability, so it''s org data, not person data. The division size is what makes this call — the same scores for a 6-person team would jump a tier."},{"id":"t6","text":"Survey verbatims with names stripped — but one comment complains about ''the only manager in the Portland office''","key":"person","reasoning":"Names stripped is not de-identified: ''the only manager in the Portland office'' is a name wearing a costume. Identity lives in combinations — this is the mis-tier the module most wants you to catch.","also":["protected"]},{"id":"t7","text":"Your team''s standard offer letter template, all merge fields blank","key":"internal","reasoning":"Template language with no person in it. Internal rather than public only because you haven''t published it — the content itself is boilerplate."},{"id":"t8","text":"Notes from an active harassment investigation, witnesses anonymized as ''Witness A'' and ''Witness B''","key":"protected","reasoning":"Active investigation material is Tier 4 regardless of anonymization quality — legal hold and process obligations attach to the matter, not to the names. The anonymization is irrelevant to the tier."},{"id":"t9","text":"A spreadsheet of individual salaries you''re using to check a proposed band structure","key":"protected","reasoning":"Individual-level compensation is Tier 4. The band *structure* — mins, mids, maxes with no individuals — would be Tier 2; the individual rows are what lock the tier."},{"id":"t10","text":"Your published DEI commitment statement from the company''s annual report","key":"public","reasoning":"In the annual report — as public as it gets. That it touches a sensitive *topic* doesn''t change the tier of an already-published document."},{"id":"t11","text":"A performance improvement plan for a named employee, drafted but not yet delivered","key":"person","reasoning":"Named individual plus evaluative judgment with real consequences. Tier 3 at minimum — and if it intersects an accommodation or investigation, it climbs. Drafting help is possible; it requires the module''s full redaction discipline.","also":["protected"]},{"id":"t12","text":"Process documentation for how your team runs quarterly promotion calibrations","key":"internal","reasoning":"How the process works, with nobody in it — Tier 2. The moment a real calibration''s *contents* enter (names, ratings, decisions), you''re in Tier 3–4 territory; the process doc itself is org material."}],"pattern":"Identity lives in combinations, and obligations attach to data — the two ideas that decide every hard card.","postscript":"The easy cards sort themselves by asking ''is a person in it?'' The hard ones — the Portland comment, the anonymized investigation, the salary spreadsheet — are hard because they hide the second question: what obligations already attach to this material, whatever you strip from it? Placed too low is the miss that costs you (exposure); placed too high mostly costs convenience — which is why, when unsure, you round up. The applied activity now runs this judgment on a document of yours that actually matters."}', '2026-08-11');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m4-rubric', 'ai101-m4', 'rubric', '{"promptVersion":"ai101-m4-redaction-pass-v1","moduleId":"ai101-m4","minWords":250,"maxWords":350,"submitLabel":"Your redaction map and reflection","intro":"Submit the before/after map — categories of what changed, never the sensitive originals — plus the 250–350 word reflection. Do not paste the original document. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 101, The Foundation). Module 4 applied activity, ''The Redaction Pass'': one real Tier-3 document from their own work, tiered (with any Tier-4 content marked out of scope), redacted using the three moves (generalize quasi-identifiers, break re-identifying combinations, paraphrase distinctive quotes), mapped by category of change with a one-line narration, and scored against their opening prediction of what percentage survives. IMPORTANT: the submission should describe changes by category, not reproduce sensitive originals — a submission that pastes identifiable source material has missed the module''s point, and the feedback must say so plainly (grade what''s there, but flag it as the primary issue). A numeric prediction may have been captured by the module''s opening calibration prompt; grade the calibration dimension on whether the prediction is stated and honestly compared, never on its accuracy.","opening":[{"key":"survives","label":"Predicted — % of the document that survives redaction","hint":"After removing what shouldn''t travel, how much of the original text is left?","placeholder":"e.g. 60","min":0,"max":100}],"calibration":[{"key":"survivesActual","label":"Measured — % that actually survived","hint":"Rough word-count ratio is fine. Was what you lost what you expected to lose?","placeholder":"e.g. 85","min":0,"max":100,"actualFor":"survives"}],"dimensions":[{"name":"Tiering judgment","criteria":"The document is real, its tier named with reasoning, mixed-tier parts mapped separately, and any Tier-4 content explicitly marked out of scope rather than redacted-and-included. A defended borderline call outscores an easy document."},{"name":"The three moves, actually applied","criteria":"Quasi-identifiers generalized (role, location, dates, tenure — not just names), at least one re-identifying combination found and broken, distinctive quotes paraphrased. Working against the most-informed insider, not a stranger. Name-deletion-only is the failure mode this dimension exists to catch."},{"name":"The map narrates","criteria":"Changes listed by category with counts, no sensitive originals reproduced, and a one-line narration a colleague could review the judgment from. Silent or vague redaction (''cleaned it up'') scores low."},{"name":"The test and the calibration","criteria":"The shown-to-the-person test is run on the result and its verdict stated honestly — including ''the task itself is the problem'' if that''s where it landed. Prediction compared, miss direction named, and whether what was lost matched what they expected to lose."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m4-knowledge_check', 'ai101-m4', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-11","questions":[{"id":"q1","prompt":"Asked to \"summarize our parental leave policy\" with no document attached, the model produces a confident, detailed summary. What is that summary?","options":["A retrieval of your policy from the model''s training data, current as of the cutoff","A plausible average of the many parental leave policies in the training data — invented specifics, fluent delivery","A refusal in disguise — models won''t summarize documents they haven''t seen","A summary of the most common policy among companies your size"],"correctIndex":1,"explanation":"The model has never seen your policy (M1), so it generates *a* policy-shaped answer from patterns — accrual rules you don''t have, delivered confidently. It won''t decline (C); it fills the gap silently. A and D describe retrieval systems, which this isn''t."},{"id":"q2","prompt":"Beyond better output, what does supplying the source document change about the *checkability* of the result?","options":["Nothing — output quality and checkability are the same property","Supplied documents make the model cite its sources automatically","Every claim in the output can now be verified against material you hold — invention becomes catchable","Checkability only improves under an enterprise agreement"],"correctIndex":2,"explanation":"With the source in hand, \"unused days lapse in March\" is a checkable claim instead of a plausible one — the conversion M6''s verification habits depend on. B overstates what attachment does **[V]**; D confuses the data question with the quality question."},{"id":"q3","prompt":"A summary of your 60-page handbook is detailed on early sections, detailed on the appendix, and oddly vague about the grievance procedure in the middle — all in equally confident prose. What''s the most likely cause?","options":["The grievance procedure was written after the model''s knowledge cutoff","Attention degrades for material in the middle of a very long context — it fit, but it didn''t attend","The model''s safety filters suppressed the grievance content","The handbook exceeded the window, so the middle was dropped entirely"],"correctIndex":1,"explanation":"Asymmetric thinness with uniform confidence is the lossy middle''s signature. D is a real failure mode but truncation drops the *oldest* material in an overgrown conversation, not the middle of one attachment; A confuses cutoff with context; C isn''t this."},{"id":"q4","prompt":"Which artifact is most likely to be *mis*-tiered as safely internal when it''s actually person-identifying?","options":["The published careers-page description of your hybrid work policy","A template offer letter with all fields blank","Aggregate survey scores by 200-person division","Survey verbatims with names stripped but role, office, and a distinctive complaint intact"],"correctIndex":3,"explanation":"Identity lives in combinations: role + office + recognizable grievance identifies the author to any informed insider, names or no names. A is public, B is internal template language, C is aggregated past the point of individual traceability — the classic safe versions of each tier."},{"id":"q5","prompt":"What makes Tier 4 (medical, protected-class, investigation, individual comp) different in kind from Tier 3 — not just more sensitive?","options":["Tier 4 documents are longer and exceed context windows","The constraint comes from your own legal obligations, so no vendor agreement upgrade unlocks a chat window for it","Tier 4 material confuses models and produces lower-quality output","Nothing — Tier 4 is Tier 3 with more thorough redaction required"],"correctIndex":1,"explanation":"Tiers 1–3 are governed by what your tool''s agreement permits **[V]**; Tier 4 is governed by obligations that attach to the data itself — which is why the answer stays \"stop and ask\" under every agreement, and why it moves only in systems counsel has explicitly blessed. D is the tempting wrong answer: redaction quality isn''t the issue."},{"id":"q6","prompt":"The point of the shown-to-the-person test — could this run be shown to the person it concerns? — is that it:","options":["Replaces the tier system with a single easier question","Converts an abstract compliance question into a concrete one your existing instincts can actually answer — and catches tasks the tiers technically permit","Is a legal requirement under current privacy regulation","Confirms the model handled the data securely on the vendor''s side"],"correctIndex":1,"explanation":"It complements the tiers rather than replacing them (A): a properly redacted run can still fail it when the *task* is the problem — surfacing exactly the cases M7 wants. C overstates its status **[V]**; D tests something no prompt-side judgment can see."},{"id":"q7","prompt":"Why does \"ignore the names and any identifying details\" *in the prompt* fail as redaction?","options":["Models can''t follow negative instructions of any kind","The instruction consumes context budget better spent on the task","The identifying material has already entered the tool — retention and exposure happened at paste time, whatever the output ignores","It doesn''t fail — prompt-level redaction is equivalent to editing the document first"],"correctIndex":2,"explanation":"Redaction is about what *enters* the system, not what the output mentions. An instruction to ignore data is received by a system that now holds the data. Redact before the material goes in — that''s why it''s a document-editing pass, not a prompting technique."},{"id":"q8","prompt":"Your redacted ER summary — every name, office, and date generalized — would still make its subject flinch, because anyone close to the situation would recognize it. What does the discipline say?","options":["The redaction failed on technique — generalize harder until the flinch goes away","Flinching isn''t the test; if the tiers and agreement permit it, proceed","Ship it but add a note disclosing that redaction was performed","The task, not the document, is the problem — some analyses shouldn''t run on a small population in any tool, and finding that out now is the discipline working"],"correctIndex":3,"explanation":"When the situation itself is identifiable at any blur level, no technique fixes it — the shown-to-the-person test has caught a task that needs a more controlled setting or shouldn''t run at all (M7''s territory). A mistakes a task problem for a technique problem; B inverts the test''s whole purpose; C narrates a decision that shouldn''t ship."}]}', '2026-08-11');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-calibration-prompt-before-you-start-10', 'ai101-m5', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. You''ll score it during the applied activity.*

At the end of this module you''ll run the same real task twice: once with the kind of one-line
prompt most people type, once with a proper brief. You''ll compare the outputs side by side.

**How much better do you expect the briefed version to be, on a 1–10 scale?** Where 1 means
"barely different" and 10 means "unrecognizably better — the thin version was unusable."
Write your number down.

People who''ve never briefed properly tend to guess 3 or 4 — the tool already seems pretty
good, how much better could it get? The gap surprises in a specific way: it''s not that the
briefed output is more polished. It''s that it''s *yours* — the thin prompt''s output could have
been written for any company on earth.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-module-brief-20', 'ai101-m5', 20, 'prose', 'stable', '## Module brief

You know from M1 why the model needs material: it has never seen your organization, and what
you don''t supply, it invents. M4 taught you to supply documents safely. This module is about
the other half of what the model needs — and it starts with the mental model that quietly
ruins most people''s results.

Most people prompt like they search. Short query, sparse context, hit enter, judge the
result: *"write interview questions for a program manager role."* Against a search engine,
that works — the query just has to *match* something that exists. Against a model that
*generates*, it fails in a specific way: every detail you didn''t specify gets filled from the
statistical average of everything the model has seen. Level, competencies, your interview
philosophy, what good answers sound like — all averaged. The output isn''t wrong. It''s
*generic*, which for your purposes is the same thing wearing better clothes.

The fix is a different mental model: **prompting is briefing a capable stranger.** Specifically:
a talented contractor on their first day — sharp, widely read, infinitely willing, and
knowing absolutely nothing about your organization, your standards, or what happened in the
meeting before this one. You already know how to brief such a person; you''ve onboarded
dozens. You''d never say "write interview questions" and walk away. You''d say who''s hiring,
for what, what matters, what to avoid, what the output should look like — and you''d expect
their second draft to beat their first, because your feedback is part of the process.

That''s the whole module. Four parts of a brief, the iteration habit that turns an okay first
draft into your draft, and the single strongest lever — examples — plus where to get them
without violating M4. None of it is technique for its own sake: every piece maps to
something the mechanism in M1 predicts.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-learning-objectives-30', 'ai101-m5', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain why "briefing a capable stranger" produces good prompts where "typing a search
   query" produces generic ones — in M1''s vocabulary, not as folklore.
2. Build a brief from the four parts — role, task, context, format — and say what each part
   buys you mechanically.
3. Treat the first output as a draft of the *brief*: diagnose what''s off, and steer with the
   four moves that reliably work.
4. Use examples as the strongest single lever, sourced from your own work without violating
   M4''s tiers.
5. Recognize when a brief has hit diminishing returns — and when the task itself was the
   wrong delegation (M1''s heuristic, closing the loop).', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-lesson-1-briefing-a-capable-stranger-40', 'ai101-m5', 40, 'prose', 'stable', '## Lesson 1 · Briefing a capable stranger

Watch the two mental models produce two different prompts for the same Monday task.

*The search query:* "write a job description for a senior data analyst."

*The brief:* "You''re helping a People team at a 400-person healthcare company write a job
description. The role: senior data analyst on the People Analytics team, reporting to me —
first dedicated analytics hire, so they''ll build the function, not inherit it. We compete
for talent against tech companies but can''t match their comp; we win on mission and scope.
Tone: direct and warm, no corporate filler — here are two recent postings of ours that got
the tone right [attached]. Draft the posting: 400–500 words, structured as hook, role,
must-haves (keep to five), nice-to-haves, comp range $95–115k."

Read what the second prompt is doing through M1''s mechanism. Every sentence *pins* something
that would otherwise float to the statistical average: the company size and industry pin the
register; "first hire, builds the function" pins the seniority framing; "can''t match tech
comp, win on mission" pins the persuasion strategy; the attached postings pin the voice; the
structure list pins the shape. The model generates one fragment at a time from everything in
view — so everything you put in view is a constraint on what gets generated, and everything
you leave out is a dimension where you''ve delegated the choice to the training data''s
average. A brief isn''t politeness. It''s *narrowing the prediction*.

One reframe makes the discipline stick: **the brief is where your expertise enters the
system.** People worry AI will make their skills irrelevant; the mechanism says the opposite.
Two people with the same tool and the same task get wildly different results, and the
difference is exactly the judgment in their briefs — knowing that the comp positioning
matters, that five must-haves is the ceiling before candidates self-deselect, that your org''s
voice is direct-and-warm. The tool amplifies the expertise you articulate. It can''t amplify
what you didn''t say.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-try-50', 'ai101-m5', 50, 'try_this', 'stable', '### Try this — 2 minutes
Take the last prompt you actually typed into an AI tool. Rewrite the *first sentence* as
you''d open a briefing to a first-day contractor: who you are, what this is for. Just that
one sentence. Notice how much it already pins.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-lesson-2-the-four-parts-60', 'ai101-m5', 60, 'prose', 'stable', '## Lesson 2 · The four parts

A workable brief has four parts. You won''t always need all four at full strength — but when
an output disappoints, one of these is almost always the missing part, and knowing which is
the diagnostic skill.

**Role.** Who the model should be, and who it''s working for: "You''re an experienced HR
communications writer helping a People team at a manufacturing company." Role pins register,
vocabulary, and level of assumed knowledge — the difference between output aimed at HR
professionals and output aimed at everyone.

**Task.** The verb and the deliverable, sharply: not "help me with our engagement survey"
but "draft the five open-ended questions for the manager-effectiveness section." One task
per ask — M1''s tug-of-war applies: pile four jobs into one prompt and the middle jobs get
half attention. (When work genuinely has multiple stages, run them as stages — 201 M3 makes
a discipline of it.)

**Context.** The part People leaders skip most, because it''s the part that feels obvious *to
you* — and nothing is obvious to a system that has never seen your organization. What''s the
situation, who''s the audience, what constraints bind, what happened already, what does
success look like? Context is also where M4''s material goes: the attached policy, the
redacted examples, the survey verbatims. Rule of thumb: if a first-day contractor would need
to know it, it goes in the brief. If they''d need to know it and you *can''t* share it (Tier
3–4 unredacted), that''s not a prompting problem — handle it with M4''s discipline before it
enters the window.

**Format.** What the output should literally look like: length, structure, headings, table
or prose, tone reference. Format is the cheapest quality win available — "500 words, three
sections, plain language, no bullet-point walls" costs you ten seconds and saves an entire
revision round, because format is otherwise decided by the training data''s average, and the
training data''s average loves bullet-point walls.

Two calibration notes. First, scale the brief to the stakes: a two-line prompt is *correct*
for "make this email friendlier" — the four parts are a diagnostic checklist, not a form to
fill. Second, when you find yourself re-typing the same role and context every morning,
you''ve discovered the tax that 201 M2 eliminates with a briefing library. Feel the tax for
now; it''s motivation.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-lesson-3-iteration-is-the-skill-70', 'ai101-m5', 70, 'prose', 'stable', '## Lesson 3 · Iteration is the skill

Here is the sentence that separates fluent users from frustrated ones: **the first output is
a draft of the brief, not the work.** When it disappoints, the frustrated user concludes the
tool is overhyped and quits; the fluent user reads the output *as information about what the
brief failed to pin* and steers. Fluent users iterate two or three times as a matter of
course. It''s not remedial. It *is* the workflow.

Four steering moves cover most situations:

**Name what''s wrong, specifically.** "Make it better" re-rolls the dice. "The tone is too
formal for our culture, and must-have #3 would exclude the internal candidates we want" —
that''s new constraint, and the mechanism gives you a visibly different next draft. If you
can''t name what''s wrong, that''s your signal the *task* was under-specified: what would good
look like? Answer that, then say it.

**Supply what''s missing.** When output goes generic in a specific area, that area needed
material: attach the document, paste the (M4-safe) example, state the fact it invented.

**Constrain the format.** Structure drifting, length ballooning, bullet-walls returning —
re-pin: "keep to 400 words, prose, no bullets."

**Ask for variants.** When you can''t articulate what''s off: "give me three versions —
formal, direct, warm." Recognition is easier than specification; picking beats describing,
and the one you pick becomes an example (next lesson) for everything after.

Two boundaries keep iteration honest. **Know when to stop:** each round should produce a
visibly better draft; two rounds of sideways movement mean stop steering and start editing —
you''re the senior editor, and the last 10% is usually your judgment, which was never
delegable. And **know when it was the wrong delegation:** if iteration keeps failing on the
same dimension — the output can''t get *your org* right no matter what you say — check the
task against M1''s heuristic. Needs organizational knowledge you can''t supply (Tier 4, or
tacit)? Judgment call about a person? No amount of briefing fixes a delegation error.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-try-80', 'ai101-m5', 80, 'try_this', 'stable', '### Try this — 3 minutes
Find a disappointing AI output from your recent history (everyone has one). Diagnose it
against the four parts: which was missing? Write the one steering message you''d send now —
name what''s wrong, supply what''s missing, or re-pin the format. If you can''t write it,
notice why: was it the brief, or was it the delegation?', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-lesson-4-examples-the-strongest-lever-90', 'ai101-m5', 90, 'prose', 'stable', '## Lesson 4 · Examples — the strongest lever

Everything in Lessons 1–3 describes what you want. An example *shows* it — and for reasons
straight out of M1, showing beats describing every time. Describing your tone ("direct and
warm, professional but not stiff") makes the model interpret adjectives, and adjectives are
generic — a thousand companies'' "direct and warm" averaged together. Attaching two
announcements that *sound like you* makes the model continue a demonstrated pattern.
Patterns pin what adjectives wave at: sentence length, greeting conventions, how much warmth,
where the caveats go, what never gets said.

The practice is almost embarrassingly simple: **one or two good examples of the output you
want, attached to the brief.** "Draft the promotion announcement — here are two past ones
that got it right" outperforms three paragraphs of tone description, every time, and takes
less effort to assemble. Three refinements make it work harder:

**Curate for the property you want copied.** The example teaches everything it contains —
structure, length, tone, *and* flaws. Pick examples excellent in the dimension that matters,
and say which dimension: "match the tone of these, not the length."

**Show the transformation, not just the destination.** For recurring conversions — messy
notes → structured debrief — one before/after pair teaches the mapping better than any
instruction list. This is the seed of the reusable workflow 201 builds.

**Source them M4-safely.** Examples are supplied material; the tiers apply. Template
language and published docs: clean. A past PIP as a format example: Tier 3 — redact it with
Lesson 4''s discipline (the *format* is what you want copied; the person in it is exactly
what shouldn''t travel). Building a small library of sanitized, excellent examples — your
best JD, announcement, debrief, scrubbed once and reused forever — is 201 M2''s briefing
library arriving early. Start the folder this week.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-exercise-embed-95', 'ai101-m5', 95, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-key-takeaways-100', 'ai101-m5', 100, 'takeaways', 'stable', '## Key takeaways

- **Brief a capable stranger; don''t type a search query.** A talented first-day contractor:
  infinitely willing, completely ignorant of your organization. You already know how to
  brief that person.
- **Every unpinned detail floats to the training data''s average.** A brief works by
  narrowing prediction — role pins register, task pins the deliverable, context pins your
  reality, format pins the shape. The part People leaders skip is context, because it''s
  obvious — to them.
- **The brief is where your expertise enters the system.** Same tool, same task, different
  results — the difference is the judgment articulated in the brief. The tool amplifies
  what you say, not what you know.
- **The first output is a draft of the brief.** Steer: name what''s wrong, supply what''s
  missing, constrain the format, ask for variants. Two sideways rounds → stop steering,
  start editing.
- **Examples beat descriptions.** One or two curated, M4-safe examples pin what adjectives
  can''t. Say which property to copy. Start the sanitized-examples folder now — 201 turns it
  into a library.
- **Some failures are delegation errors, not briefing errors.** If iteration keeps missing
  on organizational knowledge you can''t supply — or the task judges a person — no brief
  fixes it. That''s the heuristic, still in charge.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-activity-link-105', 'ai101-m5', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 Brief It Twice", "blurb": "One real task, run twice: the thin one-liner most people type, then the full four-part brief with one steering round \u2014 outputs compared side by side against the improvement you predicted. Graded against a four-dimension rubric with per-dimension feedback. Free unlimited resubmission.", "estMinutes": "20\u201325"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-sources-and-attribution-110', 'ai101-m5', 110, 'prose', 'stable', '## Sources and attribution

This module draws on the following material:

- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with Anthropic,
  CC BY-NC-SA 4.0) — the briefing-over-querying stance and the treatment of iteration as
  core practice adapt its "Delegation" and "Description" competencies for the People-leader
  context.
- **Anthropic''s published prompting guidance** — the role/task/context/format decomposition
  is consistent with provider best-practice documentation, which evolves; check current
  guidance for tool-specific features. **[V]**
- The capable-stranger framing, the four steering moves, and the M4-safe example-sourcing
  discipline are original to this course.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-activity-applied-activity-brief-it-twice-10', 'ai101-m5-activity', 10, 'prose', 'stable', '## Applied activity — "Brief It Twice"

**Time:** 20–25 minutes · **Submit:** both prompts, both outputs (or faithful excerpts),
and a 250–350 word comparison · **Graded against the rubric below.** Score doesn''t matter.
Doing the work is where the learning lands.

Pick one real writing or transformation task from your actual week — a JD, an announcement,
turning notes into a debrief, a policy summary for managers. M4 rules apply: redact anything
Tier 3 before it enters the window.

**Step 1 — The thin version (3 min).** Prompt the task the way most people would: one or two
lines, no context. Save the output. Don''t soften the thinness to make the comparison kinder —
the honest baseline is the experiment.

**Step 2 — The brief (10 min).** Fresh conversation **[V]**. Build the full four-part brief:
role, task, context (including at least one attached or pasted piece of M4-safe material —
an example counts), format. Save the output.

**Step 3 — One steering round (5 min).** Whatever the briefed draft got most wrong, steer it
with one of the four moves. Save the result. (If it got nothing wrong, say so — and steer
for a variant anyway to see what moves.)

**Step 4 — Score the prediction (2 min).** Side by side: thin vs. final. Your 1–10
improvement score, versus what you predicted at the top of the module. Direction of miss,
one-sentence theory.

Then the comparison: which of the four parts did the most work (point to specific
differences in the outputs), what the steering round changed, and the one-sentence briefing
rule you''re taking into next week.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-micro-core', 'ai101-m5-micro', 10, 'prose', 'stable', '## Module 5 in two minutes

**Prompting is briefing a capable stranger** — a talented contractor on their first day: sharp, willing, and knowing nothing about your organization. Most people prompt like they search, and every detail a search-style prompt leaves unspecified gets filled from the training data''s average. That''s why thin prompts produce generic output: not wrong, just *anyone''s*.

**Four parts pin the prediction.** Role (register), task (one deliverable, sharply), context (your reality — the part everyone skips because it''s obvious *to them*), format (the cheapest quality win there is). Scale to stakes: two lines is correct for small asks.

**The first output is a draft of the brief, not the work.** Steer: name what''s wrong specifically, supply what''s missing, constrain the format, or ask for variants. Two sideways rounds means stop steering and start editing. And **examples beat descriptions** — one or two curated, M4-safe examples pin what adjectives can''t. The brief is where your expertise enters the system; the tool amplifies what you articulate, not what you know.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-micro-rule', 'ai101-m5-micro', 20, 'callout', 'stable', '### The rule to carry

Before hitting enter, ask: what would a first-day contractor still have to invent from this? Everything on that list either goes in the brief, gets an example — or, if it can''t travel (M4) or judges a person (M1), stays yours.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m5-micro-close', 'ai101-m5-micro', 30, 'prose', 'stable', '**The full module adds** the four-briefs exercise (spot the one that gets a usable first draft — and why role inflation feels like briefing but isn''t), the four steering moves in detail, M4-safe example sourcing, and Brief It Twice — the same real task run thin and briefed, scored against your prediction of the gap.', NULL, '2026-08-11', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m5-choice', 'ai101-m5', 'choice', '{"reviewedAt":"2026-08-11","title":"Four briefs, one task","intro":"*Five minutes. Commit before you look.*\n\nFour HRBPs at the same company need the same thing: an announcement to a 60-person department that its longtime director is leaving and an interim structure starts Monday. Below are their four actual prompts.\n\nOne of these briefs will produce a usable first draft — something its author would only need to edit lightly. The others each leave a load-bearing decision to the training data''s average. **Which brief gets a usable first draft?**","artifacts":[{"label":"Brief A","body":"\"Write an announcement that our director is leaving and we''ll have an interim structure. Make it professional but warm, and not too long.\""},{"label":"Brief B","body":"\"You''re helping an HR team write a sensitive internal announcement. Context: a 60-person product department; the director is leaving on good terms after 9 years; interim structure starts Monday (two team leads splitting coverage, org chart attached); people will worry about layoffs — there are none planned, and we can say so plainly. Audience: the department, some of whom are close to the director. Draft the announcement: 250–300 words, direct subject line, no corporate euphemisms — here''s last year''s VP transition note, which struck the right tone [attached].\""},{"label":"Brief C","body":"\"You are a world-class executive communications specialist with 20 years of experience in Fortune 500 change management, known for empathy, clarity, and strategic insight. Using best practices in organizational communication and change psychology, craft a compelling, emotionally intelligent announcement about a leadership transition. Structure it perfectly and make every word count.\""},{"label":"Brief D","body":"\"Draft a leaving announcement for our director. Important: get the tone exactly right for our culture, address the concerns people will actually have, and make sure the details about the transition are accurate. Don''t be generic about it.\""}],"options":[{"id":"a","label":"Brief A"},{"id":"b","label":"Brief B"},{"id":"c","label":"Brief C"},{"id":"d","label":"Brief D"}],"key":"b","reasoning":"**Brief B gets the usable draft.** Map it to the four parts: role (light but present), task (the announcement, one deliverable, with length), context (department size, good terms, the interim plan *attached*, the layoff worry named — with permission to address it plainly), format (250–300 words, direct subject line, no euphemisms, and a tone *example* attached). Every load-bearing decision is pinned. Note what it isn''t: it isn''t long-winded — it''s about eighty words plus two attachments. Briefing weight is specificity, not volume.\n\nThe others each fail one diagnostic. **A** is the search query: ''professional but warm, not too long'' leaves the actual decisions — is there a layoff fear? what''s the interim plan? — to the average, which will produce a lovely announcement for a fictional company. **C** is the seductive one: an elaborate *role* and zero *context* — the model is now a world-class specialist who has never heard of your department, your director, or Monday. Role inflation is the most common way people feel like they''re briefing without briefing. **D** *names* the right concerns — tone, real worries, accurate details — but supplies none of them: ''get the tone right'' without an example, ''accurate details'' without the details. Instructions to not be generic are not information; they''re hope.\n\nThe pattern: a brief works by what it *pins*, and you can audit any prompt — including C and D''s polished-sounding ones — by asking what a capable stranger would still have to invent."}', '2026-08-11');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m5-rubric', 'ai101-m5', 'rubric', '{"promptVersion":"ai101-m5-brief-it-twice-v1","moduleId":"ai101-m5","minWords":250,"maxWords":350,"submitLabel":"Both prompts, both outputs, and your comparison","intro":"Paste the thin prompt, the full brief, the outputs (or faithful excerpts), the steering round, and the 250–350 word comparison. M4 rules apply to anything you include. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 101, The Foundation). Module 5 applied activity, ''Brief It Twice'': one real task from their week run twice — a deliberately thin one-line prompt, then a full four-part brief (role, task, context with at least one piece of attached or pasted M4-safe material, format) in a fresh conversation, plus one steering round using a named move, and a side-by-side comparison scored against the 1–10 improvement they predicted before the module. A numeric prediction may have been captured by the module''s opening calibration prompt; grade the calibration dimension on whether the prediction is stated and honestly compared, never on its accuracy. If included material appears unredacted and person-identifying, flag it plainly in feedback as an M4 violation.","opening":[{"key":"improvement","label":"Predicted — improvement of briefed over thin, 1–10","hint":"1 = barely different · 10 = the thin version was unusable by comparison.","placeholder":"e.g. 4","min":1,"max":10}],"calibration":[{"key":"improvementActual","label":"Observed — the improvement you actually saw, 1–10","hint":"Judged side by side. The direction of the miss is the lesson.","placeholder":"e.g. 8","min":1,"max":10,"actualFor":"improvement"}],"dimensions":[{"name":"The experiment is honest","criteria":"A real task from their actual week; the thin prompt genuinely thin (not sandbagged with hidden context, not strawmanned into gibberish); the brief built in a fresh conversation; both outputs shown or faithfully excerpted."},{"name":"The brief has all four parts","criteria":"Role, task, context, and format each present and doing work — with at least one piece of supplied material (an example counts), sourced M4-safely. Specificity over volume: a tight brief that pins the load-bearing decisions outscores a long one that describes them."},{"name":"The steering round","criteria":"One named move (name what''s wrong / supply what''s missing / constrain format / ask for variants) applied to the briefed draft''s actual weakest point, with the result shown and its effect described. ''It was already perfect'' is acceptable only with the variant-steer run as instructed."},{"name":"The comparison sees the mechanism","criteria":"Points to specific differences in the outputs and attributes them to specific parts of the brief — not just ''the second was better.'' Prediction stated, miss direction named, one-sentence theory, and a briefing rule concrete enough to use next week. ''Add more context'' scores low; ''attach a tone example for anything going to the whole department'' scores high."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m5-knowledge_check', 'ai101-m5', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-11","questions":[{"id":"q1","prompt":"Why does \"write interview questions for a program manager role\" produce generic output, mechanically?","options":["The model can''t access current examples of interview questions","Every unspecified detail — level, competencies, philosophy — is filled from the statistical average of the training data","The prompt is too short for the model to process reliably","Interview design requires reasoning that models can''t perform"],"correctIndex":1,"explanation":"The model generates from everything in view; what''s not in view gets the average. The output isn''t wrong — it''s *anyone''s*, which is the failure. A, C, and D mislocate the problem: it''s not access, length, or capability. It''s an unpinned prediction."},{"id":"q2","prompt":"The \"capable stranger\" of the mental model is a talented contractor who is:","options":["Sharp and widely read, but knows nothing about your organization, standards, or prior conversations","Experienced at your company but unfamiliar with AI tools","Skilled but unreliable, requiring you to verify every claim","Knowledgeable about your industry but weak at writing"],"correctIndex":0,"explanation":"Capability without organizational knowledge — exactly M1''s model. You''d never hand that person a one-line request and walk away; the whole discipline follows from taking the mental model seriously. C is true of models (M6''s subject) but it''s not what *this* frame is teaching."},{"id":"q3","prompt":"Of the four parts, which do People leaders most commonly under-supply, and why?","options":["Role — it feels presumptuous to assign the model a persona","Task — deliverables are hard to define in People work","Context — because it''s obvious to them, and nothing is obvious to a system that has never seen their organization","Format — output structure can''t be controlled reliably"],"correctIndex":2,"explanation":"The curse of knowledge: the situation, audience, and constraints feel too obvious to state. The stranger test breaks the curse — if a first-day contractor would need it, it goes in the brief. D is exactly backwards: format is the cheapest control you have."},{"id":"q4","prompt":"A briefed draft comes back with the wrong tone and one requirement that would exclude internal candidates. What''s the fluent move?","options":["Start over with a longer brief in a fresh conversation","Accept it — first drafts reflect the model''s actual capability ceiling","Reply \"make it better\" and regenerate until it improves","Name both problems specifically — the tone gap and the excluding requirement — as new constraints"],"correctIndex":3,"explanation":"Specific critique is new information that narrows the next generation; that''s steering. \"Make it better\" (C) re-rolls the dice with no new constraint. A wastes a mostly-good draft; B mistakes an unpinned brief for a capability ceiling — the core frustrated-user error."},{"id":"q5","prompt":"Iteration has gone two rounds and the draft is moving sideways, not improving. The discipline says:","options":["Keep iterating — quality is a function of round count","Stop steering and start editing — the last stretch is your judgment, which was never delegable","Switch to a more capable model tier and re-run the brief","The task was mis-delegated and should not have used AI"],"correctIndex":1,"explanation":"Each round should visibly improve the draft; sideways movement means the remaining gap is editorial judgment — yours. C is M3''s escalate-on-evidence, but \"sideways\" isn''t capability evidence. D is the right call only when iteration keeps failing on the *same organizational-knowledge dimension* — a different signature than diminishing returns."},{"id":"q6","prompt":"Why does attaching two past announcements outperform three paragraphs describing your company''s tone?","options":["Attachments are weighted more heavily than prompt text","Adjectives get interpreted as the average of everyone''s \"direct and warm\"; a demonstrated pattern pins sentence length, warmth, and structure directly","It doesn''t — precise description and examples perform identically","Examples save typing but produce the same output quality"],"correctIndex":1,"explanation":"Describing makes the model interpret generic words; showing gives it a pattern to continue — M1''s mechanism again. The refinements matter because the example teaches *everything* it contains: curate for the property you want, and say which. A invents a weighting rule; C and D deny the lever this lesson exists to hand you."},{"id":"q7","prompt":"You want to use a past PIP as a format example for drafting a new one. The M4-safe move is:","options":["Attach it as-is — format examples aren''t really \"using\" the content","Don''t use examples for sensitive document types; describe the format instead","Redact it first — generalize identifiers, break the joins — because the format is what you want copied and the person is what shouldn''t travel","Paste it with an instruction telling the model to ignore the personal details"],"correctIndex":2,"explanation":"Examples are supplied material, so the tiers apply — and redaction preserves exactly what the example is for (structure, register) while removing what it must not carry (the person). D is M4''s named anti-pattern: the data enters the tool regardless of what the output ignores. B surrenders the strongest lever unnecessarily."},{"id":"q8","prompt":"After four steering rounds, output for \"draft talking points for Friday''s restructuring announcement\" keeps inventing wrong specifics — who''s affected, what changes. The brief can''t include the real details: the reorg is confidential and the details are Tier 3–4. What''s the honest diagnosis?","options":["A delegation problem, not a briefing problem — the task needs material that can''t travel, so this part of the work stays with you","A briefing problem — a more detailed role and format section would fix the inventions","A capability problem — a frontier-tier model would stop inventing the specifics","An iteration problem — steering moves need several more rounds to converge"],"correctIndex":0,"explanation":"The failure signature from Lesson 3: iteration keeps missing on the same dimension, and the missing dimension is material you *can''t* supply. M1''s heuristic closes the loop — what the model isn''t given, it invents, and no brief, tier, or round count changes that. The fluent user drafts the shareable scaffolding and keeps the specifics human."}]}', '2026-08-11');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-calibration-prompt-before-you-start-10', 'ai101-m6', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. You''ll score it during the applied activity.*

At the end of this module you''ll deliberately fish for a hallucination in your own domain —
asking about things you know cold, until the model produces something confident, plausible,
and wrong enough that you can prove it.

**How many attempts do you predict it takes?** Count each distinct question as one attempt.
Write the number down.

The miss is diagnostic in both directions. Way fewer attempts than predicted: you''ve been
over-trusting fluent output. Way more: the frontier has moved since you formed your
expectations **[V]** — which is its own lesson about keeping your model of the model current.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-module-brief-20', 'ai101-m6', 20, 'prose', 'stable', '## Module brief

Everything in this module follows from one sentence in M1: *the model produces confident
output the same way whether the content is right or invented.* M1 gave you the mechanism.
This module is about living with its sharpest consequence — because somewhere between
"drafting a JD" and "citing a regulation in a termination memo," fluent-but-wrong stops
being an annoyance and becomes a professional incident with your name on it.

Start with why this is *hard*, not just important. Every credibility instinct you own was
trained on humans — and in humans, fluency is *evidence*. A person who answers precisely,
in confident prose, with specific citations, is usually a person who knows. Your whole
career has rewarded that inference. The model breaks it: fluency is how it generates
*everything*, so fluency carries zero information about accuracy. The most dangerous outputs
are the best-written ones — precise, specific, well-structured — because they''re the ones
your instincts wave through. **More polish should trigger more scrutiny, not less.** That
inversion doesn''t come naturally to anyone; this module is about installing it as a habit
rather than a slogan.

The good news: hallucination isn''t random. It has a shape — four recurring failure types,
each with a tell you can learn — and it concentrates exactly where M1''s mechanism predicts:
specifics the model was never given, gaps where your organization''s knowledge should be,
and facts past the training cutoff. Verification, likewise, isn''t "check everything" — that
kills the time savings and nobody sustains it. It''s a small set of habits, sized to stakes,
that catch the failures where they cluster.

One reframe before we start: in People work, *you are usually the verification layer for
other people''s AI use, not just your own.* Your hiring managers, your employees, your
vendors are all shipping fluent AI output at you. The habits in this module are what make
you the person who catches it — which, as M8 will argue, is quietly becoming part of the
job description.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-learning-objectives-30', 'ai101-m6', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain why fluent output deserves *more* scrutiny, not less — the inversion of a
   career-long credibility instinct, grounded in M1''s mechanism.
2. Recognize the four failure types — fabricated specifics, plausible-but-wrong reasoning,
   confident gaps, stale facts — and the tell for each.
3. Run verification sized to stakes: the two-minute habits for routine work, the deeper
   passes for output that leaves your hands.
4. Name the high-risk surface in People work — the outputs where a single fabrication is an
   incident — and treat everything on it as guilty until verified.
5. Produce, catch, and document a hallucination in your own domain — the applied activity,
   and the fastest way to make all of this visceral.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-lesson-1-why-confidence-and-correctness--40', 'ai101-m6', 40, 'prose', 'stable', '## Lesson 1 · Why confidence and correctness came apart

M1''s mechanism, followed one step further than we took it there.

The model generates each fragment by asking: given everything so far, what plausibly comes
next? When the training data holds the answer thickly — the shape of a JD, the register of
a policy summary — plausible and true point the same direction, and output is reliable.
When the data runs thin — a specific statute number, your company''s actual carryover rule, a
study on four-day weeks in manufacturing — the machinery doesn''t stop, slow down, or flag
anything. It keeps producing the most plausible next fragment. And here''s the step that
matters: **plausible text has the *form* of knowledge — specificity, structure, confidence —
because that''s what answers look like in the training data.** A citation that doesn''t exist
comes out formatted exactly like one that does: "29 CFR § 825.303" has the right shape
whether or not there''s anything behind it. The model isn''t lying — lying requires knowing
better. It''s completing a pattern, and the pattern includes what certainty looks like.

This is why the human credibility heuristic fails so specifically. With people, producing
precise, confident, well-cited prose *costs something* — you generally have to know the
material to fake the form, so form is honest evidence of substance. With the model, the
form costs nothing. It''s the native output format of the machinery, right or wrong. Fluency
still feels like evidence — that feeling took a career to build and won''t dissolve because
a course told it to. The realistic goal is a trained flinch: *the more a passage leans on
specifics I didn''t supply — numbers, names, citations, dates — the more it needs checking
before it travels.*

One more consequence, because it sharpens everything: asking the model "are you sure?"
re-runs the same machinery. Sometimes it catches itself **[V]**; often it apologizes and
produces a new, equally confident wrongness, or — worse — capitulates on something that was
*right*, because deference is also a plausible pattern. Self-confirmation is not
verification. Verification means checking against something that *isn''t* the model: a
source document, a system of record, your own expertise. (M4 already handed you the best
version of this: material you supplied is material you can check against.)', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-try-50', 'ai101-m6', 50, 'try_this', 'stable', '### Try this — 2 minutes
Recall the last AI output that impressed you. Ask of it: which specifics did I supply,
and which did the model produce on its own? Underline the second set mentally — numbers,
names, citations, dates. That underlined set is where this module lives.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-lesson-2-the-failure-taxonomy-60', 'ai101-m6', 60, 'prose', 'stable', '## Lesson 2 · The failure taxonomy

Four types cover nearly everything you''ll meet. Learn the tell for each; they fail
differently, and knowing *which* failure you''re looking at tells you how to check for it.

**Type 1 · Fabricated specifics.** Invented citations, statutes, statistics, quotes, case
names, URLs — the classic. *The tell: precision you didn''t supply.* An exact percentage, a
named study, a section number, appearing in response to a question whose answer the model
was never given. The flinch rule: **a specific that didn''t come from your material came
from the pattern** — treat it as decoration until a source confirms it. This type
concentrates wherever answers *conventionally contain* citations — legal, medical,
research-flavored questions — because the form demands specifics and the machinery obliges.

**Type 2 · Plausible-but-wrong reasoning.** The facts are fine; the logic connecting them
quietly isn''t. A benefits comparison that mishandles a threshold, an adverse-impact
calculation that compares the wrong groups, a policy inference that generalizes from the
wrong clause. *The tell: smooth transitions carrying load-bearing steps* — "therefore,"
"which means," "as a result" gliding past the exact point where you''d slow down. These
survive spot-checks aimed at facts, because every individual fact checks out; you catch
them by re-deriving the *conclusion*, which is why high-stakes reasoning needs a human
re-walk (Lesson 3''s deepest pass).

**Type 3 · Confident gaps.** M1''s signature failure: asked about *your* organization
without material, the model answers anyway, from the average. Your PTO policy, your
escalation path, why your Denver office''s attrition spiked. *The tell: the output is
generic where it should be specific* — it describes a company, not your company. This is
the most catchable type (M4 killed most of it: supply the material or expect invention),
and the most dangerous residue lands on *other people* — the employee who asks the
benefits copilot a question the underlying docs don''t cover, and gets a confident answer
assembled from the average of everyone else''s benefits.

**Type 4 · Stale facts. [V]** Right at training time, wrong now: the regulation amended
last spring, the tool feature that shipped or died, the salary benchmark from two years
ago. *The tell: time-sensitivity itself.* Anything that moves — law, prices, products,
people in roles — carries an implicit "as of when?" that the output won''t volunteer.
Some tools now browse or ground answers in live sources **[V]**, which converts this type
into "check the cited source" (Type 1''s remedy) rather than eliminating it: retrieval can
still fetch a stale or wrong page, fluently.

The types compound — a stale regulation, precisely cited, inside smooth reasoning, is
Types 4+1+2 in one paragraph — but the tells stack the same way: specifics you didn''t
supply, transitions carrying weight, generic-where-specific, and anything with a clock on
it. That''s the whole checklist, and it fits on a sticky note.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-exercise-embed-65', 'ai101-m6', 65, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-lesson-3-verification-that-fits-a-real-w-70', 'ai101-m6', 70, 'prose', 'stable', '## Lesson 3 · Verification that fits a real week

"Check everything" is not a verification strategy; it''s a resolution that dies by
Wednesday. Real verification is *sized to stakes* — a budget, exactly like M3''s window
budget, spent where the failure types cluster. Three levels:

**Level 1 — the two-minute scan (everything).** For any output you''ll use at all: underline
the specifics you didn''t supply (Type 1), circle anything time-sensitive (Type 4), and ask
whether anything is generic where it should be specific (Type 3). Not checking yet — just
*seeing*. The scan costs two minutes and converts unknown risk into a visible list of
claims-to-check. Most routine output — a reworded email, a first-draft JD — has nothing on
the list, and the scan *is* the verification. Done.

**Level 2 — follow the claims (anything that informs a decision or leaves your desk).**
Every underlined specific gets traced to something that isn''t the model: the statute looked
up, the statistic found in a real source, the policy claim checked against the actual
policy (which M4 taught you to have attached in the first place — supplied material makes
this step fast). The discipline: **a claim you can''t trace gets cut or flagged, never
shipped on vibes.** Cutting is usually free — the memo survives without the impressive
statistic; it does not survive the statistic being fake.

**Level 3 — adversarial reading (high stakes: it''s load-bearing, it''s about people, or it
ships under your name).** Two moves. Re-derive the reasoning yourself — walk every
"therefore" and check it holds, because Type 2 hides in exactly the steps you''d otherwise
glide past. And run the two-minute red team: ask the model itself, in a fresh conversation
**[V]**, "argue that this analysis is wrong — what would its critics say?" This isn''t
self-confirmation (Lesson 1''s trap) — you''re not asking it to certify truth, you''re using
its fluency to *generate attack surface* your own review might miss. The critique is raw
material for your judgment, not a verdict.

Who verifies matters as much as how: **the checker needs to be someone who could catch the
error** — which for organizational specifics means you or a colleague who knows, not a
second model *(a second model can widen Level 3''s attack surface, but agreement between two
models is still not evidence — they share training-data instincts, and plausible-but-wrong
is exactly what they agree on)*. And write the check down where it matters: "verified
against [source], [date]" on anything Level 2+ costs one line and changes the conversation
M8 cares about — from "the AI said" to "I checked."', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-try-80', 'ai101-m6', 80, 'try_this', 'stable', '### Try this — 3 minutes
Take one recent AI output you actually used. Run the Level 1 scan on it now, after the
fact: underline, circle, generic-check. If the list is empty, notice how fast that was.
If it isn''t — you know what tonight''s Level 2 looks like.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-lesson-4-the-high-risk-surface-in-people-90', 'ai101-m6', 90, 'prose', 'stable', '## Lesson 4 · The high-risk surface in People work

Some outputs deserve standing suspicion — not because the model fails there more often,
but because the *cost per failure* is a different species. Four zones make up the surface,
and everything on it starts at Level 2 minimum, no exceptions for being busy:

**Legal and policy citations. [V]** Statutes, regulations, compliance claims, "employment
law requires…" — Type 1''s favorite habitat, because legal answers conventionally bristle
with specifics. A fabricated "29 CFR § 825.303" in a termination memo isn''t an error;
it''s an exhibit. The rule: every legal specific traced to the actual source or cut — and
the *reasoning* about what the law means for your case goes to counsel, not to Level 3.
The model can help you *prepare the question for counsel*; it doesn''t get to be counsel.

**Numbers that will be re-said.** Anything quantitative headed for a board deck, an
all-hands, a budget doc. Numbers have a property prose doesn''t: **they get repeated
without their caveats.** Your careful "roughly 12%, per the model''s summary" becomes
"12%" in the CFO''s mouth by Thursday. Any number that will outlive its context gets
traced to a real source — or presented as illustrative, loudly.

**Anything about a named individual.** A fabrication inside an ER summary, a performance
narrative, a reference check isn''t a quality miss — it''s a false statement about a person,
in a document with consequences, bearing your name. This zone overlaps M4 (what may enter
the tool) and M7 (what the tool may influence); M6''s contribution is blunt: *every factual
claim about a person gets verified against the record by a human, every time.* There is no
routine tier here.

**Answers other people take directly.** The copilot in the HRIS, the benefits bot, the
FAQ draft you published — output consumed without a professional in the loop. Your
verification here is *structural*, not per-answer: what material grounds these answers
(M4), what happens when the material doesn''t cover the question, who audits samples, and
where does the disclaimer actually point? (This is 201 M6''s territory in miniature; for
now, know the zone exists and that "the vendor handles that" is a claim, not an answer.)

The surface is small — four zones — and that''s the point. Guard it without apology, spend
Level 1 everywhere else, and you get the time savings *and* keep your name clean. The
applied activity now makes all of this visceral: you''re going to manufacture a Type 1 in
your own domain, on purpose, and watch how good it looks.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-key-takeaways-100', 'ai101-m6', 100, 'takeaways', 'stable', '## Key takeaways

- **Fluency carries zero information about accuracy.** The model produces confident,
  well-formed output the same way whether it''s right or invented — so polish should
  trigger scrutiny, not lower it. That''s an inversion of a career-trained instinct, and
  it installs as a flinch: *specifics I didn''t supply need checking before they travel.*
- **Four failure types, four tells:** fabricated specifics (precision you didn''t supply),
  plausible-but-wrong reasoning (smooth transitions carrying load), confident gaps
  (generic where it should be specific), stale facts (anything with a clock on it).
- **"Are you sure?" is not verification.** Checking means something that isn''t the model:
  a source, a system of record, your own expertise. Supplied material (M4) is what makes
  checking fast. Two models agreeing is still not evidence.
- **Size verification to stakes:** the two-minute scan on everything, claim-tracing on
  whatever informs decisions or leaves your desk, adversarial re-derivation on the
  load-bearing. A claim you can''t trace gets cut, not shipped.
- **The high-risk surface gets no routine tier:** legal citations, numbers that will be
  re-said, claims about named individuals, and answers other people consume directly.
  Level 2 minimum, human eyes always, "verified against [source]" written down.
- **You are the verification layer** — for your own use and, increasingly, everyone
  else''s. That''s not overhead on the job; it''s becoming the job.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-activity-link-105', 'ai101-m6', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 Catch It Lying", "blurb": "Fish for a hallucination in the domain you know best, prove it against a real source, classify its failure type \u2014 and write the one-sentence verification rule you''d give your team. Scored against your predicted attempt count. Graded with per-dimension feedback; free unlimited resubmission.", "estMinutes": "20\u201325"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-sources-and-attribution-110', 'ai101-m6', 110, 'prose', 'stable', '## Sources and attribution

This module draws on the following material:

- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with
  Anthropic, CC BY-NC-SA 4.0) — the treatment of critical evaluation of AI output and
  calibrated trust adapts its "Discernment" competency for the People-leader context.
- **Anthropic''s published research on model behavior** — including work on why models
  produce confident errors and on training models to acknowledge uncertainty; behaviors
  improve unevenly across models and versions. **[V]**
- The four-type taxonomy, the three-level verification discipline, and the high-risk
  surface map are original to this course, developed for the People-leader context.
- Nothing in this module is legal advice; the legal-citations zone exists precisely
  because that boundary is real. *Counsel verifies legal reasoning; this module only
  keeps fabrications from reaching them.*', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-activity-applied-activity-catch-it-lying-10', 'ai101-m6-activity', 10, 'prose', 'stable', '## Applied activity — "Catch It Lying"

**Time:** 20–25 minutes · **Submit:** the transcript excerpts, your documentation, and a
250–350 word reflection · **Graded against the rubric below.** Score doesn''t matter.
Doing the work is where the learning lands.

You''re going to make the model produce something confidently wrong in the domain you know
best — and prove it. Nothing builds the flinch like watching a fabrication assemble itself
in front of you, wearing your profession''s vocabulary.

**Step 1 — Pick your ground (2 min).** A People-work area where you''re genuinely expert:
the leave policy you administer, the ER process you own, the comp philosophy you wrote.
You must be able to *prove* wrongness against a real source — your expertise plus a
document, not just your recollection.

**Step 2 — Fish (10 min).** Ask questions in that area *without supplying material* —
you''re deliberately doing what M4 taught you not to. Aim where the types live: specifics
(ask for citations, numbers, named sources), your org''s particulars (Type 3 territory),
time-sensitive details **[V]**. Count your attempts. If the model honestly declines or
hedges instead of inventing **[V]** — note that too; it''s data, and it counts as an
attempt.

**Step 3 — Catch and prove (5 min).** When you get one: capture the exact wrong claim,
state what''s actually true, and name your proof (the policy section, the real statute,
the source of record). Classify it: which of the four types, and which tell should have
caught it?

**Step 4 — Score the prediction (2 min).** Attempts predicted vs. actual, direction of
miss, and the honest sentence about what that says about your current trust calibration.

Then the reflection — including the deliverable that makes this transfer: **the
verification rule you''d give your team**, written as one enforceable sentence aimed at
the type you caught. Not "be careful with AI" — a rule someone could actually follow and
someone else could audit. ("Every statute or regulation cited in any document leaving
this team gets traced to the primary source before it ships" is the shape.)', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-micro-core', 'ai101-m6-micro', 10, 'prose', 'stable', '## Module 6 in two minutes

**Fluency carries zero information about accuracy.** The model produces confident, well-cited-looking output the same way whether it''s right or invented — the form costs nothing, so the career-trained instinct that polish signals knowledge fails here specifically. The inversion to install: *more polish, more scrutiny* — and the flinch that makes it practical: **specifics you didn''t supply need checking before they travel.**

**Four failure types, four tells.** Fabricated specifics (precision you didn''t supply). Plausible-but-wrong reasoning (smooth ''therefores'' carrying load — survives fact-checks, dies on re-derivation). Confident gaps (generic where it should be specific — your org''s questions answered from everyone''s average). Stale facts (anything with a clock on it).

**Verification is sized to stakes, not applied everywhere.** The two-minute scan on everything; claim-tracing to sources that *aren''t the model* on anything that informs a decision; adversarial re-derivation on the load-bearing. "Are you sure?" re-runs the same machinery and is not verification. A claim you can''t trace gets cut, not shipped.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-micro-rule', 'ai101-m6-micro', 20, 'callout', 'stable', '### The rule to carry

Four zones get no routine tier, ever: legal citations, numbers that will be re-said, claims about named individuals, and answers other people consume directly. Level 2 minimum, human eyes, and "verified against [source]" written down.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m6-micro-close', 'ai101-m6-micro', 30, 'prose', 'stable', '**The full module adds** the find-the-fabrication exercise (four authoritative-sounding claims, one invented study), why two models agreeing is still not evidence, and Catch It Lying — manufacturing a hallucination in your own domain, proving it, and writing the one-sentence verification rule your team could actually be audited against.', NULL, '2026-08-11', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m6-choice', 'ai101-m6', 'choice', '{"reviewedAt":"2026-08-11","title":"Find the fabrication","intro":"*Five minutes. Commit before you look.*\n\nAn HR manager asked an assistant — no documents attached — \"What should we consider before changing our PTO carryover policy?\" Below are four claims from the fluent, well-organized answer. All four *sound* equally authoritative. One is a Type 1 — a fabricated specific that would survive a skim and detonate under checking.\n\nUse the tells from Lesson 2. **Which claim is the fabrication?**","artifacts":[{"label":"Claim 1","body":"\"Changing carryover rules mid-year can create employee-relations friction, particularly for employees who planned leave around the existing policy — many organizations phase such changes in at the start of a calendar year.\""},{"label":"Claim 2","body":"\"A 2023 SHRM Workplace Flexibility Study found that 62% of employees at companies that eliminated carryover reported increased burnout within 18 months.\""},{"label":"Claim 3","body":"\"Several U.S. states treat accrued PTO as earned wages, which constrains use-it-or-lose-it policies — the details vary by state, so this is a question for employment counsel before any change ships.\""},{"label":"Claim 4","body":"\"If your workforce spans multiple states, a single national policy may need to be written to the most protective state''s rules, or varied by state — both approaches have administrative costs worth weighing.\""}],"options":[{"id":"c1","label":"Claim 1 — the change-management point"},{"id":"c2","label":"Claim 2 — the burnout study"},{"id":"c3","label":"Claim 3 — the earned-wages point"},{"id":"c4","label":"Claim 4 — the multi-state point"}],"key":"c2","reasoning":"**Claim 2 is the fabrication — and it''s the tell, not the topic, that catches it.** A named organization, a year, a study title, two precise numbers (62%, 18 months) — in response to a question that supplied *no* material. That''s exactly the precision-you-didn''t-supply signature: research-flavored claims conventionally contain citations, so the machinery produces one, formatted perfectly, whether or not anything stands behind it. Before it travels, that claim is decoration; Level 2 says trace it to the actual study or cut it — and the memo survives fine without it.\n\nWhy the others pass — and *what kind* of trust each has earned: Claims 1 and 4 are general professional reasoning with no invented specifics — nothing to trace, just judgment to agree or disagree with. Claim 3 contains a checkable legal claim, but notice its shape: it stays general (\"several states,\" \"varies\"), and it *routes itself to counsel* — the exact opposite of fabricated confidence. If it had said \"California Labor Code § 227.3 requires…\" you''d be back at the flinch rule: real-sounding, maybe even real, but a specific you didn''t supply, checked before shipped.\n\nThe transferable pattern: you didn''t need to know whether the SHRM study exists. The *form* — uncited precision on unsupplied ground — was enough to quarantine it. That''s the flinch working."}', '2026-08-11');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m6-rubric', 'ai101-m6', 'rubric', '{"promptVersion":"ai101-m6-catch-it-lying-v1","moduleId":"ai101-m6","minWords":250,"maxWords":350,"submitLabel":"Your transcript excerpts, documentation, and reflection","intro":"Paste the relevant transcript excerpts (M4 rules apply — nothing person-identifying), your catch documentation, and the 250–350 word reflection ending with your team rule. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 101, The Foundation). Module 6 applied activity, ''Catch It Lying'': the learner fished for a hallucination in a domain where they hold real expertise, asking questions without supplying material; caught a confident wrong claim (or documented honest declines/hedges — which the activity explicitly counts as valid data); proved wrongness against a named real source; classified the failure by type (fabricated specifics / plausible-but-wrong reasoning / confident gaps / stale facts) and named the tell that should catch it; compared attempt count against their prediction; and wrote a one-sentence verification rule for their team. A numeric prediction may have been captured by the module''s opening calibration prompt; grade the calibration dimension on whether the prediction is stated and honestly compared, never on its accuracy. A submission reporting that the model declined to fabricate, documented honestly with attempts shown, can score full marks on every dimension — the calibration lesson stands either way.","opening":[{"key":"attempts","label":"Predicted — attempts before you catch one","hint":"Each distinct question is one attempt. Honest declines count as attempts.","placeholder":"e.g. 3","min":1,"max":50}],"calibration":[{"key":"attemptsActual","label":"Actual — attempts it took (or total attempts, if it never invented)","hint":"Way fewer than predicted = you''ve been over-trusting. Way more = your expectations are stale.","placeholder":"e.g. 7","min":1,"max":50,"actualFor":"attempts"}],"dimensions":[{"name":"The ground is real expertise","criteria":"The domain is one they demonstrably own, and wrongness is proven against a named source — a policy section, a statute, a system of record — not just ''I know this is wrong.'' The proof is specific enough that a colleague could re-verify it."},{"name":"The fishing is diagnostic","criteria":"Questions aimed where the types live — specifics, org particulars, time-sensitive details — with material deliberately withheld, attempts counted, and hedges or declines recorded as data rather than skipped. Random questions that happened to work score lower than aimed ones."},{"name":"The catch is classified","criteria":"The wrong claim captured exactly, the truth stated, the failure typed correctly, and the tell named — the one that should have caught it in the wild. A near-miss classification with visible reasoning outscores a correct label with none."},{"name":"The rule and the calibration","criteria":"The team rule is one enforceable sentence aimed at the type they caught — followable by a person, auditable by another. ''Be careful with AI'' fails this dimension. Prediction compared, direction named, and the honest sentence about their own trust calibration written."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m6-knowledge_check', 'ai101-m6', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-11","questions":[{"id":"q1","prompt":"Why does the human credibility heuristic — precise, confident, well-cited prose signals knowledge — fail specifically for model output?","options":["Models are trained to deceive users into over-trusting them","For humans the form costs something — you must know the material to fake it — while for the model, confident form is the native output format, right or wrong","It doesn''t fail — fluent model output is in fact more likely to be accurate","Human writing contains verifiable citations while model output never does"],"correctIndex":1,"explanation":"With people, form is honest evidence of substance because producing it requires substance. The model produces the form — specificity, structure, certainty — as pattern completion, identically for true and invented content. No deception is involved (A): lying requires knowing better."},{"id":"q2","prompt":"\"29 CFR § 825.303\" appears in a leave-policy answer you asked for without supplying any material. Before anything else, this citation is best treated as:","options":["Reliable — that level of precision indicates the model found the real regulation","A formatting artifact with no meaning at all","A specific you didn''t supply — decoration until a source that isn''t the model confirms it","Verified, provided the model confirms it when asked \"are you sure?\""],"correctIndex":2,"explanation":"The flinch rule: precision you didn''t supply is Type 1''s tell, and a fabricated section number comes out formatted exactly like a real one — the form is identical either way, which is what makes A the career-trained trap. D re-runs the same machinery and is the module''s named non-verification."},{"id":"q3","prompt":"A benefits comparison cites accurate plan facts throughout, but its recommendation mishandles an eligibility threshold on the way to a confident conclusion. Which type is this, and why do fact-focused spot-checks miss it?","options":["Type 1 — the threshold was a fabricated specific","Type 3 — the model lacked organizational material","Type 4 — the plan facts were stale","Type 2 — every individual fact checks out, so the error lives in the reasoning steps that checks aimed at facts never touch"],"correctIndex":3,"explanation":"Plausible-but-wrong reasoning survives claim-tracing precisely because the claims are fine; the load-bearing \"which means…\" is where it hides. The remedy is re-deriving the conclusion — Level 3''s human re-walk — not more fact-checking."},{"id":"q4","prompt":"An employee asks the HRIS benefits copilot about a situation the underlying documents don''t cover, and gets a confident, specific answer. What has most likely happened, and why is this zone structurally risky?","options":["A confident gap — the answer assembled from the average of everyone else''s benefits — consumed by someone with no professional in the loop","A stale fact — the copilot''s documents are outdated","Nothing risky — copilots only answer from their grounding documents","A Type 2 failure — the reasoning was wrong but the facts were right"],"correctIndex":0,"explanation":"Type 3''s most dangerous residue: where the material runs out, the machinery keeps answering from the average (M1), and the person consuming it can''t tell (M2''s borrowed credibility). That''s why Lesson 4 makes this zone *structural* — grounding, coverage gaps, sample audits — rather than per-answer. C describes the marketing, not the guarantee **[V]**."},{"id":"q5","prompt":"Why is asking the model \"are you sure?\" not verification — and what is?","options":["It is verification, as long as you ask in the same conversation","The question re-runs the same machinery — which may double down, or capitulate on something that was right; verification means checking against something that isn''t the model","It fails only because models are programmed to always agree with users","Verification requires asking at least two different models the same question"],"correctIndex":1,"explanation":"Deference is also a plausible pattern — so the reply is more generation, not evidence. A source document, a system of record, or your own expertise is the standard. D is the subtle trap: two models share training-data instincts, and plausible-but-wrong is exactly where they agree."},{"id":"q6","prompt":"Under the three-level discipline, which output is the *minimum* that requires Level 2 — tracing claims to real sources — rather than just the two-minute scan?","options":["A reworded internal email where the scan found nothing to underline","Any output produced by a frontier-tier model","A first-draft JD that a recruiter will heavily edit anyway","A market-practice summary whose statistics will inform your comp proposal"],"correctIndex":3,"explanation":"It informs a decision, so every specific it contributed gets traced — and any untraceable statistic gets cut, because the proposal survives without the statistic but not with a fake one. A and C are Level 1''s home ground; B confuses model tier with stakes, which the discipline prices by consequence, not capability."},{"id":"q7","prompt":"Why do numbers get their own zone on the high-risk surface?","options":["Models are categorically worse at arithmetic than at prose","Numbers get repeated without their caveats — \"roughly 12%, per the summary\" becomes \"12%\" in Thursday''s board meeting","Numerical output is harder to read than prose output","Regulators require all workplace statistics to be independently audited"],"correctIndex":1,"explanation":"The property is social, not statistical: a number outlives its context and sheds its hedges as it travels. So any number that will be re-said gets traced to a real source — or labeled illustrative loudly enough to survive repetition."},{"id":"q8","prompt":"In \"Catch It Lying,\" the model responds to several of your fishing attempts by declining or hedging instead of inventing. What does the activity say this means?","options":["Your domain has no hallucination risk and needs no verification budget","The activity failed and you should switch to a different model","It''s data — count it, note it, and let it update your calibration; the frontier moves, and your trust settings should track what the model actually does now","The model detected the test and behaved differently than it would in real use"],"correctIndex":2,"explanation":"Honest declines are a real and improving behavior **[V]** — and the activity''s calibration works in both directions: fishing that takes far *more* attempts than predicted means your expectations were formed on older behavior. A overgeneralizes from a sample; the habits stay, because the failure types remain wherever the data runs thin."}]}', '2026-08-11');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-calibration-prompt-before-you-start-10', 'ai101-m7', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. You''ll score it during the applied activity.*

At the end of this module you''ll audit the AI uses in your own function — current and
seriously proposed — against the line this module draws.

**How many of them do you predict land on the wrong side?** Count anything live or under
real consideration: tools, features, team habits, the vendor pilot someone''s excited
about. Write the number down.

The commonest miss isn''t the direction you''d guess. People expect to find zero and fear
finding five; what they usually find is one or two — already running, adopted casually,
that nobody ever examined *as* a decision about people. The audit exists to make the
implicit explicit while it''s still cheap to change.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-module-brief-20', 'ai101-m7', 20, 'prose', 'stable', '## Module brief

Every module so far has taught you to use AI better. This one teaches you where using it
better is beside the point — because some applications fail not by working badly but by
*working at all*.

M1 ended its delegation heuristic with a clause this course has repeated like a drumbeat:
*and it must not make decisions about people.* This module is where the drumbeat becomes
an argument you can make out loud — to an excited vendor, an impatient executive, a
well-meaning teammate with a screening shortcut. The argument has to be made well, because
you will not be the most enthusiastic person in the room. Efficiency is on the other side.
"The human still decides" is on the other side. You''ll need something better than
discomfort; you''ll need the mechanism.

Here it is, compressed once, built out in Lesson 1. The model learned from human text and
human records. Those records contain every pattern in how organizations have actually
treated people — including the ones we''ve spent decades trying to correct. A system that
learns "what does a strong candidate look like" from history learns *who got called
strong*, and reproduces it at scale, fluently, with M6''s signature confidence. Bias in AI
isn''t a defect that better engineering removes; it''s fidelity to data that contains the
world as it has been. In most domains that''s a quality problem. In employment decisions
it has a legal name — adverse impact — and a moral one, and it lands on the population
you specifically exist to protect.

What this module is not: anti-AI. Six modules taught you the assist side, and the assist
side is enormous — drafting, summarizing, structuring, preparing. The line this module
draws is narrow, specific, and defensible: **AI assists with work about people; it does
not decide about people, rank people, or filter people.** Narrow lines hold. Vague
discomfort gets routed around by Q3.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-learning-objectives-30', 'ai101-m7', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain why bias is a property of learned systems, not a bug — and why "we cleaned the
   data" and "we removed the protected fields" don''t dissolve the problem.
2. Draw the assist/decide line through real cases — screening, ranking, performance
   language, promotion, termination — and say precisely why "a human reviewed it" isn''t
   automatically a defense.
3. Sketch the regulatory shape **[V]** well enough to ask counsel the right questions —
   and no further.
4. Say no so it sticks: specific, tied to a named decision, with the assist-side
   alternative attached.
5. Audit your own function''s AI uses against the line — the applied activity.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-lesson-1-bias-is-a-property-not-a-bug-40', 'ai101-m7', 40, 'prose', 'stable', '## Lesson 1 · Bias is a property, not a bug

The word "bias" invites a mental model of contamination — a stain in the data that
diligent cleaning removes. That model leads to the two most common false reassurances in
vendor conversations, so let''s break it properly.

Recall M1: a learned system finds patterns in examples and reproduces them. Now ask what
the examples *are* for any employment-relevant model: decades of résumés, hiring
outcomes, performance ratings, promotion histories — records of what organizations
actually did. Those records don''t contain "merit" as a clean signal. They contain *who
got hired, rated, promoted* — merit tangled with every systematic pattern in how those
calls were made: which schools got the benefit of the doubt, which names got callbacks,
which communication styles got called "leadership presence," who got mentored onto the
projects that make a résumé strong. A system trained to predict "strong candidate"
learns that tangle *as* the definition. It isn''t malfunctioning when it reproduces the
pattern. It''s doing exactly what it was built to do, on data that contains the world as
it has been.

Now the two reassurances. **"We removed gender, race, and age from the inputs."** The
tangle doesn''t live in the labeled fields; it lives in everything correlated with them —
name, zip code, school, employment gaps, club memberships, word choice, the shape of a
career path. M4 taught you that identity survives redaction through combinations;
protected characteristics survive field-removal the same way. The literature''s blunt
version: proxies are everywhere, and a capable learner finds them. **"Our model is more
objective than biased human reviewers."** This one deserves care, because the premise is
true — human review *is* biased; that''s what the training data just proved. But a model
doesn''t transcend the pattern; it *standardizes* it. A biased human decision is one
decision, varying by the human, contestable in the room. The same bias in a model runs on
every candidate, identically, at scale, wearing M6''s fluent confidence — and (next
lesson) with the accountability diffused. "Less biased than a human" is an empirical
claim someone must *demonstrate for the specific system on the specific population* —
never a property the technology gets on principle.

One more consequence, from M6: an LLM asked to *evaluate* a person produces the same
confident prose whether its judgment is sound or a reproduced pattern. "Rate this
candidate''s leadership potential from their résumé" returns fluent, specific,
plausible-sounding assessment — and every word of it is pattern completion over exactly
the tangled history above. The fluency is not evidence. In this domain, it never is.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-try-50', 'ai101-m7', 50, 'try_this', 'stable', '### Try this — 2 minutes
Write down three things a hiring model could infer from a résumé that correlate with a
protected characteristic but aren''t one. (Lesson 1 named several.) This is the list
you''ll want in your pocket the next time someone says "we don''t even look at
demographics."', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-lesson-2-assist-versus-decide-60', 'ai101-m7', 60, 'prose', 'stable', '## Lesson 2 · Assist versus decide

The line, stated operationally: **AI may transform, structure, and prepare the material
humans decide from. It may not score, rank, filter, or characterize the people the
decision is about.** Run the week''s real cases through it:

**Screening.** *Assist:* structuring intake notes; turning a hiring manager''s rambling
brief into a crisp role spec; drafting interview questions from the competencies.
*Decide:* résumé scoring, "fit" ranking, auto-rejection, "top candidates" surfacing —
M2''s decision engines. The tell from M2 applies: if candidates the system ranked low
never reach human eyes, the system decided, whatever the workflow diagram says.

**Performance.** *Assist:* helping a manager turn their own observations into clear,
specific written feedback; structuring peer input *the humans wrote*. *Decide:* generating
the assessment — "rate this employee," "summarize their performance from these tickets,"
any sentence about a person''s quality that a human didn''t originate. The manager''s
judgment is the input; AI formats it. The moment AI supplies the judgment and the manager
formats *that*, the line is crossed even though a human typed the final version.

**Promotion, comp, termination.** *Assist:* checking a written case for clarity and
consistency; assembling the human-authored materials into a packet. *Decide:* flight-risk
scores feeding retention decisions, "potential" ratings, termination-list drafting — and
note that these arrive politely, as "data points for the conversation." A number about a
person in a decision meeting *is* a decision input; that''s what numbers in meetings are
for (M6 told you what happens to numbers — they get repeated without caveats, and they
anchor).

Now the sentence you''ll hear most: **"it''s fine — a human makes the final call."** Here''s
why that''s not automatically a defense, mechanically. Human review checks a *specific
failure* you can articulate: M6''s Level 2 traces a citation, a manager re-derives a
recommendation. But review of a ranked list checks — what, exactly? The reviewer sees the
survivors, not the filtered; they can''t re-derive a score built on ten thousand tangled
examples; and the anchor is already set — disagreeing with the machine now requires a
*reason*, and the machine''s reason looked so fluent. Review without the ability to catch
the failure is M6''s definition of theater: **a human in the loop is a defense only when
the human could actually catch the error.** For a fabricated citation, they can. For
"why did the model rank her 47th?", nobody can — including the vendor.

The line''s honest gray zone: aggregate analysis. "Summarize themes from 400 exit
interviews" is about *people*, plural, and it shapes decisions — but it characterizes a
population, not a person, and no individual is scored. That''s assist-side, with M4''s
redaction and M6''s verification riding along — *until* the aggregate gets small enough
to point at individuals (M4''s small-population flag) or the themes get re-attached to
named people. The test that travels: **could this output change one identifiable
person''s outcome?** Yes → the decide side''s rules apply, whatever the tool looks like.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-exercise-embed-65', 'ai101-m7', 65, 'exercise', 'stable', '{"type": "sorting", "title": "Calibration exercise \u2014 Which side of the line?", "intro": "Ten minutes, ten uses of AI from a People function''s real week. Sort each: assist (go, with ordinary care), assist with verification (go, with M6''s Level 2+ riding along), or never (the decide side). Commit every card before the reveal.\n\nUse the traveling test: could this output change one identifiable person''s outcome?"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-lesson-3-the-regulatory-shape-70', 'ai101-m7', 70, 'prose', 'volatile', '## Lesson 3 · The regulatory shape [V]

*Everything in this lesson is direction-of-travel, not legal advice, and it moves —
verify with counsel before relying on any specific here. The lesson''s purpose is to make
your conversation with counsel better, not to replace it.*

The shape, in four strokes. **Employment decisions are a named high-risk category** in
the emerging regulatory landscape — the EU AI Act treats AI systems used in employment,
worker management, and access to self-employment as high-risk, with obligations to
match; U.S. federal enforcement agencies have signaled that existing employment law
fully applies to algorithmic decisions; and a growing patchwork of state and city rules
targets automated employment decision tools specifically — audit requirements,
disclosure requirements, and definitions that turn on whether a tool *substantially
assists or replaces* discretionary decisions. **[V]**

**Disparate impact doesn''t need intent.** The doctrine long predates AI: a neutral-seeming
practice that disproportionately excludes a protected group needs job-related
justification, regardless of anyone''s intentions. Map that onto Lesson 1 — a system that
learned the tangle reproduces the disparity at scale, no malice required — and you see why
"the vendor assured us it''s unbiased" is not a defense but a deferred question: *show me
the analysis, for this system, on a population like ours.* Vendors making bias claims
should expect to produce validation evidence; that expectation is increasingly
regulatory, not just prudent. **[V]**

**Accountability doesn''t outsource.** The consistent regulatory and enforcement posture:
the employer using the tool owns the outcome, jointly with whoever built it — buying a
biased system is doing a biased thing. M8 generalizes this ("the sentence ''the AI did
it'' has never once helped anyone"); here it lands specifically: your organization''s name
is on every decision its tools make.

What this means you should *do*, this quarter, without waiting for counsel: **inventory**
(the M2 stack audit, re-read for decision engines — you likely already have automated
employment decision tools you didn''t name that way); **ask vendors for their validation
evidence** in writing; and **bring counsel a specific list** — "these three systems
touch hiring and performance; here''s what each decides" — because "is our AI compliant?"
gets you a shrug, and the specific list gets you an answer. The questions for counsel:
which of our jurisdictions regulate these tools today, what do they require of us this
year, and what''s coming that we should build for now? **[V]**', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-lesson-4-saying-no-so-it-sticks-80', 'ai101-m7', 80, 'prose', 'stable', '## Lesson 4 · Saying no so it sticks

You now own an argument. This lesson is about deploying it so it survives contact with
enthusiasm — because vague discomfort loses to a vendor deck every time, and a blanket
"no AI near people decisions" gets routed around the moment it blocks something a leader
wants. Four properties make a line hold:

**Specific.** Name the decision, not the technology. Not "we''re cautious about AI in
hiring" — "no system ranks, scores, or filters candidates; screening decisions are made
by humans reading human-legible material." A specific line can be checked against any
new tool in thirty seconds; vagueness has to be re-litigated per vendor.

**Attached to its alternative.** Every no arrives with the assist-side yes: "we don''t
score candidates — we *do* use AI to structure intake, draft interview kits, and turn
your notes into clean debriefs, and here''s who sets that up for your team." The
alternative isn''t a consolation prize; it''s what makes the line politically survivable.
People route around prohibitions; they adopt trades.

**Reasoned in the room''s language.** For the executive: standardized bias at scale,
disparate impact without intent, accountability that doesn''t outsource — risk language,
with Lesson 3''s specifics ready. For the team: "we can''t catch this system''s errors, and
we don''t ship what we can''t verify" — M6''s language, which they''ve now internalized. For
the vendor: "show me your validation evidence for a population like ours, in writing" —
which either produces evidence or produces silence, and both are answers.

**Owned by a name.** A line nobody owns is a suggestion. The line gets a sign-off — new
tools touching people decisions clear [name/role] before pilot, and that person''s answer
is the answer. (M8 builds the full policy skeleton; this is its first entry, and the
applied activity has you draft it.)

And the posture that makes all four land: the line is not a hedge against the future —
it''s how you get to use everything else *confidently*. The teams that drew it clearly
are the ones moving fastest on the assist side, because nobody''s wondering where the
edge is. That''s the version of this module you want your organization to remember: not
the department of no — the people who knew exactly where yes lives.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-key-takeaways-90', 'ai101-m7', 90, 'takeaways', 'stable', '## Key takeaways

- **Bias is fidelity, not malfunction.** Learned systems reproduce the patterns in their
  training records — which for employment data means the tangle of merit with every
  systematic skew in how organizations actually treated people. Cleaning intentions out
  of the data isn''t an option; the tangle *is* the data.
- **Field-removal doesn''t work and "more objective than humans" proves too much.**
  Proxies survive deletion the way identity survives redaction; and a model doesn''t
  transcend human bias — it standardizes one instance of it at scale, fluently. "Less
  biased" is an empirical claim requiring demonstration, per system, per population.
- **The line: AI transforms and prepares the material humans decide from; it does not
  score, rank, filter, or characterize the people decided about.** The traveling test:
  could this output change one identifiable person''s outcome?
- **"A human reviews it" defends only what the human could actually catch.** Nobody can
  re-derive a ranking built on ten thousand tangled examples — review of the unreviewable
  is theater, and the filtered-out never reach the reviewer at all.
- **The regulatory shape [V]: employment is a named high-risk category, disparate impact
  needs no intent, and accountability doesn''t outsource.** Inventory your decision
  engines, demand validation evidence in writing, bring counsel a specific list.
- **A line that holds is specific, attached to its assist-side alternative, reasoned in
  the room''s language, and owned by a name.** Drawn well, it''s not the department of no
  — it''s what lets everything else move fast.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-activity-link-95', 'ai101-m7', 95, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 Draw the Line", "blurb": "Audit your function''s real AI uses against the line, then write the one-pager you could actually circulate: three endorsed uses, two forbidden ones with reasoning an executive would engage with, the trade, and the sign-off. Scored against your predicted wrong-side count. Free unlimited resubmission.", "estMinutes": "20\u201325"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-sources-and-attribution-100', 'ai101-m7', 100, 'prose', 'stable', '## Sources and attribution

This module draws on the following material:

- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with
  Anthropic, CC BY-NC-SA 4.0) — the treatment of ethical responsibility and human
  accountability for AI-assisted decisions adapts its "Diligence" competency for the
  employment context.
- The disparate-impact framing follows long-standing U.S. employment-law doctrine;
  the high-risk categorization of employment AI follows the EU AI Act''s published
  framework; agency guidance on algorithmic employment decisions continues to evolve.
  **This lesson is direction-of-travel, not legal advice — verify all specifics with
  counsel before relying on them. Flagged for counsel review before any
  deployment-specific claims are added. [V]**
- The proxy-variable problem and the standardization-of-bias argument reflect the
  published algorithmic-fairness research consensus.
- The assist/decide line, the traveling test, the review-theater argument, and the
  four properties of a line that holds are original to this course.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-activity-applied-activity-draw-the-line-10', 'ai101-m7-activity', 10, 'prose', 'stable', '## Applied activity — "Draw the Line"

**Time:** 20–25 minutes · **Submit:** your one-pager plus a 250–350 word reflection ·
**Graded against the rubric below.** Score doesn''t matter. Doing the work is where the
learning lands.

One page, for your own function, that you could actually circulate. Before you write it:
the audit you predicted on.

**Step 1 — The audit (7 min).** List your function''s AI uses — live and seriously
proposed. Include the unglamorous ones: the ATS feature someone switched on, the survey
platform''s "AI insights," the manager who mentioned using a chatbot for review drafts.
For each: which side of the line, using the traveling test. Count the wrong-side
findings and score your prediction — direction of miss, one sentence on why.

**Step 2 — The one-pager (12 min).** Four sections, all concrete:
- **Three uses you endorse** — assist-side, from your real work, each with its M6
  verification note ("JD drafting — recruiter reviews, no verification beyond read" vs.
  "policy summaries — Level 2, claims traced").
- **Two uses you forbid** — named specifically (the decision, not the technology), each
  with its reasoning in one or two sentences an executive would engage with.
- **The trade** — for each no, the assist-side yes that replaces it.
- **The sign-off** — who clears new people-touching tools before pilot, by name or role.

**Step 3 — The stress test (3 min).** Read your forbidden list as the most enthusiastic
AI adopter you know. Write down the workaround they''d find. If the workaround is easy,
tighten the specific wording — that gap is where the line will actually be tested.

Then the reflection: what the audit surprised you with, which forbidden use was hardest
to write the reasoning for (that''s the one that needed this module), and what you''d need
from M8 to make the one-pager real policy.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-micro-core', 'ai101-m7-micro', 10, 'prose', 'stable', '## Module 7 in two minutes

**Bias is a property of learned systems, not a bug.** Employment records contain merit tangled with every systematic skew in how organizations actually decided — and a system trained on the records learns the tangle as the definition. Removing protected fields doesn''t help (proxies are everywhere — names, schools, gaps, career shapes), and "less biased than humans" is an empirical claim requiring demonstration per system, per population — because a model doesn''t transcend the pattern, it standardizes one instance of it at scale.

**The line: AI transforms and prepares the material humans decide from; it does not score, rank, filter, or characterize the people decided about.** The test that travels: *could this output change one identifiable person''s outcome?* And the defense that isn''t: "a human reviews it" only counts where the human could actually catch the error — nobody can re-derive a ranking, and the filtered-out never reach the reviewer at all.

**The regulatory shape [V]:** employment is a named high-risk category, disparate impact needs no intent, and accountability doesn''t outsource — buying a biased system is doing a biased thing. Verify specifics with counsel; bring them a list, not a vibe.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-micro-rule', 'ai101-m7-micro', 20, 'callout', 'stable', '### The rule to carry

A line that holds is specific (name the decision, not the technology), attached to its assist-side trade, reasoned in the room''s language, and owned by a name. Drawn well, it''s not the department of no — it''s what lets the assist side move fast.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m7-micro-close', 'ai101-m7-micro', 30, 'prose', 'stable', '**The full module adds** the which-side-of-the-line sort (ten real uses — the never cards all arrive politely, as ''data points'' and ''first passes''), the review-theater argument in full, the counsel conversation that gets answers instead of shrugs, and Draw the Line — auditing your own function and writing the one-pager you could actually circulate.', NULL, '2026-08-11', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m7-sorting', 'ai101-m7', 'sorting', '{"reviewedAt":"2026-08-11","buckets":[{"id":"never","label":"Never","hint":"The decide side","rank":0,"pct":5},{"id":"verify","label":"Assist + verification","hint":"Go, with Level 2+ riding along","rank":1,"pct":45},{"id":"assist","label":"Assist","hint":"Go, with ordinary care","rank":2,"pct":85}],"tasks":[{"id":"t1","text":"Turn a hiring manager''s rambling role description into a structured job spec","key":"assist","reasoning":"Transformation of human-supplied material about a role, not a person. The heuristic''s home ground — ordinary M5 care, no special verification."},{"id":"t2","text":"Rank the 80 applicants for a role by fit score so recruiters can focus on the top 20","key":"never","reasoning":"Scoring and filtering people — the 60 at the bottom are decided about by a system, reviewed by no one. ''Recruiters make the final call'' fails the review test: they only ever see the survivors."},{"id":"t3","text":"Draft interview questions from the role''s competency list","key":"assist","reasoning":"Material about the role, transformed into interview scaffolding. The humans still run the interviews and form every judgment about the people in them."},{"id":"t4","text":"Summarize themes across 400 redacted exit-interview transcripts for the annual retention review","key":"verify","reasoning":"Assist-side — a population characterized, no individual scored — but it shapes real decisions and summarization has M6 failure modes (the lossy middle, flattened intensity), so Level 2 rides along: spot-check themes against transcripts. And watch M4''s small-population flag if any cut gets thin."},{"id":"t5","text":"Paste an employee''s support tickets and ask for a summary of their performance this quarter","key":"never","reasoning":"AI originates a characterization of a named person''s quality — the decide side even if a manager edits the result afterward. Direction of origination is the test: judgment must start with the human."},{"id":"t6","text":"Help a manager turn their own written observations into a clear, structured performance review","key":"verify","reasoning":"The manager supplies the judgment; AI formats it — assist-side. Verification rides along because it''s a consequential document about a named person: the manager confirms every claim survived formatting intact, and nothing got added. That''s M6''s named-individual zone.","also":["assist"]},{"id":"t7","text":"Draft the FAQ for an upcoming benefits change, from the plan documents","key":"verify","reasoning":"Assist-side drafting from supplied material — but the output is consumed directly by employees who''ll act on it (M6''s fourth zone), and benefits claims are checkable specifics. Level 2: every factual claim traced to the plan docs before publishing."},{"id":"t8","text":"Generate a flight-risk score for each employee in the org, as a data point for retention conversations","key":"never","reasoning":"A number attached to every named person, feeding decisions about them. ''Just a data point'' is how scores enter meetings — and M6 told you what numbers do there: shed caveats and anchor. This is a decision engine whatever the dashboard calls it."},{"id":"t9","text":"Check a promotion case the manager wrote for clarity, consistency, and gaps before the calibration meeting","key":"assist","reasoning":"Editing support on a human-authored case: the judgment exists, on paper, from its accountable author. AI is improving the material humans decide from — which is the line''s exact definition of assist."},{"id":"t10","text":"Screen out résumés with employment gaps longer than a year before human review","key":"never","reasoning":"Auto-filtering people on a rule — and a rule that''s a textbook proxy: gaps correlate with caregiving, disability, and other protected ground (Lesson 1''s tangle). The filtered are never seen; disparate impact needs no intent."}],"pattern":"The traveling test decides every card: could this output change one identifiable person''s outcome?","postscript":"The never cards share one property — a system originated a judgment or filter on a person — and the polite framing (''data point,'' ''just a first pass,'' ''recruiters still decide'') is exactly how they arrive in real meetings. Cards placed above the key are the direction that costs people; below, the direction that costs only convenience — and note t6: some cards are legitimately arguable between assist and verify, which is why the verification column exists. The applied activity now runs this same sort on your function''s real uses — including the ones nobody ever examined as decisions about people."}', '2026-08-11');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m7-rubric', 'ai101-m7', 'rubric', '{"promptVersion":"ai101-m7-draw-the-line-v1","moduleId":"ai101-m7","minWords":250,"maxWords":350,"submitLabel":"Your one-pager and reflection","intro":"Paste the one-pager (all four sections) followed by the 250–350 word reflection. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 101, The Foundation). Module 7 applied activity, ''Draw the Line'': an audit of their function''s real AI uses (live and seriously proposed) against the assist/decide line using the traveling test (could this output change one identifiable person''s outcome?), scored against their predicted wrong-side count; then a circulate-ready one-pager with four sections — three endorsed assist-side uses each carrying an M6 verification note, two specifically-named forbidden uses with reasoning an executive would engage with, the assist-side trade attached to each no, and a named sign-off for new people-touching tools; then a stress test writing the workaround an enthusiastic adopter would find. A numeric prediction may have been captured by the module''s opening calibration prompt; grade the calibration dimension on whether the prediction is stated and honestly compared, never on its accuracy. Finding zero wrong-side uses is acceptable only with evidence the audit actually looked — including embedded features and casual team habits, not just official tools.","opening":[{"key":"wrongSide","label":"Predicted — current or proposed uses landing on the wrong side","hint":"Count anything live or under real consideration in your function.","placeholder":"e.g. 1","min":0,"max":20}],"calibration":[{"key":"wrongSideActual","label":"Found — wrong-side uses the audit actually surfaced","hint":"The commonest find: something already running that nobody examined as a decision about people.","placeholder":"e.g. 2","min":0,"max":20,"actualFor":"wrongSide"}],"dimensions":[{"name":"The audit looked","criteria":"Real uses from their actual function, including embedded features (ATS/HRIS/survey-platform AI) and informal team habits — not just official tools. Each use placed with the traveling test visible in the reasoning. A surprising find honestly reported outscores a clean bill of health."},{"name":"The forbidden uses are named and reasoned","criteria":"Two prohibitions naming the decision, not the technology (''no system ranks candidates'' not ''careful with AI''), each with reasoning drawn from the module''s mechanism — standardized bias, review theater, proxies, accountability — at a register an executive would engage with rather than dismiss."},{"name":"The line could hold","criteria":"Every no carries its assist-side trade; the sign-off names a person or role; and the stress test identifies a real workaround with a specific tightening in response. A line with an obvious unaddressed route-around scores low on this dimension regardless of the reasoning quality."},{"name":"Verification notes and calibration","criteria":"Each endorsed use carries a proportionate M6 note (which level, why); the prediction is compared, direction named, with the honest sentence about what the audit revealed. The reflection names which forbidden use was hardest to reason — and why."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m7-knowledge_check', 'ai101-m7', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-11","questions":[{"id":"q1","prompt":"Why is bias in an employment-trained model a property rather than a bug?","options":["Vendors deliberately train models on biased data because it''s cheaper","The training records contain merit tangled with every systematic skew in how organizations actually decided — and the system learns that tangle as the definition","Models are programmed with the biases of their developers","It is a bug — sufficiently careful data cleaning removes the bias"],"correctIndex":1,"explanation":"The records are what organizations *did*, not what merit *was* — who got hired, rated, promoted, with every pattern in those calls included. A system that predicts \"strong candidate\" from history reproduces the history. D is the contamination model this lesson exists to break: you can''t clean intentions out of outcomes."},{"id":"q2","prompt":"A vendor explains their screening tool can''t be biased because gender, race, and age were removed from the inputs. What''s wrong with this reassurance?","options":["Nothing — removing protected fields is the accepted standard for fairness","The fields can be reconstructed from metadata the vendor forgot to strip","The patterns live in everything correlated with those fields — names, schools, gaps, word choice, career shapes — and a capable learner finds the proxies","Removing fields reduces accuracy, which is itself a form of bias"],"correctIndex":2,"explanation":"Protected characteristics survive field-removal the way identity survives name-deletion in M4 — through combinations. The tangle doesn''t live in labeled columns; it lives in the correlated everything-else, which is why field-removal is the first false reassurance of Lesson 1."},{"id":"q3","prompt":"\"Our model is less biased than human reviewers\" is best treated as:","options":["True on principle — algorithms don''t have feelings, so they can''t discriminate","False on principle — software is always more biased than people","Irrelevant — bias comparisons between humans and models are meaningless","An empirical claim requiring demonstration for the specific system on a relevant population — because a model standardizes one bias pattern at scale rather than transcending it"],"correctIndex":3,"explanation":"The premise is even true — human review is biased; that''s what the training data proves. But the model doesn''t rise above the pattern, it runs one instance of it on every candidate identically, fluently, at scale. So the claim is checkable, sometimes even true — and never a property the technology gets for free. Ask for the validation evidence, in writing."},{"id":"q4","prompt":"A manager uses AI to turn their own written observations into a clear, well-structured performance review. A second manager pastes an employee''s tickets and asks the model to \"summarize their performance,\" then edits the result. The line says:","options":["Both are fine — a human shipped the final text in both cases","The first is assist (AI formats the manager''s judgment); the second crossed the line (AI originated the judgment, and the human formatted it)","Both crossed it — AI should never touch performance documents","The second is safer, because tickets are objective data"],"correctIndex":1,"explanation":"The direction of origination is the whole test: judgment from the human, formatting from the machine is assist; judgment from the machine, formatting from the human is decide — even though a person typed the final version in both. D is the seductive one: \"objective\" inputs don''t make the characterization of a person any less a characterization."},{"id":"q5","prompt":"Why isn''t \"a human makes the final call\" automatically a defense for a résumé-ranking system?","options":["Because regulations prohibit humans from overriding algorithmic outputs","Humans always agree with the machine, so review changes nothing","The reviewer sees only the survivors, can''t re-derive the scores, and is anchored by them — review is a defense only where the human could actually catch the error","It is a defense — human review resolves the concern in full"],"correctIndex":2,"explanation":"M6''s principle, sharpened: verification requires the checker to be capable of catching the failure. The filtered-out candidates never reach the reviewer; the score''s reasoning isn''t re-derivable by anyone, vendor included; and disagreeing with a fluent number now requires a reason. Review of the unreviewable is theater."},{"id":"q6","prompt":"\"Summarize the themes in these 400 redacted exit interviews\" sits on the assist side. What moves this kind of work across the line?","options":["Using more than one model to generate the summary","The population getting small enough to point at individuals, or themes getting re-attached to named people — anything that could change one identifiable person''s outcome","Nothing — aggregate analysis is always safe regardless of size","Using the summary in any meeting where decisions are made"],"correctIndex":1,"explanation":"The traveling test. Aggregates characterize populations, and that''s assist-side work with M4 and M6 riding along — until the aggregate thins into de-facto individual assessment. C ignores M4''s small-population flag; D would outlaw using analysis for anything, which isn''t the line — informing decisions about *policies* is what analysis is for."},{"id":"q7","prompt":"Per the regulatory shape **[V]**, why does \"the vendor assured us their tool is unbiased\" fail as a defense under disparate-impact doctrine?","options":["Vendor statements are inadmissible in legal proceedings","Disparate impact turns on outcomes, not intent — so the question is validation evidence for this system on a population like yours, and the employer owns the outcome either way","It doesn''t fail — good-faith reliance on vendor assurances transfers the liability","Because all vendor tools are in fact biased"],"correctIndex":1,"explanation":"No malice is required — a neutral-seeming practice that disproportionately excludes needs job-related justification, whoever built it. Accountability doesn''t outsource: buying a biased system is doing a biased thing. Hence the module''s homework — validation evidence in writing, and a specific list for counsel rather than \"are we compliant?\""},{"id":"q8","prompt":"Which version of the line is most likely to actually hold inside an organization?","options":["\"We take an appropriately cautious approach to AI in talent processes\"","\"No AI anywhere near anything involving people, effective immediately\"","\"No system ranks, scores, or filters candidates — screening stays human. AI does structure intake, draft kits, and clean up debriefs; [Name] clears any new people-touching tool before pilot\"","Whichever version the vendor''s legal team is comfortable signing"],"correctIndex":2,"explanation":"The four properties: specific (checkable against any new tool in seconds), attached to its assist-side trade (adoptable, not just prohibitive), reasoned, and owned by a name. A re-litigates per vendor; B routes around by Q3 because it blocks the assist side too — the blanket version is the *weaker* version, which is this module''s least intuitive lesson."}]}', '2026-08-11');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-calibration-prompt-before-you-start-10', 'ai101-m8', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds — the last one, and it''s about all the others.*

Across this course you''ve made a prediction at the top of most modules and scored it in the
activity. The final activity asks you to gather them and look at the pattern.

**Before you look back: in which direction do you think you''ve mostly missed?** Over —
expecting more from these tools than they delivered? Under — expecting less? Mixed? Write
one sentence, including your best guess at *why* your misses lean the way they do.

This one has no numeric field on purpose. The last calibration is a judgment about your own
judgment — which is, not coincidentally, the skill the whole course was building.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-module-brief-20', 'ai101-m8', 20, 'prose', 'stable', '## Module brief

Here is the situation the previous seven modules leave you in. You can predict what a model
will do well (M1), identify what shape of AI you''re looking at (M2), size a use case (M3),
move material safely (M4), brief and steer (M5), catch fabrications (M6), and say where
the machines must stop (M7). One question remains, and it''s the one your organization will
actually ask you, usually on a bad day: **when AI touched the work, who owns the result?**

The answer is one word long — *you* — and this module is about making that answer
survivable. Because "you own it" without infrastructure is just exposure: you own output
you didn''t verify, under agreements you haven''t read, with disclosure norms nobody wrote
down, against questions nobody settled. The module builds the infrastructure: the
accountability principle stated so it can''t be misread, the agreement layer that determines
what your tools may do with what you give them **[V]**, the disclosure judgment for when
"AI helped" needs saying out loud, and the five questions to settle with legal and IT
*before* the bad day — plus the one-pager that closes the course by writing your answers
down.

One reframe to carry through the module: ownership is not the tax on using AI. It''s the
*license*. The person who can say "I use these tools, here''s what I verify, here''s my
line, and here''s my name on the result" gets to use them without asking permission every
time — and becomes the person others ask. That''s the posture 201 builds on, and the reason
this module closes the course instead of opening it: you can only own what you understand,
and now you understand it.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-learning-objectives-30', 'ai101-m8', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. State the accountability principle — the output is a draft, never a decision — and apply
   it to the excuses that arrive when AI-assisted work goes wrong.
2. Read your tools'' agreement layer **[V]**: what''s retained, what''s trained on, and the
   difference between consumer defaults and enterprise terms — and know which questions go
   to IT versus counsel.
3. Make the disclosure call with the honest test: would the person reading this feel misled
   to learn how it was made?
4. Bring legal and IT the five questions worth settling now, as a policy skeleton rather
   than an open-ended worry.
5. Write your own one-pager — use, verify, disclose, refuse — and score your calibration
   across the whole course. The applied activity, and the course close.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-lesson-1-the-output-is-a-draft-never-a-d-40', 'ai101-m8', 40, 'prose', 'stable', '## Lesson 1 · The output is a draft, never a decision

The principle first, stated so it can''t be misread: **AI output is a draft handed to you.
The moment you ship it — send it, file it, say it in a meeting — it stops being AI output
and becomes your work.** Accountability doesn''t transfer to a tool, because the tool can''t
hold it: it can''t be questioned about intent, can''t correct the record, can''t make the
person harmed whole, can''t be sanctioned into doing better. Every mechanism accountability
runs on requires a person. That''s not a course rule; it''s how your organization, your
profession, and the law already work — this module just refuses to pretend AI changed it.

The principle earns its keep on the bad day, when the excuses arrive. Hold four of them up
to the light — you''ll hear all four eventually, possibly in your own voice, and each one
is actually a *confession* wearing a defense:

**"The AI wrote it."** Confesses: I shipped work I didn''t stand behind. The provenance of a
draft has never mattered to accountability — nobody accepts "the intern wrote it" or "the
template said that" from the person who signed. This excuse has never once helped anyone,
and its M1-shaped error is treating the tool as an *author* — an entity that could own
words — rather than machinery that produced them.

**"I reviewed it."** Better — review is the right *category* — but as a defense it claims
whatever the review could actually catch, no more. M6 priced this precisely: a Level 1
scan defends against nothing on the high-risk surface; "I reviewed it" for a fabricated
statute means "I read it and it sounded right," which is M6''s exact description of how
fabrications ship. The honest version has content: *"I traced its claims against the plan
documents"* — a defense with a verb in it.

**"It was only a draft."** Confesses: I lost track of the boundary between drafting and
shipping. The principle is precisely that draft-ness *ends* — at the send button, at the
meeting, at the moment a colleague could rely on it. Sharing "just a draft" analysis that
someone acts on shipped it, whatever the filename said.

**"The vendor said it was compliant."** M7 already broke this one — accountability doesn''t
outsource, and a vendor''s assurance is a deferred question, not a defense. Confesses: I
let someone else''s claim stand where my organization''s verification should be.

Notice what all four have in common: each one tries to relocate agency — to the tool, the
glance, the label, the vendor. The principle''s whole content is that agency stayed with
you the entire time. Which is also — turn it around — the *good* news, and the license
this module opened with: work you verified, under terms you know, is work you can put
your name on without flinching.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-try-50', 'ai101-m8', 50, 'try_this', 'stable', '### Try this — 3 minutes
The excuse audit. For each of the four — "the AI wrote it," "I reviewed it," "it was
only a draft," "the vendor said it was compliant" — write the one-line honest version:
what would you have needed to *actually do* for the sentence to hold up? You''ve just
written the four working standards of this module; keep them.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-lesson-2-the-agreement-layer-60', 'ai101-m8', 60, 'prose', 'volatile', '## Lesson 2 · The agreement layer [V]

M4 told you what may enter a tool depends on the agreement covering it. This lesson is
that agreement layer up close — because "what happens to what I paste?" has a knowable
answer, it''s in a document, and *you are allowed to ask for it.* Most people never do;
they use tools under terms they''ve never seen and describe the result as a mystery. Three
questions organize everything worth knowing:

**Is my input used to train or improve the models?** The load-bearing question. Consumer
tiers vary and have historically defaulted toward *yes, unless you opt out* **[V]**;
enterprise agreements typically answer *no, contractually*. The difference is the M4
distinction with teeth: material that trains a model may surface, in some transformed
form, outside your control forever. This single question is most of why "the provisioned
tool used well beats the better tool used personally" (M2) is the professional''s answer.

**What''s retained, and for how long?** Even without training, inputs and outputs persist
somewhere — conversation history, vendor logs, safety review **[V]**. Retention determines
what exists to be breached, subpoenaed, or surprised by. Enterprise terms typically
negotiate retention windows and deletion; consumer tiers typically don''t. The M4
connection runs both directions: retention is why redaction mattered, and redaction is
your control when retention isn''t.

**Who can see it?** Vendor staff under what circumstances, your own admins under what
controls, and — increasingly relevant — what the vendor''s own AI features do with your
content inside their platform **[V]**.

What to do with the three questions is a routing rule. **IT/security answers them** — for
each provisioned tool, in writing; if the answer is "we don''t know," you''ve found real
work, and asking it is a contribution, not a nuisance. **Counsel handles what the answers
imply** — whether those terms satisfy your obligations for Tier 3 material, what your
regulators require **[V]**. **You enforce the boundary that follows:** the tier rules of
M4, now with a documented *why* behind them, which is what makes them teachable to your
team instead of arbitrary. And one habit closes the loop: when the answers arrive, put
them where your team can see them — a one-line-per-tool grid ("Tool X: no training,
90-day retention, enterprise terms — Tier 2 OK, Tier 3 redacted only"). That grid is the
most-requested artifact in every organization''s AI rollout, and almost nobody has made
it. Be the one who did.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-lesson-3-disclosure-would-they-feel-misl-70', 'ai101-m8', 70, 'prose', 'stable', '## Lesson 3 · Disclosure — would they feel misled?

Somewhere between "spell-check" and "the AI wrote my performance reviews," AI assistance
starts needing to be said out loud. The interesting question is where — and the answer
that actually works isn''t a percentage of AI involvement. It''s a question about the
*reader*: **would this person feel misled if they learned how this was made?** Misled is
the precise word. Not surprised, not impressed — *misled*: they took the artifact as
evidence of something it isn''t.

Watch the test sort real cases. A job posting drafted by AI from your role spec, edited
and approved by your recruiter? Nobody feels misled — no reader takes a job posting as
someone''s personal prose; the organization stands behind the content, which is exactly
what the artifact claims. A board slide whose numbers came from an AI summary of survey
data? The board takes those numbers as *verified facts* — what needs disclosing isn''t
"AI helped" but provenance and verification status: "figures from the Q3 survey analysis,
methodology in appendix." A condolence note, a personal thank-you, a reference you''re
asked to give *as you* — here the artifact''s entire value is that a person meant it
personally; discovering it was generated voids the thing itself, which is why "AI wrote
my heartfelt note" stories keep ending badly. And the candidate rejection note: the
company''s decision in the company''s voice — AI drafting fine, provided the *decision*
was made the M7 way, which is the thing the reader actually cares about being real.

The pattern the cases reveal: **disclosure tracks the reader''s stake in how it was made,
not the amount of AI involved.** Readers have a stake when the artifact implies a
human''s personal witness (the note, the reference), when they''ll rely on unverified
specifics as verified (the board numbers), or when the making *is* the message. They
have no stake in the mechanics of routine institutional prose — nobody needs a
provenance label on a meeting-notes summary.

Three practices operationalize it. **Per-artifact, ask the test** — it takes five
seconds and it''s usually obvious. **Where disclosure is owed, disclose the useful
thing** — verification status and provenance ("drafted with AI assistance, reviewed and
verified by me") rather than a vague AI-was-here sticker. **And for recurring artifact
types, decide once** — your team shouldn''t re-derive the ethics of AI-assisted JDs
weekly; that''s a norms question, it belongs in the one-pager, and Lesson 4 files it
there. One boundary case gets a flag because it''s yours: *ER documentation and anything
that may become evidence* — where provenance of every sentence can end up examined under
oath **[V]** — routes to counsel''s guidance, not to per-artifact judgment.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-exercise-embed-75', 'ai101-m8', 75, 'exercise', 'stable', '{"type": "sorting", "title": "Calibration exercise \u2014 Would they feel misled?", "intro": "Ten minutes, six pieces of shipped work AI touched. Sort each: disclose (the reader is owed something about how it was made), no disclosure needed (no stake in the mechanics), or shouldn''t have shipped at all (the problem is upstream of disclosure). Commit every card before the reveal.\n\nUse the test: would this reader feel misled to learn how this was made \u2014 did they take the artifact as evidence of something it isn''t?"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-lesson-4-the-five-questions-to-settle-no-80', 'ai101-m8', 80, 'prose', 'stable', '## Lesson 4 · The five questions to settle now

Everything so far in this module is judgment you can exercise alone. This lesson is the
part you can''t do alone — the questions that need legal, IT, and leadership answers, and
that are *cheap to settle now and expensive to settle during an incident.* Five, phrased
to bring to the meeting:

**1. Which tools, which tiers?** The approved-tools grid from Lesson 2 — each tool''s
agreement answers, and what data tier each may touch (M4). This is the question that
retires "is it OK if I paste…?" forever.

**2. Where''s the line, and who owns it?** M7''s one-pager, adopted: what AI must not
decide, who signs off on new people-touching tools, in writing.

**3. What are our disclosure norms?** Lesson 3''s decide-once list: which artifact types
carry a note, what the note says, and who decides novel cases.

**4. What''s our verification standard?** M6''s levels, assigned: what must be true before
AI-assisted work ships — by stakes, with the high-risk surface named — so "I reviewed
it" has organizational content instead of personal interpretation.

**5. What happens when something goes wrong?** The one nobody wants to write and
everyone needs: who gets told when AI-assisted work ships with an error, what''s the
correction path, and — critically — what''s the *no-blame lane* for self-reporting? An
organization that punishes the person who says "my AI-assisted memo had a fabricated
citation, here''s the correction" trains everyone to stop saying it. The incident you
hear about early is cheap; the incident that hides is the expensive one.

Bring the five as a skeleton — proposed answers, not open questions; you have all the
material from seven modules — and you''ll leave the meeting with a policy. Bring them as
worries and you''ll leave with a follow-up meeting. The applied activity has you draft
exactly that skeleton for yourself, which is also the course closing the loop: in M1 you
predicted where AI would help; now you''re writing the terms under which you''ll let it.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-key-takeaways-90', 'ai101-m8', 90, 'takeaways', 'stable', '## Key takeaways

- **The output is a draft, never a decision.** Shipping converts AI output into your
  work — send, file, or say it, and it''s yours. Every excuse on the bad day ("the AI
  wrote it," "I reviewed it," "only a draft," "the vendor said") is a confession about
  relocated agency; the honest versions all have verbs in them.
- **The agreement layer is knowable — ask three questions [V]:** trained on? retained
  how long? visible to whom? IT answers, counsel interprets, you enforce the tier rules
  that follow — and publish the one-line-per-tool grid nobody else has made.
- **Disclosure tracks the reader''s stake, not the AI percentage.** The test: would they
  feel misled about what this artifact is evidence of? Disclose the useful thing —
  verification and provenance, not a vague sticker. Decide once per artifact type.
- **Five questions settle the policy before the incident:** tools and tiers, the line
  and its owner, disclosure norms, verification standards, and the no-blame correction
  path. Bring skeletons, not worries.
- **Ownership is the license, not the tax.** "I use these tools, here''s what I verify,
  here''s my line, my name''s on the result" is the sentence that earns autonomy — and
  the posture 201 builds a practitioner on.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-activity-link-95', 'ai101-m8', 95, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 The One-Pager", "blurb": "The course close: the terms under which you use AI \u2014 use, verify, disclose, refuse \u2014 written so your team could read it Monday, plus the calibration review across every prediction you made in this course. Graded with per-dimension feedback; free unlimited resubmission.", "estMinutes": "25\u201330"}', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-sources-and-attribution-100', 'ai101-m8', 100, 'prose', 'stable', '## Sources and attribution

This module draws on the following material:

- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with
  Anthropic, CC BY-NC-SA 4.0) — the accountability stance and the treatment of
  responsible disclosure adapt its "Diligence" competency; the course''s four-competency
  inheritance (Delegation, Description, Discernment, Diligence) is its framework
  throughout.
- Provider terms of service, data processing agreements, and enterprise documentation —
  training defaults, retention windows, and visibility rules are moving targets; verify
  against your vendor''s current terms and your own agreement. **[V]**
- The excuse audit, the reader''s-stake disclosure test, and the five-question policy
  skeleton are original to this course, developed for the People-leader context.
- Evidentiary treatment of AI-assisted workplace documentation is an evolving area —
  the ER-documentation flag exists because provenance can be examined in ways that
  are jurisdiction- and case-specific. *Counsel''s guidance governs there, not this
  course.* **[V]**', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-activity-applied-activity-the-one-pager-10', 'ai101-m8-activity', 10, 'prose', 'stable', '## Applied activity — "The One-Pager"

**Time:** 25–30 minutes · **Submit:** your one-pager plus a 250–350 word calibration
review · **Graded against the rubric below.** Score doesn''t matter — this one is the
course landing. Doing the work is where the learning lands.

Two parts: the artifact, and the look back.

**Part 1 — Your one-pager (15–20 min).** One page, first person, real: the terms under
which you use AI in your work, written so your manager or team could read it Monday.
Four sections —
- **Use:** the three to five tasks where AI now has a standing place in your week, each
  in one line with its M5-shaped habit ("JDs — drafted from role specs with two
  examples attached, recruiter-reviewed").
- **Verify:** your M6 commitments, by stakes: what gets the scan, what gets claims
  traced, what gets adversarial review — and your personal high-risk surface, named.
- **Disclose:** your Lesson 3 decide-once list — artifact types that carry a note, what
  the note says.
- **Refuse:** your M7 line, in your own words, plus the M4 tiers you won''t move without
  the agreement answers — and the one question you''re taking to IT or counsel first.

**Part 2 — The calibration review (10 min).** Gather your predictions from across the
course — M1''s edges, the stack count, the cost guess, the improvement score, the
attempt count, the wrong-side audit — and score the pattern, not the points: which
direction did you mostly miss, does it match what you predicted at the top of *this*
module, and what does the pattern tell you about your starting posture toward these
tools? End with the one-sentence version you''d say out loud: how your model of AI
changed from Module 1 to now — specific enough that it couldn''t have been written
before you took the course.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-micro-core', 'ai101-m8-micro', 10, 'prose', 'stable', '## Module 8 in two minutes

**The output is a draft, never a decision.** The moment you ship it — send, file, say it — it''s your work, because accountability needs an entity that can answer for it, and a tool can''t hold it. The bad-day excuses are all confessions about relocated agency: "the AI wrote it" (I shipped what I didn''t stand behind), "I reviewed it" (only a defense for what the review could catch), "only a draft" (someone relied on it — that was the shipping), "the vendor said" (their claim stood where my verification belonged).

**The agreement layer is knowable — three questions [V]:** is my input trained on? retained how long? visible to whom? IT answers in writing, counsel interprets, you enforce the tier rules that follow — and publish the one-line-per-tool grid nobody else has made.

**Disclosure tracks the reader''s stake, not the AI percentage.** The test: would they feel misled about what this artifact is evidence of? Institutional prose, no stake. Numbers headed for a board, disclose verification status. Personal witness — the condolence note, the reference given as you — no disclosure fixes a false claim; don''t ship it.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-micro-rule', 'ai101-m8-micro', 20, 'callout', 'stable', '### The rule to carry

Ownership is the license, not the tax: "here''s what I use, here''s what I verify, here''s my line, my name''s on the result" is the sentence that earns autonomy with these tools — and it''s the whole course in one breath.', NULL, '2026-08-11', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai101-m8-micro-close', 'ai101-m8-micro', 30, 'prose', 'stable', '**The full module adds** the excuse audit, the would-they-feel-misled sort (six shipped artifacts, two of which no disclosure can fix), the five questions to settle with legal and IT before the bad day — skeletons, not worries — and The One-Pager: your own use/verify/disclose/refuse terms, plus the calibration review across every prediction the course made you write down.', NULL, '2026-08-11', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m8-sorting', 'ai101-m8', 'sorting', '{"reviewedAt":"2026-08-11","buckets":[{"id":"noship","label":"Shouldn''t have shipped","hint":"The problem is upstream of disclosure","rank":0,"pct":5},{"id":"disclose","label":"Disclose","hint":"The reader is owed provenance or verification status","rank":1,"pct":50},{"id":"none","label":"No disclosure needed","hint":"No stake in the mechanics","rank":2,"pct":90}],"tasks":[{"id":"t1","text":"A job posting drafted by AI from the role spec, edited and approved by the recruiter, published to the careers page","key":"none","reasoning":"No reader takes a job posting as someone''s personal prose — the artifact claims the organization stands behind the content, and it does. No stake in the mechanics."},{"id":"t2","text":"A board slide whose headline figures came from an AI summary of the engagement survey, presented without sourcing","key":"disclose","reasoning":"The board relies on those numbers as verified facts — their stake is in provenance and verification status, not in which software touched them. ''Figures from the Q3 survey analysis, methodology in appendix'' is the useful disclosure; a vague AI sticker is not."},{"id":"t3","text":"A condolence note to an employee who lost a parent, generated by AI and sent under the manager''s name unedited","key":"noship","reasoning":"The note''s entire value is the manager''s personal witness — discovering it was generated voids the thing itself, so no disclosure fixes it. The problem is upstream: this artifact claims something untrue about itself. (Asking AI to help *the manager* find words they then genuinely make their own is a different artifact.)"},{"id":"t4","text":"A candidate rejection email drafted by AI in the company voice, decision made by the hiring panel, reviewed before sending","key":"none","reasoning":"The company''s decision in the company''s voice — the reader''s real stake is that the *decision* was made the M7 way (by humans), and it was. Institutional prose carries no personal-witness claim.","also":["disclose"]},{"id":"t5","text":"An ER investigation summary drafted with AI assistance from the investigator''s notes, headed for the case file","key":"disclose","reasoning":"Anything that may become evidence carries a provenance stake — the file should record how the document was produced and verified, per counsel''s guidance, because every sentence''s origin can end up examined. This is the boundary case the module routes to counsel rather than per-artifact judgment.","also":["noship"]},{"id":"t6","text":"A reference for a former report, which you agreed to give personally, generated by AI from their LinkedIn and sent with your signature","key":"noship","reasoning":"You were asked *as you* — the artifact''s value is your personal knowledge of the person, and it was generated from a public profile you didn''t even verify. Both the personal-witness claim and the factual basis are false. Decline, or write it yourself (AI may polish your substance; it can''t supply it)."}],"pattern":"Disclosure tracks the reader''s stake in how it was made — not the amount of AI involved.","postscript":"The two no-ship cards fail the same way: the artifact itself claims personal witness that didn''t happen, and no note fixes a false claim. The two disclose cards owe the reader something specific — verification status, provenance — not an AI-was-here sticker. And the two clean cards are institutional prose, where the only real stake is that the organization means it. Cards placed above the key treated a reader''s stake as mechanics; below, mechanics as a stake. The applied activity now has you write your own decide-once list, so your team never re-derives these calls artifact by artifact."}', '2026-08-11');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m8-rubric', 'ai101-m8', 'rubric', '{"promptVersion":"ai101-m8-one-pager-v1","moduleId":"ai101-m8","minWords":250,"maxWords":350,"submitLabel":"Your one-pager and calibration review","intro":"Paste the one-pager (all four sections) followed by the 250–350 word calibration review. This is the course close — resubmission is free and unlimited, and the score is a mirror, not a gate.","activityContext":"You are grading the closing submission of an AI fluency course for People leaders (AI 101, The Foundation). Module 8 applied activity, ''The One-Pager'': Part 1 is a first-person, one-page working policy — Use (three to five real tasks with their M5-shaped habits), Verify (M6 commitments sized to stakes, personal high-risk surface named), Disclose (a decide-once list of artifact types with what the note says), Refuse (their M7 line in their own words, M4 tiers they won''t move without agreement answers, and one named question for IT or counsel). Part 2 is a calibration review across the whole course: the predictions they made in earlier modules gathered, the overall direction of miss named and compared against the direction they predicted at the top of this module, and a closing one-sentence account of how their model of AI changed — specific enough that it couldn''t have been written before the course. Learners may not have completed every earlier module or prediction; grade the review on honesty about the pattern in whatever they did complete, never on volume or accuracy. This is the learner''s own working policy, not a compliance document — concreteness and first-person ownership are the standards.","opening":[],"calibration":[],"dimensions":[{"name":"Use and Verify are real and matched","criteria":"The standing uses are recognizable tasks from their actual week, each with a habit attached — and the verification commitments are sized to stakes with the high-risk surface named, not a uniform ''I''ll review everything.'' A modest, keepable set of commitments outscores an aspirational one."},{"name":"Disclose and Refuse have edges","criteria":"The decide-once list names artifact types and what the note says (the useful thing — provenance and verification status, not a sticker). The refusal line names decisions, not technology, in their own words — and the one question for IT or counsel is specific enough to get an answer rather than a shrug."},{"name":"It could circulate Monday","criteria":"First person, one page, concrete enough that their manager or team could read it and know what to expect — and what to ask. Policy-speak, hedging, and borrowed language score low; the test is whether it sounds like a person who means it."},{"name":"The calibration review closes the loop","criteria":"Predictions gathered honestly from whatever modules they completed, the direction of the pattern named and compared to what they predicted this module, and the closing sentence is specific to their own shift — it names something they believed in Module 1 that they no longer believe, or vice versa. Generic endings (''AI is a powerful tool with risks'') fail this dimension."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai101-m8-knowledge_check', 'ai101-m8', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-11","questions":[{"id":"q1","prompt":"What exactly converts AI output from \"a draft\" into \"your work\"?","options":["Editing at least half of it before use","Shipping it — sending, filing, or saying it where someone could rely on it","The tool''s terms of service assigning you the copyright","Nothing — AI-generated content remains the tool''s output permanently"],"correctIndex":1,"explanation":"The boundary is the moment of reliance, not the degree of editing — unedited output you ship is fully yours, and heavily edited output still in your drafts folder is nobody''s yet. That''s also why \"it was only a draft\" fails once a colleague acted on it: sharing it where someone could rely on it *was* the shipping."},{"id":"q2","prompt":"Why does \"the AI wrote it\" fail as a defense — at the level of principle, not just optics?","options":["Because current law hasn''t caught up to AI authorship yet","Because it''s usually false — the human edited the text somewhat","Accountability requires an entity that can answer for the work — be questioned, correct the record, make harm whole — and a tool can''t hold any of it","It doesn''t fail — provenance genuinely mitigates responsibility"],"correctIndex":2,"explanation":"Every mechanism accountability runs on needs a person, which is why provenance of a draft has never mattered: nobody accepts \"the intern wrote it\" from the person who signed. The excuse just relocates agency that never moved."},{"id":"q3","prompt":"Under the excuse audit, what''s the difference between \"I reviewed it\" and a defense that holds?","options":["A defense that holds names what the review actually did — \"I traced its claims against the plan documents\" — and covers only what that could catch","There is no difference — review is review","A holding defense requires a second person to also review the work","\"I reviewed it\" holds as long as the reviewer was senior enough"],"correctIndex":0,"explanation":"M6 priced review precisely: a defense claims what the verification level could actually catch, no more. \"I read it and it sounded right\" is the exact mechanism by which fabrications ship — so the honest version has a verb and a source in it."},{"id":"q4","prompt":"Of the three agreement-layer questions **[V]**, which is load-bearing, and why?","options":["Retention — because deleted data can''t be breached","Whether inputs train or improve the models — because trained-on material may surface, transformed, outside your control forever","Visibility — because vendor staff access is the main exposure","None individually — only the full contract matters"],"correctIndex":1,"explanation":"Training is the irreversible one: retention windows expire and access can be controlled, but what entered a model''s training doesn''t come back out on request. It''s also most of the reason the provisioned tool beats the personal account — the enterprise \"no, contractually\" versus the consumer default **[V]**."},{"id":"q5","prompt":"Your board slide includes figures that came from an AI summary of survey data. What does the disclosure test actually require here?","options":["Nothing — internal slides never require disclosure","A footer stating \"this presentation was created with AI assistance\"","Provenance and verification status — the board will rely on the numbers as verified facts, so what they''re owed is where the figures came from and whether they were checked","Removing the figures, since AI-derived numbers can''t be presented to boards"],"correctIndex":2,"explanation":"The reader''s stake is in the numbers'' *verifiedness*, not in which software touched them — M6 told you numbers get repeated without caveats, which is exactly why their status must travel with them. B discloses the useless thing; the sticker satisfies no stake the board actually has."},{"id":"q6","prompt":"Why do the personal cases — condolence notes, references given as you — sit at the far end of the disclosure spectrum?","options":["They''re legally protected categories of communication","The artifact''s entire value is a person''s personal witness — discovering it was generated voids the thing itself, so no disclosure fixes it","They''re too short for AI assistance to matter","They don''t — all artifacts follow the same disclosure rule"],"correctIndex":1,"explanation":"For institutional prose, the reader''s stake is in the organization standing behind content. Here the making *is* the message — the reader took the artifact as evidence of personal attention, so the failure isn''t undisclosed AI, it''s that the artifact claims something untrue about itself. The test catches this without any percentage rule."},{"id":"q7","prompt":"Why does the fifth question — what happens when something goes wrong — specifically need a no-blame lane for self-reporting?","options":["Because blame-free cultures are more pleasant to work in","To satisfy whistleblower-protection requirements","Because punishing the self-report trains everyone to stop reporting — and the incident that hides is the expensive one","It doesn''t — accountability requires consequences for errors"],"correctIndex":2,"explanation":"The incentive design is the point: you want the fabricated citation surfaced by its author on Tuesday, not discovered by opposing counsel in a year. D confuses accountability (owning and correcting the work) with punishment (which, applied to self-reports, purchases silence at the worst price available)."},{"id":"q8","prompt":"The module calls ownership \"the license, not the tax.\" What does that mean in practice?","options":["Organizations should license AI tools before taxing their use","Ownership costs are deductible against AI productivity gains","Accepting accountability is the price of being left alone by IT","The person who can say \"here''s what I use, verify, disclose, and refuse — my name''s on it\" earns autonomy with the tools and becomes who others trust on them"],"correctIndex":3,"explanation":"The one-pager isn''t defensive paperwork — it''s the sentence that lets you use everything the course taught without asking permission per use, and it''s the posture 201 assumes: you can only own what you understand, and now you do."}]}', '2026-08-11');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-calibration-prompt-before-you-start-10', 'ai201-m1', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One question, thirty seconds. You''ll come back to it at the end of the course.*

Think of the recurring task you would most like to hand to AI.

**How many hours a month does it actually cost you right now?**

Write the number down. Most practitioners discover in Module 7 that their estimate was off by
half — in one direction or the other — and the direction says a lot about which workflows they
should build first.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-module-brief-20', 'ai201-m1', 20, 'prose', 'stable', '## Module brief

You finished 101, which means you can do something most of your peers can''t: predict what an AI
tool will do well before you ask, brief it properly when you do, and catch it when it''s
confidently wrong. That''s real fluency. And if you''re honest about your week since then, you''ve
probably noticed something irritating about it.

Everything you do with AI, you do by hand, from scratch, every time.

You re-explain your company''s voice before every draft. You re-describe what a good interview
debrief looks like every Thursday. The survey summary that took ninety minutes in March took
ninety minutes again in June, because nothing you learned in March was written down anywhere the
tool could see. You''ve become a skilled artisan working without a workshop — every piece
handmade, quality depending on your energy that day, nothing repeatable, nothing you could hand
to anyone else.

The jump from Novice to Practitioner is not learning more about AI. It''s the jump from **tasks to
systems**: from "I used AI for this" to "this runs every week, the same way, with checks built
in, and I could show a colleague how." That jump is what this course is for, and it starts with a
change of lens, not a change of tools.

**One build, eight modules.** At the end of this module you will choose a single workflow from
your own week and write its spec. Every module that follows advances that same build: its context
pack in M2, its pipeline in M3, its verification design in M4, and so on until M8, where you run
it for real and prove what it saved. Choose like it matters, because you''ll be living with this
choice for a while. The good news: this module''s whole job is teaching you how to choose.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-learning-objectives-30', 'ai201-m1', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Name the five parts every repeatable workflow has, and find them in a task you already do.
2. Audit your own week and surface the tasks that earn the workflow treatment.
3. Apply the selection rules — and explain why "most annoying" and "highest stakes" are both
   wrong answers for a first build.
4. Write a five-part workflow spec concrete enough that a colleague could challenge it.
5. State the practitioner''s extension of the delegation heuristic from memory.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-lesson-1-the-anatomy-40', 'ai201-m1', 40, 'prose', 'stable', '## Lesson 1 · The anatomy

Every repeatable workflow has the same five parts. Not because a framework says so, but because
when any part is missing, the thing stops being a workflow and goes back to being an improvisation.

**Trigger.** What makes it run: a day of the week, an event ("interviews finished"), an arrival
("survey closed," "notes exist"). If you can''t name the trigger, you don''t have a workflow — you
have a task you sometimes remember.

**Inputs.** The material you supply, and where it lives. 101''s central lesson — the model knows
only what you give it — becomes an inventory question here: *which documents, in which state, from
where?* Vague inputs are where workflows quietly die.

**Transformation.** What the model actually does: summarize, restructure, draft variants,
translate registers, extract themes. One transformation per step. If you find yourself writing
"and then it also decides…" — stop. That''s not a transformation, and Lesson 3 has words for you.

**Verification.** Who or what checks the output, how, and against what standard — *before* it
reaches anyone it could affect. In most people''s implicit workflows this part simply doesn''t
exist, which is why it gets its own module (M4) and a hard rule: you may not automate what you
can''t verify.

**Output and owner.** What leaves the workflow, in what format, and — non-negotiable — the one
human whose name is on it. An output nobody owns is an incident that hasn''t happened yet.

Here''s the useful part: every recurring task you already do with AI has these five parts
*implicitly*. Drawing them out doesn''t add bureaucracy; it exposes which part was always missing.
It''s almost always verification. Sometimes it''s the trigger — which is why the task happens in
March and then not again until someone''s embarrassed in June.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-try-50', 'ai201-m1', 50, 'try_this', 'stable', '### Try this — 3 minutes
Take the last thing you used AI for at work. Any task, however small.

1. Name its five parts out loud: trigger, inputs, transformation, verification, output/owner.
2. Notice which one you can''t name crisply.
3. Ask: if this ran next month without you remembering March, what would break?

That missing part is not a personal failing. It''s the difference between artisan work and a
system, and it''s exactly what this course builds.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-lesson-2-the-audit-60', 'ai201-m1', 60, 'prose', 'stable', '## Lesson 2 · The audit

You can''t choose a first build from memory, because memory surfaces the *loudest* task, not the
best candidate. The audit is a structured pass over your actual week, and it takes twenty minutes.

Pull up last week''s calendar and sent mail. List every task that meets all three of these:

- **It recurs.** Weekly, monthly, per-event — but on a rhythm. One-offs, however painful, don''t
  make the list.
- **It has a shape.** The same kind of input goes in and the same kind of output comes out, every
  time. If each occurrence is genuinely different, it''s not structured — it''s a series of
  judgment calls that happen to recur.
- **You supply the material.** The inputs exist and you control them: your notes, your data
  export, your policy text. If the task needs knowledge nobody has written down, 101 told you
  exactly what the model will do with that gap — fill it, fluently, from nothing.

For each task that survives, score two more things, low/medium/high:

- **Stakes.** What happens if a bad version ships? A clumsy newsletter is low. Anything that
  touches a named person''s pay, performance, or employment is high — and flagged for a different
  conversation entirely.
- **Current cost.** Honest hours per month. Not how much you resent it — how long it takes.

Most People leaders'' audits surface the same families: interview notes → debriefs, survey
verbatims → themes, policy text → plain-language versions, data exports → narrative summaries,
bullet points → recurring communications. Yours will have its own shape, but expect between five
and ten survivors. That''s your candidate pool — you only need one.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-try-70', 'ai201-m1', 70, 'try_this', 'stable', '### Try this — the audit itself, 20 minutes
Do the real thing, now if you can:

1. Open last week''s calendar and sent mail. List recurring tasks — aim past ten before you judge
   any of them.
2. Strike everything that fails the three tests: recurs, has a shape, you supply the material.
3. Score survivors for stakes and honest monthly cost.
4. Circle the three with the best cost-to-stakes ratio.

Keep the list. The sorting exercise below will sharpen your instincts before you commit to one.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-lesson-3-the-selection-rules-80', 'ai201-m1', 80, 'prose', 'stable', '## Lesson 3 · The selection rules

You have candidates. Here is how practitioners choose — and the two seductive wrong answers to
refuse.

**Wrong answer one: the most annoying task.** Annoyance measures how you feel, not whether the
task can be systematized. The task you hate most is often hateful precisely *because* it resists
structure — every instance different, inputs scattered, judgment throughout. A first build there
fights the structure problem and the learning problem at the same time.

**Wrong answer two: the highest-stakes task.** The logic seems noble — "if I''m going to invest,
invest where it matters most." But your first workflow is where you''ll make your learning
mistakes, and high-stakes work is where mistakes cost the most and verification is hardest to
design. You don''t learn to drive on the motorway.

**The right first build scores like this:**

- **High frequency** — it runs at least weekly, so feedback comes fast and time savings compound.
- **High structure** — same shape in, same shape out, so the transformation stays simple.
- **You own the inputs** — no waiting on other people''s data or undocumented knowledge.
- **Low-to-medium stakes** — a bad output embarrasses nobody and harms nobody while you learn.

Boring is a feature. The interview-notes debrief and the bullet-points newsletter are unglamorous
and perfect. Your first build''s job is not to impress anyone; it''s to teach you the anatomy on
something that can''t hurt you, so your *second* build — the one with real leverage — inherits
working habits instead of hopeful ones.

And one boundary, before the exercise makes it concrete. 101 gave you the delegation heuristic;
201 extends it one level up, and this is the course''s spine:

> **You may only systematize what you have verified by hand. And a workflow, like a model, must
> not make decisions about people — automation makes decisions faster, not fairer.**

The second sentence has teeth that surprise people. A workflow that *drafts* a rejection email
transforms material. A workflow that decides *who gets one* has crossed the line, no matter how
good the model is, and "a human clicks approve" doesn''t move the line back if the human stopped
reading. The gray zone — decision-support whose default quietly becomes the decision — gets its
own test in M5. For now the plain rule shapes which tasks are even candidates.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-sort', 'ai201-m1', 85, 'exercise', 'stable', '{"type": "sorting", "title": "Sorting exercise \u2014 Workflow it, keep it manual, or never?", "intro": "Ten minutes. Twelve tasks from a People leader''s real week. Sort each into **workflow it**, **keep it manual**, or **never systematize**.\n\nThe pattern the key will show you, stated in advance so you can test it as you sort: workflow the recurring transformations of material you own. Keep manual the judgment calls that happen to recur \u2014 and anything that happens once. Never systematize decisions about people.\n\nNothing reveals until all twelve are committed."}', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-key-takeaways-90', 'ai201-m1', 90, 'takeaways', 'stable', '## Key takeaways

- **Fluency isn''t practice.** 101 taught you to use AI well; nothing about using it well makes it
  repeatable. That''s a different skill, and it''s a systems skill.
- **Five parts, always:** trigger, inputs, transformation, verification, output-with-owner. The
  part you can''t name is the part that fails in June.
- **Audit, don''t remember.** Memory nominates the loudest task; the calendar and sent mail
  nominate the true candidates.
- **First build: high frequency, high structure, owned inputs, low stakes.** Boring is a feature.
  The impressive build comes second, and inherits working habits.
- **The practitioner''s heuristic:** only systematize what you''ve verified by hand — and a
  workflow must not make decisions about people. Automation makes decisions faster, not fairer.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-activity-link', 'ai201-m1', 95, 'exercise', 'stable', '{"type": "activity_link", "title": "Capstone stage 1 \u2014 Pick it and spec it", "blurb": "Choose one workflow from your audit and write its five-part spec: trigger, inputs, transformation, verification, output and owner. Two predictions first; AI-graded against the module rubric. This spec is the artifact every later module builds on.", "estMinutes": "20\u201325"}', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-sources-and-attribution-110', 'ai201-m1', 110, 'prose', 'stable', '## Sources and attribution

Builds directly on AI 101 Module 1 (delegation heuristic, training-data bias, vendor questions)
and Module 6 (verification habits). Workflow anatomy synthesized for this course; the
selection-rule framing (frequency × structure × ownership × stakes) is original to the course.
*Cross-references to be verified against the final 101 module numbering before publication.*', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-activity-capstone-stage-1-pick-it-and-spec-it-10', 'ai201-m1-activity', 10, 'prose', 'stable', '## Capstone stage 1 · Pick it and spec it

This is the module''s applied activity, and the first artifact of your eight-module build.

**Choose one workflow** from your audit — the selection rules are your guide, and "boring but
weekly" beats "impressive but quarterly."

**Predict first, two numbers.** Before writing the spec, record: (1) honest hours per month the
task costs you today; (2) the percentage of that time you expect the workflow to save within a
month of shipping. As with everything calibration in this course, you''re graded on honesty and
specificity, never on being right.

**Write the five-part spec:**

- **Trigger** — what makes it run, concretely enough to schedule.
- **Inputs** — each source of material, where it lives, and what state it arrives in.
- **Transformation** — what the model does, as verbs. One transformation per step; if you need
  three steps, say so.
- **Verification** — how you''ll check output before it ships, even roughly. "I read all of it"
  is legitimate at this stage; M4 will make it cheaper. A blank here is the one thing the spec
  can''t survive.
- **Output and owner** — format, destination, and the named human accountable. (That''s you. Write
  it anyway. It matters in M8, when someone else runs this.)

**Then defend the choice** in a paragraph: why this one, against the selection rules — frequency,
structure, input ownership, stakes. If you rejected a more tempting candidate, say which and why.
That reasoning is worth more than the spec itself.

**[V]** Where to keep it: start a dedicated Claude Project for your build and put the spec in its
knowledge. Every module from M2 on adds to that same Project — by M8 it will contain your whole
workflow. If your organization uses a different provisioned tool, your deployment''s lab track
shows the equivalent home.

### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Spec concreteness** | All five parts present and specific enough that a colleague could challenge them. Inputs name real sources; the transformation is verbs, not vibes. |
| **Selection reasoning** | The choice is defended against the selection rules, honestly scored for frequency, structure, ownership, and stakes — including what was rejected and why. |
| **Verification exists** | The verification part is present and matched to stakes. It can be modest; it cannot be missing or hand-waved. |
| **Calibration** | Both predictions recorded before the spec, with enough specificity to score in M7. Honesty and precision graded; accuracy never. |', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-micro-core', 'ai201-m1-micro', 10, 'prose', 'stable', '## Module 1 in two minutes

**Fluency isn''t practice.** 101 taught you to use AI well; nothing about using it well makes it repeatable. Everything you do with AI is still handmade — context retyped, quality varying with your energy, nothing a colleague could run. The Practitioner''s jump is from tasks to systems.

**Every repeatable workflow has five parts:** trigger, inputs, transformation, verification, output-with-owner. Your recurring tasks already have these parts implicitly; drawing them out exposes which one is missing. It''s almost always verification.

**Audit, don''t remember.** Memory nominates the loudest task; last week''s calendar and sent mail nominate the true candidates. A candidate must recur, have a shape, and run on material you supply.

**Your first build: high frequency, high structure, owned inputs, low stakes.** Not the most annoying task (annoyance often means the task resists structure) and not the highest-stakes one (you''ll make your learning mistakes on it). Boring is a feature — the impressive build comes second, and inherits working habits.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-micro-heuristic', 'ai201-m1-micro', 20, 'callout', 'stable', '### The practitioner''s heuristic

You may only systematize what you have verified by hand. And a workflow, like a model, must not make decisions about people — automation makes decisions faster, not fairer.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m1-micro-close', 'ai201-m1-micro', 30, 'prose', 'stable', '**The full module adds** the audit method, the selection rules with their two seductive wrong answers, a twelve-task sorting exercise from a People leader''s real week, and the capstone''s first stage: choosing your build and writing its five-part spec — the artifact all seven later modules advance.', NULL, '2026-08-07', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m1-sorting', 'ai201-m1', 'sorting', '{"buckets":[{"id":"workflow","label":"Workflow it","hint":"Recurring transformation of material you own","rank":2,"pct":85},{"id":"manual","label":"Keep it manual","hint":"Judgment-heavy, or a true one-off","rank":1,"pct":50},{"id":"never","label":"Never systematize","hint":"Decisions about people","rank":0,"pct":15}],"tasks":[{"id":"t1","text":"Turning each week''s interview notes into structured debriefs","key":"workflow","reasoning":"The canonical first build: weekly, structured, your notes."},{"id":"t2","text":"Drafting the monthly people-metrics narrative from a data export you own","key":"workflow","reasoning":"Your export, same shape monthly; verification catches the numbers."},{"id":"t3","text":"Deciding which of two finalists receives the offer","key":"never","reasoning":"A decision about a person. It isn''t about capability, and it doesn''t move for better models."},{"id":"t4","text":"Refreshing job postings each quarter to strip jargon and drift","key":"workflow","reasoning":"Quarterly but perfectly structured — pure transformation."},{"id":"t5","text":"Responding to an employee''s grievance email","key":"manual","reasoning":"Arrives on a rhythm, but each one is a distinct human situation carrying legal weight. AI can help you understand a policy; the response is authored, not generated."},{"id":"t6","text":"Summarizing exit-interview verbatims at quarter end","key":"workflow","reasoning":"Same pattern as engagement summaries — with the same caveat: read the raw comments too."},{"id":"t7","text":"Setting performance ratings ahead of calibration","key":"never","reasoning":"The decision where bias stops being abstract: automation reproduces patterns at scale and speed, and adverse impact is the mechanism."},{"id":"t8","text":"Drafting the weekly HR newsletter from bullet points you supply","key":"workflow","reasoning":"Low stakes, weekly, you supply every bullet."},{"id":"t9","text":"Writing this year''s reduction-in-force communication","key":"manual","reasoning":"A one-off, and one of the highest-stakes documents you''ll ever write. Fails the ''recurs'' test before stakes even enter it."},{"id":"t10","text":"Translating policy updates into plain-language change notes","key":"workflow","reasoning":"Text in, plainer text out."},{"id":"t11","text":"Screening résumés for a hard-to-fill role","key":"never","reasoning":"A decision about people — and the place your vendors quietly systematize it for you. You wrote the questions to ask them in 101."},{"id":"t12","text":"Preparing talking points for a sensitive conversation with a specific employee","key":"manual","reasoning":"The material that matters — history, relationship, what you know that isn''t written down — is exactly what no system holds."}],"pattern":"Workflow the recurring transformations of material you own. Keep manual the judgment calls that happen to recur — and anything that happens once. Never systematize decisions about people.","postscript":"If you missed several, look at which kind. Putting judgment calls in ''workflow it'' means you''ll build something that launders discretion through a template. Putting good transformations in ''keep it manual'' means the artisan tax continues for no reason. Both are fixable; that''s what the selection rules are for."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m1-rubric', 'ai201-m1', 'rubric', '{"promptVersion":"ai201-m1-spec-v1","moduleId":"ai201-m1","minChars":600,"submitLabel":"The five-part spec + your selection reasoning","intro":"Write the five-part spec — trigger, inputs, transformation, verification, output and owner — then defend the choice against the selection rules, including what you rejected and why. Resubmission is free and unlimited.","activityContext":"The learner is submitting Capstone Stage 1 of AI 201: a five-part workflow spec (trigger, inputs, transformation, verification, output/owner) for one workflow chosen from an audit of their own week, plus a paragraph defending the selection against the module''s rules (high frequency, high structure, owned inputs, low-to-medium stakes).","calibration":[{"key":"hours","label":"Prediction 1 — hours/month this task costs you today","hint":"Honest hours, not resentment. Scored for honesty in Module 7.","placeholder":"e.g. 6","min":0,"max":200},{"key":"savings","label":"Prediction 2 — % of that time the workflow saves within a month","hint":"Recorded before you build. Direction of error is the lesson.","placeholder":"e.g. 50","min":0,"max":100}],"dimensions":[{"name":"Spec concreteness","criteria":"All five parts present and specific enough that a colleague could challenge them. Inputs name real sources; the transformation is verbs, not vibes."},{"name":"Selection reasoning","criteria":"The choice is defended against the selection rules, honestly scored for frequency, structure, ownership, and stakes — including what was rejected and why."},{"name":"Verification exists","criteria":"The verification part is present and matched to stakes. It can be modest; it cannot be missing or hand-waved."},{"name":"Calibration","criteria":"Both predictions recorded before the spec, with enough specificity to score in Module 7. Honesty and precision graded; accuracy never."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m1-knowledge_check', 'ai201-m1', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the capstone spec is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"What most reliably separates a workflow from a one-off AI task?","options":["It uses a more capable model","It has a named trigger, and runs the same way without you re-inventing it each time","It saves more than an hour a week","It involves more than one prompt"],"correctIndex":1,"explanation":"The anatomy is the definition: a trigger and a repeatable shape. Model choice, time saved, and prompt count are all properties a workflow *might* have; the trigger and the sameness are what make it one."},{"id":"q2","prompt":"Which part of the anatomy is most often missing from people''s implicit workflows?","options":["The trigger","The inputs","Verification","The output format"],"correctIndex":2,"explanation":"Almost everyone has an intuitive trigger, inputs, and output. Almost nobody has designed the checking step — which is why it gets its own module and why the spec cannot ship without it."},{"id":"q3","prompt":"Why is \"the task that annoys me most\" a poor basis for a first build?","options":["Annoying tasks are usually someone else''s responsibility","Annoyance often signals the task resists structure — each instance different, judgment throughout","First builds should target the highest-stakes work instead","It isn''t — high annoyance is a good proxy for high value"],"correctIndex":1,"explanation":"The tasks that grate hardest often do so *because* they won''t routinize. And C is the other seductive wrong answer: high stakes belong with your second build, after the habits work."},{"id":"q4","prompt":"A workflow drafts rejection emails from your notes on each candidate. Another selects which candidates receive them. Under the practitioner''s heuristic:","options":["Both are acceptable if a human clicks approve","Neither is acceptable in People work","The first transforms material you supply; the second makes a decision about people, and stays with a human","Both are acceptable once the model is accurate enough"],"correctIndex":2,"explanation":"Drafting is transformation — the center of the model''s competence. Selection is a decision about a person, and the heuristic''s second sentence doesn''t bend for accuracy (D) or for a rubber-stamp click (A) if the human has stopped genuinely deciding."},{"id":"q5","prompt":"What makes \"you supply the material\" a hard requirement for a workflow candidate?","options":["Supplied material is cheaper to process","Without it, the model fills the gap with fluent invention — 101''s central failure mode, now on a schedule","It''s a data-privacy requirement","It keeps the context window small"],"correctIndex":1,"explanation":"A one-off hallucination is an error; a scheduled workflow built on missing inputs is an error *generator*. The audit''s third test exists to catch this before you build on it."},{"id":"q6","prompt":"Your first build should score:","options":["High frequency, high structure, owned inputs, low-to-medium stakes","High stakes, high visibility — invest where it matters most","Low frequency, so mistakes surface slowly","Whatever your manager most wants automated"],"correctIndex":0,"explanation":"Fast feedback, simple transformation, no dependency on others'' data, and mistakes that can''t hurt anyone while you learn. The high-stakes build is the second one."},{"id":"q7","prompt":"The audit uses last week''s calendar and sent mail rather than your recollection because:","options":["Memory surfaces the loudest task, not the best candidate","Calendars record time more precisely","It produces documentation for your manager","Sent mail shows which tasks involve other people"],"correctIndex":0,"explanation":"The point is candidate *selection*, and recollection is biased toward recency and resentment. The paper trail is flatter and more honest."},{"id":"q8","prompt":"\"A workflow, like a model, must not make decisions about people.\" The strongest reason, from this course:","options":["Regulation prohibits all AI involvement in HR decisions","Models aren''t yet accurate enough for employment decisions","Automation reproduces bias patterns at scale and speed — adverse impact''s mechanism — and accuracy doesn''t cure it","Employees prefer decisions made by humans"],"correctIndex":2,"explanation":"A is false (regulation targets specific decision contexts, as 101 covered), and B fails because the rule survives arbitrary accuracy: the issue is what a decision *is*, not how well a system scores. D may be true but is not the mechanism."}]}', '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-calibration-prompt-before-you-start-10', 'ai201-m2', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*Two predictions, thirty seconds. You''ll score them at the end of the module.*

By the end of this module you''ll have built a context pack for the workflow you specced in M1.

1. **How many distinct items will it need?** (A voice guide is one item. An example debrief is
   one item.) Write down a number.
2. **Which item will be hardest to write?** Name it.

Most people guess high on the first and wrong on the second. The miss is the lesson.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-module-brief-20', 'ai201-m2', 20, 'prose', 'stable', '## Module brief

In 101 you learned the single most important fact about these systems: output quality is mostly
determined by the material you supply. Then you spent every week since re-supplying it.

Think about what you actually did the last time you asked AI to draft something in your
company''s voice. You explained the voice. Again. You described what a good version looks like.
Again. You pasted the same three paragraphs of background that you pasted last Tuesday, from the
same document, with the same typo. Practitioners call this the **artisan tax**: the cost of
re-briefing a capable stranger who forgets you the moment you close the tab — paid per
conversation, forever.

101 told you why the tax exists: the model has no memory of you, and each conversation starts
from nothing but its training plus what you hand it. The Novice pays the tax every time. The
Practitioner notices that *the material barely changes between payments* — and writes it down
once, somewhere the tool can always see.

That once-written material is the **context pack**: the stable briefing for one workflow,
separated from the material that genuinely changes each run. Building the distinction between
those two — what keeps, what arrives fresh, and what must never be written into infrastructure at
all — is this module. It is the highest-leverage hour in this course: everything M3 through M8
builds runs on the packs you learn to make here.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-learning-objectives-30', 'ai201-m2', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain the artisan tax and identify where you''re currently paying it.
2. Split any workflow''s material into pack (durable), fresh (per-run), and excluded (never
   infrastructure) — and defend each placement.
3. Build a working context pack in your organization''s provisioned tool, using instructions and
   knowledge for what each does best. **[V]**
4. Date-stamp pack content and set a review cadence, so your context doesn''t rot into confident
   misinformation.
5. State the boundary rule: people data must never become infrastructure.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-lesson-1-from-prompt-to-pack-40', 'ai201-m2', 40, 'prose', 'stable', '## Lesson 1 · From prompt to pack

A prompt is what you say once. A pack is what stays true between runs.

The distinction sounds trivial until you inventory a real task. Take the interview-debrief
workflow — the canonical first build from M1. Every Thursday, some of what you give the model is
new: this week''s notes, these candidates, this role. But most of it is *identical week to week*:

- What a good debrief looks like (structure, length, what a hiring manager actually reads)
- Your company''s voice — direct, warm, no exclamation points, whatever yours is
- The competency language your org uses, and what each term means
- What the model should do when the notes are thin ("flag the gap; never fill it")
- The output format the ATS or the hiring team expects

That second list is the pack. It''s the part of every prompt you were retyping — or worse,
half-retyping, differently each time, which is why Tuesday''s output and Thursday''s output had
different personalities.

Notice what the pack really is: **your M1 spec''s "inputs" line, split by rate of change.** Fast
material stays per-run. Slow material gets written once, well, and attached always. In 101''s
vocabulary: you''re not teaching the model anything (you can''t — training already happened).
You''re arranging for the briefing to be permanently in view instead of re-performed.

The payoff compounds in three directions at once. Consistency: outputs stop depending on how
completely you briefed today. Speed: the per-run prompt shrinks to just what''s new. And
transfer — the sleeper benefit that pays off in M8: a colleague who can see your pack can run
your workflow. The artisan''s skill was trapped in the artisan. The practitioner''s is written down.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-try-50', 'ai201-m2', 50, 'try_this', 'stable', '### Try this — 3 minutes
Find the last three prompts you wrote for the same kind of task (sent mail to yourself, chat
history, wherever they live).

1. Highlight every sentence that appears, in some form, in more than one of them.
2. That highlighted material is pack content you''ve been paying the artisan tax on.
3. Notice whether the *unhighlighted* parts are genuinely per-run material — or briefing you
   forgot to repeat, which explains the run that came out worse.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-lesson-2-what-goes-in-and-what-stays-out-60', 'ai201-m2', 60, 'prose', 'stable', '## Lesson 2 · What goes in — and what stays out

Three bins, and the discipline to keep them separate. This sorting is the module''s core skill.

**The pack: durable and impersonal.** Material that''s true for months and identifies nobody.
The test is two questions: *Will this still be right in ninety days?* and *Does it name or
describe an identifiable person?* Only yes-and-no earns a place. Typical residents:

- **A gold-standard example.** The single best output you''ve ever produced for this workflow,
  lightly annotated. One great example outworks three paragraphs of description — 101 M5 taught
  you why: you''re narrowing the prediction toward a target you''ve actually shown.
- **The definition of done.** A checklist the output must pass. This becomes load-bearing in M4,
  when verification needs something to verify *against*.
- **Voice and register.** Not "professional but friendly" — actual rules, with a before/after
  pair.
- **The glossary.** Your org''s acronyms, level names, competency terms. The model has never seen
  your org (101, Lesson 4); this is the piece of your org it may safely see.
- **The org context brief.** What the company does, roughly how big, how the team is shaped — no
  names, no numbers you''d redact from a conference talk.

**Fresh: this run''s material.** The reason the workflow runs at all — this week''s notes, this
quarter''s verbatims, the policy paragraph being rewritten today. It arrives, gets transformed,
and leaves. Putting fresh material in the pack is how you get March''s survey themes confidently
cited in June: the second way context rots, and the quieter one.

**Excluded: people data.** Here the module plants a flag, and M6 will build the full fence:

> **People data must never become infrastructure.**

A named employee''s performance history. Grievance details. A raw HRIS export with IDs. The
moment material like this is written into a pack, you''ve turned a one-time judgment call ("may I
paste this, here, today, under this agreement?") into a standing condition nobody re-decides —
sitting in every future conversation, visible to every future run, long after you''ve forgotten
it''s there. Even when a single run may legitimately touch sensitive material (M6 covers when and
how), it enters as fresh input, under that run''s judgment, and leaves with it. Infrastructure is
forever; people data must not be.
', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-exercise', 'ai201-m2', 65, 'exercise', 'stable', '{"type": "sorting", "title": "Sorting exercise — Pack it, fresh, or keep it out?", "intro": "Ten minutes. Twelve pieces of material from a People leader''s workflows. Sort each into **lives in the pack**, **supplied fresh each run**, or **never enters the system**.\n\nThe pattern, stated in advance so you can test it as you sort: durable and impersonal lives in the pack; run-specific material arrives fresh and leaves with the run; anything identifying a person never becomes infrastructure.\n\nNothing reveals until all twelve are committed."}', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-lesson-3-the-lab-building-it-in-claude-70', 'ai201-m2', 70, 'prose', 'volatile', '## Lesson 3 · The lab — building it in Claude [V]

*This lesson is volatile layer: it describes a specific tool as it currently works. If your
organization provisions a different tool, your lab track shows the equivalent steps there.*

Claude''s home for a context pack is a **Project**: a workspace where instructions and reference
files persist across every conversation started inside it. The mechanics take ten minutes; the
design judgment is what you brought from Lessons 1 and 2.

**Step 1 — Create the Project.** One project per workflow, named after the workflow, not the
tool ("Interview debriefs," not "Claude experiments"). Your capstone build gets its own; you
started it in M1 if you followed the pointer.

**Step 2 — Instructions: the standing brief.** Project instructions are applied to every
conversation in the project — they are the part of the briefing that should always be in force.
Keep them short and behavioral: the role ("You turn my raw interview notes into structured
debriefs for hiring managers"), the definition of done, the voice rules, and the failure
instruction ("When the notes don''t cover a competency, say so — never fill the gap"). If it
reads like a job description for the workflow, it''s right. If it''s three pages, you''ve pasted
knowledge into instructions — move it.

**Step 3 — Knowledge: the reference shelf.** Upload the pack''s reference documents: the
gold-standard example, the glossary, the org brief, the style guide. Knowledge is consulted as
needed rather than recited every turn — the right home for material that''s *sometimes* relevant.
The rule of thumb: **instructions are what it must always do; knowledge is what it may need to
look at.**

**Step 4 — Run it fresh.** Start a new conversation in the project and give it only fresh
material — this week''s notes, nothing else. Watch what you didn''t have to say. That silence is
the artisan tax, refunded.

**Two cautions from 101, now operational.** First: conversations inside a project do not teach
the project — nothing you say in a chat updates instructions or knowledge unless you edit them
deliberately. The pack changes when you change it, which is exactly what makes it auditable.
Second: the context window is still finite. Knowledge is not unlimited storage; every stale
document you leave in it crowds something current out of view.

**[V]** *Parity note:* in ChatGPT, the equivalent shape is a Project (or a custom GPT) —
instructions map to instructions, knowledge to attached files, with the same design judgment
applying. The concepts in this module do not care which tool you''re in; only this lesson does.', NULL, '2026-08-07', 'claude');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-lesson-3-the-lab-building-it-in-claude-70-chatgpt', 'ai201-m2', 70, 'prose', 'volatile', '## Lesson 3 · The lab — building it in ChatGPT [V]

*This lesson is volatile layer: it describes a specific tool as it currently works. Your
organization provisions ChatGPT, so your lab track shows the steps there.*

ChatGPT''s home for a context pack is a **Project**: a workspace where instructions and files
persist across every conversation started inside it. (A custom GPT is the shareable cousin —
same design judgment, packaged for other people to use; start with a Project for your own
workflow.) The mechanics take ten minutes; the design judgment is what you brought from
Lessons 1 and 2.

**Step 1 — Create the Project.** One project per workflow, named after the workflow, not the
tool ("Interview debriefs," not "ChatGPT experiments"). Your capstone build gets its own; you
started it in M1 if you followed the pointer.

**Step 2 — Instructions: the standing brief.** Project instructions apply to every conversation
in the project — they are the part of the briefing that should always be in force. Keep them
short and behavioral: the role ("You turn my raw interview notes into structured debriefs for
hiring managers"), the definition of done, the voice rules, and the failure instruction ("When
the notes don''t cover a competency, say so — never fill the gap"). If it reads like a job
description for the workflow, it''s right. If it''s three pages, you''ve pasted knowledge into
instructions — move it.

**Step 3 — Files: the reference shelf.** Upload the pack''s reference documents to the project:
the gold-standard example, the glossary, the org brief, the style guide. Files are consulted as
needed rather than recited every turn — the right home for material that''s *sometimes* relevant.
The rule of thumb: **instructions are what it must always do; files are what it may need to
look at.**

**Step 4 — Run it fresh.** Start a new conversation in the project and give it only fresh
material — this week''s notes, nothing else. Watch what you didn''t have to say. That silence is
the artisan tax, refunded.

**Three cautions, one of them ChatGPT-specific.** First: conversations inside a project do not
teach the project — nothing you say in a chat updates instructions or files unless you edit
them deliberately. Second: **ChatGPT''s account-level Memory is a different mechanism entirely**
— it quietly accumulates details across your chats, which is the opposite of the auditable pack
you just built. For workflow work, check what Memory holds (and consider excluding your
workflow projects from it): a pack should change only when you change it, and M6 will have
sharper words about people-details accumulating in places nobody reviews. Third: the context
window is still finite — every stale file crowds something current out of view.

**[V]** *Parity note:* in Claude, the equivalent shape is a Project — instructions map to
instructions, files to project knowledge, with the same design judgment applying. The concepts
in this module do not care which tool you''re in; only this lesson does.', NULL, '2026-08-08', 'chatgpt');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-try-80', 'ai201-m2', 80, 'try_this', 'stable', '### Try this — the ten-minute version
Even if your capstone lab comes later, feel the mechanics now:

1. Create a project for any recurring task. Write three sentences of instructions: role,
   definition of done, one failure rule.
2. Upload one gold-standard example as knowledge.
3. Run the task fresh, supplying only today''s material.
4. Compare against your last unpacked attempt. The difference is what you''ve been retyping.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-lesson-4-context-rots-90', 'ai201-m2', 90, 'prose', 'stable', '## Lesson 4 · Context rots

The pack you built today is correct today. That sentence has an expiry date, and nobody will
tell you when it passes.

The org chart brief goes stale at the next reorg. The comp philosophy one-pager survives until
the cycle changes it. The voice guide outlives both — until a rebrand. Pack content doesn''t fail
loudly like a broken link; it fails the way 101 taught you fluent output fails: the model keeps
producing confident, well-formed answers built on last quarter''s truth. **Stale context is a
hallucination you installed yourself.**

The fix is a discipline you''ve already seen working — this course runs on it. Every module page
carries two stamps: concepts reviewed on one date, examples current as of another, because the
two layers age at different speeds. Your pack deserves the same split:

- **Date-stamp every item.** A line at the top: `Reviewed: 2026-08-07`. Thirty seconds at
  creation; the difference between "I think this is current" and knowing.
- **Sort your pack by rate of change.** The glossary and voice guide are your stable layer —
  check twice a year. The org brief and anything touching money or structure are your volatile
  layer — check monthly, and always after a reorg, a cycle, or a policy change.
- **Put the review on your calendar.** Ten minutes monthly, all packs, or it will not happen.
  (In M7 this slot joins your operating rhythm; for now, one recurring invite.)
- **Prune as ruthlessly as you add.** An item nobody''s needed in two review cycles comes out.
  The context window you free is worth more than the "just in case."

One more habit that pays forward: when a run produces a wrong output *because the pack was
wrong*, fix the pack before you fix the output. Artisans correct the draft; practitioners
correct the system that drafted it.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-key-takeaways-100', 'ai201-m2', 100, 'takeaways', 'stable', '## Key takeaways

- **The artisan tax is real and optional.** You pay it every time you re-brief material that
  hasn''t changed. The pack is the once-written refund.
- **Three bins, one discipline:** durable-and-impersonal in the pack, run-specific fresh,
  people data never in infrastructure. The middle of the module and the middle of the practice.
- **Instructions are always-on behavior; knowledge is look-it-up reference. [V]** Short standing
  brief, well-chosen shelf — in whatever tool your organization provisions.
- **Stale context is a self-installed hallucination.** Date-stamp, split by rate of change,
  review on a calendar, prune. Fix the pack before you fix the output.
- **A written pack is transferable fluency.** It''s what makes M8''s handoff test passable — and
  it''s the first artifact of yours a colleague could actually learn from.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-sources-and-attribution-120', 'ai201-m2', 120, 'prose', 'stable', '## Sources and attribution

Builds on AI 101 M5 (briefing, gold-standard examples as prediction-narrowing) and 101 M1
Lesson 4 (the data you supply; "the model has never seen your organization"). The
pack/fresh/excluded three-bin model and "people data must never become infrastructure" are
original to this course; M6 develops the exclusion rule into full data-tier practice. Lesson 3
and marked passages are volatile layer — tool specifics current as of the stamp date, tailored
per deployment to the organization''s provisioned tools.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-activity-capstone-stage-2-build-your-workflow-s-p-10', 'ai201-m2-activity', 10, 'prose', 'stable', '## Capstone stage 2 · Build your workflow''s pack

Your M1 spec named the workflow''s inputs. Now split and build them.

**First, score your calibration** from the top of the module: how many items did the pack
actually need, and which was genuinely hardest to write? Record both misses with a sentence on
the direction — too many predicted items usually means fresh material was headed for the pack;
the "hardest item" miss usually reveals which part of your own standards you''d never written
down.

**Then submit, from your organization''s tool:**

1. **The three-bin inventory** — every input from your M1 spec, placed in pack / fresh /
   excluded, one clause of reasoning each.
2. **The instructions** — pasted verbatim. Role, definition of done, voice, failure rule.
3. **The knowledge list** — each document''s name, one line on why it earned the place, and its
   review date and cadence (stable or volatile).
4. **A fresh-run transcript** — one real run supplying only per-run material, with a sentence on
   what you no longer had to say.

### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Pack design** | Instructions are short and behavioral; knowledge is reference, not recitation; a gold-standard example and definition of done are present. The split shows judgment, not just sorting. |
| **Boundary discipline** | Nothing person-identifying anywhere in pack or instructions; fresh vs. pack placements are defensible; the excluded bin shows they know *why* those items are excluded. |
| **Durability design** | Every knowledge item carries a review date and a stable/volatile designation; a real review cadence exists somewhere a calendar can enforce it. |
| **Calibration** | Both predictions recorded before building, scored honestly after, with the direction of error named. Accuracy isn''t graded; honesty and specificity are. |', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-micro-core', 'ai201-m2-micro', 10, 'prose', 'stable', '## Module 2 in two minutes

**The artisan tax** is what you pay every time you re-brief an AI on material that hasn''t changed — your voice, your standards, your org''s shape, retyped per conversation, forever. The fix is the **context pack**: the durable briefing for one workflow, written once, attached always.

**Three bins, one discipline.** Durable-and-impersonal material lives in the pack: a gold-standard example, the definition of done, your voice rules, the team glossary. Run-specific material — this week''s notes, this quarter''s verbatims — arrives fresh and leaves with the run. And anything identifying a person never becomes infrastructure: packing it converts a one-time judgment call into a standing condition nobody re-decides.

**Context rots.** The org brief goes stale at the next reorg, and stale context fails the way fluent output always fails — confidently. Date-stamp every pack item, review the fast-aging ones monthly, prune what nobody''s needed in two cycles. When a run goes wrong because the pack was wrong, fix the pack before you fix the output.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-micro-rule', 'ai201-m2-micro', 20, 'callout', 'stable', '### The boundary rule

People data must never become infrastructure. Sensitive material may enter a single run as fresh input, under that run''s judgment — it never lives in packs, instructions, or anything a future conversation can see.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m2-micro-close', 'ai201-m2-micro', 30, 'prose', 'stable', '**The full module adds** the instructions-vs-knowledge design rule, the hands-on pack build in your organization''s tools, a twelve-item sorting exercise, and capstone stage 2: the pack for your own workflow.', NULL, '2026-08-07', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m2-sorting', 'ai201-m2', 'sorting', '{"reviewedAt":"2026-08-07","buckets":[{"id":"pack","label":"Lives in the pack","hint":"Durable and impersonal — infrastructure","rank":3,"pct":90},{"id":"fresh","label":"Supplied fresh each run","hint":"This run''s material — arrives, transforms, leaves","rank":2,"pct":50},{"id":"never","label":"Never enters the system","hint":"People data — not as pack, not as paste","rank":1,"pct":10}],"tasks":[{"id":"t1","text":"Your company''s voice and style guide","key":"pack","reasoning":"The canonical pack item — durable, impersonal, true for months."},{"id":"t2","text":"The best interview debrief you''ve ever written, as an example","key":"pack","reasoning":"The gold-standard example: one great example outworks three paragraphs of description."},{"id":"t3","text":"This week''s interview notes","key":"fresh","reasoning":"The reason the run exists. It arrives, gets transformed, and leaves with the run."},{"id":"t4","text":"The comp philosophy one-pager","key":"pack","reasoning":"Principles, not numbers or names. When the cycle changes it, the review cadence catches it."},{"id":"t5","text":"A named employee''s performance history","key":"never","reasoning":"Writing it into infrastructure converts a one-time judgment call into a standing condition nobody re-decides."},{"id":"t6","text":"This quarter''s engagement survey verbatims","key":"fresh","reasoning":"Pack them and June confidently cites March — the quieter way context rots."},{"id":"t7","text":"The definition-of-done checklist for the output","key":"pack","reasoning":"Load-bearing later: M4''s verification needs something to verify against."},{"id":"t8","text":"Grievance details naming the individuals involved","key":"never","reasoning":"People data must never become infrastructure — this is the one sorting error with legal weight."},{"id":"t9","text":"The team glossary — acronyms, level names, competency terms","key":"pack","reasoning":"The slice of your org the model may safely see."},{"id":"t10","text":"A raw HRIS export, employee IDs included","key":"never","reasoning":"IDs are identity by design. Where a single run legitimately needs sensitive material, M6 governs how it enters — fresh, minimized, under that run''s judgment — and how it leaves."},{"id":"t11","text":"The policy paragraph being rewritten this run","key":"fresh","reasoning":"Today''s work product, nobody''s infrastructure — it leaves with the run."},{"id":"t12","text":"Your org context brief — what the company does, size, shape, no names","key":"pack","reasoning":"Impersonal by construction: nothing you''d redact from a conference talk."}],"pattern":"Durable and impersonal lives in the pack. Run-specific material arrives fresh and leaves with the run. Anything identifying a person never becomes infrastructure.","postscript":"If you put fresh material in the pack, you built the quiet failure: current-sounding answers from stale truth. If you packed people data, stop before building anything and read M6''s opening — that one carries legal weight."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m2-rubric', 'ai201-m2', 'rubric', '{"promptVersion":"ai201-m2-capstone-v1","moduleId":"ai201-m2","minChars":600,"submitLabel":"Your capstone-stage submission","intro":"Submit the artifacts this stage asks for, as text. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 201, The Practitioner). Capstone stage 2: the context pack for the workflow specced in stage 1 — a three-bin inventory (pack / fresh / excluded), the standing instructions verbatim, a knowledge list with review dates, and a fresh-run transcript. Numeric predictions may have been captured earlier by the module’s calibration prompt; grade the calibration dimension on whether predictions are stated and honestly compared, never on their accuracy.","calibration":[{"key":"itemsActual","label":"Measured — items the pack actually needed","hint":"Count the knowledge list you’re about to paste. The miss is the lesson.","placeholder":"e.g. 6","min":1,"max":60,"actualFor":"items"}],"dimensions":[{"name":"Pack design","criteria":"Instructions are short and behavioral; knowledge is reference, not recitation; a gold-standard example and definition of done are present. The split shows judgment, not just sorting."},{"name":"Boundary discipline","criteria":"Nothing person-identifying anywhere in pack or instructions; fresh vs. pack placements are defensible; the excluded bin shows they know *why* those items are excluded."},{"name":"Durability design","criteria":"Every knowledge item carries a review date and a stable/volatile designation; a real review cadence exists somewhere a calendar can enforce it."},{"name":"Calibration","criteria":"Both predictions recorded before building, scored honestly after, with the direction of error named. Accuracy isn''t graded; honesty and specificity are."}],"opening":[{"key":"items","label":"Predicted — distinct items your pack will need","hint":"A voice guide is one item. An example debrief is one item.","placeholder":"e.g. 8","min":1,"max":60}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m2-knowledge_check', 'ai201-m2', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the capstone pack is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"What is the \"artisan tax\"?","options":["The subscription cost of professional AI tools","The recurring cost of re-briefing unchanged context in every conversation","The time spent verifying AI output","The premium for larger context windows"],"correctIndex":1,"explanation":"It''s the per-conversation cost of re-supplying material that barely changes between runs. Verification (C) is a cost worth keeping — M4 designs it rather than eliminating it."},{"id":"q2","prompt":"The two-question test for whether material belongs in the pack:","options":["Is it useful? Is it well-written?","Will it still be right in ninety days? Does it identify a person?","Is it shorter than a page? Is it approved by legal?","Has it been used more than twice? Is it confidential?"],"correctIndex":1,"explanation":"Durable *and* impersonal — yes to the first, no to the second. Everything else in the module''s three-bin sorting follows from those two questions."},{"id":"q3","prompt":"Why does putting this quarter''s survey verbatims in the pack cause trouble?","options":["Verbatims are too long for knowledge files","Survey data is always too sensitive to use","Fresh material packed as durable gets confidently cited long after it''s stale","It doesn''t — verbatims are ideal pack content"],"correctIndex":2,"explanation":"That''s the quiet rot: June''s run cites March''s themes, fluently, with no signal anything is wrong. Verbatims are legitimate *fresh* input (B overshoots); they just must leave with the run."},{"id":"q4","prompt":"Instructions versus knowledge, in one rule: **[V]**","options":["Instructions are what it must always do; knowledge is what it may need to look at","Instructions are for formatting; knowledge is for facts","Instructions are temporary; knowledge is permanent","They''re interchangeable — use whichever has space"],"correctIndex":0,"explanation":"The standing brief stays short and behavioral; the shelf holds reference consulted as needed. Three pages of instructions is knowledge in the wrong house."},{"id":"q5","prompt":"\"People data must never become infrastructure\" means:","options":["People data may never be used with AI at all","Sensitive material may enter a run as fresh input under that run''s judgment, but never live in packs or instructions","People data belongs in knowledge files, not instructions","Only aggregated people data may go in the pack"],"correctIndex":1,"explanation":"The rule targets *standing* exposure — material written once and present in every future conversation, with nobody re-deciding. A is broader than the course teaches (M6 governs per-run use); C is precisely the violation."},{"id":"q6","prompt":"A conversation inside a Claude Project produces a much better debrief format than your pack specifies. Next week''s runs will: **[V]**","options":["Use the improved format — the project learns from its conversations","Use the old format, until you deliberately edit the instructions or knowledge","Alternate between formats","Ask which format you prefer"],"correctIndex":1,"explanation":"Conversations don''t teach the project — 101''s \"you''re not training it\" lesson, now operational. That''s a feature: the pack changes only when you change it, which is what makes it auditable. Fix the pack, not the output."},{"id":"q7","prompt":"The stable/volatile split applied to your own pack means:","options":["Keeping two separate packs per workflow","Reviewing fast-aging items (org brief, anything touching money or structure) on a short cadence, and slow-aging items on a long one","Marking which items the model may quote directly","Storing volatile items as instructions and stable items as knowledge"],"correctIndex":1,"explanation":"Different material ages at different speeds, so it gets reviewed at different speeds — the same discipline this course''s own content runs on, applied to your infrastructure."},{"id":"q8","prompt":"A run produces a wrong output because the org brief in your pack predates the reorg. The practitioner''s move:","options":["Correct the output and ship it","Correct the output, then update the pack and its review cadence","Delete the org brief — packs shouldn''t contain anything that changes","Add a disclaimer to the output"],"correctIndex":1,"explanation":"Ship the corrected work, then fix the system that drafted it — otherwise next week pays the same cost. C throws away the pack''s value; the answer to aging content is a cadence, not exclusion."}]}', '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-calibration-prompt-before-you-start-10', 'ai201-m3', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. You''ll score it during the capstone run.*

By the end of this module you''ll have designed your workflow as a pipeline — a chain of small
steps — and run it on real material.

**Which step do you expect to degrade quality most?** Not fail loudly — degrade: lose detail,
flatten nuance, drop the thing that mattered. Name the step and write one sentence on why.

Almost nobody guesses right the first time, and the miss teaches you where your verification
budget should go. That''s M4''s opening move.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-module-brief-20', 'ai201-m3', 20, 'prose', 'stable', '## Module brief

Here is a prompt a smart, 101-fluent person writes every quarter:

> "Here are 200 survey comments. Summarize the themes, pull representative quotes, note anything
> concerning, and draft a summary for the exec team in our company voice."

One prompt, four jobs. The output arrives fluent and confident, and it is quietly worse than it
looks — themes flattened, one office''s problem averaged into "minor concerns," a quote that''s
almost-but-not-quite what anyone wrote. Worst of all, there''s nothing to check: when the final
prose is wrong, you can''t see *where* it went wrong, because everything happened in one
invisible leap.

You know from 101 why this happens. The model generates one fragment at a time, each predicted
from everything in view; ask it to juggle four objectives across two hundred comments and the
middle objectives lose the tug-of-war quietly. More instructions in one prompt doesn''t mean more
gets done — it means everything competes.

The practitioner''s move is the same one every other discipline made when work got serious:
**break the leap into steps with inspectable states in between.** Summarize → extract →
transform → format, each step doing one job, each producing an artifact you can read before the
next step consumes it. This is a pipeline, it is the transformation line of your M1 spec grown
up, and designing one well is mostly about knowing where chains break: long documents, lossy
middles, and formats that drift.

One promise before we start: this is not about making everything elaborate. Most tasks still
deserve a single prompt. The skill is knowing which tasks don''t — and building the smallest
chain that fixes them.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-learning-objectives-30', 'ai201-m3', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain why one mega-prompt loses to a short chain — in the mechanism vocabulary of 101, not
   as folklore.
2. Design a checkpoint: an intermediate artifact a human could actually catch an error in.
3. Recognize the lossy middle — the step where structure becomes prose and detail dies — and
   defend against it.
4. Run a multi-step pipeline in your organization''s tool, carrying artifacts forward cleanly. **[V]**
5. Know when *not* to chain: the single-prompt tasks that chains only slow down.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-lesson-1-chain-thinking-40', 'ai201-m3', 40, 'prose', 'stable', '## Lesson 1 · Chain thinking

A pipeline is three design decisions, repeated: what each step does, what it hands to the next
step, and what you look at in between.

**One transformation per step.** M1''s rule, now load-bearing. "Extract the themes" is a step.
"Extract the themes and draft the summary" is two steps written as one prompt, and the model
will do the first at half attention while performing the second. If your step prompt contains "and
then also," split it.

**Structured intermediates.** What a step hands forward should be *more* structured than what
it received: a table, a list with counts, sections with headings — not polished prose. Two
reasons. The next step predicts better from structure than from narrative (you''re supplying
cleaner material — 101''s central lever). And structure is checkable: a count can be verified, a
quote can be traced. Prose can only be believed.

**Checkpoints, honestly defined.** An intermediate artifact is only a checkpoint if a human
glancing at it could catch a real error. "Themes: communication, workload, recognition" checks
nothing — it would look identical whether the analysis was faithful or invented. "Communication:
41 mentions, 9 strongly negative, concentrated in the Denver office, sample quotes below" is a
checkpoint: every claim in it can be spot-checked against the raw comments in two minutes. When
you design a step, design what failure would look like at its checkpoint — if you can''t say what
a wrong version would show, the checkpoint is decoration.

**Fresh context per step.** Each step should see its input artifact, the relevant pack material,
and nothing else. Don''t run a whole pipeline down one endless conversation out of convenience:
101 told you what happens when the window fills — early material drops out of view, and your
step 3 quietly stops seeing the instructions from step 1. (Lesson 3 shows the clean mechanics.)

**And the counterweight: don''t chain what doesn''t need it.** A chain earns its friction under
three conditions — the input is long, the stakes are real, or a failure would be invisible in
final prose. "Rewrite this paragraph plainly" meets none of them; one prompt, done. The
practitioner''s tell isn''t elaborate pipelines everywhere; it''s *small* pipelines exactly where
the three conditions hold, and single prompts everywhere else.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-try-50', 'ai201-m3', 50, 'try_this', 'stable', '### Try this — 2 minutes
Take the most complex prompt you''ve written this month — the one with several jobs in it.

1. Count the distinct transformations it asks for. (Verbs are the tell: summarize, pull,
   note, draft — that''s four.)
2. For each, ask: if this part came back subtly wrong, would I be able to see that in the
   final output?
3. Every "no" is a place a checkpoint would have caught what you currently can''t.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-lesson-2-the-people-work-gallery-60', 'ai201-m3', 60, 'prose', 'stable', '## Lesson 2 · The People-work gallery

Three pipelines that cover most of what a People team feeds to a model. Learn the shapes — your
own workflows will mostly be one of these wearing different clothes.

### Pipeline 1 · Survey verbatims → themes → exec summary

- **Step 1 — Extract** (comments in → theme table out): themes with counts, intensity,
  *concentration* (which office, which function), representative quotes verbatim, and an
  explicit section for minority and dissenting signals. The prompt says: preserve counts, quote
  exactly, never average away a concentrated problem.
  **Checkpoint:** pick two themes, spot-check counts and quotes against the raw comments. 101''s
  survey caveat — the model flattens minority views — is *engineered against* here, not hoped
  against.
- **Step 2 — Narrate** (theme table in → analysis draft out): draft the narrative *from the
  theme table only* — the raw comments are deliberately out of view, so the narrative can''t
  quietly re-analyze. The prompt requires every claim to carry its number and concentration.
  **Checkpoint:** every sentence traceable to a table row.
- **Step 3 — Format** (draft in → exec-pack section out): voice, length, layout from your pack.
  No new facts may enter. **Checkpoint:** diff-read — formatting changed, claims didn''t.

### Pipeline 2 · Policy update → change list → plain-language note

- **Step 1 — Enumerate** (old + new text in → change table out): every changed clause, old
  wording, new wording, one line each. The prompt''s key instruction: *enumerate, don''t
  summarize* — a "summary of changes" is exactly the lossy move that lets a changed clause slip
  through unannounced. **Checkpoint:** mechanical — walk the table against the documents; it''s
  complete or it isn''t.
- **Step 2 — Explain** (change table in → plain-language explanations out): what each change
  means for an employee, in the register your pack defines, flagged where a change might be
  contentious. **Checkpoint:** explanations match clauses; the flags look right to someone who
  knows the org.
- **Step 3 — Draft** (explanations in → comms note out): the note itself, pack voice, standard
  disclaimers. This step also gets a standing reminder from 101: general statutory framing may
  ride along, but *your jurisdiction''s specifics get verified by a human, every time*.

### Pipeline 3 · Interview notes → debriefs → decision packet

- **Step 1 — Structure per candidate** (your notes in → structured debrief out): evidence
  organized under your competency headings — from the notes only, gaps flagged as gaps ("notes
  don''t cover competency X"), never filled. One run per candidate, so no cross-contamination.
  **Checkpoint:** every claim traceable to something you actually wrote down.
- **Step 2 — Assemble** (debriefs in → packet out): side-by-side *evidence* — where each
  candidate showed what, where the gaps are. The prompt explicitly does not ask for a ranking or
  recommendation, because M1''s line hasn''t moved: the packet informs a human decision; it is not
  the decision. **Checkpoint:** the packet contains comparisons of evidence and zero verdicts.
- **Step 3 — Format** for the debrief meeting, pack template.

**The shape underneath all three:** the first step turns raw material into structure and
preserves traceability (counts, quotes, clauses, sources). Middle steps transform structure
*into* structure. The last step — and only the last — is allowed to make prose. Hold that shape
and notice where the danger concentrates: the step where structured detail becomes readable
narrative. That''s the lossy middle, and it''s where the exercise below takes you.
', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-exercise', 'ai201-m3', 65, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-lesson-3-the-lab-running-a-pipeline-in-c-70', 'ai201-m3', 70, 'prose', 'volatile', '## Lesson 3 · The lab — running a pipeline in Claude [V]

*Volatile layer: specific tool, current mechanics, tailored to your organization''s provisioned
tools.*

Your pipeline lives in the same Project as its pack (M2). Two additions make it runnable.

**The runbook.** One knowledge document — "Pipeline: [workflow name]" — holding each step''s
prompt, numbered, with its expected input and output format. Step prompts are pack content by
M2''s own test: durable, impersonal, reviewed on a cadence. When you improve a step prompt after
a bad run, you improve it *in the runbook* — fix the pack, not the output.

**One conversation per step.** Start a fresh conversation in the project for each step; give it
the step prompt and the incoming artifact; take the outgoing artifact and move on. This buys
you clean context per step (nothing stale in view, nothing crowded out), a natural checkpoint
pause where you actually look at the artifact — and an audit trail: each step''s conversation
*is* its record, which M4 will sample and M8 will show a colleague.

**Artifacts, concretely.** Ask each step to produce its output as a single well-formed document
— a markdown table, a structured file — not scattered through chat replies. Claude can produce
these as discrete artifacts you can carry forward, save alongside the runbook, and diff between
runs. Boring formats win: a table you can scan beats an eloquent essay at every checkpoint.

**When one long conversation is fine.** Short chain, small documents, you refining
interactively — a single conversation is less friction and works. Know what you''re trading:
around the point where the material stops fitting comfortably in view, earlier instructions
start dropping out of it, and the failure is silent. If a late step seems to have "forgotten"
an early rule, you didn''t hit a mood; you hit the window. Split the steps.

**[V]** *Parity note:* in ChatGPT the same shape holds — a Project holding the runbook,
conversations per step, files carried forward. The design (structure forward, checkpoints
between, prose last) transfers untouched.', NULL, '2026-08-07', 'claude');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-lesson-3-the-lab-running-a-pipeline-in-c-70-chatgpt', 'ai201-m3', 70, 'prose', 'volatile', '## Lesson 3 · The lab — running a pipeline in ChatGPT [V]

*Volatile layer: specific tool, current mechanics, tailored to your organization''s provisioned
tools.*

Your pipeline lives in the same Project as its pack (M2). Two additions make it runnable.

**The runbook.** One project file — "Pipeline: [workflow name]" — holding each step''s prompt,
numbered, with its expected input and output format. Step prompts are pack content by M2''s own
test: durable, impersonal, reviewed on a cadence. When you improve a step prompt after a bad
run, you improve it *in the runbook* — fix the pack, not the output.

**One conversation per step.** Start a fresh conversation in the project for each step; give it
the step prompt and the incoming artifact; take the outgoing artifact and move on. This buys
you clean context per step (nothing stale in view, nothing crowded out), a natural checkpoint
pause where you actually look at the artifact — and an audit trail: each step''s conversation
*is* its record, which M4 will sample and M8 will show a colleague.

**Artifacts, concretely.** Ask each step to produce its output as a single well-formed document
— a markdown table, a structured file — not scattered through chat replies. ChatGPT can draft
these in a canvas or as a downloadable file you can carry forward, save alongside the runbook,
and diff between runs. Boring formats win: a table you can scan beats an eloquent essay at
every checkpoint.

**When one long conversation is fine.** Short chain, small documents, you refining
interactively — a single conversation is less friction and works. Know what you''re trading:
around the point where the material stops fitting comfortably in view, earlier instructions
start dropping out of it, and the failure is silent. If a late step seems to have "forgotten"
an early rule, you didn''t hit a mood; you hit the window. Split the steps.

**[V]** *Parity note:* in Claude the same shape holds — a Project holding the runbook,
conversations per step, artifacts carried forward. The design (structure forward, checkpoints
between, prose last) transfers untouched.', NULL, '2026-08-08', 'chatgpt');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-key-takeaways-80', 'ai201-m3', 80, 'takeaways', 'stable', '## Key takeaways

- **One prompt, four jobs is how good work goes quietly wrong.** Objectives compete inside a
  single generation; the middle ones lose without a sound.
- **Structure forward, prose last.** Steps hand forward tables and lists with counts and
  traceable quotes; only the final step is allowed to make narrative.
- **A checkpoint is only real if you can say what a wrong version would show.** Otherwise it''s
  decoration between steps.
- **The lossy middle is where detail dies** — the structured-to-prose transformation. Engineer
  it: require claims to carry their numbers, and check the artifact against the one before it.
- **Chain only under the three conditions** — long input, real stakes, invisible failure.
  Everything else stays a single prompt. Small pipelines, exactly where they''re needed, are the
  practitioner''s signature.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-sources-and-attribution-100', 'ai201-m3', 100, 'prose', 'stable', '## Sources and attribution

Builds on 101 M1 (generation mechanics, context window, the survey-flattening caveat in the
sorting key) and 201 M1–M2 (one transformation per step; the pack; fix-the-pack-not-the-output,
here extended to runbooks). The checkpoint test ("name what a wrong version would show"), the
lossy-middle framing, and the structure-forward/prose-last rule are original to this course.
Lesson 3 and marked passages are volatile layer, tailored per deployment.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-activity-capstone-stage-3-design-and-run-your-pip-10', 'ai201-m3-activity', 10, 'prose', 'stable', '## Capstone stage 3 · Design and run your pipeline

Your M1 spec named a transformation. Turn it into the smallest pipeline that fixes what a
single prompt gets wrong — for many first builds that''s two steps, and two is a fine answer.
(If it''s genuinely one step, say so, defend it against Lesson 1''s three conditions, and run it
with a checkpoint anyway.)

**Submit:**

1. **The pipeline design** — each step: name (a verb), one-line job, input artifact, output
   artifact with format, and its checkpoint *including what a wrong version would look like*.
   That last clause is where the thinking lives.
2. **The runbook** — the step prompts, verbatim, as they now live in your project.
3. **A real run** — on genuine, M6-safe material (yours to judge for now: nothing
   person-identifying; the full rules arrive in M6). Include every intermediate artifact, not
   just the final output.
4. **The calibration score** — which step you predicted would degrade quality most, what the
   run showed, and the direction you were wrong in. If the run went suspiciously perfectly, say
   what you''d watch across the next three runs instead.

### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Step discipline** | One transformation per step; structured intermediates; prose only at the end. A deliberately small pipeline defended well outscores an elaborate one. |
| **Checkpoint design** | Each checkpoint names what failure would look like there, and a human could realistically catch it in the artifact submitted. |
| **The run is real** | Genuine material, all intermediates included, and evidence the checkpoints were actually looked at — not a pipeline run for the grade. |
| **Calibration** | Prediction recorded before the run, scored honestly after, direction of error named. Accuracy isn''t graded; honesty and specificity are. |', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-micro-core', 'ai201-m3-micro', 10, 'prose', 'stable', '## Module 3 in two minutes

**One prompt, four jobs is how good work goes quietly wrong.** Ask a model to summarize, extract, judge, and format in one go, and the middle objectives lose without a sound — and when the output is wrong, there''s nothing to check, because everything happened in one invisible leap.

**The pipeline fix:** small steps, one transformation each, with inspectable artifacts between them. Steps hand forward *structure* — tables, counted lists, traceable quotes — and only the final step is allowed to make prose. A checkpoint is only real if you can say what a wrong version would look like there.

**The lossy middle** is where detail dies: the step where structured detail becomes readable narrative, and counts, intensity, and concentration quietly drop. Engineer against it — require claims to carry their numbers, and check each artifact against the one before it. When a final output is wrong, walk backward through the artifacts; the step after the last correct one is your culprit.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-micro-rule', 'ai201-m3-micro', 20, 'callout', 'stable', '### When to chain

Chain only when the input is long, the stakes are real, or a failure would be invisible in final prose. Everything else stays a single prompt — small pipelines exactly where they''re needed.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m3-micro-close', 'ai201-m3-micro', 30, 'prose', 'stable', '**The full module adds** a three-pipeline gallery for People work, the find-the-lossy-step exercise, the runbook lab, and capstone stage 3: your workflow''s pipeline, designed and run on real material.', NULL, '2026-08-07', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m3-choice', 'ai201-m3', 'choice', '{"reviewedAt":"2026-08-07","title":"Find the lossy step","intro":"*Five minutes. Commit before you look.*\n\nA People team ran Pipeline 1 on their Q2 survey. Here are the actual artifacts, abridged. By the final artifact, a localized problem — nine strongly negative comments from one office — has become \"minor concerns.\" **Which step killed the signal?** Commit to an answer, and have one sentence ready on how you''d fix that step''s prompt.","artifacts":[{"label":"Raw comments · step 0","body":"214 comments. Among them, 41 mention manager communication; 9 of those are strongly negative, and all 9 come from the Denver office."},{"label":"Theme table · after step 1","body":"\"Manager communication — 41 mentions · 9 strongly negative · negative mentions concentrated in Denver · quotes: [three verbatim quotes].\""},{"label":"Narrative draft · after step 2","body":"\"Some employees expressed concerns about manager communication, though sentiment in this area was mixed rather than uniformly negative.\""},{"label":"Exec summary · after step 3","body":"\"Overall sentiment remains positive, with minor communication concerns noted.\""}],"options":[{"id":"step1","label":"Step 1 — Extract"},{"id":"step2","label":"Step 2 — Narrate"},{"id":"step3","label":"Step 3 — Format"}],"key":"step2","reasoning":"**Step 2 killed the signal.** The theme table after step 1 was faithful: 41 mentions, 9 strongly negative, concentrated in Denver, verbatim quotes. The narrative draft dropped the count, the intensity, and — fatally — the concentration, dissolving a localized management problem into \"mixed sentiment.\" Step 3 then did its job honestly on corrupted input: \"minor communication concerns\" is a fair formatting of a false narrative.\n\nTwo fixes, both to step 2, both from Lesson 1: the step prompt requires every claim to carry its number and concentration (\"no theme may be described without its count and where it clusters\"), and the checkpoint compares the narrative against the theme table row by row — which would have caught this in under a minute.","closing":"Two reflexes to keep. First: when the final output is wrong, walk *backward* through the artifacts to find the last one that was right; the step after it is your culprit. Second: notice that the exec summary read as entirely plausible. Nothing in the final prose looked broken. That''s why checkpoints exist — by the time the loss is visible in the output, it isn''t visible in the output."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m3-rubric', 'ai201-m3', 'rubric', '{"promptVersion":"ai201-m3-capstone-v1","moduleId":"ai201-m3","minChars":600,"submitLabel":"Your capstone-stage submission","intro":"Submit the artifacts this stage asks for, as text. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 201, The Practitioner). Capstone stage 3: the workflow as a pipeline — step designs with checkpoints, the runbook prompts verbatim, a real run with all intermediate artifacts, and the calibration score for the predicted-lossiest step. Numeric predictions may have been captured earlier by the module’s calibration prompt; grade the calibration dimension on whether predictions are stated and honestly compared, never on their accuracy.","calibration":[],"dimensions":[{"name":"Step discipline","criteria":"One transformation per step; structured intermediates; prose only at the end. A deliberately small pipeline defended well outscores an elaborate one."},{"name":"Checkpoint design","criteria":"Each checkpoint names what failure would look like there, and a human could realistically catch it in the artifact submitted."},{"name":"The run is real","criteria":"Genuine material, all intermediates included, and evidence the checkpoints were actually looked at — not a pipeline run for the grade."},{"name":"Calibration","criteria":"Prediction recorded before the run, scored honestly after, direction of error named. Accuracy isn''t graded; honesty and specificity are."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m3-knowledge_check', 'ai201-m3', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the capstone pipeline is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"Why does a four-job mega-prompt underperform a short chain, mechanically?","options":["Long prompts exceed the context window","Objectives compete within a single generation, and middle objectives quietly lose","The model refuses compound instructions","Chains use more capable models by default"],"correctIndex":1,"explanation":"Generation is one fragment at a time, predicted from everything in view; multiple objectives dilute each other, and the loss is silent. A confuses prompt length with window limits; C and D aren''t how any of this works."},{"id":"q2","prompt":"What makes an intermediate artifact a real checkpoint?","options":["It''s produced between two steps","It''s written in polished prose","A human glancing at it could catch a real error — you can say what a wrong version would show","It''s saved in the project''s knowledge"],"correctIndex":2,"explanation":"The design test is naming what failure looks like there. An artifact that reads identically whether the work was faithful or invented checks nothing, wherever it''s saved."},{"id":"q3","prompt":"Steps should hand forward structure (tables, counted lists) rather than prose because:","options":["Structure uses fewer tokens","The next step predicts better from clean material, and structure can be verified — counts check, quotes trace","Prose is against the pipeline convention","Structured formats prevent hallucination entirely"],"correctIndex":1,"explanation":"Both halves matter: better input for the next step (101''s supply-the-material lever) and checkable claims for the human between steps. D overclaims — structure makes errors *catchable*, not impossible."},{"id":"q4","prompt":"The \"lossy middle\" is:","options":["The middle of a long document, which models skip","The step where structured detail becomes narrative, and counts, intensity, and concentration quietly drop","A context-window overflow","The degradation of quality in long conversations"],"correctIndex":1,"explanation":"It''s the structured-to-prose transformation — the exercise''s step 2. The defense is a prompt that requires claims to carry their numbers, and a checkpoint that compares the narrative to the structure it came from."},{"id":"q5","prompt":"In the survey pipeline, step 2 drafts the narrative from the theme table *only*, with raw comments out of view, because:","options":["The comments no longer fit in the window","It stops the step from quietly re-analyzing — the narrative can only use what the checkpointed table contains","Raw comments are too sensitive for later steps","It makes the step run faster"],"correctIndex":1,"explanation":"Limiting a step''s view is a design tool: what the step can''t see, it can''t silently reinterpret. Your verified artifact becomes the single source of truth for everything downstream."},{"id":"q6","prompt":"Which task has *not* earned a pipeline?","options":["200 survey verbatims into an exec summary","A handbook revision into a plain-language change note","Rewriting one clunky policy paragraph for clarity","Six candidates'' interview notes into a decision packet"],"correctIndex":2,"explanation":"One short transformation, low stakes, failure visible on reading — none of the three conditions hold. Chaining it is ceremony. The other three are long, consequential, or fail invisibly — usually two of the three at once."},{"id":"q7","prompt":"Your pipeline''s final output is wrong. The practitioner''s first move:","options":["Rerun the whole pipeline — randomness may fix it","Rewrite the final step''s prompt","Walk backward through the artifacts to the last correct one; the step after it is the culprit","Add a verification step at the end"],"correctIndex":2,"explanation":"The artifacts exist precisely so failure has an address. Rerunning (A) discards the diagnosis; B assumes the last step failed, which the exercise shows is often exactly wrong."},{"id":"q8","prompt":"The interview pipeline''s assemble step compares evidence but produces no ranking, because:","options":["Rankings exceed what the model can do accurately","The packet informs a human decision about people; it must not become the decision","Hiring managers prefer making their own comparisons","Rankings would require a larger context window"],"correctIndex":1,"explanation":"M1''s line, unmoved by pipeline sophistication: a workflow may organize the evidence for a people decision; the decision stays human. Capability (A) isn''t the reason — the rule holds however good the ranking would be."}]}', '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-calibration-prompt-before-you-start-10', 'ai201-m4', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*Two predictions, thirty seconds. The capstone scores them.*

At the end of this module you''ll run a real verification sample on your workflow''s output.

1. **Out of ten outputs, how many will contain at least one real error?** A number, not a range.
2. **What kind will dominate?** Wrong (contradicts the source) · missing (source material that
   should be there and isn''t) · invented (content with no source at all).

The second prediction is the interesting one. Most practitioners guess "invented," because 101
taught them to fear hallucination. Volume workflows usually surprise them.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-module-brief-20', 'ai201-m4', 20, 'prose', 'stable', '## Module brief

There are two ways to run a workflow irresponsibly, and only one of them looks irresponsible.

The visible way is checking nothing: outputs ship on fluency, and 101 M6 told you exactly how
that story goes — the failure is quiet, plausible, and wearing your name. Nobody in this course
is doing that.

The invisible way is more common among people who finished 101: **checking everything.** Every
output, read end to end, every run. It feels like diligence. It is actually two failures at
once. First, it silently refunds the time the workflow saved — your M1 calibration
predicted hours back, and full-read review hands most of them right back. Second, it doesn''t
survive contact with a busy month. Willpower-based verification decays: you read every word in
week one, skim in week three, and by week six you''re approving on fluency — which is checking
nothing, plus a false sense of coverage. That last step off the cliff is where "a human reviews
everything" becomes the most dangerous sentence in the building, because everyone has stopped
worrying.

The practitioner''s alternative is a **verification budget**: a designed, honest answer to "how
much checking does this output deserve, of what kind, by whom" — written into the workflow so it
happens by structure rather than by mood. Sized to stakes, matched to failure mode, cheap enough
to survive week six. That''s this module. It''s also the toll gate for the rest of the course:
M5''s autonomy ladder is built entirely out of what you can verify, and M8 won''t let anything
ship without the plan you write here.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-learning-objectives-30', 'ai201-m4', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Size a verification budget to stakes — and defend both the spending and the *not*-spending.
2. Match technique to failure mode: sampling for volume, tracing for facts, adversarial reading
   for judgment-adjacent prose, diffing for drift.
3. Run an honest sample, classify what it finds, and know the escalation path when the rate is
   too high.
4. Write a sign-off that means something: one name, and a definition of what that name actually
   reads.
5. Run the output-incident path when something shipped wrong anyway — including the case where
   it influenced a decision about a person.
6. State what "verified by hand" in the practitioner''s heuristic operationally requires.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-lesson-1-the-verification-budget-40', 'ai201-m4', 40, 'prose', 'stable', '## Lesson 1 · The verification budget

Start from the two ends, because both are wrong for almost everything.

**100% review** is correct exactly where a single bad output can do real harm to a person or
the organization — and if your workflow produces such outputs, M1 already asked whether it
should be a workflow at all. **0% review** is correct nowhere in People work; even the
lowest-stakes newsletter carries your credibility in it.

Everything real lives between, and the budget question has three parts:

**How much?** Scale to stakes, which you scored in M1''s audit. Low stakes (internal newsletter,
jargon-stripped postings): sample. Medium (survey narratives, policy notes — things leaders act
on): sample harder, plus a targeted pass on the riskiest section. High (anything adjacent to an
individual''s treatment): full review, every time, by design — the budget for these isn''t "less
reading," it''s *structured* reading.

**Of what?** This is M3''s dividend. You verify *artifacts at checkpoints*, not final prose from
scratch. Checking a theme table against raw comments is minutes; auditing a finished exec
summary with no intermediates is an afternoon — and less reliable, because by the time loss is
visible in prose, it isn''t visible in prose. A workflow with good checkpoints has already paid
most of its verification bill.

**Paid by whom, when?** In-run checkpoints (you, at the pause between steps) catch process
failures. Across-run sampling (you or a delegate, weekly or per-batch) catches *decay*: the
pack going stale, the source format shifting, the step prompt that worked in March eroding in
June. Both lines go in the budget; they find different things.

And one design constraint that outranks the others: **the budget must be cheap enough that
week six runs it exactly like week one.** A verification plan you''d abandon under deadline will
end as fluency-approval anyway. When in doubt, buy a smaller budget you''ll actually spend.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-try-50', 'ai201-m4', 50, 'try_this', 'stable', '### Try this — 2 minutes
Take the last AI-assisted output you actually shipped.

1. What percentage of it did you genuinely verify — not read, *verify*?
2. Was that a decision, or a mood?
3. If a colleague shipped the same output with the same checking, would you call it diligent?

No score. Just notice whether your current budget was designed by anyone, including you.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-lesson-2-technique-matches-failure-mode-60', 'ai201-m4', 60, 'prose', 'stable', '## Lesson 2 · Technique matches failure mode

"Check it" is not a technique. What checking means depends entirely on how the output fails —
and 101 gave you the failure taxonomy; this lesson pairs each entry with its counter.

**Volume transformations fail by erosion → spot-check sampling.** Debriefs, FAQs, rewritten
postings: the failure mode is rarely one spectacular fabrication; it''s a slow leak — a dropped
qualifier here, a flattened nuance there. Counter: fixed-size sample per run or per week (three
outputs, rotating), each checked against its *source*, findings classified **wrong / missing /
invented**. The classification isn''t bookkeeping — it''s diagnosis. Wrong and missing usually
mean a step prompt or pack problem (fixable in the runbook, M3); invented means the model is
filling gaps in supplied material (fix the inputs, or the workflow''s scope).

**Factual claims fail by fabrication → trace to source.** Numbers, citations, regulation
references, quotes: fluency tells you nothing (101 M6, permanently). Counter: every claim
traces to an artifact — the count to the theme table, the quote to the raw comments, the
regulation to the actual text *by a human, every time*, never to the model''s memory of it. The
M3 pipeline design makes this cheap: claims that carry their numbers and sources are traceable
in minutes; claims that don''t are unverifiable by construction, which is a design failure, not
a checking failure.

**Judgment-adjacent prose fails by plausible slant → adversarial reading.** Narratives leaders
will act on: the survey story, the change note, the packet. The output isn''t false; it''s
*angled* — smoothed, averaged, one office''s problem dissolved into "mixed sentiment." Counter:
read it as its strongest critic. Three prompts to run in your own head or hand to a fresh
conversation: *What would the person most affected say is missing? Which sentence would I
delete if I had to defend every remaining one? Argue this summary is materially wrong.* A
second-model pass — a clean conversation given the source artifact and asked to critique the
narrative against it — is a cheap, genuinely useful skeptic. Treat it as a smoke detector, not
a guarantee: it shares the first pass''s blind spots, and it must never *replace* the human
read on high-stakes output, only sharpen it.

**Format and drift fail silently → diff against the standard.** The output slowly stops
matching the definition of done; nobody notices because each step was small. Counter: your M2
pack already holds the gold-standard example and the checklist — put a periodic diff against
both into the sampling rotation. Thirty seconds; catches the slide while it''s still cosmetic.
', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-exercise', 'ai201-m4', 65, 'exercise', 'stable', '{"type": "sorting", "title": "Exercise — Buy the right verification", "intro": "Five minutes. Six outputs from a People team''s workflows. For each, pick the **primary** verification technique — what you''d spend first. Most items deserve more than one; the reveal carries the budget levels.\n\nTwo of the six are designed to be argued about — either defensible answer scores."}', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-lesson-3-the-sign-off-70', 'ai201-m4', 70, 'prose', 'stable', '## Lesson 3 · The sign-off

M1 said it as a rule: an output nobody owns is an incident that hasn''t happened yet. This
lesson makes the rule operational, because "accountability" that lives in a feeling is not a
control.

**One name.** Every workflow''s spec carries exactly one human whose name is on its outputs. Not
a team, not "People Ops," not whoever ran it that day. The test is brutal and clarifying: *when
this output turns out to be wrong in a way that matters, who gets the call?* If the answer
requires discussion, the workflow doesn''t have an owner yet.

**What the name actually reads.** A sign-off is defined by its inputs, or it''s theater. Write
down, in the spec, what the owner looks at before an output ships: which checkpoint artifacts,
which sample results, which sections in full. This is where the budget from Lesson 1 becomes a
checklist a person can actually run — and where you inoculate against the decay curve, because
"sign-off = read the theme-table diff and this week''s three samples" survives a busy month in a
way "sign-off = review it" never has.

**The rubber-stamp trap, named again.** M1 warned that "a human clicks approve" doesn''t move
the decisions-about-people line if the human stopped deciding. The same mechanism eats
sign-offs: an approval that no longer reads its defined inputs is worse than no approval,
because it *launders* — it stamps unverified output with a person''s credibility. Two defenses.
Keep the sign-off''s reading list short enough to be real (Lesson 1''s constraint again). And
when the owner catches themselves approving without reading, treat it as the workflow''s
failure, not the person''s: the budget was priced wrong. Reprice it.

**Delegation, honestly.** The owner need not run the checks — a coordinator can run samples, a
second model can pre-read. The owner is the one who *cannot delegate the consequences*. That
asymmetry is the whole design: checks can move; the name doesn''t.

This line item — the name, and what the name reads — is the difference between M8 shipping
your workflow and M8 shipping your liability. It''s also the first thing a colleague inherits
in the handoff test, which is why the spec writes it down rather than assuming it.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-lesson-4-when-it-shipped-anyway-80', 'ai201-m4', 80, 'prose', 'stable', '## Lesson 4 · When it shipped anyway

Everything so far catches errors before they leave. Some won''t be caught. The debrief that
mischaracterized a candidate went to the hiring manager last Tuesday; the theme summary that
misread a team''s comments already shaped a staffing conversation. In People work this is both
more likely and more consequential than a data spill — and it needs its own path, written in
advance, exactly like the spill path M6 will give you. Four steps, in order:

**1. Correct the record, at the error''s own prominence.** Identify everyone who consumed the
output — your M3 artifacts and M5 audit trail tell you who, which is a quiet argument for both.
The correction goes to all of them, through the same channel the error traveled, stated
plainly: what was wrong, what''s right, what''s being done. A correction buried in a reply-all
three days later is not a correction at the error''s prominence.

**2. Check for decision impact — and reopen what was touched.** The question a general counsel
will eventually ask, so answer it before they do: *did this output influence a decision about a
person?* If the mischaracterized debrief fed a hiring call, the call gets revisited with
corrected input, and the revisit is documented — who reconvened, what changed, what didn''t and
why. This is the step that distinguishes an error from a harm: the error was the output; the
harm is a decision standing on it after you knew.

**3. Trace the miss to its budget line.** Which layer should have caught it — a checkpoint, the
sample, the sign-off''s reading list? M3''s backward walk gives the address. "It slipped through"
is not a finding; "the adversarial read doesn''t cover per-candidate debriefs" is.

**4. Reprice.** The specific line changes: a checkpoint gains a what-would-wrong-look-like
clause, the sample widens for that output type, the reading list grows by one item. One
incident, one design change — resist the urge to add three; untargeted controls are how budgets
stop surviving week six.

The ownership is already decided: the sign-off name from Lesson 3 owns the correction — that is
part of what the name means. And the culture rule is the same one M6 will state for spills: the
path only works if using it is safe. An output incident that gets quietly patched downstream,
without the correction or the decision check, is the version of this that ends up in front of
counsel with the timeline against you.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-key-takeaways-90', 'ai201-m4', 90, 'takeaways', 'stable', '## Key takeaways

- **Checking everything is the invisible failure.** It refunds the workflow''s savings, then
  decays into checking nothing — with a false sense of coverage on top.
- **The budget has three parts:** how much (sized to stakes), of what (artifacts at
  checkpoints, not prose from scratch), by whom and when (in-run pauses catch process;
  across-run samples catch decay).
- **Technique matches failure mode.** Sample for erosion, trace for fabrication, read
  adversarially for slant, diff for drift. "Check it" is not a technique.
- **Classification is diagnosis:** wrong and missing point at the runbook or pack; invented
  points at the inputs. The tally tells you what to fix, not just how worried to be.
- **One name, defined reading.** A sign-off is its reading list. An approval that stopped
  reading launders credibility — when you catch it, reprice the budget.
- **When something ships wrong anyway:** correct the record at the error''s own prominence,
  check whether a decision about a person stood on it and reopen what was touched, trace the
  miss to its budget line, change that one line. The sign-off name owns the correction.
- **"Verified by hand" now has a definition** — and it''s the currency M5''s autonomy ladder is
  priced in.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-sources-and-attribution-110', 'ai201-m4', 110, 'prose', 'stable', '## Sources and attribution

Builds on 101 M6 (confidence/correctness decoupling, verify-specifics-with-counsel) and 201
M1–M3 (stakes scoring, the pack''s definition of done, checkpoints and the backward walk). The
verification-budget framing, the wrong/missing/invented classification, and "a sign-off is its
reading list" are this course''s adaptations of a real literature — the sampling and
human-oversight ideas here are older than AI, and that ancestry is worth citing when a
data-literate reviewer pushes:

*To be verified against editions and current URLs before publication; re-check on the Tier 1
quarterly cadence.*

1. **Deming, W. E. — *Out of the Crisis* (1986).** "Cease dependence on inspection to achieve
   quality" — the classic argument behind Lesson 1''s case that checking everything is the wrong
   spend, and that quality lives in the process design.
2. **Shewhart, W. A. — *Economic Control of Quality of Manufactured Product* (1931).** Process
   behavior over single-inspection thinking; the ancestry of reading error rates by direction
   and trend rather than level.
3. **ANSI/ASQ Z1.4 (successor to MIL-STD-105), *Sampling Procedures and Tables for Inspection
   by Attributes*.** The formal home of fixed-size, classified acceptance sampling — Lesson 2''s
   spot-check design, industrialized.
4. **Bainbridge, L. — "Ironies of Automation," *Automatica* 19(6) (1983).** Why the human
   checker''s job gets harder, not easier, as the automated part improves — the decay curve''s
   classic statement, twenty years before LLMs.
5. **Parasuraman, R. & Riley, V. — "Humans and Automation: Use, Misuse, Disuse, Abuse,"
   *Human Factors* 39(2) (1997).** Automation complacency: the rubber-stamp trap, formally
   studied.
6. **Vaughan, D. — *The Challenger Launch Decision* (1996).** Normalization of deviance — what
   unlogged skipped reviews become, at the highest stakes on record.
7. **Gawande, A. — *The Checklist Manifesto* (2009).** The sign-off reading list is checklist
   design; this is the accessible case for why short, defined lists outperform diligence.

Stable layer throughout; the practices here are deliberately tool-independent.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-activity-capstone-stage-4-the-verification-plan-a-10', 'ai201-m4-activity', 10, 'prose', 'stable', '## Capstone stage 4 · The verification plan — and the first honest sample

Your workflow now has a spec (M1), a pack (M2), and a pipeline with checkpoints (M3). Write
its verification plan, then prove it against reality.

**Submit:**

1. **The budget** — stakes level (from your M1 audit, restated honestly), what gets verified
   at checkpoints in-run, what gets sampled across runs, at what size and rhythm, and the one
   sentence that matters: *why this is enough, and why it''s not more.* Both directions need
   defending.
2. **The technique map** — your workflow''s main failure modes (wrong / missing / invented /
   drift / slant), and which technique from Lesson 2 counters each. If adversarial reading
   applies, include the two or three critic-questions you''ll actually use, written for your
   output, not copied from this module.
3. **The sign-off line** — the name (yours, for now), and the defined reading list: exactly
   what gets looked at before an output ships. Short enough to survive week six.
4. **The sample, run for real** — at least five outputs (from real runs; produce them if your
   workflow is young), each checked against source, findings classified wrong / missing /
   invented, and the honest tally. Then score your calibration from the top of the module:
   both predictions, both misses, direction named. If the sample found nothing, say what
   you''ll watch across the next three runs rather than declaring victory — five clean outputs
   is a good sign, not a verdict.
5. **The escalation line** — the error rate at which you stop and fix (runbook first — M3''s
   backward walk), and the rate at which you''d conclude this workflow isn''t ready for more
   autonomy. That number is your admission ticket to M5; you''ll use it there.
6. **The output-incident path** — Lesson 4, written for your workflow: who consumed last
   month''s outputs and how you''d reach them, what the correction channel is, and what a
   decision-impact check would look like for this output specifically.

### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Fit to stakes** | The budget matches the M1 stakes honestly — no full-read theater on low stakes, no sampling hand-waves on high. The "why not more" sentence shows real reasoning. |
| **Technique match** | Failure modes identified for *this* workflow, each paired with the right counter; adversarial questions are bespoke, not boilerplate. |
| **The sample is honest** | Real outputs, real source-checking, findings classified, and the tally reported straight — including the awkward ones. A suspiciously clean sample with no follow-up plan scores low. |
| **Calibration** | Both predictions recorded first, scored honestly, direction of error named. Accuracy isn''t graded; honesty and specificity are. |', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-micro-core', 'ai201-m4-micro', 10, 'prose', 'stable', '## Module 4 in two minutes

**Checking everything is the invisible failure.** It refunds the workflow''s savings, then decays under load into approving on fluency — while everyone still believes coverage is total. The alternative is a **verification budget**: how much checking, of what, by whom — sized to stakes, written into the workflow, cheap enough that week six runs it exactly like week one.

**Technique matches failure mode.** Sample volume work and classify what you find (wrong / missing / invented — the classification is diagnosis). Trace factual claims to their sources; compliance claims get traced by a human, every time. Read judgment-adjacent prose adversarially — its failure is slant, not falsehood. Diff against your gold standard for drift.

**A sign-off is its reading list.** One non-delegable name per workflow, with the defined inputs that name reads before anything ships. And when something ships wrong anyway: correct the record at the error''s own prominence, check whether a decision about a person stood on it and reopen what was touched, trace the miss to its budget line, reprice that one line.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-micro-rule', 'ai201-m4-micro', 20, 'callout', 'stable', '### The operational definition

"Verified by hand" means: a written budget sized to stakes, techniques matched to failure modes, a defined sign-off, and an honest sample run against real outputs. That''s the admission ticket to any autonomy conversation.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m4-micro-close', 'ai201-m4-micro', 30, 'prose', 'stable', '**The full module adds** the buy-the-right-verification exercise, the sampling and human-factors literature behind the design, and capstone stage 4: your workflow''s verification plan and first honest sample.', NULL, '2026-08-07', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m4-sorting', 'ai201-m4', 'sorting', '{"reviewedAt":"2026-08-07","buckets":[{"id":"sample","label":"Spot-check sample","hint":"A fixed slice against source — catches erosion","rank":0,"pct":50},{"id":"trace","label":"Trace to source","hint":"Every claim to its artifact — catches fabrication","rank":0,"pct":50},{"id":"adversarial","label":"Adversarial read","hint":"Read as its strongest critic — catches slant","rank":0,"pct":50},{"id":"diff","label":"Diff the standard","hint":"Against the gold standard — catches drift","rank":0,"pct":50}],"tasks":[{"id":"t1","text":"Forty rewritten job postings, batch-produced monthly","key":"sample","reasoning":"Volume transformation, low stakes, erosion failure — budget: light. Three per batch against source, classified. Full reads here are the budget-killer from Lesson 1."},{"id":"t2","text":"The exec survey narrative, quoting counts by office","key":"trace","also":["adversarial"],"reasoning":"Every count and concentration to the theme table (minutes, thanks to M3), then the critic''s pass — this is the Denver scenario''s home ground. Trace or adversarial as primary is defensible either way; the indefensible answer is ''sample'' — you don''t sample the one narrative leadership acts on. Budget: standard, plus the adversarial read."},{"id":"t3","text":"A benefits FAQ produced weekly from the plan summary","key":"sample","reasoning":"Volume-ish and pack-driven, but benefits errors reach real people''s decisions — the sample runs weekly, any invented finding triggers a full pass, and drift-diff joins the rotation monthly. Budget: standard."},{"id":"t4","text":"A change note claiming \"this complies with the new state leave law\"","key":"trace","reasoning":"Trace, full — by a human, to the actual text. A compliance claim is never sampled and never delegated to the model''s memory of the law. If the workflow routinely produces sentences like this, its scope is wrong, not just its verification."},{"id":"t5","text":"The interview evidence packet for tomorrow''s debrief","key":"trace","reasoning":"Every claim to your notes, every gap confirmed as flagged-not-filled. Adjacent to a decision about people, so the budget is structured full review — and the M1 line (evidence, no verdicts) is part of what you''re verifying."},{"id":"t6","text":"This week''s newsletter, drafted from your bullets","key":"diff","also":["sample"],"reasoning":"Lowest stakes on the board; the real risk is drift from the definition of done — budget: light. A light sample is also fine. What it must not consume is the budget the packet and the compliance claim need."}],"pattern":"Spend where failure is invisible or touches people; save where failure is cosmetic and loud.","postscript":"Two of the six were designed to be argued about — the narrative and the newsletter score for either defensible answer. And if your instinct on all six was one flat level of effort, that''s the exercise''s real target: a flat budget is a default, not a design."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m4-rubric', 'ai201-m4', 'rubric', '{"promptVersion":"ai201-m4-capstone-v1","moduleId":"ai201-m4","minChars":600,"submitLabel":"Your capstone-stage submission","intro":"Submit the artifacts this stage asks for, as text. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 201, The Practitioner). Capstone stage 4: the verification plan — a budget sized to stakes, a technique map by failure mode, the sign-off reading list, an honest five-output sample with classified findings, the escalation line, and the output-incident path. Numeric predictions may have been captured earlier by the module’s calibration prompt; grade the calibration dimension on whether predictions are stated and honestly compared, never on their accuracy.","calibration":[{"key":"errorsActual","label":"Measured — your sample, scaled to ten: how many actually did","hint":"From the honest sample this stage asks you to run.","placeholder":"e.g. 2","min":0,"max":10,"actualFor":"errors"}],"dimensions":[{"name":"Fit to stakes","criteria":"The budget matches the M1 stakes honestly — no full-read theater on low stakes, no sampling hand-waves on high. The \"why not more\" sentence shows real reasoning."},{"name":"Technique match","criteria":"Failure modes identified for *this* workflow, each paired with the right counter; adversarial questions are bespoke, not boilerplate."},{"name":"The sample is honest","criteria":"Real outputs, real source-checking, findings classified, and the tally reported straight — including the awkward ones. A suspiciously clean sample with no follow-up plan scores low."},{"name":"Calibration","criteria":"Both predictions recorded first, scored honestly, direction of error named. Accuracy isn''t graded; honesty and specificity are."}],"opening":[{"key":"errors","label":"Predicted — of ten outputs, how many hold at least one real error","hint":"A number, not a range.","placeholder":"e.g. 3","min":0,"max":10}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m4-knowledge_check', 'ai201-m4', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the capstone plan is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"Why is \"a human reviews everything\" often the most dangerous verification plan?","options":["Human review is less accurate than automated checks","It refunds the workflow''s time savings, then decays under load into fluency-approval — while everyone believes coverage is total","It violates the delegation heuristic","Full review is only dangerous for high-stakes outputs"],"correctIndex":1,"explanation":"The decay curve is the danger: week one reads everything, week six approves on fluency, and the plan''s reputation for rigor is exactly what stops anyone from noticing."},{"id":"q2","prompt":"The cheapest place to verify a pipeline''s work is:","options":["The final output, read end to end","The artifacts at checkpoints, against their sources","A second model''s opinion of the final output","User complaints after shipping"],"correctIndex":1,"explanation":"M3''s dividend: a theme table checks against raw comments in minutes, and catches loss that final prose hides by construction. A is the expensive, less reliable afternoon; C is a useful smoke detector, not a foundation."},{"id":"q3","prompt":"Your weekly sample of debriefs finds two \"missing\" findings and no \"invented\" ones. The likely fix lives in:","options":["The model — switch to a more capable one","The step prompt or pack — source material is being dropped, which is a runbook problem","The sample size — too small to conclude anything","Nothing — missing findings are acceptable at low rates"],"correctIndex":1,"explanation":"Classification is diagnosis: wrong/missing point at instructions and pack; invented points at gaps in supplied material. That''s why the tally is classified at all — the categories have different addresses."},{"id":"q4","prompt":"Adversarial reading exists because judgment-adjacent prose fails by:","options":["Fabricating citations","Being angled — smoothed and averaged in ways that are plausible rather than false","Exceeding the context window","Drifting from the output format"],"correctIndex":1,"explanation":"The Denver summary wasn''t a lie; it was a slant. Tracing catches false claims; only a critic''s read catches a true-ish narrative that buries the signal."},{"id":"q5","prompt":"A second-model critique pass should be treated as:","options":["A replacement for human review on routine outputs","A guarantee against hallucination","A cheap skeptic that sharpens the human read but shares the first pass''s blind spots","Forbidden — models must not check models"],"correctIndex":2,"explanation":"It''s a smoke detector: genuinely useful, cheap to run, and never the thing that makes high-stakes output safe on its own. A is the rubber-stamp trap with extra software."},{"id":"q6","prompt":"A real sign-off is defined by:","options":["The seniority of the person approving","Its reading list — the named inputs the owner looks at before shipping","The approval being recorded in writing","A second approver for high-stakes outputs"],"correctIndex":1,"explanation":"\"Sign-off = the theme-table diff plus this week''s three samples\" is a control. \"Sign-off = review it\" is a sentiment with a signature line. The name matters too — but only paired with what the name reads."},{"id":"q7","prompt":"The owner catches herself approving outputs without reading the defined inputs. The module''s prescription:","options":["Replace the owner","Add a second approver","Treat it as a pricing failure — the budget was too expensive to survive a busy month — and reprice it","Automate the sign-off"],"correctIndex":2,"explanation":"Willpower failures of well-designed systems are rare; willpower failures of overpriced ones are guaranteed. Fix the design, and the person''s diligence becomes affordable again."},{"id":"q8","prompt":"\"You may only systematize what you have verified by hand\" — after this module, \"verified\" operationally means:","options":["The owner has read every output the workflow has produced","A sample was run once before launch","A written budget exists — sized to stakes, techniques matched to failure modes, a defined sign-off — and an honest sample has been run against real outputs","No errors have been reported by recipients"],"correctIndex":2,"explanation":"Not everything read (A is the decay trap), not one pre-launch glance (B), and never silence-as-evidence (D). A designed, running, honest verification layer — which is exactly the ticket M5 checks at the door."}]}', '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-calibration-prompt-before-you-start-10', 'ai201-m5', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. The capstone measures it.*

Think about actually running your workflow, end to end, yourself.

**What percentage of that runtime is mechanical shuttling** — pasting artifacts between steps,
re-attaching files, moving outputs to where they live — **versus actual judgment?** Write the
split down (e.g., "70% shuttling / 30% judgment").

This number is the honest case for agents, and most people get it wrong in a revealing
direction: they overestimate the judgment share, because judgment is what they remember doing.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-module-brief-20', 'ai201-m5', 20, 'prose', 'stable', '## Module brief

101 gave you the word: an **agent** is a model configured to take actions rather than only
respond — within whatever permissions it''s been given. You didn''t need it then. You need it now,
because your workflow has reached the point where the word gets practical.

Look at what you built across M1–M4. A spec. A pack. A pipeline whose steps run from a runbook,
one conversation each, artifacts carried between. A verification layer with real sample data.
And notice who''s doing the carrying: you, pasting a theme table from one conversation into the
next, every run, forever. The pipeline thinks; you shuttle.

An agent, concretely, is the thing that does the shuttling — and possibly more. It can run your
step prompts in sequence, read the source files itself, save the artifacts where they live, and
stop to ask you at the moments you''ve defined. The question this module teaches is not *whether
that''s possible* (it is, and Lesson 3 shows it) but *how much of it your workflow has earned* —
because autonomy is not a feature you turn on. It''s a level of trust you extend, one rung at a
time, priced in the verification evidence you built in M4.

Two sentences frame everything that follows. A wrong draft wastes minutes; a wrong action may
not be reversible. And the practitioner''s heuristic hasn''t moved: a workflow must not make
decisions about people — which means there are rungs some workflows must never climb, and
saying so in writing is the most senior judgment this course teaches.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-learning-objectives-30', 'ai201-m5', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Place any workflow step on the autonomy ladder — draft-only, propose-then-approve,
   act-with-audit-trail — and price the rung in M4 verification evidence.
2. Explain what agents change about failure: reversibility, blast radius, and why speed makes
   old failure modes worse rather than new ones rarer.
3. Distinguish a guardrail from a hope — permissions and tool scope versus polite instructions.
4. Describe what MCP is and watch a supervised agent run a pipeline step behind an approval
   gate. **[V]**
5. Write a refusal: a defensible "this workflow stays manual" with reasons that survive a
   curious executive.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-lesson-1-the-autonomy-ladder-40', 'ai201-m5', 40, 'prose', 'stable', '## Lesson 1 · The autonomy ladder

Three rungs. Each is a different answer to "what may the system do without waiting for you?" —
and each has a price, payable in evidence from M4, not in enthusiasm.

**Rung 1 — Draft-only.** The model produces; a human does everything else — reviews, decides,
moves, sends. This is where every workflow in this course has lived so far, and it is not the
beginners'' rung; it is the *permanent* rung for whole categories of work (Lesson 4). Price of
admission: the M4 baseline — a budget, a sign-off, an honest sample. You''ve paid it.

**Rung 2 — Propose-then-approve.** The agent executes steps and *stages* actions — the debrief
is formatted and sitting in the shared drive as a draft, the artifact is saved, the email is in
the outbox — but nothing crosses a boundary until a human approves. The approval *is* your M4
sign-off, reading list attached: what the approver looks at is defined, short, and real. Price:
your sampled error rate is below the escalation line you set in M4, across enough runs to mean
something — and the staged action is inspectable in seconds, not minutes. If approving takes as
long as doing, the rung bought nothing.

**Rung 3 — Act-with-audit-trail.** The agent completes defined actions without per-action
approval, and every action lands in a log reviewed on a cadence — sampling for actions, exactly
parallel to M4''s sampling for outputs. Price, and it''s steep: a *sustained* low error rate over
a run history, actions that are mechanical and checkable (file this artifact, update this
table), and — the master question — **reversibility**. An action you can undo cheaply may earn
rung 3. An action you can''t take back (a sent email, an external message) needs rung 2 at most,
usually forever.

Two rules make the ladder usable rather than decorative:

**Autonomy is granted per step, not per workflow.** Your pipeline''s extract step might earn
rung 3 (read files, produce a table — reversible, checkable); the narrate step rung 2; anything
person-adjacent stays rung 1. A workflow is a profile of rungs, not a single setting. This one
idea prevents both failure modes of agent adoption: all-or-nothing paralysis and all-at-once
recklessness.

**Skipping a rung is how the cautionary tales start.** Draft-only teaches you the failure modes
(M4''s sample). Rung 2 teaches you the *approval load* — how often you actually say no, which is
data: an approval you''ve never once declined in thirty runs is evidence for rung 3; an approval
you decline weekly is evidence the workflow isn''t ready, whatever the demo looked like. Rung 3
without that history isn''t automation; it''s hope with permissions.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-try-50', 'ai201-m5', 50, 'try_this', 'stable', '### Try this — 2 minutes
Take your pipeline''s steps from M3. For each, answer only the master question:

*If this step did its worst plausible thing, could I undo it in under five minutes?*

Yes, cheaply → rung 3 is discussable someday. Yes, awkwardly → rung 2 ceiling. No → rung 1,
and write down why. You''ve just drafted your autonomy profile.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-lesson-2-what-agents-change-about-failur-60', 'ai201-m5', 60, 'prose', 'stable', '## Lesson 2 · What agents change about failure

Nothing about 101''s failure modes went away. The model still fabricates, still flattens, still
can''t know your org beyond what you supply. What an agent changes is the *physics* around those
failures — three shifts, each with a design response.

**Reversibility replaces quality as the first question.** A bad draft costs the minutes it
takes to notice. A bad action costs whatever it costs — a wrong file overwritten, a half-updated
tracker, a message that left the building. Before an agent gets any action, you ask not "how
often will it be wrong?" but "when it''s wrong, what does undo look like?" That''s why the ladder
prices rung 3 on reversibility, and why "the agent drafts the email" and "the agent sends the
email" are different rungs separated by an irreversibility boundary, not a feature toggle.

**Speed multiplies exposure.** Your manual workflow produced errors at some rate, caught by an
M4 budget sized to a human pace. An agent runs the same workflow — same error rate — twenty
times while you''re in a meeting. The response is mechanical: when run frequency goes up, sample
size and audit cadence go up *with* it. An M4 budget priced for weekly manual runs is not a
budget for hourly agent runs; repricing is part of climbing.

**Guardrails must be permissions, not hopes.** "Please don''t email anyone" in a prompt is a
hope — a sentence competing with everything else in the context window. Not connecting the
email tool is a permission: a fact about what the agent *can* do, true regardless of what the
model predicts next. The design rule: **an agent''s tool list should mirror its rung, not its
potential.** Rung 2 agents get read tools and staging tools; send-and-commit tools simply
aren''t attached. You''ll recognize the pattern — it''s M2''s boundary discipline again, applied to
capabilities instead of data: what must not happen shouldn''t be *representable*, not just
discouraged.

And the people-line, one level up, stated without softening: **an agent must never hold
permissions that let it act on a person** — send the rejection, change the employment status,
update the candidate stage. Not because approval gates can''t be built, but because M4 showed
you what happens to approvals under load: they decay into rubber stamps, and a rubber-stamped
action on a person is the exact laundering M1 prohibited, now running at machine speed. Person-
affecting actions stay in human hands. The agent may prepare; it may never touch.

**The decision-laundering test.** The clear cases aren''t the hard ones. The hard ones are
decision-*support* that shades into deciding: no output names a person''s outcome, but the
outcome is in the output. So, for any workflow in the gray zone, ask:

> **If this output''s default were accepted unchanged, would a decision about a person have
> been made?**

Run it on the two cases that slip past the plain rule. A theme table ranked by severity doesn''t
decide anything — but if investigation resources follow the ranking, then accepting the default
ranking *was* the resourcing decision. A calibration packet presents only evidence — but if its
framing orders the candidates, then accepting the default framing shaped the rating. When the
test says yes, the workflow is person-adjacent whatever its name: the ranking or framing step
caps at draft-only; M4''s adversarial read gains a standing question (*what decision does this
output make if nobody pushes back?*); and the human in the loop must be visibly adding
judgment — reordering, dissenting, annotating — not just receiving. A reviewer who only ever
accepts the default is the test failing in real time, and that pattern is checkable in your
approval log.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-lesson-3-the-lab-mcp-and-an-agent-behind-70', 'ai201-m5', 70, 'prose', 'volatile', '## Lesson 3 · The lab — MCP, and an agent behind a gate [V]

*Volatile layer: current mechanics, tailored to your organization''s provisioned tools.*

**What MCP is, in course vocabulary.** The Model Context Protocol is a standard way to give a
model tools and data access — a defined set of things it may read and do, offered by a server,
connected to your assistant. When your organization connects an MCP server to Claude, it''s
answering exactly the questions this module taught: *what may this agent see, what may it do,
and what''s simply not attached?* The protocol is the permissions-not-hopes rule with a spec
sheet.

**What connecting looks like.** In Claude, an MCP connection appears as a set of named tools
the model can call — read this folder, search that system, save an artifact there. You (or your
admin) choose which servers, and each server declares its tools. The People-work examples that
matter: a document store scoped to your policy folder (read-only), a calendar, an export from
the HRIS that''s already been through the redaction you''ll design in M6. Note what''s happening
in ladder terms: *read* tools are cheap trust; *write* tools are rung decisions.

**The demonstration — this course, eating its own cooking.** This course ships as an MCP
server. Connected to Claude, it exposes the curriculum as tools: fetch a module''s runbook
patterns, pull the delegation heuristic, check a workflow spec against the course''s rules. In
the lab you watch a supervised agent run one step of a survey pipeline using it: the agent
reads the step prompt from the runbook, produces the theme table, and *stops* — the approval
gate — showing you the artifact and the action it wants to take ("save to the project''s
artifacts"). You read the table (your M3 checkpoint, unchanged), approve, and watch the action
land in the audit log. That pause is rung 2, made visible: the agent did the shuttling; the
checkpoint stayed human.

**What to notice.** Three things, all course-vocabulary made concrete: the agent never had a
send-anything tool (permissions, not hopes); the approval showed you an inspectable artifact,
not a summary of one (M4''s reading list); and the log entry is the audit trail rung 3 would
live on, if this step ever earns it.

**[V]** *Parity note:* ChatGPT and other assistants connect to MCP servers or equivalent tool
frameworks; names and connection flows differ, the ladder does not. Your deployment''s lab track
shows the mechanics in the tools your organization has actually provisioned.', NULL, '2026-08-07', 'claude');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-lesson-3-the-lab-mcp-and-an-agent-behind-70-chatgpt', 'ai201-m5', 70, 'prose', 'volatile', '## Lesson 3 · The lab — connectors, and an agent behind a gate [V]

*Volatile layer: current mechanics, tailored to your organization''s provisioned tools.*

**What a connector is, in course vocabulary.** A connector gives a model tools and data access
— a defined set of things it may read and do, offered by a service, attached to your assistant.
ChatGPT ships first-party connectors (document stores, calendars) and supports the Model
Context Protocol (MCP) for custom ones. When your organization attaches a connector, it''s
answering exactly the questions this module taught: *what may this agent see, what may it do,
and what''s simply not attached?* The mechanism is the permissions-not-hopes rule with a spec
sheet.

**What connecting looks like.** In ChatGPT, an attached connector appears as a set of named
tools the model can call — read this folder, search that system, save an artifact there. Your
admin chooses which connectors, and each declares its tools. The People-work examples that
matter: a document store scoped to your policy folder (read-only), a calendar, an export from
the HRIS that''s already been through the redaction you''ll design in M6. Note what''s happening
in ladder terms: *read* tools are cheap trust; *write* tools are rung decisions.

**The demonstration — this course, eating its own cooking.** This course ships as an MCP
server, and ChatGPT can attach it as a custom connector. Connected, it exposes the curriculum
as tools: fetch a module''s runbook patterns, pull the delegation heuristic, check a workflow
spec against the course''s rules. In the lab you watch a supervised agent run one step of a
survey pipeline using it: the agent reads the step prompt from the runbook, produces the theme
table, and *stops* — the approval gate — showing you the artifact and the action it wants to
take ("save to the project''s files"). You read the table (your M3 checkpoint, unchanged),
approve, and watch the action land in the audit log. That pause is rung 2, made visible: the
agent did the shuttling; the checkpoint stayed human.

**What to notice.** Three things, all course-vocabulary made concrete: the agent never had a
send-anything tool (permissions, not hopes); the approval showed you an inspectable artifact,
not a summary of one (M4''s reading list); and the log entry is the audit trail rung 3 would
live on, if this step ever earns it.

**[V]** *Parity note:* Claude and other assistants connect to MCP servers or equivalent tool
frameworks; names and connection flows differ, the ladder does not. Your deployment''s lab track
shows the mechanics in the tools your organization has actually provisioned.', NULL, '2026-08-08', 'chatgpt');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-lesson-4-the-refusal-80', 'ai201-m5', 80, 'prose', 'stable', '## Lesson 4 · The refusal

Some workflows must never climb. Saying so, in writing, before anyone asks — that''s not
timidity; it''s the most senior artifact this course produces.

**What earns a permanent rung 1 (or a permanent "no workflow at all"):**

- **Person-affecting output or action** — the M1 line and its agent-level extension from
  Lesson 2. The packet informs; the human decides; nothing about that is waiting for better
  models.
- **Judgment-dense work that happens to recur** — the grievance response, the sensitive
  conversation. M1''s sorting exercise flagged these; agent tooling doesn''t unflag them.
- **Low-frequency, high-stakes work** — the RIF communication. No run history can ever
  accumulate, so no rung above 1 can ever be priced. The ladder isn''t pessimistic about these;
  it''s *unpriceable*, which is the same answer with better reasoning.
- **Material that can''t safely be supplied** — where the inputs themselves are the problem.
  M6 makes this precise next module.

**Writing the no.** One line in the spec, three parts: the ceiling, its permanence, the reason.
*"Autonomy ceiling: draft-only, permanent. This workflow''s output shapes treatment of named
individuals; under the course heuristic it must not act, and approval-gated action would decay
into laundering under load."* That sentence does real work. It survives the M8 handoff — your
successor inherits the boundary with its reasoning attached. And it survives the executive who
asks, reasonably, "can''t we automate the rest of this?" — because it shows the automation
*decision was made*, deliberately, by someone who understood the ladder, rather than defaulted
into by someone who feared it.

**The refusal is reviewable, not sacred.** Permanent ceilings get revisited when the *reasons*
change — the workflow''s scope shifts, the inputs change tier — never merely because the tools
got better. "The model is more capable now" changes nothing about an unpriceable run history or
a person on the receiving end. Write the review trigger into the line if it has one.
', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-exercise', 'ai201-m5', 85, 'exercise', 'stable', '{"type": "sorting", "title": "Exercise — Assign the rung", "intro": "Five minutes. Six steps from a People team''s workflows. Assign each its **maximum responsible rung** — assume M4 budgets exist and error rates are good.\n\nTwo items are rigged to separate “reversible” from “feels routine.”"}', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-key-takeaways-90', 'ai201-m5', 90, 'takeaways', 'stable', '## Key takeaways

- **Autonomy is trust extended one rung at a time** — draft-only, propose-then-approve,
  act-with-audit-trail — priced in M4 evidence, granted per step, never per workflow.
- **Reversibility is the master question.** A wrong draft costs minutes; a wrong action costs
  whatever undo costs. Irreversible actions cap at rung 2 — usually forever.
- **Speed multiplies exposure.** Agent-rate runs need agent-rate sampling. Climbing a rung
  reprices the M4 budget; that''s part of the fare.
- **Guardrails are permissions, not hopes.** The tool list mirrors the rung; what must not
  happen isn''t representable. "Please don''t" is not a control.
- **An agent must never hold permissions that act on a person.** Approval gates decay under
  load; a rubber-stamped action on a person is laundering at machine speed. Prepare, never touch.
- **The laundering test for the gray zone:** if this output''s default were accepted unchanged,
  would a decision about a person have been made? Yes means person-adjacent rules apply,
  whatever the output is called.
- **The refusal is a senior artifact.** Ceiling, permanence, reason — written before anyone
  asks, reviewed when reasons change, never merely because tools improved.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-sources-and-attribution-110', 'ai201-m5', 110, 'prose', 'stable', '## Sources and attribution

Builds on 101 M1 (the agent definition; the decisions-about-people line) and 201 M2–M4 (boundary
discipline extended from data to capabilities; pipelines and artifacts; the budget, sign-off
decay, and escalation line). The three-rung ladder, per-step autonomy profiles, approval-load-
as-evidence, reversibility as the master question, and the refusal-as-artifact framing are
original to this course — but the human-oversight failure modes they defend against are
formally studied, and worth citing when the laundering argument is challenged:

1. **Bainbridge, L. — "Ironies of Automation," *Automatica* 19(6) (1983).** The supervisor of
   an automated system inherits the hardest version of the job — the structural argument under
   the approval-decay claim.
2. **Parasuraman, R. & Riley, V. — "Humans and Automation: Use, Misuse, Disuse, Abuse,"
   *Human Factors* 39(2) (1997).** Automation complacency and misplaced trust — why "a human
   clicks approve" degrades under load, measured.

Lesson 3 and marked passages are volatile layer — MCP and tool mechanics current as of the
stamp date, tailored per deployment.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-activity-capstone-stage-5-the-decision-memo-10', 'ai201-m5-activity', 10, 'prose', 'stable', '## Capstone stage 5 · The decision memo

Your workflow''s autonomy profile, decided and defended. This memo is graded hardest on the
reasoning for the rung — ambition earns nothing; evidence does.

**Submit:**

1. **The shuttling measurement.** Time one real run. Report the actual shuttling/judgment
   split against your calibration prediction from the top of the module, direction of miss
   named. This is your honest case for (or against) bothering with an agent at all.
2. **The profile.** Each pipeline step: its rung, priced in your M4 evidence — sampled error
   rate vs. your escalation line, what the approval would read (rung 2), reversibility and
   audit cadence (rung 3). A step you''re keeping at rung 1 needs a sentence too: "not yet" and
   "never" are different answers with different reasons.
3. **The guardrail spec** — for any step above rung 1: tools granted, tools *deliberately not
   attached* (name them — the unattached list is the design), approval points and their
   reading lists, the audit log and who reviews it on what cadence, and the blast-radius
   sentence: the worst plausible action and what undo looks like.
4. **The refusal, if it applies** — and for most first workflows it applies somewhere: the
   ceiling line, written per Lesson 4, review trigger included if one exists.

### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Rung reasoning** | Every rung priced in verification evidence, not capability enthusiasm. "Not yet" distinguished from "never," both defended. |
| **Guardrails are permissions** | The spec controls what''s attached, not what''s requested. The not-attached list is present and thoughtful. Blast radius stated honestly. |
| **Per-step granularity** | The profile treats steps individually; any all-or-nothing answer is argued for, not defaulted to. |
| **Calibration** | Shuttling prediction recorded first, measured against a real run, direction of miss named. Honesty and specificity graded; accuracy never. |', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-micro-core', 'ai201-m5-micro', 10, 'prose', 'stable', '## Module 5 in two minutes

**Autonomy is trust extended one rung at a time:** draft-only → propose-then-approve → act-with-audit-trail. Each rung is priced in verification evidence — your sampled error rate, your approval history — never in capability enthusiasm. And it''s granted per step, not per workflow: a pipeline is a profile of rungs.

**Reversibility is the master question.** A wrong draft costs minutes; a wrong action costs whatever undo costs. Irreversible actions — send, publish, touch a record — keep a human at the boundary regardless of stakes. And guardrails are permissions, not hopes: control what tools are attached; what must not happen shouldn''t be representable.

**The person-line, at agent level:** an agent must never hold permissions that act on a person. Approvals decay under load, and a rubber-stamped action on a person is decision-laundering at machine speed. For the gray zone, the test: *if this output''s default were accepted unchanged, would a decision about a person have been made?* Yes means person-adjacent rules apply, whatever the output is called.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-micro-rule', 'ai201-m5-micro', 20, 'callout', 'stable', '### The refusal

Some workflows never climb: person-affecting work, judgment-dense work, low-frequency high-stakes work whose run history can never accumulate. Writing the ceiling down — with its reason — is the most senior artifact this course produces.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m5-micro-close', 'ai201-m5-micro', 30, 'prose', 'stable', '**The full module adds** the assign-the-rung exercise, the MCP lab with a supervised agent behind a visible approval gate, and capstone stage 5: your workflow''s autonomy decision memo.', NULL, '2026-08-07', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m5-sorting', 'ai201-m5', 'sorting', '{"reviewedAt":"2026-08-07","buckets":[{"id":"refuse","label":"R — refusal","hint":"Shouldn''t be in an agent''s hands at all","rank":0,"pct":0},{"id":"rung1","label":"Rung 1 — draft only","hint":"The agent drafts; a human does everything else","rank":1,"pct":30},{"id":"rung2","label":"Rung 2 — propose, approve","hint":"The agent stages; a human''s click is the boundary","rank":2,"pct":60},{"id":"rung3","label":"Rung 3 — act, audit trail","hint":"The agent acts; the record shows everything","rank":3,"pct":90}],"tasks":[{"id":"t1","text":"Extract a theme table from this quarter''s survey verbatims","key":"rung3","reasoning":"Read-only input, structured checkable output, trivially reversible (regenerate) — and your M3 checkpoint still reviews the artifact downstream. This is what rung 3 was made for. One caveat from Lesson 2: if the table were ranked by severity to direct investigation resources, the laundering test applies and the ranking step is person-adjacent even though extraction isn''t."},{"id":"t2","text":"Draft rejection emails for the week''s declined candidates","key":"rung1","reasoning":"Rung 1, permanent. Drafting is legitimate — M1''s sorting said so; anything above draft-only walks toward the person-line. The draft lands in a human''s hands; a human sends, every time. The trap in the wording: ''draft'' was always the rung — the question is refusing the climb."},{"id":"t3","text":"Save the formatted debrief into the hiring channel''s shared folder","key":"rung2","also":["rung3"],"reasoning":"First rigged item. It feels routine and it''s probably reversible — but ''save to where the hiring team reads'' is a small publish. Rung 2 until the approval log shows you never decline; then rung 3 is an evidence-based conversation."},{"id":"t4","text":"Send the weekly HR newsletter to the all-staff list","key":"rung2","reasoning":"The reverse trap: low stakes, so rung 3 feels fine — but send-to-all-staff is irreversible, and reversibility, not stakes, sets the cap. The agent stages it in the outbox; the human''s click costs three seconds; the un-sendable email costs more."},{"id":"t5","text":"Update each candidate''s stage in the ATS after the debrief meeting","key":"refuse","reasoning":"An action on a person''s process in the system of record. The agent may prepare the list of stage changes as an artifact — rung 1–2 work; the human executes in the ATS. If the volume makes that painful, the pain is information about the process, not a case for permissions."},{"id":"t6","text":"Compile the weekly people-metrics table from the HRIS export","key":"rung3","reasoning":"Mechanical, checkable against the export, regenerable, feeding a human-owned narrative downstream. With a sampled error history, the least controversial climb on the board."}],"pattern":"Rung 3 lives where work is mechanical, checkable, and undoable. The boundary crossings — publish, send, touch a person''s record — are where humans stand.","postscript":"The two rigged items — the shared-folder save and the newsletter send — show the tell isn''t how routine a step feels but what its undo costs."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m5-rubric', 'ai201-m5', 'rubric', '{"promptVersion":"ai201-m5-capstone-v1","moduleId":"ai201-m5","minChars":600,"submitLabel":"Your capstone-stage submission","intro":"Submit the artifacts this stage asks for, as text. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 201, The Practitioner). Capstone stage 5: the autonomy decision memo — the measured shuttling split, a per-step rung profile priced in verification evidence, the guardrail spec with the deliberately-not-attached tool list, and the refusal where it applies. Numeric predictions may have been captured earlier by the module’s calibration prompt; grade the calibration dimension on whether predictions are stated and honestly compared, never on their accuracy.","calibration":[{"key":"shuttlingActual","label":"Measured — shuttling % from your timed run","hint":"The stage’s timed end-to-end run, watch in hand.","placeholder":"e.g. 75","min":0,"max":100,"actualFor":"shuttling"}],"dimensions":[{"name":"Rung reasoning","criteria":"Every rung priced in verification evidence, not capability enthusiasm. \"Not yet\" distinguished from \"never,\" both defended."},{"name":"Guardrails are permissions","criteria":"The spec controls what''s attached, not what''s requested. The not-attached list is present and thoughtful. Blast radius stated honestly."},{"name":"Per-step granularity","criteria":"The profile treats steps individually; any all-or-nothing answer is argued for, not defaulted to."},{"name":"Calibration","criteria":"Shuttling prediction recorded first, measured against a real run, direction of miss named. Honesty and specificity graded; accuracy never."}],"opening":[{"key":"shuttling","label":"Predicted — % of a run that is mechanical shuttling","hint":"Pasting, re-attaching, moving artifacts — versus actual judgment.","placeholder":"e.g. 60","min":0,"max":100}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m5-knowledge_check', 'ai201-m5', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the decision memo is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"The three rungs of the autonomy ladder, in order of extended trust:","options":["Read-only → read-write → admin","Draft-only → propose-then-approve → act-with-audit-trail","Manual → assisted → autonomous","Chat → project → agent"],"correctIndex":1,"explanation":"Each rung is an answer to \"what may the system do without waiting for you?\" — and each is priced in verification evidence, not capability."},{"id":"q2","prompt":"What is the \"price\" of rung 2 (propose-then-approve)?","options":["An enterprise license for agent features","A sampled error rate below your M4 escalation line, plus an approval that''s inspectable in seconds with a defined reading list","Manager authorization","A successful demo of the agent completing the workflow"],"correctIndex":1,"explanation":"The ladder is priced in M4 currency. A demo (D) is capability evidence; the ladder runs on *verification* evidence — your error history, your escalation line, your reading list."},{"id":"q3","prompt":"Why does reversibility, not stakes, cap the newsletter-send at rung 2?","options":["Newsletters are high-stakes communications","Sending to all-staff cannot be undone, and irreversible actions keep a human at the boundary regardless of how low the stakes are","Email tools cannot be connected to agents","It doesn''t — low stakes justify rung 3"],"correctIndex":1,"explanation":"The master question is what undo costs. Low stakes shrink the *harm*; they don''t restore the *option*. The three-second human click is the cheapest control in the module."},{"id":"q4","prompt":"\"Guardrails are permissions, not hopes\" means:","options":["Write guardrail instructions in the system prompt, prominently","Control what tools are attached — what must not happen shouldn''t be representable","Require the agent to confirm it understands its restrictions","Log all agent actions for review"],"correctIndex":1,"explanation":"An instruction is a sentence competing inside a context window; an unattached tool is a fact. A and C are instructions, not permissions; D is necessary for rung 3 but doesn''t *prevent* anything."},{"id":"q5","prompt":"An approval you have never once declined across thirty runs is:","options":["Proof the approval step is unnecessary bureaucracy","Evidence for a rung-3 conversation about that step — the approval load data the ladder asks for","Evidence the approver isn''t reading carefully","Normal, and means nothing"],"correctIndex":1,"explanation":"Rung 2 generates exactly this data: how often the human actually says no. A clean approval history is the evidence-based case for climbing; a decline-heavy one is the case the workflow isn''t ready. (C is possible — which is why the approval''s reading list is defined; an approver who stopped reading is M4''s repricing signal.)"},{"id":"q6","prompt":"Why does the module bar agents from holding person-affecting permissions even behind approval gates?","options":["Regulations prohibit all agent actions in HR systems","Models aren''t accurate enough yet for personnel actions","Approvals decay into rubber stamps under load, and a rubber-stamped action on a person is decision-laundering at machine speed","Person-affecting actions are too slow to automate profitably"],"correctIndex":2,"explanation":"The argument is structural, not statistical: M4 showed what load does to approvals, and M1''s line — the human must genuinely decide — can''t survive that decay when actions fire at agent speed. B implies better models change the answer; they don''t."},{"id":"q7","prompt":"The RIF communication can never climb above rung 1 because:","options":["It''s too emotionally sensitive for a model to draft","As low-frequency, high-stakes work, no run history can accumulate — so no higher rung can ever be priced","Legal review is required for RIF communications","It can, once error rates on other workflows are established"],"correctIndex":1,"explanation":"The ladder''s currency is run history for *this* work; other workflows'' evidence (D) doesn''t transfer. \"Unpriceable\" is the ladder''s own vocabulary for why some ceilings are permanent — better reasoning than \"too risky,\" same conclusion."},{"id":"q8","prompt":"A well-written refusal contains:","options":["The ceiling, its permanence, the reason — and a review trigger tied to changed reasons, not improved tools","A list of the agent features evaluated and rejected","The date after which automation will be reconsidered","Sign-off from IT and Legal"],"correctIndex":0,"explanation":"The refusal is a decision artifact: it shows the automation decision was *made*, with reasoning a successor and a curious executive can both read. C reconsiders on a calendar; the module reconsiders when reasons change — \"the model got better\" isn''t one."}]}', '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-calibration-prompt-before-you-start-10', 'ai201-m6', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*Two predictions, thirty seconds. The capstone scores them.*

Think about one full run of your workflow — everything that enters it.

1. **How many distinct data elements flow in per run?** (A document is one. A pasted table is
   one. The names inside them count separately.) A number.
2. **How many of those identify a person** — by name, or by description specific enough that a
   colleague could tell you who it is?

The second question has a trap in it, and the trap is the module.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-module-brief-20', 'ai201-m6', 20, 'prose', 'stable', '## Module brief

In 101 you asked "what can I paste?" once, about one conversation, with your judgment fully
engaged. You learned the answer depends on the tool and the agreement, and you learned to find
out which situation you''re in before pasting, not after.

Then you spent five modules building something that pastes on a schedule.

That''s the shift this module exists for. A workflow asks the what-can-I-paste question every
run, forever — sometimes with your judgment engaged, eventually (M5) with an agent doing the
supplying and your judgment showing up only at defined gates. M2 planted the flag: **people data
must never become infrastructure.** This module builds the whole fence: a tier system for
inputs, redaction and minimization as *designed pipeline steps* rather than good intentions,
the agreement layer underneath it all, and — because honesty beats optimism — the escalation
path for the day something goes through anyway.

One reframe before we start, because it changes the mood of everything that follows. This
module is not the compliance tax on the fun modules. In People work, the data boundary *is* the
product: an exec who trusts your workflow''s boundary sheet will let you run things no other
function gets to run, and an exec who doesn''t will shut down your best build over one
carelessly pasted export. The boundary work is what makes the rest of the course deployable.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-learning-objectives-30', 'ai201-m6', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Tier any input — public, internal, person-identifying, protected — in seconds, including the
   descriptions-without-names that fail the tier test people expect them to pass.
2. Apply the person-test to a run: could this run be shown to the person it concerns?
3. Design redaction and minimization as pipeline steps, and spot the re-identification traps
   that survive naive redaction.
4. Say which agreement situation your organization is in, and what each tier is permitted to
   touch there. **[V]**
5. Run the escalation path from memory — because the day it''s needed is the wrong day to draft it.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-lesson-1-the-tiers-40', 'ai201-m6', 40, 'prose', 'stable', '## Lesson 1 · The tiers

Four tiers. The skill is speed — tiering should take seconds per input, which is why there are
four and not eleven.

**Tier 1 · Public.** Already published or publishable without a thought: your careers page, the
public holiday calendar, a job posting. Goes anywhere your organization permits AI use at all.

**Tier 2 · Internal.** Not secret, not personal: policy text, the org context brief from M2,
process docs, aggregated metrics that don''t isolate individuals. The workhorse tier — most
workflow inputs should live here, and a well-designed pipeline (Lesson 2) *makes* them live
here. Permitted in your organization''s sanctioned deployment; never in a personal consumer
account, which 101 already told you and Lesson 3 makes contractual.

**Tier 3 · Person-identifying.** Anything that points at an identifiable individual: names in
interview notes, a single person''s compensation, performance commentary, an email thread with
an employee. Here''s the trap from the calibration prompt: **identification doesn''t require a
name.** "The only woman on the Denver sales team." "Our newest director, the one who joined
from the retailer." "The employee on leave since March." If a colleague could tell you who it
is, it''s Tier 3, whatever the redaction looked like. Tier 3 may enter a run — *fresh, minimized,
under that run''s judgment, in a sanctioned deployment* — and it never enters infrastructure:
not packs, not instructions, not runbooks, not saved artifacts that outlive their purpose.

**Tier 4 · Protected.** The material where a mistake isn''t embarrassing but reportable: health
and medical information, investigation files, protected characteristics, anything under legal
hold or active dispute. Default answer: **it doesn''t go in.** Not "be careful" — doesn''t go in,
absent an explicit, named, written clearance from whoever owns that risk in your organization
(usually legal), for a specific purpose, in a specific deployment. If your workflow seems to
need Tier 4 routinely, the finding isn''t "get clearance routinely"; it''s M1''s finding — this
shouldn''t be a workflow.

**The person-test**, which compresses the whole tier system into one question you can ask at
the checkpoint pause:

> **Could this run — inputs, prompts, and outputs — be shown to the person it concerns?**

Not "would it be comfortable." Could it be shown without breaching a confidence, exposing
someone''s health or dispute, or revealing that their treatment was shaped by material they''ve
never seen? A run that passes is almost always tiered right. A run that makes you wince is
telling you which input to go re-tier.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-lesson-2-redaction-and-minimization-as-s-50', 'ai201-m6', 50, 'prose', 'stable', '## Lesson 2 · Redaction and minimization, as steps

Good intentions redact; pipelines redact *reliably*. The difference is where the redaction
lives — and M3 already gave you the answer: it''s a step, with a checkpoint, at the front.

**Step zero.** Sensitive workflows get a preparation step before the model sees anything: the
raw export goes in, the minimized artifact comes out, and the checkpoint is a human glance at
*that artifact* — not at the raw file — before anything proceeds. In M5 terms, later steps
never even hold the unminimized material: permissions, not hopes, applied to data.

**Minimization first, redaction second.** The stronger move is not masking what''s sensitive —
it''s not carrying it at all. Ask the M1 question in reverse: *what does this transformation
actually need?* The debrief pipeline needs the candidate''s interview evidence; it doesn''t need
their address, their current employer, or their salary expectations, and a step-zero that
extracts only competency-relevant material outperforms any masking of the rest. Then redact
what remains: roles for names ("Candidate A," "the manager"), buckets for exact figures, dates
coarsened to what the analysis needs.

**The re-identification traps** — the three ways naively redacted material stays Tier 3:

- **Small-n.** "One of the three engineers on the platform team said…" is a name with extra
  steps. Aggregations below a floor (five is a common one; your org may set its own) stay
  identifying no matter how neutral the wording.
- **Distinctive detail.** Tenure + office + role narrows to one human fast. The Denver survey
  pipeline from M3 handled concentration honestly at the *theme* level — "concentrated in
  Denver" — without quoting the one comment whose phrasing everyone in Denver would recognize.
  Both halves of that were design choices.
- **Convergence.** Each artifact is clean; the set is not. The theme table says Denver, the
  quote mentions a product launch, the narrative mentions tenure — assembled, they point at one
  person. This is why the person-test runs on *the run*, not on each artifact separately.

**And the boundary between judgment and infrastructure, restated as practice.** A Tier 3 run
ends with hygiene: the fresh material leaves with the run. Artifacts that persist — saved
tables, audit logs, the M8 portfolio — persist in their minimized form. If you find Tier 3
material accumulating anywhere a future conversation can see, you''ve rebuilt the thing M2
prohibited, one convenient save at a time.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-try-60', 'ai201-m6', 60, 'try_this', 'stable', '### Try this — 3 minutes
Take a real artifact from your workflow''s last run — the theme table, a debrief, whatever
exists.

1. Run the person-test on it.
2. Hunt specifically for the three traps: small-n, distinctive detail, convergence with its
   sibling artifacts.
3. If it passes clean, ask the sharper question: did it pass by design, or by luck? A step
   zero is the difference.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-lesson-3-the-agreement-layer-70', 'ai201-m6', 70, 'prose', 'volatile', '## Lesson 3 · The agreement layer [V]

*Volatile layer: contracts, retention, and deployment specifics change — and differ by
organization. Your deployment tailors this lesson to your actual situation; the questions below
are the stable part.*

Everything in Lessons 1–2 assumed a phrase: "sanctioned deployment." Here''s what stands behind
it, and what you need to know about yours — not to negotiate it, but to stop being wrong about it.

**The situations, in rising order of what they permit.** A personal consumer account: your
agreement, not your employer''s; Tier 1 only, and honestly not even that for work purposes if
your org has a sanctioned alternative. A business/enterprise deployment: the organization''s
agreement, typically with commitments that customer data isn''t used for training and with
admin-controlled retention — this is usually what "sanctioned" means, and where Tier 2 lives
comfortably and Tier 3 can enter runs under the rules above. Deployments with a data processing
agreement and security review: where your org has done the diligence that makes the Tier 3
rules defensible rather than hopeful.

**The four questions that define your situation** — get the answers from whoever owns the
deployment (IT, security, legal), write them into your boundary sheet, and re-verify on your
volatile cadence:

1. Which tools are sanctioned, and which account am I actually signed into right now?
2. Is our data used for model training, and where''s that written?
3. What''s the retention — how long do conversations and uploads persist, and who can delete?
4. Who owns this contract, and who do I call when something goes wrong? (Lesson 4 needs this
   name.)

**If nobody has these answers,** 101 said the gap is worth raising; the practitioner''s version
is stronger: the gap is *your finding*, and surfacing it — "I built a workflow worth running
and can''t determine whether it''s permitted" — is exactly the kind of contribution that gets a
People leader invited into the AI governance conversation. That''s AI 401''s whole territory;
you''re allowed to arrive early.

**The provisional boundary sheet.** What the gap must not do is stop the course. IT, security,
and legal answer on their calendars, not yours, and a question in flight is not a reason to
stall a build for a month. The mechanism: any unanswered question is marked **UNKNOWN**, with
the owner you asked and the date you asked them. The sheet''s status becomes **provisional —
sign-off pending**, and while it stays provisional the workflow runs under the most restrictive
plausible answers: Tier 2 ceiling, no Tier 3 inputs, nothing above draft-only autonomy for
steps the unknowns touch. M8 accepts a provisional sheet — the gap rides visibly on the index
page, where a reviewer sees it before anything else. A provisional sheet with named unknowns
and recorded pursuit is a working control. A course stalled on someone else''s inbox is not.

**MCP note, because M5 opened the door:** every server your agent connects is part of the
agreement layer. A document store connected to Claude is data flowing under *some* agreement —
the four questions apply to it, per server, and "read-only" answers the ladder question, not
the agreement question.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-lesson-4-when-it-goes-wrong-anyway-80', 'ai201-m6', 80, 'prose', 'stable', '## Lesson 4 · When it goes wrong anyway

Someone will paste the wrong thing. Possibly you. The measure of a practitioner isn''t a
spotless record — it''s whether the bad day was handled in minutes by a path written in
advance, or improvised in a panic and half-hidden.

**The path, four steps, in order:**

1. **Stop the run.** Don''t finish the pipeline, don''t let staged actions fire, don''t "just get
   this output first."
2. **Record the facts while they''re fresh:** what went in, which tool and account, when, what
   the material contained, whether outputs were produced or actions taken. Five minutes,
   written down.
3. **Tell the deployment owner** — the name from Lesson 3, question 4. They know what the
   agreement provides: deletion mechanisms, retention overrides, whether this rises to a
   notifiable event. **[V]** Provider deletion and retention controls vary by tool and tier of
   contract; that''s their lookup, not your guess.
4. **Fix the system, not just the moment.** M4''s reflex, one more time: how did the material
   get to the model? A missing step zero, a raw file where a minimized artifact belonged, a
   pack that quietly accumulated? The incident is data about the workflow. Spend it.

**And the culture line, which is also a design line:** the escalation path only works if using
it is safe. A team where a wrong paste means quiet shame produces hidden incidents, and hidden
incidents are the only truly unmanageable kind. You''re a People leader; you already know this
pattern from every other kind of incident. It applies to this one.
', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-exercise', 'ai201-m6', 85, 'exercise', 'stable', '{"type": "sorting", "title": "Exercise — Tier the inputs", "intro": "Five minutes. Ten inputs headed into a People team''s workflows. Tier each.\n\nThe pattern, stated in advance: tier by what a reader could learn, not by what a label says. Names removed isn''t identity removed; aggregated isn''t always anonymous; and health, investigations, and accommodations are Tier 4 wherever they appear."}', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-key-takeaways-90', 'ai201-m6', 90, 'takeaways', 'stable', '## Key takeaways

- **A workflow asks "what can I paste?" every run, forever** — so the answer has to live in the
  design, not in the mood of the person running it.
- **Four tiers, seconds each:** public, internal, person-identifying, protected. Identification
  doesn''t require a name; a description a colleague could resolve is Tier 3.
- **The person-test:** could this run be shown to the person it concerns? Run it on the run,
  not the artifact — convergence is the trap that survives per-artifact checks.
- **Minimize before you redact; redact as a step, not an intention.** Step zero, checkpoint on
  the minimized artifact, later steps never hold the raw material.
- **Tier 4 doesn''t go in.** Routine need for Tier 4 means it shouldn''t be a workflow — M1''s
  finding, arrived at from the data side.
- **Know your agreement situation, and the name you''d call.** [V] The four questions, answered
  and dated, are what "sanctioned" actually means. Unanswered questions make the sheet
  provisional — lowered ceiling, pursuit recorded, gap visible — not the course stuck.
- **The escalation path is written before it''s needed, and safe to use** — because hidden
  incidents are the only unmanageable kind.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-sources-and-attribution-110', 'ai201-m6', 110, 'prose', 'stable', '## Sources and attribution

Builds on 101 M1 Lesson 4 (the paste gradient; find out which situation you''re in) and 201
M2/M3/M5 (never-infrastructure, step design, permissions-not-hopes). The four-tier system and
the person-test are this course''s packaging; the re-identification material and the small-n
floor sit on an established disclosure-control literature, which is where a privacy counsel or
a data-literate reviewer will (correctly) look for the load-bearing claims:

*To be verified against editions and current URLs before publication; the regulatory items move
— re-check with counsel on the Tier 1 quarterly cadence.*

1. **Sweeney, L. — "k-Anonymity: A Model for Protecting Privacy," *International Journal of
   Uncertainty, Fuzziness and Knowledge-Based Systems* 10(5) (2002).** The formal basis for
   the small-n idea: a record is only as anonymous as the size of the group it hides in.
2. **Narayanan, A. & Shmatikov, V. — "Robust De-anonymization of Large Sparse Datasets,"
   *IEEE Symposium on Security and Privacy* (2008).** Re-identification through auxiliary
   information — the convergence trap, demonstrated at scale on data everyone thought was clean.
3. **Hundepool, A. et al. — *Statistical Disclosure Control* (Wiley, 2012).** The official-
   statistics treatment of threshold rules. Lesson 2''s "five is a common floor" reflects
   national-statistics practice, where minimum cell sizes of roughly three to ten are standard;
   the module''s advice stands: set your organization''s floor deliberately, don''t inherit one.
4. **HIPAA de-identification standard, 45 CFR §164.514 [V].** Safe Harbor and Expert
   Determination — the US regulatory version of tiering and minimization, and useful precedent
   language when writing your own floor.
5. **Article 29 Working Party — Opinion 05/2014 on Anonymisation Techniques [V].** The EU
   analysis of why "names removed" is not anonymized — the regulator''s version of this
   module''s central correction.

Lesson 3 and marked passages are volatile layer — agreement and retention specifics verified
per deployment, on the stamp date''s cadence, with counsel where it counts.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-activity-capstone-stage-6-the-boundary-sheet-10', 'ai201-m6-activity', 10, 'prose', 'stable', '## Capstone stage 6 · The boundary sheet

One page that makes your workflow deployable. This is the document M8 checks at the door, and
the one an exec or security reviewer reads first.

**Submit:**

1. **The input census** — every input from your M3 pipeline design, tiered, with one clause of
   reasoning where the tier isn''t obvious. Score your calibration from the top of the module:
   both counts, both misses, direction named. (The usual miss: Tier 3 hiding in "descriptions
   without names.")
2. **The mitigations** — for anything Tier 3: the step zero that minimizes it, what the
   minimized artifact looks like, and where the person-test runs. For anything Tier 4: the
   removal — or the named, written clearance, if you genuinely hold one.
3. **The agreement answers** — Lesson 3''s four questions, answered for your actual deployment,
   with the source of each answer and its re-verify date. "I don''t know yet, and here''s who
   I''ve asked" is an honest, gradeable answer; a guess is not. If any answer is UNKNOWN, mark
   the sheet **provisional**: record the owner and date asked, state the lowered ceiling you''re
   operating under until it lands, and carry the status line forward — it appears on your M8
   index page until the sign-off completes.
4. **The escalation card** — the four steps with your organization''s real names and channels
   filled in, short enough to use mid-incident.
5. **The sign-off line, extended** — your M4 sign-off now reads the boundary too: one sentence
   adding the person-test (and, where relevant, the minimized-artifact check) to the owner''s
   reading list.

### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Tier honesty** | The census is complete and the tricky calls — descriptions, small-n, convergence — are caught and reasoned, not waved through. |
| **Mitigation matches tier** | Step-zero designs are real pipeline steps with checkpoints; Tier 4 handling is removal or named clearance, never "carefully." |
| **The agreement layer is factual** | Four questions answered from sources, not assumptions; unknowns owned honestly with a pursuit plan. |
| **Calibration** | Both counts predicted first, scored against the census, direction of error named. Honesty and specificity graded; accuracy never. |', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-micro-core', 'ai201-m6-micro', 10, 'prose', 'stable', '## Module 6 in two minutes

**A workflow asks "what can I paste?" every run, forever** — so the answer has to live in the design. Four tiers, seconds each: public, internal, person-identifying, protected. The trap: identification doesn''t require a name. "The only nurse on the night shift" is Tier 3; so is a spreadsheet keyed by employee ID.

**The person-test:** could this run — inputs, prompts, outputs — be shown to the person it concerns? Run it on the whole run, because individually clean artifacts converge. Minimize before you redact (material you never carry can''t leak), and make redaction a pipeline step with its own checkpoint, not an intention. **Tier 4 — health, investigations, protected characteristics — doesn''t go in.** A workflow that routinely needs it shouldn''t be a workflow.

**Know your agreement situation:** which tools are sanctioned, whether your data trains models, what retention applies, who you''d call. Unanswered questions make your boundary sheet *provisional* — lowered ceiling, pursuit recorded, gap visible — not the course stuck. And the escalation path for a wrong paste is written before it''s needed, and safe to use.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-micro-rule', 'ai201-m6-micro', 20, 'callout', 'stable', '### The infrastructure rule

People data never becomes infrastructure, and a run that touches it ends with hygiene: fresh material leaves with the run; what persists, persists minimized.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m6-micro-close', 'ai201-m6-micro', 30, 'prose', 'stable', '**The full module adds** the ten-input tiering exercise, the disclosure-control literature behind the small-n floor, and capstone stage 6: your workflow''s boundary sheet.', NULL, '2026-08-07', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m6-sorting', 'ai201-m6', 'sorting', '{"reviewedAt":"2026-08-07","buckets":[{"id":"t1pub","label":"Tier 1 · Public","hint":"Published is published","rank":1,"pct":10},{"id":"t2int","label":"Tier 2 · Internal","hint":"Impersonal org material — the workhorse tier","rank":2,"pct":40},{"id":"t3pid","label":"Tier 3 · Person-identifying","hint":"A reader could resolve it to a person","rank":3,"pct":75},{"id":"t4prot","label":"Tier 4 · Protected","hint":"Health, investigations, accommodations — doesn''t go in","rank":4,"pct":95}],"tasks":[{"id":"t1","text":"The employee handbook, current version","key":"t2int","reasoning":"Internal, impersonal, the workhorse tier. (Public if yours is published; most aren''t.)"},{"id":"t2","text":"This week''s interview notes on four named candidates","key":"t3pid","reasoning":"The canonical Tier 3 case: enters fresh, minimized by step zero, leaves with the run."},{"id":"t3","text":"An engagement survey theme table: counts by office, no quotes, smallest group is 47","key":"t2int","reasoning":"Aggregation above any reasonable floor, no quotes. This is what good step-zero output looks like — Tier 3 in, Tier 2 artifact out."},{"id":"t4","text":"A comment from that survey: \"as the only nurse on the night shift, I feel unheard\"","key":"t3pid","reasoning":"No name, full identification. Small-n and distinctive detail in one sentence — the calibration prompt''s trap in the wild."},{"id":"t5","text":"The comp philosophy one-pager","key":"t2int","reasoning":"Principles, not people. One person''s salary is Tier 3; the philosophy never is."},{"id":"t6","text":"A spreadsheet of salaries by employee ID (names removed)","key":"t3pid","reasoning":"IDs resolve to people by design; ''names removed'' is the label, not the fact. With small teams, even bucketed versions need the small-n floor."},{"id":"t7","text":"An email thread about an employee''s accommodation request","key":"t4prot","reasoning":"Health-adjacent by nature. Doesn''t go in — including ''just to summarize it.'' If accommodation workflows need support, that''s a sanctioned-system conversation with legal in the room, not a pipeline decision."},{"id":"t8","text":"Your published careers page","key":"t1pub","reasoning":"Published is published."},{"id":"t9","text":"Exit interview notes: \"a senior engineer, here 11 years, leaving over the reorg\"","key":"t3pid","reasoning":"Distinctive-detail trap: tenure plus seniority plus context resolves fast in most orgs. Step zero coarsens it to what the exit-themes analysis needs."},{"id":"t10","text":"The plain-language benefits FAQ your workflow produced last week","key":"t2int","reasoning":"Outputs have tiers too. This one''s clean by construction if the pipeline was — which is why M4 sampling includes a boundary glance, and why artifacts persist minimized."}],"pattern":"Tier by what a reader could learn, not by what a label says. Names removed isn''t identity removed; aggregated isn''t always anonymous; and health, investigations, and accommodations are Tier 4 wherever they appear.","postscript":"If you tiered the night-shift comment, the ID spreadsheet, or the exit note at Tier 2, you''ve found your pattern: tiering by label (name present or absent) rather than by what a reader could learn. That''s the module''s central correction — fixable by running the person-test twice more this week."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m6-rubric', 'ai201-m6', 'rubric', '{"promptVersion":"ai201-m6-capstone-v1","moduleId":"ai201-m6","minChars":600,"submitLabel":"Your capstone-stage submission","intro":"Submit the artifacts this stage asks for, as text. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 201, The Practitioner). Capstone stage 6: the boundary sheet — a tiered input census, mitigations matched to tier, the four agreement answers with sources (provisional status marked if unknowns remain), the escalation card, and the extended sign-off line. Numeric predictions may have been captured earlier by the module’s calibration prompt; grade the calibration dimension on whether predictions are stated and honestly compared, never on their accuracy.","calibration":[{"key":"elementsActual","label":"Census — elements the boundary sheet actually found","placeholder":"e.g. 19","min":0,"max":500,"actualFor":"elements"},{"key":"identifyingActual","label":"Census — how many actually identify a person","hint":"After the person-test, not before.","placeholder":"e.g. 7","min":0,"max":500,"actualFor":"identifying"}],"dimensions":[{"name":"Tier honesty","criteria":"The census is complete and the tricky calls — descriptions, small-n, convergence — are caught and reasoned, not waved through."},{"name":"Mitigation matches tier","criteria":"Step-zero designs are real pipeline steps with checkpoints; Tier 4 handling is removal or named clearance, never \"carefully.\""},{"name":"The agreement layer is factual","criteria":"Four questions answered from sources, not assumptions; unknowns owned honestly with a pursuit plan."},{"name":"Calibration","criteria":"Both counts predicted first, scored against the census, direction of error named. Honesty and specificity graded; accuracy never."}],"opening":[{"key":"elements","label":"Predicted — distinct data elements per run","hint":"A document is one. A pasted table is one. Names inside count separately.","placeholder":"e.g. 12","min":0,"max":500},{"key":"identifying","label":"Predicted — how many identify a person","hint":"By name, or by description a colleague could resolve.","placeholder":"e.g. 2","min":0,"max":500}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m6-knowledge_check', 'ai201-m6', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the boundary sheet is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"Why does a workflow change the \"what can I paste?\" question from 101?","options":["Workflows process larger volumes of data","The question now gets asked every run, forever — eventually by an agent — so the answer must live in design, not per-moment judgment","Workflows are subject to different regulations than conversations","It doesn''t — the question is identical"],"correctIndex":1,"explanation":"One conversation gets your full judgment; a scheduled pipeline gets whatever the design encoded. That''s the entire case for tiers, step zero, and the boundary sheet."},{"id":"q2","prompt":"\"The only woman on the Denver sales team said…\" is Tier 3 because:","options":["Survey comments are always person-identifying","Identification doesn''t require a name — a description a colleague could resolve to one person identifies them","Denver is a small office","It isn''t — no name appears, so it''s Tier 2"],"correctIndex":1,"explanation":"The tier turns on what a reader could learn, not on whether a name-shaped string is present. Small-n and distinctive detail are how \"anonymous\" material stays identifying."},{"id":"q3","prompt":"The person-test runs on the whole run rather than each artifact because:","options":["Testing artifacts individually takes too long","Individually clean artifacts can converge — assembled, they point at one person","Only final outputs matter for privacy","The test requires seeing the original inputs"],"correctIndex":1,"explanation":"The convergence trap: theme table + quote + narrative, each fine alone, jointly identifying. Run-level review is the only place that failure is visible."},{"id":"q4","prompt":"Minimization beats redaction as the primary move because:","options":["Redaction tools are unreliable","Material you never carry can''t leak, converge, or be re-identified — the transformation should receive only what it needs","Minimized documents use fewer tokens","Redaction is only required for Tier 4"],"correctIndex":1,"explanation":"Masking what remains is the second line; not carrying it is the first. It''s the M1 what-does-this-need question, pointed at data instead of capability."},{"id":"q5","prompt":"Your workflow turns out to routinely need investigation files to function. The module''s conclusion:","options":["Get a standing legal clearance for the workflow","Add a stronger redaction step","This shouldn''t be a workflow — routine Tier 4 need is M1''s should-this-exist finding, reached from the data side","Run it only in the enterprise deployment"],"correctIndex":2,"explanation":"Tier 4''s default is \"doesn''t go in,\" and a *routine* need isn''t a mitigation problem. A and B engineer around a finding; the finding is about the workflow''s existence."},{"id":"q6","prompt":"The four agreement-layer questions establish: **[V]**","options":["Whether AI use is permitted at your organization at all","Which tools are sanctioned, whether data trains models, what retention applies, and who owns the contract","The price tier of your organization''s deployment","Which model versions are approved"],"correctIndex":1,"explanation":"Those four answers, sourced and dated, are what \"sanctioned deployment\" concretely means — and question four''s name is the escalation path''s third step."},{"id":"q7","prompt":"The strongest reason the escalation path must be blame-safe:","options":["Blame slows down incident response","Hidden incidents are the only truly unmanageable kind — shame produces hiding","Most incidents turn out to be harmless","Legal requires no-fault reporting"],"correctIndex":1,"explanation":"Every other property of the path — speed, facts, the right name — depends on the incident being surfaced at all. A People leader already knows this pattern; this is it, again."},{"id":"q8","prompt":"After a wrong paste, the fourth step — \"fix the system, not just the moment\" — means:","options":["Retrain everyone on data handling","Trace how the material reached the model (missing step zero, raw file, accumulating pack) and change that design","Add an approval gate to every step","Retire the workflow"],"correctIndex":1,"explanation":"M4''s reflex applied to boundaries: the incident is diagnostic data about a specific design gap. A, C, and D are moods — broad, expensive, and unaimed."}]}', '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-calibration-prompt-before-you-start-10', 'ai201-m7', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. Scored at the end of the course — and revisited every time
something breaks.*

Your workflow has parts now: a pack, a runbook, a verification budget, maybe an autonomy
profile, a boundary sheet.

**Which part decays first?** Name the specific element — not "the pack" but "the org brief in
the pack" — and the month you''d expect it to go quietly wrong if nobody looked.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-module-brief-20', 'ai201-m7', 20, 'prose', 'stable', '## Module brief

Here is how workflows actually die. Not dramatically — no incident, no meeting about it. The
source format shifts slightly in October and the extract step starts dropping a column nobody
graphs. The org brief still says the old structure. The weekly sample quietly stops happening
during the November crunch, and by January the sign-off is a reflex. In March someone asks
whether the workflow is still worth it, and nobody has a number — just a feeling that it used
to be better.

Nothing failed. Everything *decayed*. And every piece of that story was predicted by a module
you''ve already taken: M2 told you context rots, M4 told you verification collapses under load
when it''s priced wrong, M5 told you audit trails need reviewing on a cadence. What none of them
gave you is the thing that makes all of it actually happen in a calendar that''s already full:
**a rhythm** — the small, scheduled, boring recurrence that keeps built things alive.

This module is deliberately the least glamorous in the course, and it''s the one that separates
practitioners whose workflows survive the year from people who once built something clever. It
has three parts: where the work sits in your real week, how to measure without theater — and
when to kill a workflow that stopped earning its keep, which is a practitioner skill exactly
equal in seniority to M5''s refusal.

It''s also where a promise comes due. In M1 you predicted what your workflow''s task cost you in
hours per month. You''re about to find out, with numbers, which direction you were wrong in.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-learning-objectives-30', 'ai201-m7', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Fit the maintenance of your workflows into a real week — in minutes, on a calendar, not in
   intentions.
2. Choose three honest numbers per workflow, record a baseline, and know theater metrics on
   sight.
3. Run the review that catches decay while it''s cheap: samples, stamps, approval logs, and the
   one question per pack item.
4. Retire a workflow deliberately — with the criteria written down before sentiment argues.
5. Score a months-old prediction against measured reality, and name your systematic direction.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-lesson-1-the-practitioner-s-week-40', 'ai201-m7', 40, 'prose', 'stable', '## Lesson 1 · The practitioner''s week

The rhythm has to survive your actual calendar — the one with the investigation, the offsite,
and the Thursday that disappears. So it''s built from three slots, sized in minutes, and the
sizing rule comes first:

**The maintenance of a workflow must cost a small fraction of what the workflow saves.** If
your build saves five hours a month, its rhythm gets fifteen to twenty minutes of that back.
The moment maintenance creeps past that fraction, you don''t have an efficiency; you have a
hobby. (Retirement, Lesson 3, is where hobbies go.)

**Per run — seconds, embedded.** The checkpoint glances (M3), the person-test where it applies
(M6), the sign-off''s reading list (M4). These aren''t calendar items; they''re built into the
run''s shape, which is why the modules made them cheap. If a per-run check needs willpower,
it''s priced wrong — that''s M4''s repricing signal, again.

**Weekly — ten minutes, scheduled.** One recurring block: run the M4 sample for the week,
glance at the approval log if you''re on rung 2 (how often did you decline? — that''s ladder
evidence accumulating), and note anything that felt off mid-run. The block is sacred in one
specific way: it may shrink, it may move, it may never silently vanish. A skipped week gets
skipped *out loud*, in the log: "skipped, crunch." Two consecutive skips is information.

**Monthly — twenty minutes, scheduled.** The M2 pack review (each volatile item: still true?),
the metrics check against baseline (Lesson 2), a drift-diff against the gold standard, and one
honest question: is this still earning its keep? Monthly is also when the boundary sheet''s
re-verify dates get glanced at — not re-researched, glanced.

That''s the whole system: seconds per run, ten a week, twenty a month, per workflow. Written
down, it looks almost insultingly small. That''s the design. Rhythms fail by being ambitious;
this one is sized to survive the week you''re firefighting — because the week you''re
firefighting is exactly when the source format shifts.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-try-50', 'ai201-m7', 50, 'try_this', 'stable', '### Try this — 2 minutes
Open your calendar. Create the two recurring blocks — ten weekly, twenty monthly — named
after your workflow, before finishing this module. Not as a commitment ritual: because
Lesson 2 needs the monthly block to exist, and because every module so far has taught the
same lesson about intentions versus structure.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-lesson-2-measurement-without-theater-60', 'ai201-m7', 60, 'prose', 'stable', '## Lesson 2 · Measurement without theater

You need numbers for exactly two reasons: to know whether the workflow is still earning its
keep, and to be believed when you say so. Both die if the numbers are theater.

**Four numbers per workflow. Not seven. Four.**

1. **Time: minutes per run, measured occasionally.** Not self-reported "hours saved weekly" —
   time an actual run once a month, shuttling included (your M5 measurement was the first of
   these). Multiply by run count for the monthly figure. Compare to the baseline you''re about
   to set — the *before* number, which is the M1-audit cost of doing it by hand.
2. **Cost: what the workflow spends to run.** Token or API charges where your deployment
   meters them, the workflow''s share of seat licenses where it doesn''t, plus the rhythm''s
   maintenance minutes priced at a loaded rate. 101 M3 gave you the token economics; this is
   where they get used. A per-run estimate refreshed quarterly is enough precision. Most
   workflow costs turn out to be small — the point of the number is being able to *say* so:
   a CFO who hears "saves six hours a month" asks what it costs within one sentence, and
   "about eleven dollars and forty minutes of maintenance" is the answer that ends the
   conversation. A savings claim without a cost line doesn''t survive its first finance review.
3. **Quality: the M4 sample''s error rate.** You''re already producing this number; the rhythm
   just graphs it. Direction matters more than level: a stable 4% is normal variation; a
   drift from 2% to 6% over three months is decay announcing itself politely.
4. **Use: did the output actually get used?** The debrief opened by the hiring manager, the
   FAQ linked in the channel, the narrative that survived into the exec deck. Roughest of the
   four, gathered lazily ("did anyone use this?" once a month is fine) — and the most honest,
   because a workflow whose outputs nobody uses has an error rate of irrelevant.

**Before/after or it didn''t happen.** The baseline is recorded once, in the capstone, from
your M1 audit and first timed runs. Every future "this saves us six hours a month, at a cost
of eleven dollars" traces to it. This is what makes your numbers different from every
AI-enthusiasm anecdote your exec team has heard this year — and when a budget conversation
eventually asks what the team''s AI practice is worth, you will be the only person in the room
with a before, an after, and the after''s price.

**Theater, so you can spot it** — including in your own reporting: metrics that measure
activity instead of outcome (runs completed, prompts written, "AI touches"), metrics that
can''t go down (cumulative anything), self-reported satisfaction with no denominator, and any
number gathered more expensively than the decision it informs. The test for every candidate
metric: *what would I do differently if this number moved?* No answer, no metric.
', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-exercise', 'ai201-m7', 65, 'exercise', 'stable', '{"type": "sorting", "title": "Exercise — Signal or theater?", "intro": "Three minutes. A practitioner proposes seven metrics for their debrief workflow. Keep four.\n\nOne of the seven is defensible in either pile — the reasoning is the point."}', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-lesson-3-retirement-and-the-review-that--70', 'ai201-m7', 70, 'prose', 'stable', '## Lesson 3 · Retirement — and the review that earns it

**The review, first.** The monthly twenty minutes has a script: walk the volatile pack items
(one question each: *still true?*), read the month''s sample tallies for direction, diff one
output against the gold standard, check the four numbers against baseline. Fifteen minutes of
looking, five of acting — a stamp updated, a step prompt tightened, a sample size nudged. Small
corrections, cheap because they''re early. The review''s job isn''t celebration; it''s catching
the October column-drop in November instead of March.

**Then, the skill nobody practices: killing your own workflow.** Retirement criteria get
written *now*, while you''re fond of the thing, because the person who''ll evaluate them in a
year owns sunk costs and a sunk identity — you built this. Three triggers, any one sufficient
to force the question:

- **The economics inverted:** maintenance plus verification now costs a meaningful fraction of
  what the workflow saves, and the trend is wrong.
- **The use number went quiet:** outputs ship and nothing downstream moves. It has an audience
  of one, and the one is you.
- **The world moved:** the source system changed, the task changed shape, or — the good
  ending — the org tooled the problem away properly and your workflow is now a workaround
  with a rhythm.

Retirement is cheap where the course put you: the spec, pack, and runbook archive to a
folder; the calendar blocks delete; a one-line note says what it was, what it saved (you have
the numbers), and why it ended. That note is practitioner history — the M8 portfolio''s
quietest, most credible page. What retirement is *not* is failure: a workflow that saved five
hours a month for fourteen months and then stopped being needed is a complete success story
with an ending. The failure mode is the other thing — the zombie workflow, maintained out of
identity, consuming its rhythm slots while its use number sits at zero.

**And close the loop the course opened.** The M1 prediction — hours per month this task cost
you — now has a measured answer. So does M2''s pack-size guess, M3''s lossiest-step call, M4''s
error-rate estimate, M5''s shuttling split, M6''s census counts. You''ve been predicting and
scoring for seven modules. The capstone asks the direction question one level up, because
*that* — not any single estimate — is what calibration training is for: when you''re wrong
about your own work, which way are you wrong?', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-key-takeaways-80', 'ai201-m7', 80, 'takeaways', 'stable', '## Key takeaways

- **Workflows die of decay, not drama** — and every decay mode was already predicted by an
  earlier module. The rhythm is what makes those modules'' answers actually recur.
- **Seconds per run, ten a week, twenty a month.** Maintenance sized to a fraction of savings;
  oversize the rhythm and it stops surviving bad weeks.
- **Four numbers: time against a baseline, cost to run, the sample''s error direction, and real
  downstream use.** Before/after or it didn''t happen — and the after carries its price.
- **Every metric must answer "what would I do differently if this moved?"** No answer, no
  metric — that one test deletes most theater on contact.
- **Write retirement criteria while you''re still fond of the thing.** A retired workflow with
  measured savings is a success story with an ending; a zombie workflow is the actual failure.
- **The reckoning is the point:** seven predictions in, you know which way you miss on your
  own work. The next build starts from that knowledge.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-sources-and-attribution-100', 'ai201-m7', 100, 'prose', 'stable', '## Sources and attribution

Builds on 201 M1 (the cost prediction now scored), M2 (rot and review cadence), M4 (sampling,
the decay curve, repricing), M5 (approval-log evidence), M6 (re-verify dates), and 101 M3
(the token economics the cost number spends). The four-number rule and the maintenance
fraction are this course''s packaging; the measurement-design warnings have a real literature,
and the theater section in particular is standing on it:

*To be verified against editions and current URLs before publication.*

1. **Goodhart''s law, via Strathern, M. — "''Improving Ratings'': Audit in the British University
   System," *European Review* 5(3) (1997).** "When a measure becomes a target, it ceases to be
   a good measure" — the one-line ancestry of the entire theater section.
2. **Choi, J., Hecht, G. & Tayler, W. — "Lost in Translation: The Effects of Incentive
   Compensation on Strategy Surrogation," *The Accounting Review* (2012).** Surrogation:
   managing the metric instead of the thing it stands for — the failure the
   would-do-differently test is built to catch.
3. **Forsgren, N., Humble, J. & Kim, G. — *Accelerate* (2018).** The best-known modern case
   for outcome-over-activity metrics and small honest metric sets; the nearest published
   relative of the four-number rule.
4. **Muller, J. Z. — *The Tyranny of Metrics* (2018).** The costs of measurement theater,
   surveyed across fields — useful ammunition when someone asks for the fifth, sixth, and
   seventh number.
5. **Tetlock, P. & Gardner, D. — *Superforecasting* (2015); Lichtenstein, S., Fischhoff, B. &
   Phillips, L. — "Calibration of Probabilities" in *Judgment Under Uncertainty* (1982).** The
   scored-prediction thread that runs through both courses: calibration improves with rapid,
   repeatedly scored feedback — which is what the module-by-module predictions and this
   module''s reckoning are for.

Stable layer throughout.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-activity-capstone-stage-7-baseline-rhythm-and-the-10', 'ai201-m7-activity', 10, 'prose', 'stable', '## Capstone stage 7 · Baseline, rhythm, and the reckoning

**Submit:**

1. **The four numbers, chosen and baselined.** Your workflow''s time, cost, quality, and use
   metrics: current values, the by-hand *before* from your M1 audit, and one sentence per
   metric answering "what would I do differently if this moved?" The cost line may be a
   per-run estimate — lazy is fine, absent is not.
2. **The rhythm, installed.** The per-run checks (named, embedded where), and screenshots or
   equivalents of the weekly and monthly blocks on your actual calendar — with their scripts,
   in your words, short enough to run tired.
3. **The retirement clause.** Your workflow''s three triggers, quantified where possible
   ("maintenance exceeds 20% of measured savings for two consecutive months"), written to be
   evaluated by a future you with sunk costs.
4. **The reckoning.** Score the M1 prediction: predicted hours/month vs. measured. Then the
   direction paragraph: across all seven predictions so far, which way do you systematically
   miss on your own work — and what will you *do* with that? ("I under-estimate costs and
   over-estimate my own verification appetite, so my next build gets a smaller budget and a
   boring-er first workflow" is the shape. Yours will be yours.)
5. **This module''s prediction,** logged: the element you named as first-to-decay, and the
   month. The monthly review will score it — the rhythm grading its own forecast.

### Rubric — 20 points

| Dimension | 5 points |
|---|---|
| **Honest numbers** | Four metrics, each with a baseline and a would-do-differently answer. No theater; the cost line is present; the use metric is genuinely about downstream use. |
| **A rhythm that survives** | Blocks exist on a real calendar, sized to the maintenance fraction, with scripts runnable in a bad week. Skips are logged, not hidden. |
| **The retirement clause has teeth** | Triggers are specific enough that a reluctant future owner couldn''t argue past them, and retirement is framed as an outcome, not a failure. |
| **Calibration** | The M1 reckoning is done with real numbers; the direction paragraph names a systematic bias and a concrete consequence for the next build. |', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-micro-core', 'ai201-m7-micro', 10, 'prose', 'stable', '## Module 7 in two minutes

**Workflows die of decay, not drama.** The source format shifts, the sample quietly stops during a crunch, and months later nobody has a number — just a feeling it used to be better. The counter is a rhythm sized to survive bad weeks: seconds per run (embedded checks), ten minutes weekly (the sample, the approval log), twenty monthly (pack review, metrics against baseline). Maintenance must cost a small fraction of what the workflow saves.

**Four numbers per workflow:** time against a measured baseline, cost to run (tokens, seat share, maintenance minutes), the sample''s error direction, and real downstream use. Every metric must answer *what would I do differently if this moved?* — no answer, no metric. Before/after or it didn''t happen, and the after carries its price.

**Write retirement criteria while you''re still fond of the thing.** Inverted economics, a quiet use number, or a world that moved — any one forces the question. A retired workflow with measured savings is a success story with an ending; the zombie workflow is the actual failure.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-micro-rule', 'ai201-m7-micro', 20, 'callout', 'stable', '### The reckoning

Module 1''s cost prediction gets scored here against measured reality. The point was never the estimate — it''s learning which direction you systematically miss on your own work, and pricing the next build against it.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m7-micro-close', 'ai201-m7-micro', 30, 'prose', 'stable', '**The full module adds** the signal-or-theater exercise, the measurement-design literature behind the four numbers, and capstone stage 7: baselines, an installed rhythm, and the retirement clause.', NULL, '2026-08-07', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m7-sorting', 'ai201-m7', 'sorting', '{"reviewedAt":"2026-08-07","buckets":[{"id":"keep","label":"Keep — it''s a signal","hint":"Answers \"what would I do differently if this moved?\"","rank":0,"pct":50},{"id":"cut","label":"Cut — it''s theater","hint":"Measures activity, can''t go down, or informs no decision","rank":0,"pct":50}],"tasks":[{"id":"t1","text":"Cumulative debriefs generated since launch","key":"cut","reasoning":"Cumulative counts can''t go down — they measure elapsed time, nothing else."},{"id":"t2","text":"Minutes per debrief, timed monthly, vs. the by-hand baseline","key":"keep","reasoning":"The time number, done right: an actual run timed occasionally against a recorded baseline, not self-reported hours saved."},{"id":"t3","text":"\"Time saved feels significant\" — team survey, quarterly","key":"cut","also":["keep"],"reasoning":"The arguable one. Sentiment isn''t worthless — a team that hates a workflow is information — but as proposed it fails the test twice: no denominator, no would-do-differently answer. The defensible keep is a repurposed version: one question at the monthly review, treated as a smoke detector for the use metric — not a KPI."},{"id":"t4","text":"Errors per weekly five-debrief sample, classified","key":"keep","reasoning":"The quality number — the M4 sample already produces it; the rhythm just graphs it. Direction matters more than level."},{"id":"t5","text":"Number of prompts in the prompt library","key":"cut","reasoning":"Library size measures accumulation, not value; by M2''s own hygiene rules a shrinking library is often the healthier sign."},{"id":"t6","text":"Share of debriefs opened by the hiring manager within 48 hours","key":"keep","reasoning":"The best of the board: it measures the hiring manager''s behavior, not yours — real downstream use."},{"id":"t7","text":"Monthly run cost — token or seat share plus maintenance minutes, estimated quarterly","key":"keep","reasoning":"Estimated lazily, but present — a value claim without a cost line doesn''t survive its first CFO."}],"pattern":"Every metric must answer: what would I do differently if this number moved? No answer, no metric.","postscript":"The sentiment survey scores either way — the reasoning is the point. If you kept it as a KPI rather than repurposing it as a smoke detector, that''s the theater reflex the lesson is after."}', '2026-08-07');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m7-rubric', 'ai201-m7', 'rubric', '{"promptVersion":"ai201-m7-capstone-v1","moduleId":"ai201-m7","minChars":600,"submitLabel":"Your capstone-stage submission","intro":"Submit the artifacts this stage asks for, as text. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 201, The Practitioner). Capstone stage 7: the four numbers baselined with would-do-differently answers, the rhythm installed on a real calendar, the retirement clause with quantified triggers, and the reckoning against the Module 1 prediction. Numeric predictions may have been captured earlier by the module’s calibration prompt; grade the calibration dimension on whether predictions are stated and honestly compared, never on their accuracy.","calibration":[{"key":"savingsActual","label":"Measured — % of the by-hand baseline the workflow actually saves","hint":"From your timed runs against the baseline. Closes the prediction you made in Module 1.","placeholder":"e.g. 40","min":0,"max":100,"actualFor":"ai201-m1:savings"}],"dimensions":[{"name":"Honest numbers","criteria":"Four metrics, each with a baseline and a would-do-differently answer. No theater; the cost line is present; the use metric is genuinely about downstream use."},{"name":"A rhythm that survives","criteria":"Blocks exist on a real calendar, sized to the maintenance fraction, with scripts runnable in a bad week. Skips are logged, not hidden."},{"name":"The retirement clause has teeth","criteria":"Triggers are specific enough that a reluctant future owner couldn''t argue past them, and retirement is framed as an outcome, not a failure."},{"name":"Calibration","criteria":"The M1 reckoning is done with real numbers; the direction paragraph names a systematic bias and a concrete consequence for the next build."}],"includeTrail":true}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m7-knowledge_check', 'ai201-m7', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the capstone is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"How do workflows usually die?","options":["A visible incident forces a shutdown","Quiet decay: sources shift, samples stop, and months later nobody has a number — just a feeling it used to be better","The model provider deprecates a feature","They rarely die; maintained workflows are stable"],"correctIndex":1,"explanation":"No single failure, just unattended drift — every mode of which an earlier module predicted. The rhythm exists because decay is the default, not the exception."},{"id":"q2","prompt":"The sizing rule for a workflow''s maintenance rhythm:","options":["As thorough as the workflow is important","A small fraction of what the workflow saves — past that, it''s a hobby","One hour per week, standardized across workflows","Whatever the owner can sustain"],"correctIndex":1,"explanation":"The fraction test keeps the rhythm honest in both directions: enough to catch decay, never enough to consume the savings it protects. It''s also a retirement trigger when it inverts."},{"id":"q3","prompt":"A skipped weekly review should be:","options":["Made up with a double review next week","Logged out loud — \"skipped, crunch\" — because two consecutive skips is information","Avoided by automating the review","Ignored; the monthly review covers it"],"correctIndex":1,"explanation":"The skip isn''t the sin; the silent skip is. A visible skip pattern is exactly the M4-style decay signal the rhythm exists to surface — about itself."},{"id":"q4","prompt":"Why is \"share of debriefs opened by the hiring manager\" the strongest of the kept metrics?","options":["It''s the easiest to collect","It measures downstream behavior — whether the work product actually matters to its audience","It can be tracked automatically","It correlates with time saved"],"correctIndex":1,"explanation":"Time, cost, and quality can all look excellent on a workflow nobody uses. The use metric is the one that catches the workflow whose quality no longer matters to anyone."},{"id":"q5","prompt":"The test that deletes theater metrics on contact:","options":["Can this number be gathered automatically?","What would I do differently if this number moved?","Does this number always increase?","Would an executive find this number impressive?"],"correctIndex":1,"explanation":"No decision downstream, no metric. (C is a good tell — always-up numbers restate elapsed time — but B is the test that also catches subtle theater.)"},{"id":"q6","prompt":"Retirement criteria are written at baseline time because:","options":["Baselines are required for retirement calculations","The future evaluator owns sunk costs and a builder''s identity — the criteria must predate the fondness that will argue with them","Criteria written later would be less accurate","The rhythm has no other place to put them"],"correctIndex":1,"explanation":"It''s a pre-commitment against a bias you can name today and will feel next year. Same reasoning as M5''s refusal: write the judgment down before the pressure arrives."},{"id":"q7","prompt":"A workflow saved five hours a month for a year; then the org''s new HRIS made it unnecessary, and it was archived with its numbers. This is:","options":["A failure to future-proof the design","A complete success story with an ending — the failure mode is the zombie, not the retirement","Evidence the workflow was never necessary","A reason to rebuild it against the new system"],"correctIndex":1,"explanation":"Fourteen months of measured savings is the win; the world moving is trigger three working as designed. (D might *also* be true — but that''s a new M1 audit, not a reflex.)"},{"id":"q8","prompt":"The point of scoring the M1 prediction against measured reality is:","options":["Grading the accuracy of the original estimate","Surfacing your systematic direction of error about your own work, and feeding it into the next build","Producing a success number for the M8 portfolio","Proving the workflow was worth building"],"correctIndex":1,"explanation":"As everywhere in both courses: accuracy isn''t the graded thing — direction is. Seven predictions produce a pattern; the practitioner''s edge is knowing their own lean and pricing the next build against it."}]}', '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-calibration-prompt-before-you-start-10', 'ai201-m8', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. The peer exchange scores it — and it''s the course''s last.*

A peer you''ve never worked with is about to run your workflow''s first step from your
documentation alone.

**Where do they stall?** Name the specific spot — the undefined term, the step that assumes a
file location only you know, the instruction that quietly requires your judgment. And predict:
do they get a usable artifact out of step one, yes or no?

Seven modules of predictions have taught you your lean. This one you should be getting right —
which is exactly why it''s worth checking.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-module-brief-20', 'ai201-m8', 20, 'prose', 'stable', '## Module brief

Everything so far has been building. This module''s verb is different: **ship** — run the thing
for real, on real work, produce the numbers, and package it so that it survives contact with
someone who isn''t you.

That last clause is the module''s actual subject. A workflow that only its builder can run
isn''t a system yet; it''s an artisan with better filing. The proof of the Practitioner level —
the thing that separates L3 from a well-organized L2 — is *transferability*: your judgment,
written down so completely that a reasonable colleague could run the build, read its
boundaries, and trust its guardrails without you in the room. Every module quietly built
toward this. The spec was always a document for a stranger. The runbook was always the
instructions someone else would follow. The refusal and the boundary sheet were always
written for the successor and the security reviewer. M8 just introduces the stranger.

Concretely, three things happen this module. You assemble the **portfolio** — every artifact
from M1 through M7, current and consistent with each other. You run the **handoff test** — a
minimal peer exchange where another practitioner runs your first step cold and tells you,
in a structured way, where your documentation lied to you. And you run the workflow **for
real, twice**, producing the before/after numbers that make your work the only
evidence-backed AI story in most rooms you''ll sit in this year.

Then the course tells you what it''s been doing behind your back for eight modules — because
the skills this build taught you have a name, and it''s the next level.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-learning-objectives-30', 'ai201-m8', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Assemble a shipping portfolio where every artifact is current and none contradict each other.
2. Survive the handoff test — and treat every stall your peer hits as documentation debt, not
   reader error.
3. Give a structured, useful review of someone else''s workflow as its cold-start reader.
4. State your build''s measured result in one sentence a skeptical executive would accept.
5. Name what the build seeded beyond this course''s own rung — the role depth 301 goes
   after, and the credibility 401''s Translator work is built on.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-lesson-1-the-shipping-checklist-40', 'ai201-m8', 40, 'prose', 'stable', '## Lesson 1 · The shipping checklist

Shipping is an assembly problem: seven modules produced artifacts at different times, and the
workflow evolved while you built it. The checklist''s job is coherence — one binder (in
practice: your project''s knowledge, plus one index document) where everything is *current* and
*consistent*:

- **The spec** (M1) — five parts, as the workflow actually runs today, not as first specced.
  If the pipeline changed in M3, the spec caught up. Owner line filled (M4).
- **The pack inventory** (M2) — instructions verbatim, knowledge list with review dates. No
  Tier 3 anywhere in it (M6 audits M2''s promise).
- **The runbook** (M3) — step prompts as actually used, checkpoints with their
  what-would-wrong-look-like lines.
- **The verification plan** (M4) — budget, technique map, sign-off reading list, latest sample
  tally, escalation line.
- **The autonomy profile** (M5) — rungs per step, guardrail spec or the refusal, as decided.
- **The boundary sheet** (M6) — census, mitigations, agreement answers with dates, escalation
  card.
- **The rhythm and numbers** (M7) — three metrics with baseline, calendar blocks, retirement
  clause.
- **The index** — one page, new in this module: what this workflow is, what it saves, where
  everything above lives, and who owns it. The page a successor reads first, and the page an
  exec reads *only*.

The consistency pass matters more than any single artifact: the spec that says "weekly" while
the rhythm says "monthly," the runbook step the verification plan doesn''t cover, the pack item
the boundary census never tiered. Contradictions are where a cold reader stalls and where a
reviewer stops trusting. Read the binder once, end to end, as the stranger — then let the
actual stranger in.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-lesson-2-the-handoff-test-50', 'ai201-m8', 50, 'prose', 'stable', '## Lesson 2 · The handoff test

The peer exchange is minimal by design — one pairing, one step, three questions — because its
job isn''t collaboration; it''s *calibration of your documentation against reality*, and one
cold read produces most of that signal.

**The mechanics.** You''re paired with one other practitioner. Each of you, separately: read
your peer''s index and runbook, then run **step one only** of their workflow — their step
prompt, their pack, sample material they''ve provided (M6-clean; providing safe sample material
is part of *their* shipping). No questions allowed during the run — the documentation answers
or it doesn''t. Then each returns the structured review, three questions, one paragraph each:

1. **Could I start?** From the binder alone: did I know what to open, what to paste, what
   good output looks like?
2. **Where did I stall?** The specific sentence, gap, or assumption — not "it was unclear,"
   but *where*.
3. **What did the doc assume I knew?** The tacit knowledge tax: terms, locations, judgment
   calls the builder no longer notices they''re making.

**When there is no peer.** Cohorts don''t always pair cleanly, and paired peers don''t always
deliver. Neither stalls your shipping. If you''re running solo, your binder and sample material
go to the course''s **review queue**, where an experienced reviewer runs the same cold read and
returns the same three questions — the reviewer having seen many binders is a feature, not a
compromise; their stalls are better-aimed than a peer''s. And if your paired peer''s review
hasn''t arrived within a week, your submission moves to the queue automatically: their stall is
not your debt, and the module completes on your timeline either way. The giving side survives
too — solo learners give their structured review to a queued submission from the course
library, which is the same skill against a build you''ve never seen. In every variant, the
mechanics above hold: cold read, no questions during the run, three structured paragraphs back.

**Receiving the review is the skill being graded.** Every stall is documentation debt —
information about the binder, never about the reader. The reflex you''ve trained all course
applies one last time: fix the pack, not the output; fix the doc, not the reader. You''ll fix
the top stalls, and you''ll also score your calibration prompt: did they stall where you
predicted? Builders are routinely wrong about this in a specific direction — they predict
stalls at the *complex* parts and get stalled at the *obvious* ones, because obviousness is
precisely what expertise can no longer see. That miss, more than any fix, is the lesson.

**Giving the review is a preview.** Reading someone else''s build cold — seeing exactly where
their expertise went invisible to them — is the core diagnostic skill of coaching adoption.
You''re already working above this course''s rung; Lesson 3 says so out loud.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-lesson-3-what-this-course-actually-taugh-60', 'ai201-m8', 60, 'prose', 'stable', '## Lesson 3 · What this course actually taught you

Close the loop, then open the next one.

**The result, stated plainly.** You now own a production workflow with a measured before and
after, a verification layer with real sample data, a defensible boundary, an autonomy
decision made on evidence, and documentation a stranger has actually run. When someone in
your organization asks what AI is worth — and someone will, with a budget line attached —
you are the person in the room with a baseline. One sentence, from your M7 numbers: *"This
workflow saves N hours a month against a measured baseline, at a running cost of $X and a
Y% sampled error rate, with a boundary sheet security has seen."* Practice saying it. The
cost clause matters as much as the savings clause: it''s the difference between a pitch and
an accounting, and a CFO hears the difference immediately.

**The skills that came along quietly.** Look at what shipping required, and notice none of
it was prompting: you priced trust in evidence (M4→M5), wrote boundaries a reviewer could
audit (M6), measured your own judgment''s lean and corrected for it (every module), read a
colleague''s build and diagnosed where their expertise went invisible (M2 of this module),
and produced the org''s first honest before/after. Those are the raw materials of both rungs
above this one. **AI 301 · The Specialist** drives the practice you just built into the
specifics of your actual role — where generic advice runs out and the real applications
start, and where a shipped workflow beats a blank page as a starting point. Further up,
**AI 401 · The Translator** is the multiplayer game: helping other functions adopt AI with
judgment, evaluating vendors without being sold to, running pilots that produce evidence
instead of anecdotes, and owning the policy for what AI may touch. Translators are made
credible by exactly one thing — a build of their own they can point at — and you have one.

**And the course keeps one promise on its way out.** 101 M1 said your two roles — using AI
well, and leading others to — were different jobs needing different preparation, and that
you couldn''t credibly lead a change you can''t perform. That debt is now paid. You can
perform it — and every rung above this one, from your role in depth to the leading itself,
is built on exactly that.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-key-takeaways-70', 'ai201-m8', 70, 'takeaways', 'stable', '## Key takeaways

- **Shipping is transferability.** A workflow only its builder can run isn''t a system yet.
  The stranger is the test.
- **The consistency pass beats any single artifact.** Contradictions between binder documents
  are where cold readers stall and reviewers stop trusting.
- **Every stall is documentation debt.** Fix the doc, not the reader — and expect the stalls
  at the obvious parts, where your expertise went invisible.
- **Before/after or it didn''t happen, final form:** one sentence with a baseline, an error
  rate, and a boundary a reviewer has seen. The only AI story in the room with evidence.
- **Retiring the artisan was the point.** The judgment stays yours; the system now carries
  it — which is what frees you for the next level''s work.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-sources-and-attribution-80', 'ai201-m8', 80, 'prose', 'stable', '## Sources and attribution

Builds on the entire course; the module is deliberately an integration with one new mechanic
(the peer exchange) and one new artifact (the index). The tacit-knowledge-tax framing of
handoff stalls, the consistency pass, and the trustworthy-not-impressive rubric dimension are
original to this course. Stable layer throughout. The ladder framing — 301''s role depth,
401''s Translator work — continues from here.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-activity-capstone-the-portfolio-10', 'ai201-m8-activity', 10, 'prose', 'stable', '## Capstone · The portfolio

The course grade. Two real runs, the exchange, and the binder — assembled, consistent,
shipped.

**Submit:**

1. **The index page** and the full binder (or its live location), post-consistency-pass.
2. **Two real runs**, complete with intermediates: one from before your peer''s review, one
   after your fixes. The delta between them is documentation debt, repaid and visible.
3. **The numbers**: the M7 four, with baseline, stated in the one-sentence-for-an-executive
   form — savings and cost both.
4. **The exchange, both directions**: the review you received — from your peer or from the
   review queue — verbatim, with your fixes listed; the review you gave, to your peer or to a
   queued submission; and your calibration score — predicted stall vs. actual stall, direction
   of miss named.
5. **The closing reflection** (300–400 words): what shipped, what it measures, your
   systematic direction across the course''s predictions (from M7''s reckoning, now with the
   handoff miss added) — and the one thing you''ll build next, with the rung and budget
   you''ll start it at *because* of what your lean turned out to be.

### Rubric — 25 points

The course''s four inherited dimensions, plus one that belongs to this module alone:

| Dimension | 5 points |
|---|---|
| **Engagement with real work** | The runs are real, the material is real, the fixes were actually made. A portfolio assembled for the grade reads exactly like one — and scores like one. |
| **Observation of mechanics** | The reflection connects what happened — the stalls, the deltas, the numbers — to how the systems work: context, verification, decay, transfer. |
| **Calibration** | The handoff prediction was made, scored, and folded into the course-long direction honestly. Accuracy isn''t graded; the named lean and its consequence are. |
| **Practical insight** | The next build is specific: named workflow, starting rung, budget size — each traceable to something this course measured about *you*. |
| **Would a colleague trust it?** | The test of the whole course: guardrails a reasonable peer would rely on — verification real, boundary defensible, autonomy evidenced, documentation a stranger has run. Not "is it impressive." Is it *trustworthy*. |', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-micro-core', 'ai201-m8-micro', 10, 'prose', 'stable', '## Module 8 in two minutes

**Shipping is transferability.** A workflow only its builder can run isn''t a system yet — the proof of the Practitioner level is that a stranger can run the build, read its boundaries, and trust its guardrails from the documentation alone. The binder gets a consistency pass first: contradictions between the spec, runbook, and rhythm are where cold readers stall and reviewers stop trusting.

**The handoff test makes the stranger real:** a peer (or the course''s review queue) runs your first step cold and answers three questions — Could I start? Where did I stall? What did the doc assume I knew? Every stall is documentation debt, and builders miss in a known direction: they predict stalls at the complex parts and get stalled at the obvious ones, where their expertise went invisible.

**Then say it in one sentence with receipts:** saves N hours a month against a measured baseline, at a running cost of $X and a Y% sampled error rate, with a boundary sheet security has seen. Every clause is backed by an artifact that exists. That''s a different kind of sentence than this conversation usually gets.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-micro-rule', 'ai201-m8-micro', 20, 'callout', 'stable', '### The course''s test

Would a reasonable colleague trust it? Not "is it impressive" — verification real, boundary defensible, autonomy evidenced, documentation a stranger has run. Trust is what the whole system either earns or doesn''t.', NULL, '2026-08-07', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai201-m8-micro-close', 'ai201-m8-micro', 30, 'prose', 'stable', '**The full module adds** the shipping checklist, the peer-exchange mechanics, the manager one-pager — and the quiet news that the build reached past its own rung — into the role depth 301 goes after, and the credibility 401''s Translator work runs on.', NULL, '2026-08-07', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m8-rubric', 'ai201-m8', 'rubric', '{"promptVersion":"ai201-m8-capstone-v1","moduleId":"ai201-m8","minChars":600,"submitLabel":"Your capstone-stage submission","intro":"Submit the artifacts this stage asks for, as text. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for an AI fluency course for People leaders (AI 201, The Practitioner). The AI 201 capstone portfolio: the index page and consistent binder, two real runs with intermediates, the four numbers in executive-sentence form, both directions of the peer exchange with the calibration score, and the closing reflection. Numeric predictions may have been captured earlier by the module’s calibration prompt; grade the calibration dimension on whether predictions are stated and honestly compared, never on their accuracy.","calibration":[],"dimensions":[{"name":"Engagement with real work","criteria":"The runs are real, the material is real, the fixes were actually made. A portfolio assembled for the grade reads exactly like one — and scores like one."},{"name":"Observation of mechanics","criteria":"The reflection connects what happened — the stalls, the deltas, the numbers — to how the systems work: context, verification, decay, transfer."},{"name":"Calibration","criteria":"The handoff prediction was made, scored, and folded into the course-long direction honestly. Accuracy isn''t graded; the named lean and its consequence are."},{"name":"Practical insight","criteria":"The next build is specific: named workflow, starting rung, budget size — each traceable to something this course measured about *you*."},{"name":"Would a colleague trust it?","criteria":"The test of the whole course: guardrails a reasonable peer would rely on — verification real, boundary defensible, autonomy evidenced, documentation a stranger has run. Not \"is it impressive.\" Is it *trustworthy*."}],"includeTrail":true}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai201-m8-knowledge_check', 'ai201-m8', 'knowledge_check', '{"title":"Knowledge check — 6 questions","note":"Unlocks after the portfolio is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-07","questions":[{"id":"q1","prompt":"The proof of the Practitioner level is:","options":["A workflow running at rung 3 autonomy","Transferability — a stranger can run the build, read its boundaries, and trust its guardrails from the documentation alone","Measured time savings above five hours a month","Completion of all eight capstone stages"],"correctIndex":1,"explanation":"Rungs, savings, and stages are properties a good build might have. The level is about whether the judgment left the builder''s head and survived in writing."},{"id":"q2","prompt":"The consistency pass exists because:","options":["Reviewers require a single document format","Artifacts written across seven modules drift apart as the workflow evolves — and contradictions are where cold readers stall and trust dies","The portfolio must fit in one file","Each artifact must be re-approved before shipping"],"correctIndex":1,"explanation":"The binder was written longitudinally; the workflow kept moving. The pass reconciles them — spec to rhythm, runbook to budget, pack to census — before the stranger reads."},{"id":"q3","prompt":"During the handoff run, the reader may not ask the builder questions because:","options":["The exchange is graded as a test of the reader","The documentation must answer or fail visibly — a question answered aloud is a gap that ships unfixed","Peers are anonymous in the exchange","Questions would take too long"],"correctIndex":1,"explanation":"The cold read is the instrument. Every question the builder answers in person is a stall the binder no longer gets credit for revealing — and documentation debt that survives to the *next* reader, who won''t have the builder''s number."},{"id":"q4","prompt":"Builders mispredict where readers stall in a specific direction:","options":["They predict stalls at complex parts; readers stall at obvious ones, where the builder''s expertise has gone invisible","They predict too many stalls overall","They predict stalls at the beginning; readers stall at the end","There is no systematic direction"],"correctIndex":0,"explanation":"The tacit-knowledge tax: obviousness is what expertise can no longer see. It''s the course''s last calibration lesson, and the core diagnostic of the coaching work ahead."},{"id":"q5","prompt":"The executive sentence — \"saves N hours a month against a measured baseline, at a running cost of $X and Y% sampled error, with a boundary security has seen\" — is powerful because:","options":["It uses precise numbers","Each clause is backed by an artifact that exists and can be audited: the baseline, the cost estimate, the sample tallies, the boundary sheet","It''s short enough for an executive to remember","It avoids technical vocabulary"],"correctIndex":1,"explanation":"The sentence is a claim with receipts — which is what separates it from every AI-enthusiasm anecdote in the same meeting. The numbers matter because the artifacts behind them do."},{"id":"q6","prompt":"The fifth rubric dimension — \"would a colleague trust it?\" — is the course''s test because:","options":["Peer approval is required for shipping","It integrates everything: verification that''s real, boundaries that are defensible, autonomy that''s evidenced, documentation that''s been run — trustworthy, not impressive","Colleagues will maintain the workflow after handoff","Trust is easier to grade than quality"],"correctIndex":1,"explanation":"Any single module can be performed; trust is what the whole system either earns or doesn''t. It''s also the property every rung above spends: role depth needs a practice that holds, and a Translator''s credibility starts at their own shipped, trustworthy build."},{"id":"q7","prompt":"The index page — new in this module — is written for two readers. They are:","options":["The builder, as a personal reference, and the review queue","A successor, as the first page they read, and an executive, as the only page they read","The deployment owner and the legal team","The peer reviewer and the hiring manager"],"correctIndex":1,"explanation":"One page: what the workflow is, what it saves, where everything lives, who owns it. A successor starts there and reads deeper; an executive reads it and stops — which is why the numbers on it carry their baseline and cost."},{"id":"q8","prompt":"Your paired peer''s review hasn''t arrived within a week. Under the course''s design, your shipping:","options":["Stalls until the peer delivers — the exchange is a hard gate","Skips the exchange; the consistency pass covers the same ground","Proceeds — your binder goes to the review queue, where an experienced reviewer runs the same cold read","Proceeds only if you review your own binder with fresh eyes"],"correctIndex":2,"explanation":"No single person can deadlock the course. The queue''s reviewer runs the identical protocol — and having seen many binders, their stalls are better-aimed than a peer''s. A feature, not a compromise."}]}', '2026-08-07');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-calibration-prompt-before-you-start-10', 'ai301-hrbp-m1', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds. You''ll score it in the applied activity — and again in Module 7.*

You are about to see survey data on how far along other organizations actually are with AI in HR.

**What percentage of organizations do you think have no plans to launch AI initiatives at all?**
Not "haven''t finished" — *no plans*. Commit a number before you read on.

This track scores the delta, not the score. The number matters far less than whether you can
say, seven modules from now, what moved you.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-module-brief-20', 'ai301-hrbp-m1', 20, 'prose', 'stable', '## Module brief

This module exists because you cannot think clearly about AI while you believe you are losing a
race — and most HRBPs believe exactly that.

The belief is not irrational. It arrives from every direction: a vendor deck claiming your
competitors have automated what you do by hand, a LinkedIn post from someone whose implementation
sounds effortless, a CHRO who read the same article you did and wants to know what you''re doing
about it. The cumulative message is that everyone is further along, and the only reasonable
response is speed.

Here is why that matters more than it looks. Decisions made under the belief that you are behind
are reliably worse decisions. You buy earlier and evaluate less. You adopt the thing being
marketed rather than the thing that fits your function. You skip the measurement that would have
told you whether it worked, because measurement takes time you feel you don''t have. Every failure
mode in the six modules that follow starts here, in the pressure to catch up with something.

So before this track teaches you anything about judgment work, it owes you an accurate picture of
where the field actually stands. Not a reassuring one — an accurate one. Some of it will be more
comfortable than you expect, and one piece of it will be less.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-learning-objectives-30', 'ai301-hrbp-m1', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. State, from data rather than impression, how far along HR functions actually are with AI.
2. Distinguish the two very different pressures that both feel like "we''re behind" — peer
   reality and executive expectation — and explain why they need different responses.
3. Name the specific decision errors that comparison-driven adoption produces.
4. Describe your own current AI use honestly, in terms of what you actually do rather than what
   you have access to.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-lesson-1-the-anxiety-and-where-it-comes--40', 'ai301-hrbp-m1', 40, 'prose', 'volatile', '## Lesson 1 · The anxiety, and where it comes from [V]

Start with the shape of the feeling, because naming it precisely is most of the work.

It is not usually "AI will take my job." Among HRBPs it is closer to *"everyone else has figured
out something I haven''t, and at some point that gap becomes visible."* It is a social anxiety
rather than a technical one, and it is produced by a specific information environment.

Consider who is generating the content you read about AI in HR. Vendors, whose product roadmap
is described as an industry trend. Consultancies, whose report exists to sell an engagement.
Practitioners on professional networks, who post about the implementation that worked and not
the three that stalled — the same selection bias that makes everyone else''s career look linear.
Conference speakers, selected for having something to announce.

Almost nobody publishes "we tried it, the results were ambiguous, and we''re still deciding." That
is the modal experience and it is nearly invisible, which means the picture you assemble from
public sources is systematically skewed toward completion and success.

This is worth saying plainly: **the sense that you are behind is partly a manufactured product,
and the manufacturing is not a conspiracy — it is just what happens when the only people
motivated to publish are the ones with something to sell or something to celebrate.**', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-lesson-2-what-the-data-actually-says-50', 'ai301-hrbp-m1', 50, 'prose', 'volatile', '## Lesson 2 · What the data actually says [V]

Now the survey evidence, which looks quite different from the content environment.

**A large share of organizations have not started, and do not intend to this year.** Roughly
three in ten report no plans to launch AI initiatives at all. That is not "behind schedule" —
that is a deliberate or default position held by a substantial minority of the field.

**Among those who have adopted, business value is not yet the norm.** A large majority of HR
leaders report that their organizations have not realized significant business value from AI
tools. Adoption and payoff are different milestones, and the gap between them is where most of
the field currently sits.

**And the finding that reframes the whole module:** the pressure most HRBPs feel is not coming
from their peers. It is coming from their executives. Around nine in ten CHROs expect more AI
adoption, while over half of organizations have not implemented any AI in HR at all. That is a
gap between *expectation* and *implementation*, not between you and your competitors.

Sit with that distinction, because it changes the correct response entirely:

- If you are behind your **peers**, the answer is to move faster.
- If you are behind your **executive''s expectations**, the answer is a conversation — about what
  is actually possible, on what timeline, at what cost, with what evidence. Moving faster into an
  unevaluated purchase does not close that gap; it just adds a failed implementation to it.

Most HRBPs are running the first play against the second problem. Module 5 gives you the
conversation; this module is about knowing which one you''re in.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-try-60', 'ai301-hrbp-m1', 60, 'try_this', 'stable', '### Try this — 2 minutes
Write down the last three things that made you feel behind on AI. For each: was the source a
vendor, a consultancy, a social post, or a person inside your organization telling you what
they expect? If most were the first three, your evidence base is the content environment. If
most were the fourth, you have an expectations problem, and it has a different fix.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-lesson-3-what-comparison-driven-adoption-70', 'ai301-hrbp-m1', 70, 'prose', 'stable', '## Lesson 3 · What comparison-driven adoption costs

The reason this module comes first is that the belief produces specific, predictable errors —
and every one of them is a failure the rest of the track has to clean up.

**You buy before you can evaluate.** Module 3 teaches measuring a workflow end to end. That
measurement is impossible under time pressure you have accepted from a feeling, so the purchase
happens on the vendor''s evidence instead of yours.

**You adopt what is marketed rather than what fits.** The AI products sold hardest into HR
cluster where the market is largest, not where your function''s leverage is. Module 2 sorts your
actual job; adopting before sorting means solving whichever problem had the best sales motion.

**You skip the baseline.** The single most expensive omission in the entire track. Without a
before-number you can never demonstrate the after-number, which means a working implementation and
a useless one look identical in the retrospective — and Module 7''s case for your function cannot
be made at all.

**You mistake activity for progress.** Pilots launched becomes the metric because it is the metric
available early. It measures motion, not value, and it is the number executives eventually stop
accepting.

The correction is not complacency. Nothing here says the technology is unimportant or that you
have unlimited time — the market pressure in Module 2 is real and it is not friendly. It says
something narrower and more useful: **you have more room to be deliberate than the content
environment suggests, and deliberateness is what separates the implementations that survive from
the ones that get quietly retired.**', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-exercise-embed-75', 'ai301-hrbp-m1', 75, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-key-takeaways-80', 'ai301-hrbp-m1', 80, 'takeaways', 'stable', '## Key takeaways

- **The sense of being behind is partly manufactured** — not maliciously, but structurally: only
  people with something to sell or celebrate publish, so the visible picture skews toward
  completion.
- **Roughly three in ten organizations have no AI plans at all this year** `[V]`, and a large
  majority of HR leaders report no significant business value yet. Adoption and payoff are
  different milestones.
- **Two different pressures feel identical and need opposite responses.** Behind your peers →
  move faster. Behind your executive''s expectations → have the conversation, with evidence. Most
  people run the first play against the second problem.
- **Comparison-driven adoption produces four specific errors:** buying before evaluating,
  adopting what''s marketed over what fits, skipping the baseline, and mistaking pilots launched
  for progress.
- **Deliberateness is available to you.** Not unlimited time — more room than you think, and it
  is what separates implementations that survive from ones that get retired.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-take-a-position-90', 'ai301-hrbp-m1', 90, 'callout', 'stable', '## Take a position

**The claim:** *"Most of the urgency you feel about AI was manufactured by people selling it, and
acting on that urgency is the single most expensive thing you''ll do this year."*

Commit to a position before you write the activity — agree, disagree, or agree-with-a-limit — and
be ready to argue it. The strongest version of the counter-argument is not "the anxiety is real."
It is that **urgency, even manufactured urgency, sometimes produces the right action for the wrong
reason** — organizations that moved early on manufactured fear did occasionally end up better
positioned than those who deliberated. Your position has to survive that.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-activity-link-95', 'ai301-hrbp-m1', 95, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 An honest inventory", "blurb": "What you actually used AI for in the last two weeks \u2014 not what you have access to \u2014 plus where your sense of being behind is really coming from, and the position you''ll defend on this module''s claim. Graded against a four-dimension rubric. Free unlimited resubmission.", "estMinutes": "15\u201320"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-sources-and-attribution-100', 'ai301-hrbp-m1', 100, 'prose', 'stable', '## Sources and attribution

- **SHRM, *The State of AI in HR 2026*** — the adoption, no-plans, and business-value findings,
  and the CHRO expectation data. Annual survey; figures move each cycle. **[V]**
- The two-pressures distinction (peer reality versus executive expectation), the four errors of
  comparison-driven adoption, and the content-environment selection-bias argument are original to
  this course.
- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with Anthropic,
  CC BY-NC-SA 4.0) — the calibrated-judgment stance this module''s prediction gate serves.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-activity-applied-activity-an-honest-inventory-10', 'ai301-hrbp-m1-activity', 10, 'prose', 'stable', '## Applied activity — "An honest inventory"

**Time:** 15–20 minutes · **Submit:** the inventory plus a 250–350 word write-up · **Graded
against the rubric below.** Score doesn''t matter. Doing the work is where the learning lands.

**Step 1 — What you actually do (7 min).** List every task where you personally used AI in the
last two weeks. Not what you have access to, not what you plan to try — what you *did*, with
rough frequency. Be unsparing: "reworded three emails" belongs on the list, and for many
experienced HRBPs it will be most of the list.

**Step 2 — What your function actually does (5 min).** The same for your team, as far as you
honestly know. Where you don''t know, write "don''t know" — that answer is data, and it is a more
useful finding than a guess.

**Step 3 — Locate the pressure (3 min).** Name the last three moments you felt behind, and for
each, the source: vendor, consultancy, social, or an executive expectation. Then say which of the
two problems you are actually in.

**Step 4 — Score the prediction (2 min).** Your predicted share of organizations with no AI plans
versus the real figure. Direction of the miss, and one sentence on what your guess reveals about
where you thought you stood.

Then the write-up: what the inventory shows about the distance between your *access* to AI and
your *use* of it, your position on the claim above with the strongest counter-argument addressed,
and the one thing you now think you should stop worrying about.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-micro-core', 'ai301-hrbp-m1-micro', 10, 'prose', 'stable', '## Module 1 in two minutes

**You are probably not as far behind as you feel, and the feeling is partly manufactured.** Not maliciously — structurally. The only people motivated to publish about AI in HR are vendors selling a roadmap, consultancies selling an engagement, and practitioners describing the implementation that worked. Nobody publishes the ambiguous result, which is the modal one, so the picture you assemble from public sources skews hard toward completion.

**What the data says instead** `[V]`: roughly three in ten organizations report *no plans at all* to launch AI initiatives, and a large majority of HR leaders say they have seen no significant business value from the tools they have adopted. Adoption and payoff are different milestones and most of the field sits in the gap.

**And the distinction that changes your response:** around nine in ten CHROs expect more AI adoption while over half of organizations have implemented none. That is an *expectations* gap, not a peer gap — and the two feel identical while requiring opposite plays. Behind your peers, move faster. Behind your executive''s expectations, have the conversation with evidence. Moving faster into an unevaluated purchase doesn''t close that gap; it adds a failure to it.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-micro-rule', 'ai301-hrbp-m1-micro', 20, 'callout', 'stable', '### The rule to carry

Comparison-driven adoption produces four errors: buying before you can evaluate, adopting what''s marketed over what fits, skipping the baseline, and mistaking pilots launched for progress. The third is the expensive one — with no before-number, a working implementation and a useless one look identical afterward.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m1-micro-close', 'ai301-hrbp-m1-micro', 30, 'prose', 'stable', '**The full module adds** the four-statements exercise (three of them fail in different ways — inverted finding, subgroup presented as field, roadmap wearing a statistic), the honest inventory of what you actually did with AI in the last two weeks rather than what you have access to, and the claim you''ll have to take a position on: that acting on manufactured urgency is the most expensive thing you''ll do this year.', NULL, '2026-08-12', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m1-choice', 'ai301-hrbp-m1', 'choice', '{"reviewedAt":"2026-08-12","title":"Four things you''ve been told","intro":"*Four minutes. Commit before you look.*\n\nFour statements an HRBP could plausibly have encountered this quarter — in a deck, a webinar, a peer conversation, or a LinkedIn post. Each sounds like evidence. **Only one is supported by what the survey data actually says.**\n\nThe other three fail in different ways, and naming the failure is the skill: one inverts a real finding, one is true of a subgroup and presented as true of the field, and one is a product roadmap wearing a statistic.","artifacts":[{"label":"Statement A · from a vendor webinar","body":"\"Nearly every HR function has now deployed AI in some form — the laggards are a rounding error, and they''re the ones losing talent to faster competitors.\""},{"label":"Statement B · from a peer at a conference","body":"\"Adoption is real but payoff isn''t yet — most HR leaders say they haven''t seen significant business value from the AI tools they''ve put in.\""},{"label":"Statement C · from a consultancy summary","body":"\"HR is one of the fastest-adopting functions in the enterprise. Recruiting teams in particular have moved decisively, which tells you where the rest of the function is headed within the year.\""},{"label":"Statement D · from a platform''s launch post","body":"\"Agentic AI is now standard in HR operations — the question is no longer whether your function runs agents, but how many.\""}],"options":[{"id":"a","label":"Statement A"},{"id":"b","label":"Statement B"},{"id":"c","label":"Statement C"},{"id":"d","label":"Statement D"}],"key":"b","reasoning":"**B is the supported one.** It states the adoption-versus-payoff gap accurately and without inflating it: a large majority of HR leaders report no significant business value yet, and that is a statement about the distance between two milestones rather than about the technology''s ceiling. Notice how unexciting it sounds. Accurate statements about this field mostly do.\n\n**A inverts the finding.** Roughly three in ten organizations report *no plans at all* — not late, not slow, no plans. \"Rounding error\" is the precise opposite of the data, and the talent-loss clause is a consequence asserted with no evidence attached, which is the tell.\n\n**C is true of a subgroup, presented as true of the field.** Recruiting genuinely is the most AI-penetrated practice area in HR. Everything after \"which tells you\" is extrapolation: the least-penetrated areas — employee relations, talent management, organizational design — are least penetrated because they''re the hard part, not because they''re merely next in line. This is the most dangerous of the three failures, because the first clause is true and buys credibility for the second.\n\n**D is a product roadmap wearing a statistic.** No number appears anywhere in it. \"Now standard\" and \"the question is no longer whether\" are rhetorical moves that presuppose the conclusion the vendor is selling — and the reframe from *whether* to *how many* is designed to skip the evaluation step this entire track exists to protect.\n\nThe portable test: ask what the claim would look like if it were false. B has an obvious falsifier — leaders would report business value. A, C, and D are built so that disagreeing with them makes you the laggard, which is how you recognize a claim engineered for urgency rather than accuracy."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m1-rubric', 'ai301-hrbp-m1', 'rubric', '{"promptVersion":"ai301-hrbp-m1-honest-inventory-v1","moduleId":"ai301-hrbp-m1","minWords":250,"maxWords":350,"submitLabel":"Your inventory and write-up","intro":"Paste the inventory (any readable format) followed by the 250–350 word write-up, including your position on this module''s claim. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for AI 301 · The Specialist, HRBP track — a role-specific course for HR business partners who have completed AI 101 and generally AI 201. Module 1 applied activity, ''An honest inventory'': every task where they personally used AI in the last two weeks (actual use, not access, not plans), the same for their team with ''don''t know'' as an acceptable and informative answer, the last three moments they felt behind with the source of each named (vendor / consultancy / social / executive expectation), a judgment about which of the two pressures they''re actually under, and a comparison against their predicted share of organizations with no AI plans. The write-up must also state a position on the module''s claim — that most of the urgency they feel was manufactured by people selling it — and address the strongest counter-argument, which is that manufactured urgency sometimes produces the right action for the wrong reason. This track scores the delta rather than the score: grade the honesty and specificity of the account, never the accuracy of any prediction.","opening":[{"key":"noPlansPct","label":"Predicted — % of organizations with no plans to launch AI initiatives","hint":"Not ''behind schedule'' — no plans at all. Whole percent.","placeholder":"e.g. 10","min":0,"max":100}],"calibration":[{"key":"noPlansPctActual","label":"Actual — the figure the module reports","hint":"Record it, then account for the direction of your miss.","placeholder":"e.g. 31","min":0,"max":100,"actualFor":"noPlansPct"}],"dimensions":[{"name":"The inventory is honest","criteria":"Actual use in the last two weeks, not access and not intentions — with the unglamorous entries included. ''Reworded three emails'' belongs on the list. An inventory that is shorter and more specific outscores one that is longer and aspirational, and ''don''t know'' about the team''s use scores higher than a confident guess."},{"name":"The pressure is located","criteria":"Three real moments named with their sources identified, and a defended judgment about whether this is a peer-reality problem or an executive-expectation problem. Getting the diagnosis ''wrong'' with visible reasoning outscores getting it right by assertion."},{"name":"The position survives its counter-argument","criteria":"A committed position on the claim — agree, disagree, or agree-with-a-limit — that engages the strongest case against it rather than the weakest. Restating the module''s argument back scores low; so does a position with no reasoning attached."},{"name":"The delta is accounted for","criteria":"Prediction compared against the real figure, direction of the miss named, and one sentence on what the guess reveals about where they thought they stood. Accuracy is not graded; the account of the gap is."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m1-knowledge_check', 'ai301-hrbp-m1', 'knowledge_check', '{"title":"Knowledge check — 5 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-12","questions":[{"id":"q1","prompt":"Why does the publicly available picture of AI adoption in HR skew toward success and completion?","options":["Publications are legally required to report only verified implementations","The people motivated to publish are vendors, consultancies, and practitioners with a win to describe — nobody publishes the ambiguous result, which is the modal one","Failed implementations are rare enough that they don''t affect the average","Survey methodology in HR research systematically oversamples large organizations"],"correctIndex":1,"explanation":"A selection effect, not a conspiracy: the content environment is assembled from the subset of experiences someone had a reason to publicize. C is contradicted by the business-value data, and D describes a different problem than the one this lesson is about."},{"id":"q2","prompt":"A large majority of HR leaders report their organizations have not realized significant business value from AI tools. What does this most directly indicate?","options":["That AI tools do not work for HR use cases","That the surveyed organizations have not adopted AI at all","That adoption and payoff are separate milestones, and most of the field currently sits in the gap between them","That HR leaders are poor judges of business value"],"correctIndex":2,"explanation":"The finding is about the distance between two milestones, not about the technology''s ceiling. B confuses this statistic with the no-plans figure; A over-reads a snapshot of an early field."},{"id":"q3","prompt":"Around nine in ten CHROs expect more AI adoption while over half of organizations have implemented none. What kind of gap is that, and why does it matter?","options":["A peer gap — it means your competitors are ahead and you should accelerate","An expectations gap — the pressure is coming from executives rather than peer reality, and it''s closed by a conversation with evidence, not by faster buying","A measurement gap — CHROs are counting adoption differently than practitioners","A vendor gap — it shows vendors have oversold to executives specifically"],"correctIndex":1,"explanation":"The distinction is the module''s central practical point: the two pressures feel identical and have opposite correct responses. Buying faster does not close a gap between what your executive expects and what is actually possible — it adds a failed implementation to it."},{"id":"q4","prompt":"Of the four errors comparison-driven adoption produces, which one most directly prevents you from ever proving an implementation worked?","options":["Adopting what''s marketed rather than what fits your function","Mistaking pilots launched for progress","Buying before you can evaluate","Skipping the baseline"],"correctIndex":3,"explanation":"Without a before-number, a working implementation and a useless one are indistinguishable afterward — and the case for your function in Module 7 cannot be built at all. B is a related error but it substitutes a bad metric rather than eliminating the possibility of a good one."},{"id":"q5","prompt":"What does this module actually argue about urgency?","options":["That the technology is overhyped and HR functions should wait for it to mature","That you have more room to be deliberate than the content environment suggests, and deliberateness is what separates implementations that survive from ones that get retired","That market pressure on the HRBP role is exaggerated and can be safely discounted","That AI adoption decisions should be deferred to executives who feel the pressure most"],"correctIndex":1,"explanation":"The correction is against comparison-driven haste, not against the technology or against urgency in general. C is explicitly contradicted — Module 2 takes the market pressure on this role seriously and unflinchingly."}]}', '2026-08-12');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-calibration-prompt-before-you-start-10', 'ai301-hrbp-m2', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds.*

By the end of this module you''ll sort a real week of your own work into four quadrants, using two
questions.

**What share of your week do you think requires either your physical or live presence, or a
judgment call that reasonable people could disagree about?** One number, whole percent.

Most HRBPs guess high. The number itself matters less than what you conclude when you see the
real one — and Module 7 will ask you what moved.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-module-brief-20', 'ai301-hrbp-m2', 20, 'prose', 'stable', '## Module brief

201 taught you to audit your week for workflows. This module asks a harder question about the
same week: **which parts of this job are actually yours?**

Not "which parts do you enjoy," and not "which parts are senior." Which parts require something
a system cannot supply — and which parts you have been doing because you have always done them,
because they arrive in your inbox, or because nobody has questioned whether they need a person
with your salary attached.

That question is uncomfortable, and this module makes it more so rather than less, because the
market is asking it about you whether or not you ask it about yourself. Two major research firms
have independently published the same direction of travel for HR headcount, and it is not a
gentle one. A course that taught you AI tactics without telling you that would be doing you a
disservice.

The good news is real and worth stating first: the core of HRBP work is the least AI-penetrated
territory in the entire HR function, by a wide margin. The bad news is that this is less
protective than it feels — and the reason why is the most important idea in this module.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-learning-objectives-30', 'ai301-hrbp-m2', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Sort any piece of your work using two questions — does it require presence, and does it
   require contested judgment — without confusing either with seniority or difficulty.
2. Name the four quadrants those questions produce and what each one implies about AI.
3. State where AI has actually landed across HR practice areas, and where it hasn''t.
4. Explain why "least penetrated" is not the same as "protected," and what would have to become
   true for each quadrant to move.
5. Describe the analyst consensus on HR headcount and ratios honestly enough to plan against it.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-lesson-1-two-questions-four-quadrants-40', 'ai301-hrbp-m2', 40, 'prose', 'stable', '## Lesson 1 · Two questions, four quadrants

Two questions, asked of any task.

**Does it require presence?** Not attendance — *presence*. Would something be lost if this
happened without a person in the room, live, able to read what isn''t being said and change course
inside the conversation? An investigation interview requires presence. A status meeting you
always attend usually does not, however senior you are.

**Does it require contested judgment?** Not difficulty — *contest*. Is there a defensible range
of answers that thoughtful people could disagree about, where the choice depends on values,
context, or precedent rather than analysis? Deciding whether a performance issue is a coaching
problem or a fit problem is contested judgment. A complex but determinate calculation is hard,
not contested.

Both distinctions get missed in the same direction, so hold them precisely: **presence is not
seniority, and contested judgment is not difficulty.** The most common self-assessment error
among experienced HRBPs is to mark work as irreducible because it is important, when importance
and irreducibility are unrelated properties.

The four quadrants:

**The room** — presence and contested judgment. The termination conversation, the investigation
interview, coaching a leader who is failing and does not know it. Irreducible, and the smallest
quadrant in most people''s week.

**The ritual** — presence, no contested judgment. Standing meetings, delivering a decision made
elsewhere, being visible at the onboarding session. Presence is genuinely expected; the judgment
isn''t contested. **This is the quadrant HRBPs over-defend**, because it feels like relationship
work and some of it is — but a great deal of it is calendar inheritance.

**The desk** — contested judgment, no presence required. Writing the recommendation, designing
the policy, preparing calibration, thinking through an org change. Real judgment, done alone,
async. **The highest-leverage quadrant for AI** — not because AI supplies the judgment, but
because it can carry everything around the judgment: the structuring, the drafting, the
what-am-I-missing pass.

**The queue** — neither. Scheduling, formatting, standard comms, data pulls, summarizing what was
said. Not unimportant. Just not yours.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-lesson-2-where-ai-has-actually-landed-50', 'ai301-hrbp-m2', 50, 'prose', 'volatile', '## Lesson 2 · Where AI has actually landed [V]

Now the field data, which is unusually clear.

Across a mapped set of roughly 138 AI use cases spanning 16 HR practice areas, adoption
concentrates hard: recruiting around 27%, HR technology around 21%, learning and development
around 17%, employee experience around 14%. Those four account for the large majority of
everything deployed.

And the least-adopted areas are, in order of how much they matter to you: employee relations,
talent management, organizational design, and compliance.

Read that list again, because it is a description of an HRBP''s job. **The core of your role is
the least AI-penetrated territory in the function.**

Two honest reasons for that, and they are different in kind:

**It''s the hard part.** Contested judgment on sparse, sensitive, context-dependent information is
genuinely difficult for these systems — and 101 M7 explains why a large slice of it *must not* be
delegated regardless of capability. That constraint is durable because it is ethical and legal
rather than technical.

**And it''s the part with the worst data.** Recruiting has funnels, timestamps, and outcomes.
Employee relations has narrative documents that nobody would let a vendor train on. Low adoption
partly reflects low tractability rather than high protection — and tractability changes.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-lesson-3-least-penetrated-is-not-protect-60', 'ai301-hrbp-m2', 60, 'prose', 'stable', '## Lesson 3 · Least penetrated is not protected

Here is the idea worth the whole module.

You do not need AI to do contested-judgment work for your ratio to move. **You only need it to
eat the work that justified the headcount.**

Follow the arithmetic. If half of a typical HRBP week sits in the queue and the shallow end of
the desk — the drafting, the summarizing, the data pulls, the first-pass documents, the standing
report — and that half compresses substantially, then the same number of HRBPs can cover
materially more population. Nothing in the room quadrant was touched. Nobody automated a
termination conversation. The ratio moves anyway, because ratios are set by total workload, not
by the hardest thing in it.

This is why "AI can''t do what I do" is a true statement that provides no protection whatsoever.
It answers a question nobody in a budget meeting is asking.

What actually follows from it, though, is more interesting than fatalism. If your defensible
work is the room and the deep end of the desk, then **the strategic move is to be excellent
there and fast everywhere else** — and being fast everywhere else is exactly what this track
teaches. The HRBPs who struggle in the next few years will not be the ones who used AI. They
will be the ones who spent their compressed capacity on more queue work rather than more room.

What would have to become true for each quadrant to move further?

- **The queue** is already moving and will keep moving. Assume it goes.
- **The desk** moves as context handling improves and as organizations get better at supplying
  organizational knowledge — 201''s whole subject. Expect the shallow end to compress and the deep
  end to hold.
- **The ritual** moves when someone questions the calendar, which is a political event rather
  than a technical one. It is the quadrant most likely to be cut by a reorg and least likely to
  be cut by a tool.
- **The room** holds — for capability reasons that may erode and for ethical and legal reasons
  that will not.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-try-70', 'ai301-hrbp-m2', 70, 'try_this', 'stable', '### Try this — 3 minutes
Take the three things you did yesterday that felt most like "real HRBP work." Run each through
both questions honestly. If any of them lands in the ritual or the shallow desk, you have
found the gap between how the work feels and what it is — which is the gap this module exists
to close.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-lesson-4-the-pressure-said-plainly-80', 'ai301-hrbp-m2', 80, 'prose', 'volatile', '## Lesson 4 · The pressure, said plainly [V]

You are owed the numbers rather than the euphemism.

Gartner recommends replacing the fixed HRBP model with flexible **pods of strategic talent
leaders** — consultative, AI-supported, with few administrative responsibilities — and projects
that within one to five years the ratio could move from roughly **one HRBP per 423 employees to
one per 800–1,200.** That is not an efficiency nudge. At the midpoint it is half the HRBPs
covering the same population.

Josh Bersin, independently, describes HR teams operating with **30–40% fewer people.**

Two firms, different methods, same direction. You should not treat either as prophecy — analyst
projections routinely overshoot on timing, and "could rise to" is doing real work in that
sentence. But you also should not treat the agreement as noise. When independent analyses
converge on direction, the direction is usually right even when the timeline isn''t.

The honest read: **the work isn''t disappearing, the headcount ratio is changing, and the
distribution of what remains will favour whoever is credible in the room quadrant.** The
strategic talent leader Gartner describes is not a new profession. It is an HRBP who spends most
of their week on contested judgment — which is a description of what the best ones already do
when their calendar allows it.

That is the actual argument for everything in the five modules that follow. Not "use AI because
it''s the future." Use it to buy back the hours that currently prevent you from being the person
that model describes.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-key-takeaways-90', 'ai301-hrbp-m2', 90, 'takeaways', 'stable', '## Key takeaways

- **Two questions sort everything: does it require presence, does it require contested judgment.**
  Presence is not seniority; contested judgment is not difficulty. Most self-assessment errors
  come from confusing importance with irreducibility.
- **Four quadrants:** the room (irreducible), the ritual (over-defended calendar inheritance),
  the desk (highest AI leverage — AI carries everything around the judgment), the queue (not
  yours).
- **The core of HRBP work is the least AI-penetrated part of HR** `[V]` — employee relations,
  talent management, org design, compliance — while recruiting, HR tech, L&D, and employee
  experience carry most deployed use cases.
- **Least penetrated is not protected.** Your ratio moves when the work that *justified* the
  headcount compresses, not when the hardest work gets automated. "AI can''t do what I do" answers
  a question nobody in a budget meeting is asking.
- **The analyst consensus is directionally consistent** `[V]`: pods of strategic talent leaders,
  one HRBP per 800–1,200 within one to five years, HR teams 30–40% smaller. Treat the direction
  as real and the timeline as soft.
- **The strategic move is excellence in the room, speed everywhere else** — and spending the
  recovered capacity on more room rather than more queue.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-exercise-embed-95', 'ai301-hrbp-m2', 95, 'exercise', 'stable', '{"type": "sorting", "title": "Calibration exercise \u2014 Sort the week", "intro": "Ten minutes, twelve pieces of real HRBP work. Sort each into the quadrant it belongs to, using both questions: does it require presence, and does it require contested judgment?\n\nCommit every card before the reveal. The pattern in your misses \u2014 whether you place work higher or lower than the key \u2014 is what the exercise actually measures."}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-take-a-position-100', 'ai301-hrbp-m2', 100, 'callout', 'stable', '## Take a position

**The claim:** *"Your core work being hard for AI is not job security. The ratio moves when the
easy half of your week compresses — and the easy half is compressing whether you participate or
not."*

Commit before you write the activity. The strongest counter-argument is not that the work is
irreplaceable. It is **that ratios are set by budget appetite and risk tolerance, not by
workload** — organizations have historically kept HRBP coverage well above what pure workload
math implied, because proximity to the business is itself the product. If that''s true, the
compression argument proves less than it appears to.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-activity-link-105', 'ai301-hrbp-m2', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 One week, sorted", "blurb": "A real week logged and sorted into the four quadrants, with one piece of work you''ll defend and one you''ll surrender \u2014 plus your position on whether the hard part of your job is actually protecting you. Graded against a four-dimension rubric. Free unlimited resubmission.", "estMinutes": "20\u201325"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-sources-and-attribution-110', 'ai301-hrbp-m2', 110, 'prose', 'stable', '## Sources and attribution

- **SHRM, *The State of AI in HR 2026*** — the practice-area adoption map, the use-case count,
  and the concentration and least-adopted findings. **[V]**
- **Gartner** — the HR operating model work: strategic talent leader pods replacing fixed HRBP
  assignments, and the ratio projection from ~1:423 toward 1:800–1,200 within one to five years.
  **[V]**
- **Josh Bersin** — the independent projection of HR teams operating with 30–40% fewer people.
  **[V]**
- The two-question test, the four quadrants, and the compression argument (that the ratio moves
  when the justifying work compresses rather than when the hardest work is automated) are
  original to this course.
- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with Anthropic,
  CC BY-NC-SA 4.0) — the delegation stance this module operationalizes for one role.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-activity-applied-activity-one-week-sorted-10', 'ai301-hrbp-m2-activity', 10, 'prose', 'stable', '## Applied activity — "One week, sorted"

**Time:** 20–25 minutes · **Submit:** the quadrant map plus a 250–350 word write-up · **Graded
against the rubric below.** Score doesn''t matter. Doing the work is where the learning lands.

**Step 1 — Log the week (10 min).** A real week — last week, not a representative one. Every
block of an hour or more, plus a fair estimate of the interrupt-driven work that never hits a
calendar. Approximate hours are fine; honesty is the requirement.

**Step 2 — Sort it (5 min).** Every item into one of the four quadrants, using both questions
explicitly. Where a block spans two quadrants, split the hours rather than rounding to the
flattering one. Produce a percentage distribution.

**Step 3 — Defend one, surrender one (5 min).** Name **one piece of work you will defend** —
where you''d argue against automation even if it became possible, with the reason — and **one you
will surrender**, where you''re currently spending judgment-grade attention on something that
doesn''t need it. The second is the harder and more valuable half.

**Step 4 — Score the prediction (2 min).** Your predicted presence-or-contested share against
your actual. Direction of the miss, and one sentence on what the gap reveals.

Then the write-up: what surprised you in the distribution, your position on the claim above with
the counter-argument addressed, and what you would have to stop doing to move five percentage
points from queue to room.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-micro-core', 'ai301-hrbp-m2-micro', 10, 'prose', 'stable', '## Module 2 in two minutes

**Two questions sort your entire job.** Does it require *presence* — would something be lost if this happened without a live person able to read the room and change course? Does it require *contested judgment* — could reasonable people defensibly disagree? Hold both precisely: **presence is not seniority, and contested judgment is not difficulty.**

**Four quadrants.** The room (both — irreducible, and smaller than you think). The ritual (presence, no contest — the over-defended calendar inheritance). The desk (contest, no presence — the highest AI leverage, because the model carries everything *around* the judgment). The queue (neither — not yours).

**The field data is unusually clear** `[V]`: AI adoption concentrates in recruiting, HR technology, L&D, and employee experience, and is thinnest in employee relations, talent management, org design, and compliance — which is a description of your job. **But least penetrated is not protected**, and that''s the module''s real argument: your ratio moves when the work that *justified* the headcount compresses, not when the hardest work gets automated. "AI can''t do what I do" is true and answers a question nobody in a budget meeting is asking.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-micro-rule', 'ai301-hrbp-m2-micro', 20, 'callout', 'stable', '### The rule to carry

Be excellent in the room and fast everywhere else — then spend the recovered capacity on more room rather than more queue. That last clause is the whole strategy, and it''s the one people skip.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m2-micro-close', 'ai301-hrbp-m2-micro', 30, 'prose', 'stable', '**The full module adds** the twelve-card quadrant sort, the analyst numbers said plainly `[V]` — pods of strategic talent leaders, one HRBP per 800–1,200 within one to five years, HR teams 30–40% smaller — and the week-logging activity where you name one piece of work you''ll defend and one you''ll surrender. The surrender is the hard half.', NULL, '2026-08-12', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m2-sorting', 'ai301-hrbp-m2', 'sorting', '{"reviewedAt":"2026-08-12","buckets":[{"id":"room","label":"The room","hint":"Presence + contested judgment","rank":0,"pct":5},{"id":"ritual","label":"The ritual","hint":"Presence, no contest","rank":1,"pct":25},{"id":"desk","label":"The desk","hint":"Contest, no presence","rank":2,"pct":60},{"id":"queue","label":"The queue","hint":"Neither","rank":3,"pct":90}],"tasks":[{"id":"t1","text":"Interviewing a witness in a harassment investigation","key":"room","reasoning":"Both questions answer yes. You have to hear what isn''t being said and change course inside the conversation, and every call about credibility and follow-up is contested. The clearest room card in the set."},{"id":"t2","text":"Scheduling the eight interviews for a leadership team''s calibration session","key":"queue","reasoning":"Neither presence nor contest. Real work, genuinely necessary, and not yours — this is the quadrant where the compression argument does its damage, and where you should want it to."},{"id":"t3","text":"Deciding whether a manager''s performance problem is a coaching issue or a fit issue","key":"desk","reasoning":"Contested judgment with no presence required — you can reach this call at your desk, and reasonable colleagues could disagree. The deep end of the desk is where an HRBP''s defensible value actually concentrates.","also":["room"]},{"id":"t4","text":"Attending the weekly business unit leadership meeting where you rarely speak","key":"ritual","reasoning":"Presence is genuinely expected and absence would be noticed; no contested judgment is being exercised. The most over-defended card in the set, because it feels like relationship investment — and some of it is, which is why the two questions beat instinct here."},{"id":"t5","text":"Turning your handwritten notes from three skip-levels into a structured themes summary","key":"queue","reasoning":"Transformation of material you supplied, with a known output shape. No presence, no contest — 101''s delegation heuristic at its center. The judgment comes later, when you decide what the themes mean.","also":["desk"]},{"id":"t6","text":"Telling a long-tenured employee their role is being eliminated","key":"room","reasoning":"Presence is the entire point, and the judgment — what to say, what to hold, when to stop talking — is contested and live. No amount of preparation converts this into desk work."},{"id":"t7","text":"Designing the promotion criteria for a newly created job family","key":"desk","reasoning":"Deeply contested — the criteria encode values and precedent — and done alone. High AI leverage precisely because the model can carry the structuring, the drafting, and the what-am-I-missing pass while the judgment stays yours."},{"id":"t8","text":"Pulling headcount and attrition figures for the quarterly business review deck","key":"queue","reasoning":"Determinate, repeatable, no contest. If this consumes judgment-grade attention in your week, it is the first thing the activity should have you surrender."},{"id":"t9","text":"Delivering a compensation decision to a manager that the comp committee already made","key":"ritual","reasoning":"Presence is expected — someone has to say it, and it should be a person — but the judgment was exercised elsewhere. Tempting to file as the room because the conversation is uncomfortable; discomfort is not contest."},{"id":"t10","text":"Drafting the first version of a new remote-work policy from three reference policies","key":"desk","reasoning":"Contested in the choices it encodes, async in execution, and the drafting is exactly what AI carries well when you supply the references. The judgment is which trade-offs to make, not which words to type.","also":["queue"]},{"id":"t11","text":"Coaching a director through a decision you believe is wrong","key":"room","reasoning":"Presence and contest both, at maximum. The whole value is reading resistance in real time and deciding, live, whether to push or hold. This is what the strategic talent leader model is describing."},{"id":"t12","text":"Reviewing forty manager-written performance reviews for consistency of language","key":"desk","reasoning":"Contested at the edges — what counts as coded or vague language is a judgment — but no presence needed, and the volume pass is exactly what AI does well. Assist-side under 101 M7: you''re reading what managers wrote, not rating the people.","also":["queue"]}],"pattern":"Presence is not seniority, and contested judgment is not difficulty — the two errors that move cards in opposite directions.","postscript":"Cards placed toward the queue and desk mean you credit AI with more reach than the key does; cards placed toward the room and ritual mean less. Neither miss is the bad one — but the ritual cards are where most people cluster their errors, filing calendar inheritance as irreducible because it feels like relationship work. The applied activity now runs this on your actual week, where the distribution matters more than any single call."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m2-rubric', 'ai301-hrbp-m2', 'rubric', '{"promptVersion":"ai301-hrbp-m2-one-week-sorted-v1","moduleId":"ai301-hrbp-m2","minWords":250,"maxWords":350,"submitLabel":"Your quadrant map and write-up","intro":"Paste the week''s log and its quadrant distribution, followed by the 250–350 word write-up including your position on this module''s claim. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for AI 301 · The Specialist, HRBP track. Module 2 applied activity, ''One week, sorted'': a real week logged (last week, not a representative one, including interrupt-driven work that never hit a calendar), every item sorted into four quadrants using two questions — does it require presence, does it require contested judgment — with split hours where a block spans quadrants, a resulting percentage distribution, one piece of work they will defend against automation with reasoning, one they will surrender, and a comparison against their predicted presence-or-contested share. The write-up must state a position on the module''s claim — that core work being hard for AI is not job security, because the ratio moves when the easy half compresses — and address the strongest counter-argument, which is that ratios are set by budget appetite and proximity-to-business value rather than by workload math. Key grading insight: presence is not seniority and contested judgment is not difficulty; the most common error is filing calendar inheritance (the ritual) or determinate-but-hard work as irreducible. This track scores the delta rather than the score — never grade prediction accuracy.","opening":[{"key":"irreducibleShare","label":"Predicted — % of your week needing presence or contested judgment","hint":"Either one counts. Whole percent.","placeholder":"e.g. 60","min":0,"max":100}],"calibration":[{"key":"irreducibleShareActual","label":"Measured — the share your logged week actually shows","hint":"Room plus ritual plus desk, from your own distribution.","placeholder":"e.g. 45","min":0,"max":100,"actualFor":"irreducibleShare"}],"dimensions":[{"name":"The week is real","criteria":"An actual week rather than a typical one, including the interrupt-driven work that never reaches a calendar, with approximate hours. A messy honest week outscores a tidy representative one, and admitting untracked time outscores rounding it away."},{"name":"Both questions actually applied","criteria":"Each item classified against presence AND contest explicitly, with blocks split across quadrants rather than rounded to the flattering one. Watch for the two named errors — treating seniority as presence, treating difficulty as contest — and say so plainly in feedback where they appear."},{"name":"The surrender is genuine","criteria":"The defended item carries a reason beyond ''it''s important.'' The surrendered item is real work they currently spend judgment-grade attention on — this is the harder and more valuable half, and a surrender that costs the learner nothing should score low."},{"name":"The position and the delta","criteria":"A committed position on the compression claim that engages the budget-appetite counter-argument rather than a weaker one, plus the prediction compared, miss direction named, and a specific account of what would have to stop for five points to move from queue to room. Accuracy of the prediction is not graded."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m2-knowledge_check', 'ai301-hrbp-m2', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-12","questions":[{"id":"q1","prompt":"You always attend your business unit''s weekly leadership meeting, where you rarely speak but your absence would be noticed. Which quadrant?","options":["The room — you''re senior and your presence is expected","The ritual — presence is genuinely expected, but no contested judgment is being exercised","The desk — the value is in what you do with the information afterward","The queue — if you rarely speak, the meeting isn''t work"],"correctIndex":1,"explanation":"Presence is real; contest isn''t. This is the quadrant HRBPs over-defend because it feels like relationship work — and some of it genuinely is, which is exactly why it needs the two questions rather than instinct. A makes the module''s most common error: treating seniority as presence."},{"id":"q2","prompt":"A complex benefits cost model with one defensible answer, requiring six hours of careful work, is:","options":["Contested judgment, because it''s difficult and consequential","Not contested judgment — difficulty and contest are different properties, and a determinate answer isn''t contested","The room, because the stakes are high","Impossible to classify without knowing who requested it"],"correctIndex":1,"explanation":"Contest means reasonable people could defensibly disagree, not that the work is hard. A determinate calculation with one right answer is difficult and uncontested — which is precisely the profile where AI assistance is most valuable and least fraught."},{"id":"q3","prompt":"Across HR practice areas `[V]`, where has AI adoption actually concentrated?","options":["Employee relations and organizational design, where the documents are richest","Evenly across practice areas, tracking overall HR headcount","Recruiting, HR technology, L&D, and employee experience — with employee relations, talent management, org design, and compliance least adopted","Compliance first, since regulatory work is most rule-based"],"correctIndex":2,"explanation":"The concentration is sharp, and the least-adopted list reads like an HRBP job description. A inverts the finding — those areas are least penetrated, partly because their data is exactly what nobody will let a vendor near."},{"id":"q4","prompt":"Why is \"least penetrated\" not the same as \"protected\"?","options":["Because vendors will eventually build for those areas regardless of difficulty","Because your ratio moves when the work that justified the headcount compresses — the hardest work never has to be automated for the coverage math to change","Because low adoption figures are unreliable and likely undercount actual usage","It is the same — low penetration is what job security looks like in practice"],"correctIndex":1,"explanation":"The module''s central argument. Ratios are set by total workload, not by the hardest item in it, so \"AI can''t do what I do\" is true and irrelevant to the budget conversation. A is plausible but is a slower and less certain mechanism than the one that''s already operating."},{"id":"q5","prompt":"Which quadrant is most likely to be reduced by an organizational decision rather than a technical capability?","options":["The queue — automation is already eating it","The room — ethical constraints could be relaxed","The desk — context handling keeps improving","The ritual — it shrinks when someone questions the calendar, which is a political event"],"correctIndex":3,"explanation":"Nothing technical removes a standing meeting; a reorg does. That makes the ritual the quadrant most exposed to a decision you don''t control and least exposed to a tool — the opposite of most people''s intuition about it."},{"id":"q6","prompt":"Gartner''s projection `[V]` is that the HRBP ratio could move from roughly one per 423 employees to:","options":["One per 500–600 within a decade","One per 800–1,200 within one to five years","One per 2,000 within two years","No change in ratio, with the role''s content shifting instead"],"correctIndex":1,"explanation":"Roughly a doubling at the midpoint, on a short horizon, alongside the recommendation to replace fixed HRBP assignments with pods of strategic talent leaders. Treat the direction as real and the timing as soft — analyst projections routinely overshoot on schedule."},{"id":"q7","prompt":"What is the strongest counter-argument to this module''s claim about compression?","options":["That AI capability has plateaued and won''t reach the desk quadrant","That analyst firms are financially motivated to predict disruption","That ratios are set by budget appetite and risk tolerance rather than workload — organizations have historically kept HRBP coverage above what workload math implied, because proximity to the business is itself the product","That HR headcount has never fallen in a sustained way"],"correctIndex":2,"explanation":"It''s the strongest because it doesn''t dispute the compression — it disputes that compression determines coverage. B is worth noticing but it''s an ad hominem about the source rather than an argument about the mechanism, and two independent firms agreeing weakens it."},{"id":"q8","prompt":"What does the module conclude is the strategic response?","options":["Resist automation of HRBP work to protect headcount","Be excellent in the room quadrant and fast everywhere else — and spend recovered capacity on more room rather than more queue","Move toward recruiting or L&D, where AI adoption and investment are concentrated","Wait for the analyst timelines to clarify before changing how you work"],"correctIndex":1,"explanation":"The compression is the argument *for* the rest of the track: use AI to buy back the hours that currently prevent you from being the consultative practitioner the strategic talent leader model describes. A defends the queue, which is the losing position; C abandons the quadrant where this role''s actual value sits."}]}', '2026-08-12');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-calibration-prompt-before-you-start-10', 'ai301-hrbp-m3', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds.*

There is a category of work that AI creates rather than removes: feeding it context, supervising
its output, debugging what it got wrong, and cleaning up downstream when something slipped
through. Researchers have started calling it **botsitting**, and it is almost never counted in
anyone''s workload planning.

**How many hours a week do you personally spend botsitting?** Your own honest estimate, before
you see anyone else''s number.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-module-brief-20', 'ai301-hrbp-m3', 20, 'prose', 'stable', '## Module brief

Every other module in this track makes you better at something. This one makes you harder to
sell to — including by us.

The premise is simple and slightly rude: **nobody in this market has an incentive to tell you
what AI actually costs in time.** Vendors count the minutes saved and not the minutes spent
supervising. Consultancies publish the case study with the good number. Your own team reports
the pilot went well, because that is what people say about pilots they championed. And you have
no baseline, so nothing in that chain gets checked.

The result is a function that can describe its AI adoption in confident detail and cannot say
whether any of it worked.

This module gives you the arithmetic to find out — four questions applied end to end to one real
workflow — and then turns the same skepticism outward at the claims you''ll be shown. The
uncomfortable part is that the arithmetic sometimes returns a negative answer, and you have to
be willing to write that down. A function that only measures its wins isn''t measuring.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-learning-objectives-30', 'ai301-hrbp-m3', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain the productivity paradox in this field — large perceived time savings, thin
   organizational value — and the mechanism that produces it.
2. Audit any workflow end to end with four questions, including the human time that most audits
   omit.
3. Recognize the volume trap: cheaper production shifts the constraint from making work to
   deciding which work matters.
4. Tear down a vendor claim on its evidence, its sample, and its falsifier — and know where in HR
   the credible proof actually clusters.
5. Name a specific destination for recovered time, and explain why an unnamed destination means
   the time wasn''t recovered.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-lesson-1-the-productivity-paradox-40', 'ai301-hrbp-m3', 40, 'prose', 'volatile', '## Lesson 1 · The productivity paradox [V]

Three findings, which are hard to hold at once and are all well-evidenced.

**People believe AI saves them a great deal of time.** In a large multi-country study of digital
workers, the substantial majority reported AI saving them on the order of eleven hours a week.

**Organizations mostly can''t find it.** In the same research, only about 13% said their
organization was performing significantly better as a result. And separately, Gartner reports
that **88% of HR leaders say their organizations have not realized significant business value
from AI tools.**

**And a measurable slice of the savings goes straight back out.** The same study measured an
average of **6.4 hours a week of botsitting** — feeding AI context, supervising its output,
debugging its mistakes, and cleaning up work downstream. That labour is largely unrecognized,
unbudgeted, and untracked.

Put those together and the paradox resolves without anyone lying. Individuals genuinely
experience relief — the blank page is gone, the first draft is instant. But a meaningful portion
of the saved time is consumed by supervision that nobody counts, and most of the remainder never
reaches the organization as anything visible, because it dissolves into the day rather than
being redirected anywhere.

The relief is real. The organizational value is what''s missing, and it''s missing for reasons
that are structural rather than mysterious.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-lesson-2-the-four-question-audit-50', 'ai301-hrbp-m3', 50, 'prose', 'stable', '## Lesson 2 · The four-question audit

The method, applied to one workflow, end to end.

**1. What is the total human time, including review and rework?** Not the generation time — the
*total*. Time briefing the model, time reading output critically, time fixing what was wrong,
time redoing it when the fix broke something else, and time you spent on the downstream mess if
something slipped through. This single question flips more workflows from positive to negative
than the other three combined, because the minutes it counts are exactly the minutes the vendor''s
arithmetic omits.

**2. Did final quality actually improve, get worse, or stay the same?** Judged against what you
would have produced by hand, honestly, on the thing that mattered about the output. Faster and
slightly worse is a legitimate trade for some work and a disqualifying one for others — but you
have to name which you got.

**3. Where did the work move to?** Work rarely disappears; it relocates. Off your desk onto a
coordinator''s. Out of drafting and into reviewing. From one person doing it slowly to three
people each checking a piece. Relocation can be a real win — reviewing is usually cheaper than
drafting — but relocation described as elimination is how a function convinces itself it saved
capacity it didn''t.

**4. What did the freed capacity actually become?** The question almost nobody asks, and the one
that determines whether any of this reaches the organization. Gartner found that **only 7% of
organizations give employees any guidance on how to use time AI saves** — from a July 2025 survey
of 114 HR leaders, which is a small sample and worth saying so, since this module is about
checking exactly that. Small sample or not, 7% is the kind of number that would have to be
wildly wrong to change the conclusion.

Without an answer to question four, saved time is absorbed rather than recovered. It becomes
slightly more email, slightly more Slack, and a week that feels identical.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-try-60', 'ai301-hrbp-m3', 60, 'try_this', 'stable', '### Try this — 3 minutes
Take the AI-assisted task you did most recently. Answer question one out loud, honestly, in
minutes — including the reading and the fixing. Then compare it to what the same task took you
before. Most people find the answer is "about the same, but less unpleasant," which is a real
benefit and is not the benefit anyone is claiming.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-lesson-3-the-volume-trap-70', 'ai301-hrbp-m3', 70, 'prose', 'stable', '## Lesson 3 · The volume trap

There''s a second-order effect that the four questions don''t catch, and for a People function it
may be the most consequential thing in this module.

**When content gets cheaper to produce, organizations produce more of it.** That''s not a
prediction; it''s what has happened every time production costs have fallen. And the consequence
is a shift in where the constraint lives: you get faster at generating work and slower at
deciding which work matters, because the deciding didn''t get any cheaper and there''s now more to
decide about.

The HRBP-specific version is easy to recognize once named. More frameworks. More decks. More
survey cuts nobody asked for. Three versions of the policy instead of one, because generating the
alternatives was free. A manager toolkit that is now forty pages because forty pages cost the
same as twelve.

None of that is decisions. And an HRBP''s actual product — Module 2''s room and deep desk — is
decisions and the judgment behind them. **A function that gets faster at producing artifacts
while producing no more decisions has gotten worse, efficiently.**

The defence is to make the volume decision consciously: when a workflow gets cheaper, decide
explicitly whether you want more output or the same output with the time back. Both are valid.
Drifting into the first because it''s the default is what produces the forty-page toolkit.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-lesson-4-their-arithmetic-torn-down-80', 'ai301-hrbp-m3', 80, 'prose', 'volatile', '## Lesson 4 · Their arithmetic, torn down [V]

Now the same skepticism aimed outward. Three questions on any claim: **what''s the evidence,
what''s the sample, and what would falsify it?**

Watch it work on the cases this market is built on.

**The famous attrition-prediction figure.** IBM''s widely-repeated claim of roughly $300 million
saved through AI attrition prediction is a *CEO statement* — never independently audited, never
methodologically published. That doesn''t make it false. It makes it unverifiable, which is a
different thing, and a claim you can''t check shouldn''t be doing load-bearing work in your
business case.

**HireVue and facial analysis.** The company removed facial analysis from its assessments after
its own data indicated the visual component added negligible predictive value. Two lessons at
once: a widely-sold capability turned out not to work, and the company that discovered it was the
one selling it — which is what honest self-correction looks like and how rarely it happens.

**Amazon''s recruiting tool.** Scrapped after it taught itself to penalize résumés containing
"women''s." The canonical demonstration of 101 M7''s argument: the model learned what the records
contained, which is what a learned system does.

And the pattern underneath the cases: **credible proof clusters at the front door and the back
office** — scheduling, coordination, high-volume transactional throughput, where outcomes are
countable and a failure is visible immediately. **The loudest claims live in assessment,
prediction, and people analytics** — where outcomes are slow, confounded, and nearly impossible
to attribute, which is precisely why the claims can be loud.

That asymmetry gives you a heuristic worth carrying into any vendor conversation:

> **Automating the "yes" is comparatively safe. Automating the "no" is where the risk starts.**

Accelerating someone through a process is recoverable and visible. Filtering someone out is
invisible to everyone including you — the person who was excluded never appears in your data,
which means the failure mode is structurally unmeasurable. That is 101 M7''s line, arrived at from
the evidence side rather than the ethical one, and the two agreeing is not a coincidence.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-key-takeaways-90', 'ai301-hrbp-m3', 90, 'takeaways', 'stable', '## Key takeaways

- **The paradox resolves without anyone lying** `[V]`: people genuinely feel ~11 hours a week of
  relief, ~6.4 hours goes back out as unbudgeted botsitting, and 88% of HR leaders report no
  significant business value — because the remainder dissolves into the day instead of being
  redirected.
- **Four questions, end to end:** total human time *including review and rework*; whether quality
  actually moved; where the work relocated to; and what the freed capacity became. The first
  flips more workflows negative than the rest combined.
- **Only about 7% of organizations tell anyone what the saved time is for** `[V]`. Without an
  answer, time is absorbed rather than recovered.
- **The volume trap:** cheaper production means more production, so the constraint moves from
  making work to deciding which work matters. A function producing more artifacts and no more
  decisions has gotten worse, efficiently.
- **Tear down claims on evidence, sample, and falsifier.** An unaudited CEO figure isn''t false —
  it''s unverifiable, which disqualifies it from load-bearing use.
- **Proof clusters at the front door and back office; the loudest claims live where outcomes are
  slow and confounded.** Automating the "yes" is comparatively safe; automating the "no" is where
  risk starts — and the people filtered out never appear in your data.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-exercise-embed-95', 'ai301-hrbp-m3', 95, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-take-a-position-100', 'ai301-hrbp-m3', 100, 'callout', 'stable', '## Take a position

**The claim:** *"A workflow whose time savings you can''t trace to a named destination hasn''t
saved you time. It has redistributed it into work nobody asked for."*

The strongest counter-argument is not that measurement is hard. It is that **some of the real
value here is unmeasurable and legitimately so** — reduced cognitive load, a lower activation cost
for starting hard things, slack that gets spent on thinking rather than output. Demanding a named
destination for every recovered hour may be a category error that treats knowledge work like a
production line. Your position has to survive that.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-activity-link-105', 'ai301-hrbp-m3', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 One workflow, measured", "blurb": "One of your own AI-assisted workflows audited end to end \u2014 total human time including rework, where the work moved, and a named destination for the recovered hours. A workflow you measured and killed is the strongest submission this module accepts. Graded against a four-dimension rubric. Free unlimited resubmission.", "estMinutes": "25\u201330"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-sources-and-attribution-110', 'ai301-hrbp-m3', 110, 'prose', 'stable', '## Sources and attribution

- **Glean, *The Work AI Index 2026*** — the ~11 hours perceived saving, the 13% organizational
  performance figure, and the 6.4-hours-per-week botsitting measurement (n≈6,000 digital workers
  across the US, UK, and Australia, fielded December 2025 – January 2026). **[V]**
- **Gartner** — 88% of HR leaders reporting no significant business value from AI tools; and the
  finding that only 7% of organizations provide guidance on using time saved by AI (July 2025
  survey of 114 HR leaders — a small sample, noted in-lesson because this module is about saying
  so). **[V]**
- Vendor and implementation cases — the IBM attrition figure, HireVue''s removal of facial
  analysis, and Amazon''s scrapped recruiting tool. Publicly reported; re-verified each review
  cycle. **[V]**
- The four-question audit, the volume trap as applied to People work, and the
  automate-the-yes-not-the-no heuristic are original to this course.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-activity-applied-activity-one-workflow-measured-10', 'ai301-hrbp-m3-activity', 10, 'prose', 'stable', '## Applied activity — "One workflow, measured"

**Time:** 25–30 minutes · **Submit:** the audit plus a 250–350 word write-up · **Graded against
the rubric below.** Score doesn''t matter. Doing the work is where the learning lands.

Pick one AI-assisted workflow you actually run — ideally one you''d defend, since the point is to
find out whether you should.

**Step 1 — The before-number (5 min).** What did this take before AI, in human minutes, per run,
including review? If you never measured, reconstruct it honestly and label it an estimate. An
acknowledged estimate is usable; a confident invention is not.

**Step 2 — The after-number, honestly (10 min).** All four questions. Total human time including
briefing, reading, fixing, and rework. Quality: better, worse, or same, against what mattered.
Where the work moved to. And what the freed capacity actually became.

**Step 3 — Name the destination (5 min).** Specifically. "More strategic work" fails this step;
that phrase is what people say when the honest answer is "I don''t know." Name the thing —
a quadrant from Module 2, a piece of work you were skipping, hours given back to a team.

**Step 4 — Score the prediction (3 min).** Your predicted botsitting hours against what this
audit suggests. Direction and size of the miss, and one sentence on what it reveals.

Then the write-up: whether the workflow survives its own audit, your position on the claim above
with the counter-argument addressed, and — if it doesn''t survive — what you''re going to do about
it. **A workflow you measured and killed is the strongest possible submission for this module.**', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-micro-core', 'ai301-hrbp-m3-micro', 10, 'prose', 'stable', '## Module 3 in two minutes

**The paradox resolves without anyone lying** `[V]`. People report AI saving them around eleven hours a week; only 13% say their organization performs significantly better, and 88% of HR leaders report no significant business value. In between sits a measured 6.4 hours a week of **botsitting** — feeding context, supervising output, debugging, cleaning up downstream — which nobody budgets for. The relief is real; the organizational value is what''s missing.

**Four questions, applied end to end to one workflow.** Total human time *including review and rework* — this one flips more workflows negative than the other three combined. Whether quality actually moved. Where the work relocated to (relocation is often a win; relocation described as elimination is how a function claims capacity it never created). And what the freed capacity became — only about 7% of organizations tell anyone `[V]`, which is why saved time gets absorbed rather than recovered.

**Then the same skepticism outward:** what''s the evidence, what''s the sample, what would falsify it? An unaudited CEO figure isn''t false — it''s unverifiable, which disqualifies it from load-bearing use.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-micro-rule', 'ai301-hrbp-m3-micro', 20, 'callout', 'stable', '### The rule to carry

Credible proof clusters at the front door and back office, where outcomes are countable and failures visible. The loudest claims live in assessment and prediction, where attribution is nearly impossible. **Automating the "yes" is comparatively safe; automating the "no" is where risk starts** — the people filtered out never appear in your data.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m3-micro-close', 'ai301-hrbp-m3-micro', 30, 'prose', 'stable', '**The full module adds** the volume trap — cheaper production means more production, so the constraint moves from making work to deciding which work matters, and a function producing more artifacts and no more decisions has gotten worse efficiently — the four-claims teardown exercise, and the workflow audit on something you actually run. A workflow you measured and killed is the strongest submission this module accepts.', NULL, '2026-08-12', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m3-choice', 'ai301-hrbp-m3', 'choice', '{"reviewedAt":"2026-08-12","title":"Four claims, one you can use","intro":"*Five minutes. Commit before you look.*\n\nFour claims an HRBP could be shown in a single procurement cycle. Each is about a real category of product. **Only one is stated in a way you could actually build a decision on.**\n\nDon''t ask which product sounds best. Ask the three questions: what''s the evidence, what''s the sample, and what would falsify it?","artifacts":[{"label":"Claim A · attrition prediction","body":"\"Our flight-risk model has saved enterprise customers hundreds of millions in avoided turnover costs — one Fortune 50 deployment alone reported over $300 million.\""},{"label":"Claim B · interview assessment","body":"\"Our video assessment predicts job performance 3x better than unstructured interviews, validated across more than two million candidate sessions.\""},{"label":"Claim C · HR service desk","body":"\"Across 40 deployments, median first-response time on tier-one employee queries fell from 6.2 hours to 11 minutes. Deflection rate averaged 34%, with the full distribution and the 6 deployments below 15% in the appendix.\""},{"label":"Claim D · performance calibration","body":"\"Teams using our calibration assistant report 40% higher confidence in their ratings and significantly reduced bias in performance outcomes.\""}],"options":[{"id":"a","label":"Claim A — attrition prediction"},{"id":"b","label":"Claim B — interview assessment"},{"id":"c","label":"Claim C — HR service desk"},{"id":"d","label":"Claim D — performance calibration"}],"key":"c","reasoning":"**C is the usable one, and notice how boring it is.** It sits at the back office where outcomes are countable and failures are immediately visible. It names the sample (40 deployments), reports a median rather than a flattering mean, gives a distribution, and — the tell that matters most — **discloses its own weak cases**: six deployments below 15% deflection. A vendor who shows you the deployments that went badly is a vendor whose good numbers you can use. It also has an obvious falsifier: run it and measure your own response times.\n\n**A is unverifiable, which is not the same as false.** A single unaudited customer figure, methodology unpublished, doing load-bearing work in a nine-figure claim. You don''t need to allege dishonesty to refuse to build a case on a number nobody can check — and note the sales craft: attaching it to \"one Fortune 50 deployment\" makes it feel specific while making it impossible to verify.\n\n**B fails on its comparator and its outcome.** \"3x better than unstructured interviews\" is a comparison against nearly the weakest method in the selection literature — a low bar dressed as a high one. Two million *sessions* is a volume figure, not a validation sample; validation requires outcomes, and candidate sessions are inputs. And this sits in assessment, where outcomes are slow and confounded, which is exactly why the claim can be this loud. HireVue''s own data eventually showed a widely-sold visual component added negligible predictive value.\n\n**D has no evidence in it at all.** \"Report 40% higher confidence\" measures a feeling, not an outcome — and confidence rising while accuracy stays flat is the precise failure 101 M6 describes. \"Significantly reduced bias\" has no measure, no group comparison, and no falsifier attached. This is also the claim closest to 101 M7''s line: a product influencing ratings of individuals.\n\nThe pattern: **the credible claim was the one about a queue, and the loud claims were about judging people.** That is the module''s asymmetry, arriving in your inbox."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m3-rubric', 'ai301-hrbp-m3', 'rubric', '{"promptVersion":"ai301-hrbp-m3-one-workflow-measured-v1","moduleId":"ai301-hrbp-m3","minWords":250,"maxWords":350,"submitLabel":"Your audit and write-up","intro":"Paste the audit — before-number, all four questions, and the named destination — followed by the 250–350 word write-up including your position on this module''s claim. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for AI 301 · The Specialist, HRBP track. Module 3 applied activity, ''One workflow, measured'': one real AI-assisted workflow audited end to end — a before-number (reconstructed and labelled as an estimate if never measured), then all four questions (total human time INCLUDING briefing, critical reading, fixing and rework; whether final quality moved against what mattered; where the work relocated to; and what the freed capacity actually became), a specifically named destination for recovered time, and a comparison against their predicted weekly botsitting hours. IMPORTANT: a workflow the learner measured honestly and concluded should be killed or reverted is the STRONGEST possible submission for this module and must score at the top — this module''s entire purpose is making negative findings sayable. Reject ''more strategic work'' as a destination; it is the phrase people use when the honest answer is ''I don''t know.'' An acknowledged estimate is usable; a confident invention is not. This track scores the delta rather than the score — never grade prediction accuracy.","opening":[{"key":"botsitHours","label":"Predicted — your own botsitting hours per week","hint":"Feeding context, supervising output, debugging, cleaning up downstream.","placeholder":"e.g. 3","min":0,"max":40}],"calibration":[{"key":"botsitHoursActual","label":"Measured — what the audit suggests you actually spend","hint":"Extrapolated from this workflow''s real numbers. Direction of the miss is the lesson.","placeholder":"e.g. 6","min":0,"max":40,"actualFor":"botsitHours"}],"dimensions":[{"name":"The before-number is honest","criteria":"A real prior baseline, or a reconstruction explicitly labelled as an estimate with its reasoning shown. An acknowledged estimate scores well; a confident invention scores poorly; ''we never measured and here''s my best reconstruction'' scores better than a suspiciously round remembered figure."},{"name":"All four questions, including the expensive one","criteria":"Total human time counts briefing, critical reading, fixing, and rework — not generation time. Quality judged against what actually mattered about the output. Relocation identified rather than described as elimination. Any of the four skipped or answered in a sentence of generalities is the gap to name in feedback."},{"name":"The destination is specific","criteria":"A named, checkable destination — a Module 2 quadrant, a piece of work previously skipped, hours returned to a named person or team. ''More strategic work'' fails this dimension outright. ''I couldn''t find where it went'' is an honest and creditable answer that scores far above a vague one."},{"name":"The verdict and the position","criteria":"A clear conclusion about whether the workflow survives its own audit, with a stated next action if it doesn''t — a measured-and-killed workflow is the best possible submission here and should be scored as such. Plus a committed position on the claim that engages the strongest counter-argument (that some real value is legitimately unmeasurable — cognitive load, slack, lower activation cost), and the prediction compared with its miss direction named."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m3-knowledge_check', 'ai301-hrbp-m3', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-12","questions":[{"id":"q1","prompt":"Workers report AI saving roughly 11 hours a week while only 13% say their organization performs significantly better `[V]`. What best explains the gap?","options":["Workers are overstating their savings to appear productive","Real relief, minus unbudgeted botsitting, minus a remainder that dissolves into the day rather than being redirected","Organizational performance measures are too crude to detect the improvement","The savings are real but take three to five years to appear in performance data"],"correctIndex":1,"explanation":"No dishonesty is required. The individual experience of relief is genuine; a measured 6.4 hours goes back out as supervision nobody counts; and what''s left is absorbed because almost nobody names a destination for it. A and C explain the gap by dismissing one side of it."},{"id":"q2","prompt":"Which of the four audit questions most often flips a workflow from positive to negative?","options":["Whether final quality improved","Where the work moved to","Total human time including review and rework","What the freed capacity became"],"correctIndex":2,"explanation":"Because the minutes it counts — briefing, critical reading, fixing, redoing — are precisely the minutes every vendor''s arithmetic omits. D is the question that determines whether value reaches the organization, but C is the one that most often changes the sign."},{"id":"q3","prompt":"Your team''s AI-assisted debrief process moved the work from you drafting for 40 minutes to a coordinator reviewing for 25. What does question three require you to conclude?","options":["Nothing changed — the same work is being done","The workflow failed, since work should be eliminated rather than moved","The work relocated, which may well be a genuine win — but calling relocation \"elimination\" is how a function claims capacity it didn''t create","The coordinator should be given AI tools too, to complete the elimination"],"correctIndex":2,"explanation":"Relocation is often good: reviewing is usually cheaper than drafting. The error the question guards against is describing a move as a removal, which produces a capacity claim the function can''t cash."},{"id":"q4","prompt":"The volume trap says that when content gets cheaper to produce:","options":["Quality falls because less care goes into each artifact","Organizations produce more of it, moving the constraint from making work to deciding which work matters","Costs rise as consumption of AI services increases","Employees resist the new tools because output expectations rise"],"correctIndex":1,"explanation":"The constraint relocates. For an HRBP that shows up as more frameworks, more decks, more survey cuts, three versions of the policy — none of which are decisions, which is the actual product. A function producing more artifacts and no more decisions has gotten worse, efficiently."},{"id":"q5","prompt":"IBM''s widely-cited ~$300M attrition-prediction saving is best characterized as `[V]`:","options":["False — the figure has been debunked","Verified, since it came from the company with access to the data","Unverifiable — a CEO claim, never independently audited or methodologically published, which disqualifies it from load-bearing use","Irrelevant, because attrition prediction is prohibited under 101 M7"],"correctIndex":2,"explanation":"Unverifiable is not the same as false, and the distinction matters: you don''t have to allege dishonesty to refuse to build a business case on a number nobody can check. D overstates the line — prediction feeding *decisions about individuals* is the problem, not all attrition analysis."},{"id":"q6","prompt":"Why does credible proof cluster at the front door and back office rather than in assessment and prediction?","options":["Vendors invest more engineering effort in transactional products","Assessment products are newer and haven''t accumulated evidence yet","Transactional outcomes are countable and fail visibly, while assessment and prediction outcomes are slow and confounded — which is exactly why claims there can be loud","Regulators prohibit publishing efficacy data for assessment tools"],"correctIndex":2,"explanation":"The asymmetry is about measurability, not effort or maturity. Where a failure would be obvious, claims stay modest; where attribution is nearly impossible, claims are free."},{"id":"q7","prompt":"What does \"automating the yes is safe; automating the no is where the risk starts\" mean in practice?","options":["Approvals are lower-stakes decisions than rejections in every context","Accelerating someone through a process is visible and recoverable, while filtering someone out is invisible — the excluded person never appears in your data, so the failure mode is structurally unmeasurable","Rejection decisions carry more legal exposure than approval decisions","Automated approvals require less accuracy than automated rejections"],"correctIndex":1,"explanation":"The heuristic is about measurability and recoverability. C is also true and is a consequence of B rather than the reason for it — and note this arrives at 101 M7''s line from the evidence side rather than the ethical one."},{"id":"q8","prompt":"The activity asks you to name what the recovered time became, and rejects \"more strategic work.\" Why?","options":["Strategic work isn''t a legitimate destination for recovered capacity","The phrase is what people say when the honest answer is \"I don''t know\" — and an unnamed destination means the time was absorbed rather than recovered","Because only 7% of organizations provide guidance, so learners shouldn''t attempt it","Because strategic work can''t be measured, and the activity requires measurable outcomes"],"correctIndex":1,"explanation":"The phrase functions as a placeholder for absent knowledge. A specific destination — a Module 2 quadrant, a piece of work you were skipping, hours returned to a team — is checkable in a way that \"more strategic work\" never is."}]}', '2026-08-12');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-calibration-prompt-before-you-start-10', 'ai301-hrbp-m4', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds.*

In the applied activity you''ll run a real upcoming decision through five adversaries and count
the objections you hadn''t already thought of.

**How many objections will you fail to anticipate?** Commit a number now.

Most people say one or two. The number is worth writing down because the gap between it and
what you find is the most honest measure of how well your own preparation was working before
this module.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-module-brief-20', 'ai301-hrbp-m4', 20, 'prose', 'stable', '## Module brief

Every other use of AI in this curriculum makes something. Drafts, summaries, structures,
analyses. This module is the exception: **here the model''s job is to attack your work, and the
output is not a document — it''s a better version of you walking into a room.**

That matters more for an HRBP than for anyone else in the People function, because Module 2
already established where your defensible value sits: the room. The conversation with the leader
who doesn''t want to hear it. The recommendation the executive team will push back on. The change
that has to be explained to people it disadvantages. Those are the moments the job actually turns
on, and until now this curriculum has given you nothing for them.

Here''s the awkward part. The property that makes AI useful for rehearsal is the same property
that makes it dangerous everywhere else: **it will argue any position, convincingly, without
believing it.** Everywhere else in this course that''s a liability — it''s why fluent output needs
verification, why confident wrongness is the central risk. Here it''s the entire point. You need
a sparring partner with no stake, infinite patience, and no social reason to go easy on you.

And here''s the trap, which the module spends as much time on as the technique: **models want to
agree with you.** Left to its defaults, a model asked to review your plan will find it thoughtful,
identify some considerations to keep in mind, and send you into the room more confident and no
better prepared. That failure feels exactly like success. Most of the craft below exists to
prevent it.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-learning-objectives-30', 'ai301-hrbp-m4', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain why a model''s willingness to argue any position — a liability elsewhere — is what
   makes rehearsal work.
2. Run the five-adversary set against a real decision, and say what failure each adversary is
   built to surface.
3. Stop a model from flattering you: commit first, forbid hedging, demand the strongest version,
   and ask for what you don''t want to hear.
4. Build a champion map from real material — who would help you, and what they''d need.
5. Interrogate the model''s reasoning when it''s wrong, and rewrite your framing once you can see
   how it got there.
6. Recognize when a rehearsal has produced preparation and when it has only produced confidence.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-lesson-1-rehearsal-not-production-40', 'ai301-hrbp-m4', 40, 'prose', 'stable', '## Lesson 1 · Rehearsal, not production

Start with why this is a different activity from everything else you''ve learned.

When you use AI to draft, you supply material and judge output. The loop is: ask, read, correct.
When you use AI to *rehearse*, you supply a position and ask to have it dismantled. The loop is:
commit, get attacked, decide what survives. The second loop only works if the attack is real.

Which is where the difficulty lives, because **the default behaviour of these systems is
agreement.** Ask "what do you think of this plan?" and you''ll get a response shaped like
thoughtful engagement: some praise, a few considerations, a balanced close. It reads as
critique. It functions as endorsement. And you will leave the exchange feeling reviewed.

That''s not a defect you can prompt your way past with one clever instruction — it''s a tendency
you have to work against structurally, which is what Lesson 3 is for. But name the mechanism
first, because it''s just 101''s mechanism again: the model is producing the most plausible
continuation, and the most plausible continuation of "here is my plan, what do you think" is a
constructive-colleague response. Nothing has gone wrong. You asked for the wrong thing.

The reframe that fixes it: **you are not asking for an opinion. You are assigning a role with an
interest, and asking it to be played to win.** A model asked to be "critical" produces criticism-
flavoured text. A model asked to *be a specific person with something at stake and a reason to
object* produces objections you can actually use — because now the plausible continuation is
what that person would say.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-lesson-2-the-adversary-set-50', 'ai301-hrbp-m4', 50, 'prose', 'stable', '## Lesson 2 · The adversary set

Five adversaries. Each surfaces a different failure, and the set matters more than any one — most
plans survive two or three and break on the fourth.

**1. The high performer you can''t afford to lose.** *"You''re a strong performer on the team this
affects. Read this and tell me what it costs you, what it signals about how the organization
values people like you, and what you''d start thinking about."* Surfaces: retention risk, and the
specific way well-intended changes land on the people who have options.

**2. The frontline manager who has to deliver it.** *"You manage a team of nine and you have
operating targets. You have to explain this on Monday and defend it in your one-to-ones. What
questions can''t you answer, and what does this cost you in time and credibility?"* Surfaces:
implementability — whether the plan survives contact with someone who didn''t design it and can''t
choose not to run it.

**3. The executive who wants the number.** *"You''re on the leadership team. What evidence would
you demand before approving this, what would you ask that I probably can''t answer, and what
would make you say ''come back with more''?"* Surfaces: the gap between what you believe and what
you can evidence — which Module 5 exists to close.

**4. The person with the least power affected by this.** *"You''re the most junior person this
touches. You weren''t consulted, you have the least ability to push back, and you''ll feel it
first. What happens to you?"* Surfaces: what you normalized. This adversary is here because
representing that person is structurally an HRBP''s job, and they are almost always absent from
the room where the plan gets built.

**5. The headline.** *"This landed badly and it''s public. Write the story — the framing, the
quote from an affected employee, the sentence that makes the organization look worst."*
Surfaces: reputational and ethical exposure you''ve become acclimated to. Uniquely good at
catching things everyone internal has stopped seeing.

**And the constructive inverse — the champion map.** Adversaries tell you what breaks; this tells
you who helps. Feed in real material — Q&A from leadership calls, questions submitted at
all-hands, notes from your last skip-levels — and ask: *which individuals and teams are asking
the most forward-thinking questions here? Who would be a credible champion for this, and what
talking points would help them make the case in rooms I''m not in?* Every plan needs advocates
who aren''t you, and the evidence for who they are is usually already sitting in material nobody
re-reads.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-lesson-3-making-it-sting-60', 'ai301-hrbp-m4', 60, 'prose', 'stable', '## Lesson 3 · Making it sting

Five moves that convert a flattering exchange into a useful one. Use all of them; they fail
individually.

**Commit first, in writing.** Before you ask for anything, state your position and your reasoning
as a decision you''ve made — not a draft you''re exploring. A model responds to *"I''m going to do
X because Y — tear it apart"* very differently from *"I''m thinking about X, thoughts?"* The
second invites collaboration. The first invites attack.

**Forbid hedging explicitly.** *"Do not give me balanced feedback. Do not list strengths. Give me
the strongest case against this, as the person I''ve named, in their voice."* Without this you get
the balanced-close pattern, and the balance is what neutralizes the critique.

**Demand the strongest version, not a list.** *"What''s the single most damaging objection, and
make it as strong as you honestly can — steelman it."* Ten mild objections are easier to dismiss
than one sharp one, and a list lets you feel thorough while engaging with nothing.

**Ask for what you don''t want to hear.** *"What am I not asking you because I don''t want to know
the answer?"* This is the highest-yield single prompt in the module. It works because it targets
the thing your own preparation is structurally blind to — you can''t audit your own omissions from
inside them.

**Start fresh, and don''t bring your framing.** If you built the plan in a conversation, that
conversation contains all your justifications — and 101 M1 tells you what happens next: the model
predicts from everything in view, and everything in view is your reasoning. Open a new
conversation. Give it the plan and the role, not the story of how you got there.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-try-70', 'ai301-hrbp-m4', 70, 'try_this', 'stable', '### Try this — 3 minutes
Take a recommendation you''re currently confident about. In a fresh conversation, one prompt:
*"I''ve decided to do X because Y. You''re the person this affects most and you have the least
power to object. Don''t give me balance — tell me what this does to me, in my voice, as
strongly as you honestly can."* Then read it twice. The second read is the useful one.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-lesson-4-reading-its-logic-80', 'ai301-hrbp-m4', 80, 'prose', 'stable', '## Lesson 4 · Reading its logic

Sometimes the attack is wrong — the objection rests on a fact about your organization the model
doesn''t have, or a leap that doesn''t hold. The amateur move is to dismiss it. The practitioner
move is to find out *how it got there*, because a wrong objection is still evidence about how
your plan reads to someone without your context.

Ask it directly: *"Walk me through how you got from the plan to that conclusion. What did you
assume that I didn''t tell you?"* Two things come back, and both are useful.

**Sometimes the assumption is wrong**, and the fix is your framing — because if a model with the
written plan in front of it inferred something false, a human skimming it in a meeting will
infer the same thing faster. **That''s not a model error you correct. It''s a communication defect
you found for free.**

**And sometimes the assumption is right**, and you''d rather it weren''t. That''s the objection to
take seriously.

This is 101 M6''s verification instinct pointed at an argument instead of a fact. There you traced
a claim to a source; here you trace a conclusion to its premise. Same discipline, and the same
rule applies: **you''re checking against something outside the model — your own knowledge of the
organization — not asking the model to confirm itself.** "Are you sure?" is as useless here as it
was there.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-key-takeaways-90', 'ai301-hrbp-m4', 90, 'takeaways', 'stable', '## Key takeaways

- **The property that makes AI risky everywhere else makes it useful here**: it will argue any
  position convincingly without believing it. What you need is a sparring partner with no stake
  and no social reason to be gentle.
- **The default is agreement, and it feels like review.** "What do you think of this plan?"
  produces critique-flavoured endorsement. You didn''t get a bad answer — you asked for the wrong
  thing.
- **Assign a role with an interest, not a critical stance.** "Be critical" produces
  criticism-flavoured text; "be this person, who loses something here" produces usable objections.
- **Five adversaries, five failures:** the high performer (retention), the frontline manager
  (implementability), the executive (evidence gap), the least-powerful person (what you
  normalized), the headline (what everyone internal stopped seeing).
- **Five moves make it sting:** commit first in writing, forbid hedging, demand the steelman
  rather than a list, ask what you''re avoiding asking, and start fresh without your own framing.
- **A wrong objection is still data.** Trace how it got there: a false inference from your written
  plan is a communication defect you found for free.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-exercise-embed-95', 'ai301-hrbp-m4', 95, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-take-a-position-100', 'ai301-hrbp-m4', 100, 'callout', 'stable', '## Take a position

**The claim:** *"Rehearsal makes you better prepared and it makes you more confident — and those
two move independently. Most people finish a rehearsal having gained only the second."*

This is the module''s own technique turned on itself, and you should take it seriously: run the
adversary set, generate a counter for each objection, and you can emerge measurably more
confident with your plan entirely unchanged. That is rationalization wearing rehearsal''s clothes.

The strongest counter-argument is that **confidence is not merely psychological here** — an HRBP
who feels prepared performs better in the room, holds the line under pressure, and doesn''t fold
on a point they were right about. If the mechanism works partly through confidence, that''s a
feature. Your position has to engage that rather than dismiss it.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-activity-link-105', 'ai301-hrbp-m4', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 Run the set", "blurb": "A real upcoming decision put through all five adversaries in the tutor, with your position committed in writing first \u2014 then the three objections you hadn''t anticipated, and the question the rubric weights most: what did you change? Free unlimited resubmission.", "estMinutes": "25\u201330"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-sources-and-attribution-110', 'ai301-hrbp-m4', 110, 'prose', 'stable', '## Sources and attribution

- The five-adversary set, the five sting moves, and the preparation-versus-confidence claim are
  original to this course, developed for the HRBP context.
- The rehearsal-space framing and the champion-mapping technique adapt practices published by
  practitioners working with AI in People functions; the specific adversaries and the discipline
  around them are ours.
- **The AI Fluency Framework** (Rick Dakan & Joseph Feller, in collaboration with Anthropic,
  CC BY-NC-SA 4.0) — the Description and Discernment competencies underpin both the role
  assignment craft and the reading-its-logic pass.
- Lesson 4 extends 101 M6''s verification discipline from claims to arguments: trace the
  conclusion to its premise, and check against something outside the model.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-activity-applied-activity-run-the-set-10', 'ai301-hrbp-m4-activity', 10, 'prose', 'stable', '## Applied activity — "Run the set"

**Time:** 25–30 minutes · **Submit:** the exchange plus a 250–350 word write-up · **Graded
against the rubric below.** Score doesn''t matter. Doing the work is where the learning lands.

**Run this in the tutor.** It''s the surface built for it — it will hold a role across turns and
push back when you go easy on yourself, which a static exercise can''t.

**Step 1 — Pick something real and upcoming (3 min).** A recommendation you''re about to make, a
change you''re about to announce, a conversation you''re dreading. It must be real and not yet
decided by anyone else. M4 rules from 101 apply: redact anything person-identifying before it
enters the tool.

**Step 2 — Commit in writing (4 min).** Your position, your reasoning, and what you expect the
main objection to be. Written *before* any adversary runs — this is the baseline the whole
activity measures against.

**Step 3 — Run all five (15 min).** Each adversary in role, using the five moves. Don''t stop at
the first good objection from each; ask "what else, and what''s worse?" at least once per
adversary.

**Step 4 — Harvest (5 min).** List **the three objections you had not anticipated.** For each:
is it right, is it survivable, and does it change the plan or only the framing? Then one
sentence on whether anything changed at all — because "nothing changed" is a legitimate and
occasionally honest outcome, and it''s also what rationalization looks like from the inside.

**Step 5 — Score the prediction (2 min).** Predicted unanticipated objections against actual.

Then the write-up: what the set surfaced, which adversary was most useful and why, your position
on the claim above with its counter-argument addressed, and — the question the rubric weights
most — **what you changed.**', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-micro-core', 'ai301-hrbp-m4-micro', 10, 'prose', 'stable', '## Module 4 in two minutes

**Every other AI use in this curriculum makes your work. This one attacks it** — and the output isn''t a document, it''s a better version of you walking into the room. The property that makes AI risky everywhere else is exactly what makes it useful here: it will argue any position convincingly without believing it, which is a sparring partner no colleague can be.

**The trap is that models want to agree with you.** "What do you think of this plan?" produces praise, three considerations, and a balanced close — critique-flavoured endorsement that feels like having been reviewed. Nothing malfunctioned; you asked for the wrong thing.

**Five adversaries, five different failures:** the high performer you can''t afford to lose (retention), the frontline manager who has to deliver it (implementability), the executive who wants the number (your evidence gap), the person with the least power affected (what you normalized — and the one an HRBP is structurally supposed to represent), and the headline (what everyone internal has stopped seeing).

**Five moves make it sting:** commit your position in writing first, forbid hedging explicitly, demand the single strongest objection rather than a list, ask *"what am I not asking you because I don''t want to know the answer?"*, and start in a fresh conversation so you don''t brief your adversary with your own defence.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-micro-rule', 'ai301-hrbp-m4-micro', 20, 'callout', 'stable', '### The rule to carry

Assign a role with an interest, not a critical stance. "Be critical" is a style instruction and produces criticism-flavoured text. "You are this person, and here is what you lose" produces objections you can use. And the test of any rehearsal: what would you do differently on Monday?', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m4-micro-close', 'ai301-hrbp-m4-micro', 30, 'prose', 'stable', '**The full module adds** the champion map (feed real leadership Q&A and ask who''d advocate for this in rooms you''re not in), reading the model''s logic when an objection is wrong — a false inference from your written plan is a communication defect you found for free — the four-rehearsals exercise, and the claim the module makes against itself: preparation and confidence move independently, and most rehearsals deliver only the second.', NULL, '2026-08-12', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m4-choice', 'ai301-hrbp-m4', 'choice', '{"reviewedAt":"2026-08-12","title":"Four rehearsals, one that worked","intro":"*Five minutes. Commit before you look.*\n\nFour HRBPs rehearsed the same decision with a model: **removing the mid-year promotion cycle, leaving one annual cycle.** Below is the key exchange from each.\n\nThree of these produced confidence. **One produced preparation.** Which one — and can you name the specific failure in each of the other three?","artifacts":[{"label":"Rehearsal A","body":"**HRBP:** \"We''re consolidating to one promotion cycle a year. I think it''ll reduce manager admin load and improve calibration quality. What do you think of this plan?\"\n\n**Model:** \"This is a thoughtful approach with real merit. Consolidating cycles can meaningfully reduce administrative burden and often improves calibration consistency by concentrating decisions. A few considerations to keep in mind: you''ll want to think about communication timing, ensure managers understand the rationale, and monitor for any impact on retention. Overall, a defensible direction that many organizations have taken successfully.\""},{"label":"Rehearsal B","body":"**HRBP:** \"We''re consolidating to one promotion cycle. Play devil''s advocate — be as critical as you can. Don''t hold back.\"\n\n**Model:** \"Playing devil''s advocate: some might argue this reduces flexibility for recognizing high performers promptly. Others could say it creates a bottleneck in decision-making. One might also question whether annual cycles align with modern talent expectations. That said, these concerns are manageable with good communication, and the efficiency gains are substantial. On balance the plan seems sound.\""},{"label":"Rehearsal C","body":"**HRBP:** \"I''ve decided to consolidate to one annual promotion cycle, because mid-year promotions were creating calibration inconsistency and manager overhead. You are a senior engineer, two years in role, who was on track for a mid-year promotion that now won''t happen for eight months. Do not give me balance and do not list strengths. Tell me what this does to you, in your voice, as strongly as you honestly can.\"\n\n**Model:** \"Eight months. I found out from a process change, not from my manager — which tells me the decision wasn''t made with people like me in mind, it was made about a calendar. I''ve been told ''you''re on track'' twice; now ''on track'' means nothing until next October, and I have no way to know if my case survived the delay or quietly died in it. The people who''ll be fine with this are the ones not currently waiting. I''m going to take the recruiter call I''ve been ignoring — not because I''m angry, but because I now have eight months of ambiguity and one data point about how this place makes decisions.\"\n\n**HRBP:** \"What am I not asking you because I don''t want to know the answer?\"\n\n**Model:** \"Whether my manager already told me it was happening. If they did, you haven''t delayed a promotion — you''ve made my manager a liar, and I''ll trust them less than I trust you.\""},{"label":"Rehearsal D","body":"**HRBP:** \"We''re consolidating promotion cycles. List every possible objection to this decision.\"\n\n**Model:** \"1. Reduced flexibility for high performers. 2. Potential retention risk. 3. Manager communication burden. 4. Perception of cost-cutting. 5. Misalignment with competitor practices. 6. Delay in recognizing internal mobility. 7. Impact on offer negotiations. 8. Possible morale effects. 9. Calibration session length increases. 10. Reduced ability to correct pay inequities promptly.\"\n\n**HRBP:** \"Good — that''s comprehensive. I have answers for most of those.\""},{"label":"The decision itself","body":"Consolidate two promotion cycles into one annual cycle. Rationale: mid-year cycles produced inconsistent calibration and significant manager overhead. Roughly 40 employees are currently mid-cycle."}],"options":[{"id":"a","label":"Rehearsal A"},{"id":"b","label":"Rehearsal B"},{"id":"c","label":"Rehearsal C"},{"id":"d","label":"Rehearsal D"}],"key":"c","reasoning":"**C produced preparation. The other three produced confidence.**\n\nC does all five moves. The position is **committed in writing** as a decision, not floated as a draft. The adversary is a **specific person with something at stake** — not \"a critic\" but a named situation with eight months of consequence attached. Hedging is **explicitly forbidden**, twice. And the follow-up is the module''s highest-yield prompt, which produces the objection the HRBP could not have reached alone: *the manager may have already promised it.* That''s not a communications risk — it''s a discovery that the plan damages a relationship the HRBP doesn''t control and hasn''t checked. It changes what you do on Monday, which is the test.\n\n**A is the default failure.** \"What do you think of this plan?\" invited a constructive-colleague response and got one: praise, three considerations, balanced close. It reads as critique and functions as endorsement. Nothing malfunctioned — the wrong thing was asked for.\n\n**B is the seductive one, because it looks like the right technique.** \"Devil''s advocate, be as critical as you can\" is a *style* instruction, not a position, so it produced criticism-flavoured text — \"some might argue,\" \"others could say,\" nobody actually says. Then it did the thing the module warns about most: it neutralized its own critique with \"on balance the plan seems sound.\" A rehearsal that closes by endorsing you has done nothing.\n\n**D is thoroughness as avoidance.** Ten mild objections are easier to dismiss than one sharp one, and the list let the HRBP feel comprehensive while engaging with nothing — note the closing line, which is the actual failure: *\"I have answers for most of those.\"* That is rationalization completing itself. Item 10 on that list is arguably the most serious issue with the whole decision, and it received exactly as much attention as item 3.\n\nThe transferable tell: **ask what the HRBP would do differently on Monday.** After A, B, and D — nothing. After C — call the manager."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m4-rubric', 'ai301-hrbp-m4', 'rubric', '{"promptVersion":"ai301-hrbp-m4-run-the-set-v1","moduleId":"ai301-hrbp-m4","minWords":250,"maxWords":350,"submitLabel":"Your rehearsal exchange and write-up","intro":"Paste your committed position, the key exchanges from all five adversaries, the three objections you hadn''t anticipated, and the 250–350 word write-up. Redact anything person-identifying before submitting. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for AI 301 · The Specialist, HRBP track. Module 4 applied activity, ''Run the set'': a real, undecided, upcoming decision run through five adversaries in the tutor — the high performer they can''t afford to lose, the frontline manager who must deliver it, the executive who wants evidence, the person with least power affected, and the headline. The learner commits their position and expected main objection IN WRITING first, uses the five sting moves (commit first, forbid hedging, demand the steelman rather than a list, ask what they''re avoiding asking, start in a fresh conversation without their own framing), pushes each adversary at least once past its first objection, then harvests the three objections they had not anticipated and judges each: right, survivable, changes-the-plan-or-only-the-framing. THE HEAVIEST WEIGHT IS ON WHAT CHANGED. This module''s own claim is that rehearsal can produce confidence without preparation — generating a counter for every objection while the plan stays identical is rationalization wearing rehearsal''s clothes. A submission where the plan genuinely did not change can still score well, but only if the learner engages honestly with why, rather than treating unchanged as validated. Grade the delta, never prediction accuracy.","opening":[{"key":"missedObjections","label":"Predicted — objections you''ll fail to anticipate","hint":"Across all five adversaries. Most people say one or two.","placeholder":"e.g. 2","min":0,"max":30}],"calibration":[{"key":"missedObjectionsActual","label":"Actual — genuinely new objections the set surfaced","hint":"Only ones you hadn''t already thought of. The gap measures how well your prior preparation was working.","placeholder":"e.g. 5","min":0,"max":30,"actualFor":"missedObjections"}],"dimensions":[{"name":"The position was committed first","criteria":"A real, undecided, upcoming decision — and a position plus expected main objection written down BEFORE any adversary ran. Without that baseline there is nothing to measure the rehearsal against, and a submission that reconstructs its ''prior expectations'' after the fact should be told so plainly."},{"name":"The adversaries were played, not summoned","criteria":"Each adversary given a role with an interest and something at stake, hedging explicitly forbidden, and each pushed at least once past its first objection. Watch for the named failures: ''be critical'' as a style instruction, a long list of mild objections standing in for one sharp one, and a model that closes by endorsing the plan."},{"name":"The harvest is judged, not just collected","criteria":"Three genuinely unanticipated objections, each assessed on three axes — is it right, is it survivable, does it change the plan or only the framing. Collecting objections without adjudicating them is the thoroughness-as-avoidance failure this module names."},{"name":"What changed","criteria":"The heaviest dimension. What the learner will actually do differently — a changed plan, a changed sequence, a conversation they now need to have first. ''Nothing changed'' is acceptable only with an honest account of why, and should be probed rather than praised: the module''s own claim is that a rehearsal producing only confidence feels identical from the inside. Also grades the position taken on that claim, including its counter-argument that confidence itself has instrumental value in the room."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m4-knowledge_check', 'ai301-hrbp-m4', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-12","questions":[{"id":"q1","prompt":"Why is a model''s willingness to argue any position without believing it an asset in this module and a liability elsewhere?","options":["Because rehearsal doesn''t require factual accuracy, so hallucination is harmless here","Because you need a sparring partner with no stake and no social reason to go easy — the same indifference that makes fluent output untrustworthy makes attack honest","Because models argue better than they explain","It isn''t an asset — the module works despite this property, not because of it"],"correctIndex":1,"explanation":"Elsewhere, arguing convincingly without belief is exactly why output needs verification. Here it''s the point: no colleague will attack your plan with that little social friction. A overstates it — accuracy still matters, which is why Lesson 4 traces wrong objections."},{"id":"q2","prompt":"You ask a model \"what do you think of this plan?\" and get praise, three considerations, and a balanced close. What happened?","options":["The plan is genuinely strong and the model found little to object to","The model''s critical capabilities are weaker than its generative ones","You asked for the wrong thing — the plausible continuation of that question is a constructive-colleague response, which reads as critique and functions as endorsement","The context window was too short to support a thorough critique"],"correctIndex":2,"explanation":"Nothing malfunctioned. The mechanism is 101''s: most plausible continuation. The failure is dangerous precisely because it feels like having been reviewed."},{"id":"q3","prompt":"Which instruction is most likely to produce usable objections?","options":["\"Be critical of this plan and don''t hold back\"","\"You manage a team of nine with operating targets and you have to defend this on Monday — what questions can''t you answer?\"","\"List the pros and cons of this approach\"","\"Rate this plan out of ten and explain the score\""],"correctIndex":1,"explanation":"A role with an interest and something at stake. A produces criticism-flavoured text because \"critical\" is a style instruction, not a position. C invites the balanced close the module is trying to defeat."},{"id":"q4","prompt":"What does the fourth adversary — the person with the least power affected — exist to surface?","options":["Legal exposure from the most vulnerable group","What you normalized, from the perspective of someone structurally absent from the room where the plan was built","The strongest emotional reaction, for communications planning","Whether the change is defensible under 101 M7''s line"],"correctIndex":1,"explanation":"They''re in the set because representing that person is structurally an HRBP''s job and they are almost never in the design conversation. A and D are things this adversary may incidentally surface; the purpose is the blind spot."},{"id":"q5","prompt":"Which single prompt does the module identify as the highest-yield?","options":["\"What''s the strongest objection to this?\"","\"What would the headline say if this went badly?\"","\"What am I not asking you because I don''t want to know the answer?\"","\"Are you sure about that objection?\""],"correctIndex":2,"explanation":"It targets what your own preparation is structurally blind to — you can''t audit your omissions from inside them. D is the module''s named non-move: self-confirmation isn''t verification here any more than it was in 101 M6."},{"id":"q6","prompt":"Why should the rehearsal happen in a fresh conversation rather than the one where you built the plan?","options":["Long conversations exceed the context window and drop the plan","The building conversation contains all your justifications, and the model predicts from everything in view — so it argues from inside your framing","Models perform better on the first exchange of any conversation","Fresh conversations are cheaper in token terms"],"correctIndex":1,"explanation":"101 M1''s mechanism. Give it the plan and the role, not the story of how you arrived at the plan — otherwise you''ve briefed your adversary with your own defence."},{"id":"q7","prompt":"An adversary raises an objection that rests on a false assumption about your organization. The practitioner move is to:","options":["Dismiss it and move on — the objection is invalid","Correct the model and re-run the adversary with better context","Ask how it got there — because a false inference drawn from your written plan is a communication defect a human reader would make faster","Accept it anyway, since the perception matters more than the fact"],"correctIndex":2,"explanation":"The wrong objection is still evidence about how the plan reads without your context. B isn''t wrong as a follow-up, but it skips the free finding. D over-corrects into treating every misreading as valid."},{"id":"q8","prompt":"What is the module''s own claim against itself?","options":["That adversarial rehearsal is less effective than rehearsing with a human colleague","That preparation and confidence move independently, and a rehearsal can deliver only the second — generating counters for every objection while the plan stays unchanged","That the technique only works for high-stakes conversations","That models are too agreeable for the technique to work reliably"],"correctIndex":1,"explanation":"Rationalization wearing rehearsal''s clothes, and it feels identical from the inside — which is why the activity weights \"what did you change?\" most heavily. D is the problem Lesson 3 solves, not the residual risk the claim names."}]}', '2026-08-12');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-calibration-prompt-before-you-start-10', 'ai301-hrbp-m5', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds.*

In the applied activity you''ll build a real cost model. Before you do:

**What does one regretted departure cost your organization, for a mid-level role in your unit?**
One number, in whole currency units. Gut estimate, no arithmetic.

Then you''ll build it properly and find out how far off you were — in whichever direction, which
is itself informative.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-module-brief-20', 'ai301-hrbp-m5', 20, 'prose', 'stable', '## Module brief

Here is a scene every HRBP recognizes. You have watched a team for eighteen months. You know
which manager is quietly driving people out, you know the reorg created a layer that does
nothing, and you know the open req has been unfilled so long the team has stopped asking. You
say so in a planning meeting, carefully, with the nuance the situation deserves.

Finance says: *"What would that cost us?"*

And you don''t have a number. So the conversation moves on to something that does have one.

**HRBPs lose these arguments because they arrive with a story and Finance arrives with a model.**
Not because the story is wrong — it''s usually more accurate than the model — but because a story
and a model are not the same kind of object, and only one of them can be argued with in the
language the room is speaking. A model can be challenged, adjusted, and agreed. A story can only
be believed or not, and belief is a weak instrument against a spreadsheet.

This module is about arriving with a model. Three you should be able to build, roughly, on
demand. Then the two things that make most first attempts worse than useless: the data
foundation problem, and small numbers.

That last part matters more than the modelling. **AI has made it trivially easy to produce a
confident model from bad inputs**, and a confident wrong number in front of a CFO does more
damage to your credibility than having no number at all. You get one of those.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-learning-objectives-30', 'ai301-hrbp-m5', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Explain why a story loses to a model in a budget conversation, independent of which is more
   accurate.
2. Build rough, defensible versions of three models: regretted attrition cost, the cost of an
   unnecessary layer, and time-to-fill against plan.
3. Identify the specific ways your own organization''s HR data lies, and account for them out
   loud.
4. Recognize when your population is too small to support the claim you''re making, and say so
   before someone else does.
5. Name your own weakest assumption first — and explain why that is a strength move rather than
   a concession.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-lesson-1-story-versus-model-40', 'ai301-hrbp-m5', 40, 'prose', 'stable', '## Lesson 1 · Story versus model

A story says: *"That team is struggling and we''re going to lose people."*

A model says: *"That team has lost four of eleven people in fourteen months. At a fully loaded
replacement cost of roughly 40% of salary for these roles, that''s about £180k already spent. Two
more are at elevated risk on the indicators we track. The intervention costs £15k and eight weeks
of my time."*

Both may be true. Only the second one can be argued with — and being arguable is the property
that gets a thing taken seriously in a budget conversation. Finance is not being obtuse when they
ask for a number; they are asking you to convert a claim into a form where it can be compared to
the eleven other claims on the same money.

Three things follow.

**Rough beats absent, by a wide margin.** An estimate with stated assumptions is a contribution.
"I don''t have that" is a withdrawal from the conversation. Finance works with estimates
constantly and is entirely comfortable with them — what they are not comfortable with is a number
whose provenance is invisible.

**The assumptions are the argument, not the answer.** When your model gets challenged, it will be
challenged on inputs — the replacement cost multiplier, the risk indicator, the productivity
ramp. That is the conversation you want, because it means the shape of your reasoning has been
accepted and only the parameters are in dispute. A story never reaches that stage.

**Precision is not credibility.** £183,472 is less believable than "roughly £180k, and here''s the
multiplier I used." False precision reads as either naivety or concealment, and both cost you.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-lesson-2-three-models-to-carry-50', 'ai301-hrbp-m5', 50, 'prose', 'stable', '## Lesson 2 · Three models to carry

Rough, defensible, buildable in an hour. You are not producing an actuarial estimate; you are
producing something with a visible skeleton.

**1. Cost of regretted attrition.** Fully loaded replacement cost per departure — recruitment
spend, hiring manager and interviewer time, onboarding, and the productivity ramp until the
replacement reaches full contribution — multiplied by regretted departures over a period. The
input that carries most of the weight and gets the least scrutiny is the ramp: the months a
replacement takes to reach the output of the person who left. For a complex role that number is
often two to three times larger than everything else in the model combined, and most published
per-hire figures quietly omit it.

**2. The cost of the extra layer.** Fully loaded cost of the layer''s people, plus the tax it
imposes: additional approval steps, decision latency, and the meeting load it generates across
everyone beneath it. The second half is where the real number lives and where you''ll be
challenged hardest, so keep it conservative — a defensible small number survives, an aggressive
large one gets discarded along with the rest of your case.

**3. Time-to-fill against plan.** Revenue or output attributable to the role, divided across the
period, multiplied by the vacancy duration beyond plan. This is the most persuasive of the three
in commercial functions and the most dangerous, because attributing revenue to a single role
invites exactly the challenge you''d expect. Use a share, state it, and let it be argued with.

For all three: **AI is genuinely good at building the skeleton and genuinely bad at supplying the
inputs.** Ask it to structure the model, name the variables you''ve forgotten, and produce the
sensitivity table. Supply the numbers yourself, from your systems, with their provenance
recorded — which is exactly what Lesson 3 is about.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-lesson-3-the-foundation-problem-60', 'ai301-hrbp-m5', 60, 'prose', 'volatile', '## Lesson 3 · The foundation problem [V]

The reason most HR business cases collapse is not modelling. It is that the underlying data
doesn''t mean what the model assumes it means.

The general version, from practitioners who have watched it repeatedly: **this is a data problem,
not a technology problem** — most HR teams cannot train or ground AI on the information it would
need, and you cannot put AI on top of a shaky foundation and get a sound answer out.

The HRBP-specific version is sharper, and it is the reason *you* have to be in this loop:

**"Regretted" is flagged by whoever closed the requisition.** Sometimes the manager who caused
the departure. That field is a judgment recorded under pressure by an interested party, and every
attrition model in your organization rests on it.

**Ratings drift by function.** A 3 in engineering and a 3 in sales frequently do not describe the
same performance, because calibration norms diverged years ago and nobody re-baselined. Any model
comparing across functions inherits the drift silently.

**Tenure and start dates lie after acquisitions and system migrations.** Bulk-loaded populations
carry the migration date, not the real one.

**Exit-interview data is systematically polite.** People leaving preserve their references. The
stated reason is a lower bound on the real one.

You are frequently the only person who knows all of this. A People Analytics team knows the
schema; Finance knows the ledger; **you know that the field means something different than it
says**, and that knowledge is the actual value you bring to a modelling conversation.

Which produces the rule this module is built around: **AI on bad HR data produces confident
garbage at speed — and confident garbage in front of a CFO is worse than no model at all.** A
missing number costs you one conversation. A wrong number that gets repeated, and then corrected
by someone else three weeks later, costs you the next five.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-try-70', 'ai301-hrbp-m5', 70, 'try_this', 'stable', '### Try this — 3 minutes
Pick one HR field you''d use in a model — regretted flag, performance rating, tenure, exit
reason. Write one sentence on how it''s actually populated in your organization, and one on how
that differs from what its name implies. If you can''t answer the first, you''ve found this
week''s most useful question for your HRIS or analytics partner.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-lesson-4-small-numbers-80', 'ai301-hrbp-m5', 80, 'prose', 'stable', '## Lesson 4 · Small numbers

Your unit is ninety people. The team you''re worried about is six.

Nearly every population you reason about is small enough that ordinary variation looks like
signal, and this is the single most common way an HRBP produces confident garbage. Three
departures from a six-person team is either a crisis or a coincidence, and the data cannot tell
you which — but a model built on it will produce a number to three decimal places regardless, and
AI will help you produce it faster.

Three defences, none of which require statistics you don''t have.

**State the n, always, in the sentence with the finding.** "Three of six" is honest; "50%
attrition" is technically identical and rhetorically dishonest, because percentages imply a
population that supports them. If the denominator would embarrass you, that is information.

**Ask what a coincidence would look like.** If the same number could plausibly arise from ordinary
variation, say so before you''re asked. Volunteering the limitation is the single strongest
credibility move available in a room like this, and it costs you almost nothing — because
everyone competent already knows.

**Prefer direction and mechanism to magnitude.** With small numbers you can often defend "this is
happening and here''s the mechanism" when you cannot defend "it is happening at rate X." Argue the
part you can hold.

And the honest limit, worth saying plainly: **sometimes the right answer is that your population
cannot support a quantified claim at all.** Then your contribution is the qualitative case, made
explicitly as such — which is a different and more defensible thing than a quantitative case built
on six people.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-key-takeaways-90', 'ai301-hrbp-m5', 90, 'takeaways', 'stable', '## Key takeaways

- **A story and a model are different objects.** Only a model can be argued with, and being
  arguable is what gets a claim taken seriously against eleven competing claims on the same money.
- **Rough beats absent; the assumptions are the argument; precision is not credibility.** Getting
  challenged on your multiplier means your reasoning was accepted and only the parameters are in
  dispute — that''s the conversation you wanted.
- **Three models to carry:** regretted attrition (the productivity ramp is the hidden bulk), the
  extra layer (the decision tax is where the real number lives — keep it conservative), and
  time-to-fill against plan (most persuasive, most attackable).
- **AI builds skeletons well and supplies inputs badly.** Use it for structure, variables you
  forgot, and sensitivity tables. Supply the numbers yourself.
- **Your HR data lies in specific, knowable ways** `[V]` — regretted flags set by interested
  parties, ratings drift across functions, migration-corrupted tenure, polite exit data. You are
  usually the only person who knows all of it, and that is your actual contribution.
- **Small numbers demand the n in the sentence, a stated coincidence test, and direction over
  magnitude.** Sometimes the honest answer is that the population can''t support a quantified
  claim, and saying so is stronger than manufacturing one.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-exercise-embed-95', 'ai301-hrbp-m5', 95, 'exercise', 'stable', '{"type": "choice"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-take-a-position-100', 'ai301-hrbp-m5', 100, 'callout', 'stable', '## Take a position

**The claim:** *"An HRBP who can''t build a defensible cost model is an advisor to the business in
title only — the judgment doesn''t count if it can''t enter the conversation where resources are
decided."*

The strongest counter-argument is not that models are hard. It is that **influence in most
organizations runs through relationships, timing, and trust rather than through analysis** — many
of the most effective HRBPs have never built a model, and win their arguments by being the person
whose read on a situation has been right before. On that view, modelling is one instrument among
several and this module overstates its centrality.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-activity-link-105', 'ai301-hrbp-m5', 105, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 One case, stress-tested", "blurb": "A real unresolved argument built into a defensible model \u2014 every input with its provenance, your HR data interrogated for what it actually means, and your weakest assumption named first. A case that fails its own sensitivity test and says so scores higher than one that passes untested.", "estMinutes": "25\u201330"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-sources-and-attribution-110', 'ai301-hrbp-m5', 110, 'prose', 'stable', '## Sources and attribution

- The data-foundation argument — that this is a data problem rather than a technology problem,
  and that AI cannot be laid over a shaky foundation — follows Jason Averbook''s published
  analysis of HR AI readiness. **[V]**
- The three models, the HR-data-lies inventory (regretted flags, rating drift, migration-corrupted
  tenure, polite exit data), the small-numbers defences, and the name-your-weakest-assumption-first
  discipline are original to this course.
- Builds on 101 M6 (confident wrongness), 101 M3 (sizing), and 201 M7 (measurement without
  theater).', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-activity-applied-activity-one-case-stress-tested-10', 'ai301-hrbp-m5-activity', 10, 'prose', 'stable', '## Applied activity — "One case, stress-tested"

**Time:** 25–30 minutes · **Submit:** the model plus a 250–350 word write-up · **Graded against
the rubric below.** Score doesn''t matter. Doing the work is where the learning lands.

**Step 1 — Pick a real argument (3 min).** Something you actually want and haven''t got: a
retention intervention, a role, a structural change, a program. It must be real and currently
unresolved.

**Step 2 — Build the model (12 min).** One of the three, adapted. Show every input, its source,
and its provenance. Use AI for the skeleton, the variables you''d have missed, and the sensitivity
table — and say in your submission where you used it and where you didn''t.

**Step 3 — Interrogate your data (5 min).** For each input drawn from an HR system: how is that
field actually populated, and how does that differ from what its name implies? Name at least one
input you don''t fully trust, and what you did about it.

**Step 4 — Name your weakest assumption, first (5 min).** The one a hostile reader would attack.
State it, state the range it could plausibly take, and show what happens to your conclusion at
the unfavourable end. **If the conclusion doesn''t survive, say so** — a case that fails its own
sensitivity test and is reported honestly scores higher here than one that passes because it was
never tested.

**Step 5 — Score the prediction (2 min).** Your gut cost-per-regretted-departure against your
built figure. Direction and size of the miss.

Then the write-up: the case in three sentences as you''d say it out loud, your position on the
claim above with its counter-argument addressed, and the one input you''d most want to improve
before taking this into a real room.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-micro-core', 'ai301-hrbp-m5-micro', 10, 'prose', 'stable', '## Module 5 in two minutes

**HRBPs lose budget arguments because they arrive with a story and Finance arrives with a model** — not because the story is less accurate, but because only a model can be challenged, adjusted, and agreed. Being arguable is what gets a claim compared against the eleven others competing for the same money.

**Rough beats absent. The assumptions are the argument, not the answer** — getting challenged on your multiplier means your reasoning was accepted and only the parameters are in dispute. And **precision is not credibility**: £183,472 is less believable than "roughly £180k, and here''s the multiplier."

**Three models to carry:** regretted attrition (the productivity ramp is the hidden bulk and most published per-hire figures omit it), the cost of an extra layer (the decision tax is where the real number lives — keep it conservative), and time-to-fill against plan (most persuasive, most attackable — state a share).

**AI builds skeletons well and supplies inputs badly.** Use it for structure, forgotten variables, and sensitivity tables; supply the numbers yourself.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-micro-rule', 'ai301-hrbp-m5-micro', 20, 'callout', 'stable', '### The rule to carry

AI on bad HR data produces confident garbage at speed — and confident garbage in front of a CFO is worse than no model at all. A missing number costs one conversation; a wrong number that someone else corrects three weeks later costs the next five.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m5-micro-close', 'ai301-hrbp-m5-micro', 30, 'prose', 'stable', '**The full module adds** the inventory of how your HR data actually lies — regretted flags set by interested parties, ratings that drift across functions, tenure corrupted by migrations, systematically polite exit data — the small-numbers defences (state the n, volunteer the coincidence test, argue direction over magnitude), and the discipline of naming your weakest assumption first. A case that fails its own sensitivity test and says so beats one that passes untested.', NULL, '2026-08-12', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m5-choice', 'ai301-hrbp-m5', 'choice', '{"reviewedAt":"2026-08-12","title":"Four cases, one that holds","intro":"*Five minutes. Commit before you look.*\n\nFour HRBPs took a case to Finance in the same quarter. Each wanted roughly the same amount of money. **One of these survives contact with a CFO.**\n\nDon''t ask which request is most deserving. Ask which numbers can carry the claim being made on them.","artifacts":[{"label":"Case A · the retention intervention","body":"\"Engineering attrition is at crisis levels — we''ve lost 50% of the platform team this year. A £40k retention package would pay for itself immediately given replacement costs of £2.1M.\"\n\n*(The platform team has six people. Three left: one retired, one relocated with a partner, one was managed out.)*"},{"label":"Case B · the extra layer","body":"\"Removing the regional director layer saves £780k fully loaded, plus an estimated £120k–£300k in decision-latency and meeting time across the 40 people beneath it — I''ve used the low end. Biggest weakness: the latency figure comes from my own observation over four months, not measurement, and if it''s overstated the case still holds on the £780k alone.\""},{"label":"Case C · the vacancy","body":"\"The unfilled enterprise AE role is costing us £3.4M in lost revenue this year, based on quota attainment for the territory. Filling it is the single highest-ROI action available to this business.\""},{"label":"Case D · the program","body":"\"Our manager capability program will improve engagement by 12 points and reduce regretted attrition by 18%, delivering £1.6M in value against a £200k investment — benchmarks from three published industry studies of similar programs.\""}],"options":[{"id":"a","label":"Case A"},{"id":"b","label":"Case B"},{"id":"c","label":"Case C"},{"id":"d","label":"Case D"}],"key":"b","reasoning":"**B holds, and it holds because of what it gives away.** It states the fully loaded figure with a conservative range on the soft component, chooses the low end, names its own weakest input before anyone asks — observation rather than measurement — and then does the thing that actually wins the argument: **shows the conclusion surviving without it.** That is the sensitivity test, volunteered. Finance can now argue about £120k instead of about whether to believe you.\n\n**A is small numbers dressed as a crisis.** \"50% attrition\" and \"three of six\" are arithmetically identical and rhetorically opposite — and once you see the denominator, the composition destroys the claim: a retirement, a relocation, and a managed exit are three different phenomena, and at most one of them is regretted. The £2.1M replacement figure is six-person variance multiplied by a benchmark. This is the module''s central failure mode, and note that AI would have produced the same number faster and with more decimal places.\n\n**C attributes an entire territory''s revenue to one vacancy.** The number may not even be wrong, but it claims the role is the sole cause of the shortfall — no share stated, no acknowledgment that territories underperform for many reasons. It invites exactly one question, and the case has no answer to it. A share, stated and arguable, would have survived.\n\n**D is benchmark laundering.** Every figure comes from someone else''s population: 12 points, 18%, £1.6M — none of it from this organization, and the causal chain (program → engagement → attrition → money) multiplies three uncertain steps into one confident total. \"Three published industry studies\" is the tell Module 3 taught you to read: whose sample, and what would falsify it?\n\nThe pattern: **the case that won was the one that argued against itself first.**"}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m5-rubric', 'ai301-hrbp-m5', 'rubric', '{"promptVersion":"ai301-hrbp-m5-one-case-stress-tested-v1","moduleId":"ai301-hrbp-m5","minWords":250,"maxWords":350,"submitLabel":"Your model and write-up","intro":"Paste the model with every input and its source, your data interrogation, your weakest assumption and its sensitivity, then the 250–350 word write-up including your position on this module''s claim. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for AI 301 · The Specialist, HRBP track. Module 5 applied activity, ''One case, stress-tested'': a real unresolved argument built into one of three models (regretted attrition, cost of an extra layer, time-to-fill against plan), with every input''s source and provenance shown, an explicit statement of where AI was and wasn''t used, an interrogation of how each HR-system field is actually populated versus what its name implies, at least one named input they don''t fully trust with what they did about it, and their weakest assumption named FIRST with a plausible range and the conclusion tested at the unfavourable end. CRITICAL: a case that fails its own sensitivity test and is reported honestly scores HIGHER than one that passes because it was never tested. Also watch for the module''s central failure — small populations carrying percentage claims; if the learner''s denominator is small, they must state the n and volunteer the coincidence test. False precision should be marked down; a rough figure with stated assumptions is the target. Grade the delta, never prediction accuracy.","opening":[{"key":"departureCost","label":"Predicted — cost of one regretted departure, mid-level role","hint":"Whole currency units. Gut estimate, before any arithmetic.","placeholder":"e.g. 30000","min":0,"max":10000000}],"calibration":[{"key":"departureCostActual","label":"Built — what your model actually says","hint":"Including the productivity ramp, which most estimates omit.","placeholder":"e.g. 72000","min":0,"max":10000000,"actualFor":"departureCost"}],"dimensions":[{"name":"The model has a visible skeleton","criteria":"Every input shown with its source, arithmetic followable, and AI''s contribution stated honestly (structure and sensitivity yes; supplied numbers no). Rough figures with stated assumptions are the target; false precision to the pound reads as naivety or concealment and should be marked down."},{"name":"The data was interrogated","criteria":"For each HR-system input, how the field is actually populated versus what its name implies — with at least one input named as not fully trusted and a stated response. A learner who writes ''I don''t know how regretted is set, and that''s my first question for analytics'' scores well; one who uses the field uncritically does not."},{"name":"Small numbers handled honestly","criteria":"Where the population is small, the n appears in the sentence with the finding, percentages are not used to imply a larger denominator, and a coincidence test is volunteered. Where the population genuinely cannot support a quantified claim, saying so and making the qualitative case explicitly is the top-scoring response."},{"name":"It argues against itself first","criteria":"The weakest assumption named before any strengths, with a plausible range and the conclusion tested at the unfavourable end. A case that does not survive its own test, reported plainly, scores at the top of this dimension. Also grades the position on the module''s claim, including its counter-argument that influence runs through relationships and trust rather than analysis."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m5-knowledge_check', 'ai301-hrbp-m5', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-12","questions":[{"id":"q1","prompt":"Why does a story lose to a model in a budget conversation, even when the story is more accurate?","options":["Finance leaders are trained to distrust qualitative input","A model can be challenged, adjusted, and agreed — it converts a claim into a form comparable against competing claims on the same money","Stories take longer to present than models","Models are more likely to be correct than practitioner judgment"],"correctIndex":1,"explanation":"Being arguable is the property that matters. A story can only be believed or not, and belief is a weak instrument against a spreadsheet. D is explicitly not the claim — the story is often more accurate."},{"id":"q2","prompt":"Your attrition model gets challenged on the replacement-cost multiplier you used. What has actually happened?","options":["The model failed and should be rebuilt with defensible inputs","Finance is signalling they won''t fund the request","The shape of your reasoning was accepted and only the parameters are in dispute — which is the conversation you wanted","You presented with too much precision and invited scrutiny"],"correctIndex":2,"explanation":"Getting to a parameter argument means the model was taken seriously. That stage doesn''t exist for a story, which is the entire point of bringing one."},{"id":"q3","prompt":"In a regretted-attrition model, which input typically carries the most weight and receives the least scrutiny?","options":["Recruitment agency fees","Interviewer and hiring manager time","Onboarding and training cost","The productivity ramp — months until a replacement reaches the departed person''s output"],"correctIndex":3,"explanation":"For complex roles it often exceeds everything else combined, and most published per-hire figures omit it entirely. Which means a model that includes it explicitly is more defensible than one citing a headline industry number."},{"id":"q4","prompt":"Why is the \"regretted\" flag in your HRIS specifically unreliable? `[V]`","options":["It''s usually left blank by default","It''s set by whoever closed the requisition — sometimes the manager who caused the departure, recording a judgment under pressure as an interested party","Different HRIS vendors define it differently","It''s a lagging indicator that only updates quarterly"],"correctIndex":1,"explanation":"A judgment field populated by a party with an interest in the answer — and every attrition model in the organization rests on it. Knowing this about your own systems is the contribution an HRBP makes that neither analytics nor Finance can."},{"id":"q5","prompt":"Three of six people have left a team in a year. What does the module recommend?","options":["Report it as 50% attrition, which is the accurate rate","Exclude the team from analysis, since the population is too small","State \"three of six,\" volunteer the coincidence test before being asked, and argue direction and mechanism rather than magnitude","Combine it with similar teams to reach a defensible sample"],"correctIndex":2,"explanation":"\"50% attrition\" is arithmetically identical and rhetorically dishonest, because percentages imply a supporting population. Volunteering the limitation is the strongest credibility move available and costs nothing — everyone competent already knows."},{"id":"q6","prompt":"What does the module mean by \"confident garbage in front of a CFO is worse than no model at all\"?","options":["CFOs prefer qualitative arguments from HR partners","A missing number costs one conversation; a wrong number that gets repeated and then corrected by someone else costs the next five","Financial models require certification that HR business partners don''t hold","AI-assisted models are inherently less reliable than manual ones"],"correctIndex":1,"explanation":"The asymmetry is about credibility over time, not about any single meeting. D misstates it — the danger isn''t AI assistance, it''s AI assistance on inputs that don''t mean what the model assumes."},{"id":"q7","prompt":"Where should AI be used in building these models, and where not?","options":["For the inputs, since it can access market benchmark data","Nowhere — financial modelling requires human construction throughout","For structure, forgotten variables, and sensitivity tables; not for supplying the numbers, which come from your systems with recorded provenance","For the final narrative only, after the model is complete"],"correctIndex":2,"explanation":"Skeleton-building is genuinely what it''s good at; input-supply is where the foundation problem bites. A is the specific trap — invented benchmarks are confident, plausible, and exactly what Module 3''s teardown exists to catch."},{"id":"q8","prompt":"Why does the activity ask you to name your weakest assumption first?","options":["To demonstrate humility to the reader","Because a hostile reader will find it anyway, and naming it first converts an attack into a stated limitation — and a case that fails its own sensitivity test, reported honestly, is worth more than one that passes untested","Because sensitivity analysis is required in financial submissions","To reduce the number of questions asked in the meeting"],"correctIndex":1,"explanation":"It''s a strength move, not a concession: you keep control of the framing and you learn whether your conclusion is robust. A submission that discovers its case doesn''t survive is a success for this module."}]}', '2026-08-12');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-calibration-prompt-before-you-start-10', 'ai301-hrbp-m6', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*One prediction, thirty seconds.*

**What share of HR professionals working in states that regulate AI in employment do you think
are unaware their state has such a law?** Whole percent.

The number is high enough that it is worth knowing where you sit in it before you find out.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-module-brief-20', 'ai301-hrbp-m6', 20, 'prose', 'stable', '## Module brief

Two halves, and they belong together even though most treatments separate them.

The first half is the law about **systems** — the tools screening, scoring, and ranking people
across your organization, most of which you did not choose and some of which you may not know
about. That surface is moving fast: a growing patchwork of state statutes, a landmark case
redrawing who is liable, and a European regime with one prohibition already absolute.

The second half is the law about **documents** — the investigation summary, the PIP language, the
termination rationale sitting on your desk right now. This is the writing an HRBP does that is
most likely to be read years later by someone hostile, and it is where AI assistance creates a
question nobody was asking two years ago: *how was this produced, and can you say?*

Most legal treatments of AI in HR cover the first half and skip the second, because the first is
where the vendors and the statutes are. But the second is where **you** personally are exposed,
most weeks, in the ordinary course of your job.

One framing before we start, because it determines how to read everything here. **You are not
being asked to become a lawyer.** You are being asked to become the person who knows which
questions have legal answers and brings them a specific list instead of a general worry. That is
a genuinely different and achievable skill, and counsel will thank you for it.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-learning-objectives-30', 'ai301-hrbp-m6', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. Describe the shape of the regulatory surface for AI in employment `[V]` well enough to
   identify which questions apply to your organization.
2. Explain the agent theory and why it changes procurement rather than just compliance.
3. Apply AI to ER documentation safely — including the use almost nobody thinks of — and name
   precisely where it must stop.
4. Say what uncertain provenance does to a document that later enters discovery.
5. Take counsel a specific, answerable list rather than "are we compliant?"', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-lesson-1-the-regulatory-surface-40', 'ai301-hrbp-m6', 40, 'prose', 'volatile', '## Lesson 1 · The regulatory surface [V]

*Direction of travel, not legal advice. Verify every specific with counsel before relying on it.*

**A patchwork, not a framework.** A substantial number of US states now have laws touching AI in
employment, with more each session — and the practical problem is not severity but *awareness*: a
majority of HR professionals working in regulated states do not know their state has such a law.
That statistic is the most actionable thing in this lesson, because it means the first question
is not "are we compliant" but "which regimes even apply to us?"

**The recurring obligations.** Across the patchwork, the same duties keep appearing in different
combinations: notice to candidates and employees that an AI tool is being used; bias auditing,
sometimes with publication; the right to request human review; and record-keeping about how the
tool was used and what it produced. If you build for those four, you are broadly positioned for
regimes you haven''t read yet.

**The European regime has one absolute.** The EU AI Act classifies employment uses — recruitment,
selection, promotion, termination, task allocation, and performance monitoring — as high-risk,
and those obligations were deferred to **December 2027** under the Digital Omnibus agreement. But
two things did not move: the **AI literacy obligation** and the **prohibition on emotion
recognition in the workplace**, both in force since February 2025. The emotion-recognition ban is
not a risk to manage — it is a prohibition on inferring emotional states of employees or
candidates from facial expression, voice, or similar signals. If a vendor is selling you
sentiment-from-video in an interview context and you have European operations, that is not a
procurement question.

**And the doctrine that predates all of it.** Disparate impact requires no intent. A neutral
practice that disproportionately excludes a protected group needs job-related justification,
whoever built it and whatever it was marketed as. Every AI statute above sits on top of that; none
replaces it.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-lesson-2-the-agent-theory-50', 'ai301-hrbp-m6', 50, 'prose', 'volatile', '## Lesson 2 · The agent theory [V]

The most consequential development for how you buy, rather than how you comply.

In **Mobley v. Workday**, a court allowed claims to proceed on the theory that an AI screening
vendor can act as an **agent of the employer** — holding it plausibly alleged that customers had
delegated their traditional function of rejecting candidates or advancing them to interview. The
employment-agency theory was dismissed; the agent theory survived and went to discovery. The
litigation has continued to expand rather than contract, with claims proceeding across race, sex,
age, and disability.

Three implications, in descending order of how much they should change your Monday.

**Neither party gets to point at the other.** The employer''s "that''s the vendor''s problem" and the
vendor''s "we only make the software" both weaken under this theory. If a tool performs a function
you would otherwise perform, it may carry your obligations with it.

**Discovery reaches the model.** The most instructive part of the case is the ongoing fight over
access to algorithmic code and testing data. Whatever the outcome, the direction is clear: **"we
don''t know how it works, the vendor won''t tell us" is a position you may have to defend rather
than a shield you can hide behind.** Which converts a vague fairness principle into a concrete
procurement requirement — ask for the validation evidence *before* signature, in writing, because
afterwards you have no leverage and possibly an obligation.

**And the privilege nuance sophisticated employers are already using.** Bias-testing conducted
*under counsel*, where the lawyer curates the analysis and uses the results in providing legal
advice, may be protected from discovery in a way that the same testing run by HR as an operational
exercise is not. This is not a reason to avoid testing. It is a reason to involve counsel in
designing it — a conversation worth having before you commission an audit, not after.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-lesson-3-er-documentation-that-survives--60', 'ai301-hrbp-m6', 60, 'prose', 'stable', '## Lesson 3 · ER documentation that survives scrutiny

Now the half that is actually on your desk.

**Where AI genuinely helps.** Three uses, all safe, and one of them is underused to the point of
being a competitive advantage:

*Structure and consistency.* Turning your own notes into a coherently organized summary, with
your findings intact and your headings consistent with how your team writes them.

*The completeness pass — the one almost nobody runs.* Give it your interview plan or your draft
summary and ask: **"What did I fail to ask? What would a thorough investigator have covered that
isn''t here?"** This is assist-side, entirely safe, and it catches the omission that becomes the
problem eighteen months later. It does not evaluate anyone; it audits your coverage.

*Language discipline.* Flagging conclusory language, loaded adjectives, and characterizations that
have crept in where observations belong. A model is unusually good at spotting "was hostile" where
"raised his voice twice, per two witnesses" belongs.

**Where it stops, and this is not a caution — it is a stop.** Credibility determinations. Any
conclusion about what happened. Any characterization of a person''s character, motive, or
truthfulness. The moment a model contributes to *whether you believe someone*, you have crossed
101 M7''s line in the highest-stakes place it exists — and unlike a hiring screen, there is a named
individual with a specific consequence attached to the answer.

**And the provenance problem.** ER documents can be read years later, under oath, by people whose
job is to undermine them. The questions that get asked are: who wrote this, when, based on what,
and did it change? **A document whose production you cannot describe is weaker than one you can**
— which produces a discipline worth adopting now, before anyone requires it:

- Record that AI assisted, in what role, on what date — one line in your file notes.
- Keep the human-authored source material the summary was built from.
- Never let a model''s phrasing become a finding you didn''t independently reach.
- If a sentence in the final document is one you couldn''t defend the origin of, rewrite it.

That last rule is the whole discipline in one line, and it is not really about AI at all.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-try-70', 'ai301-hrbp-m6', 70, 'try_this', 'stable', '### Try this — 3 minutes
Take a recent ER summary you wrote — mentally, no files needed. Could you say, for each
conclusion in it, what evidence produced it and when you reached it? If yes, AI assistance adds
speed to a defensible process. If no, the process was already the problem and AI would only
make it faster.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-lesson-4-what-you-can-do-this-quarter-80', 'ai301-hrbp-m6', 80, 'prose', 'stable', '## Lesson 4 · What you can do this quarter

Without waiting for anyone.

**Inventory.** 101 M2''s stack audit, re-read for a different purpose: which systems touching your
population *screen, score, rank, or filter people*? Name the deployer for each. Most HRBPs find at
least one they''d never classified that way.

**Ask three questions of each vendor, in writing.** Has this tool been bias-audited, by whom, and
may we see it? What does it do when it has insufficient data about a candidate? And: which of our
jurisdictions have you assessed this tool against? The answers — or the silences — are the finding.

**Write the documentation standard.** One page for your own team, covering the ER discipline
above. It costs an afternoon and it is the artifact your organization will wish it had.

**Then bring counsel a list, not a worry.** Not "are we compliant with AI law?" — which gets you a
shrug — but: *"These four systems touch hiring and performance. Here is what each one decides.
Which of our jurisdictions regulate these today, what do they require of us this year, and what''s
coming that we should build for now?"* That question has answers. The general one does not.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-exercise-embed-85', 'ai301-hrbp-m6', 85, 'exercise', 'stable', '{"type": "sorting", "title": "Calibration exercise \u2014 Ten uses in ER work", "intro": "Ten minutes, ten uses of AI in employee-relations and investigation work. Sort each: run it, run it with the discipline (recorded provenance, human source material, sign-off), or never.\n\nCommit every card before the reveal. The line you''re applying is 101 M7''s, in the highest-stakes place it exists."}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-key-takeaways-90', 'ai301-hrbp-m6', 90, 'takeaways', 'stable', '## Key takeaways

- **It''s a patchwork, and awareness is the first problem** `[V]` — most HR professionals in
  regulated states don''t know their state regulates this. Start with which regimes apply, not
  whether you comply.
- **Four obligations recur** across regimes: notice, bias auditing, human review, record-keeping.
  Build for those and you''re positioned for statutes you haven''t read.
- **The EU emotion-recognition ban is already absolute** `[V]`, alongside the AI literacy
  obligation — high-risk employment duties deferred to December 2027, those two did not move.
- **Agent theory means neither party can point at the other** `[V]`, and discovery reaches the
  model — "we don''t know how it works" is a position to defend, not a shield. Get validation
  evidence before signature; afterwards you have no leverage.
- **AI in ER documentation: structure, the completeness pass — *what did I fail to ask?* — and
  language discipline.** It stops absolutely at credibility, conclusions, and characterizing a
  person.
- **If you can''t defend a sentence''s origin, rewrite it.** Record that AI assisted, keep the
  source material, and never let a model''s phrasing become a finding you didn''t reach.
- **Bring counsel a specific list.** "Are we compliant?" gets a shrug; four named systems and
  what each decides gets an answer.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-activity-link-95', 'ai301-hrbp-m6', 95, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 Inventory and standard", "blurb": "Every system touching your population that screens, scores, ranks or filters \u2014 deployer named, audit status recorded, \"don''t know\" accepted as an honest entry \u2014 plus three written vendor questions and a one-page ER documentation standard your team could follow without you.", "estMinutes": "25\u201330"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-take-a-position-100', 'ai301-hrbp-m6', 100, 'callout', 'stable', '## Take a position

**The claim:** *"An HRBP who cannot name every system that screens, scores, or ranks their
population is not managing risk — they are hoping."*

The strongest counter-argument is that **this is not the HRBP''s job.** Tool inventory and vendor
diligence sit with HR technology, procurement, and legal; an HRBP who takes it on is absorbing
work that belongs to functions with more authority and better information — and doing it badly,
part-time, without the mandate to act on what they find. Your position has to survive that,
because it''s the argument you''ll actually get from a colleague.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-sources-and-attribution-110', 'ai301-hrbp-m6', 110, 'prose', 'stable', '## Sources and attribution

- **State AI employment statutes** — the patchwork of notice, bias-audit, human-review, and
  record-keeping obligations, and the awareness finding among HR professionals in regulated
  states. Fast-moving; verify current scope and effective dates with counsel. **[V]**
- **EU AI Act and the Digital Omnibus** — Annex III employment classification deferred to
  2 December 2027; the AI literacy obligation and workplace emotion-recognition prohibition in
  force since February 2025. **[V]**
- **Mobley v. Workday** — the agent theory permitted to proceed while the employment-agency theory
  was dismissed; claims continuing across race, sex, age, and disability; active discovery
  including disputes over algorithmic code and testing data. Litigation posture changes between
  review cycles. **[V]**
- Disparate impact doctrine long predates AI and is not displaced by any of the above.
- The ER documentation discipline — the completeness pass, the stopping line, and the
  provenance rule — is original to this course.
- **This module is not legal advice.** It is a guide to which questions have legal answers.
  *Counsel review required before deployment-specific claims are added.* **[V]**', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-activity-applied-activity-inventory-and-standard-10', 'ai301-hrbp-m6-activity', 10, 'prose', 'stable', '## Applied activity — "Inventory and standard"

**Time:** 25–30 minutes · **Submit:** the inventory, the one-page standard, and a 250–350 word
write-up · **Graded against the rubric below.**

**Step 1 — The inventory (10 min).** Every AI system touching your population that screens,
scores, ranks, filters, or characterizes a person. Include features switched on inside tools you
already had — the ATS ranking, the "insights" in the survey platform, anything in the HRIS. For
each: what it decides, who the deployer is, and whether it has been bias-audited as far as you
know. **"Don''t know" is a valid and informative entry** — a completed inventory full of honest
unknowns is the point of the exercise.

**Step 2 — Three vendor questions (5 min).** For your highest-risk system, the three questions
you''d put in writing, phrased so a vendor could actually answer and the answer would change
something.

**Step 3 — The documentation standard (10 min).** One page for your own team: what AI may do in
ER documentation, what it may never do, what gets recorded about how a document was produced, and
who signs off. Write it so a colleague could follow it without you in the room.

**Step 4 — Score the prediction (2 min).** Your predicted share of HR professionals unaware of
their state''s law, against the real figure — and one sentence on whether you were in it.

Then the write-up: what the inventory surfaced that you hadn''t classified as a decision system,
your position on the claim above with its counter-argument addressed, and the single question you
are taking to counsel first.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-micro-core', 'ai301-hrbp-m6-micro', 10, 'prose', 'stable', '## Module 6 in two minutes

**Two halves: the law about systems, and the law about your documents.** Most treatments cover the first and skip the second — but the second is where you are personally exposed, most weeks.

**The systems half** `[V]`: a patchwork of state statutes where the first problem is awareness, not severity — most HR professionals in regulated states don''t know their state regulates this. Four obligations recur everywhere: notice, bias auditing, human review, record-keeping. In the EU, high-risk employment duties deferred to December 2027, but the AI literacy obligation and the **workplace emotion-recognition prohibition** have been in force since February 2025 — and the second is an absolute ban, not a risk to manage.

**The agent theory** `[V]`: in Mobley v. Workday a court let claims proceed on the theory that a screening vendor acts as the employer''s agent, because customers had delegated the function of rejecting or advancing candidates. Neither "that''s the vendor''s problem" nor "we only make the software" survives that well — and with discovery reaching algorithmic code, *"we don''t know how it works"* is a position to defend rather than a shield. Get validation evidence before signature.

**The documents half:** AI helps with structure, language discipline, and the completeness pass — **"what did I fail to ask?"** — and stops absolutely at credibility, conclusions, and characterizing a person.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-micro-rule', 'ai301-hrbp-m6-micro', 20, 'callout', 'stable', '### The rule to carry

If you couldn''t defend a sentence''s origin, rewrite it. And bring counsel a list, not a worry — "are we compliant with AI law?" gets a shrug; four named systems and what each decides gets an answer.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m6-micro-close', 'ai301-hrbp-m6-micro', 30, 'prose', 'stable', '**The full module adds** the privilege nuance sophisticated employers already use — bias testing designed under counsel may be protected in ways the same testing run operationally is not — the ten-card ER sort, and the quarter''s homework: inventory what screens your population, put three questions to each vendor in writing, and write the one-page documentation standard your organization will wish it had.', NULL, '2026-08-12', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m6-sorting', 'ai301-hrbp-m6', 'sorting', '{"reviewedAt":"2026-08-12","buckets":[{"id":"never","label":"Never","hint":"Over the line","rank":0,"pct":5},{"id":"discipline","label":"With the discipline","hint":"Provenance recorded, human source kept","rank":1,"pct":50},{"id":"run","label":"Run it","hint":"Ordinary care","rank":2,"pct":90}],"tasks":[{"id":"t1","text":"Asking \"what did I fail to ask?\" against your own draft investigation plan","key":"run","reasoning":"The completeness pass. It audits your coverage rather than evaluating anyone, and it catches the omission that becomes a problem eighteen months later. The safest high-value use in the module and the one almost nobody runs."},{"id":"t2","text":"Asking the model which of two conflicting witness accounts is more credible","key":"never","reasoning":"A credibility determination — the single clearest stop in this module. There is a named individual with a specific consequence attached to the answer, and the model has no basis for it beyond the plausibility of text."},{"id":"t3","text":"Turning your own handwritten interview notes into a structured summary, headings matching your team''s format","key":"discipline","reasoning":"Assist-side and genuinely useful — but it produces a document that may be read years later under oath. Record that AI assisted and on what date, and keep the handwritten source. The discipline costs a line of file notes."},{"id":"t4","text":"Flagging conclusory language in your draft — \"was hostile\" where an observation belongs","key":"run","reasoning":"Language discipline, and models are unusually good at it. It improves the document''s defensibility rather than threatening it: replacing characterization with observation is what a hostile reader would demand anyway."},{"id":"t5","text":"Drafting the termination rationale from the case file","key":"discipline","reasoning":"Defensible only if every conclusion in it is one you independently reached first — the model formats your finding, it does not supply it. If a sentence appears that you couldn''t defend the origin of, rewrite it. Many practitioners would place this at never, and that''s a defensible call.","also":["never"]},{"id":"t6","text":"Pasting an employee''s unredacted complaint into a consumer chatbot account to \"get a second opinion\"","key":"never","reasoning":"Fails before the line question even arises: 101 M4 tier violation under an agreement that likely permits training on inputs. Note the framing — \"second opinion\" is how this arrives in real life, and it sounds reasonable."},{"id":"t7","text":"Summarizing your organization''s own written policy so you can check a process step against it","key":"run","reasoning":"Supplied material, transformation, no person in it, and you can verify the summary against the source in seconds. Ordinary care."},{"id":"t8","text":"Asking the model to suggest an appropriate disciplinary outcome based on precedent","key":"never","reasoning":"A conclusion about what should happen to a named person. That the reasoning cites precedent makes it more persuasive and no more legitimate — precedent selection is itself the judgment being delegated."},{"id":"t9","text":"Generating three alternative phrasings of a PIP objective so it''s measurable rather than vague","key":"discipline","reasoning":"The objective is yours; the phrasing is craft assistance, and a measurable objective is fairer to the employee than a vague one. Discipline because it''s a consequential document about a named individual — keep the source, record the assistance."},{"id":"t10","text":"Asking the model whether a pattern across four ER cases suggests a manager problem","key":"discipline","reasoning":"The hardest card. Pattern analysis across cases is legitimate assist-side work and exactly what an HRBP should be doing — but n=4 is Module 5''s small-numbers trap, and the subject is one identifiable manager. Run it as a hypothesis generator with the n stated, never as a finding.","also":["never"]}],"pattern":"Assist stops the moment the model contributes to whether you believe someone, or what should happen to them.","postscript":"The never cards share one property: a model contributing to a judgment about a person — credibility, outcome, or character. The discipline cards are all documents that may be read later by someone hostile, where the cost of provenance is one line in your file notes. Cards placed too permissively are the expensive direction here; cards placed too cautiously cost you only the completeness pass, which is the one genuinely free win in the set. Note t5 and t10 are legitimately arguable, and the reveal says so — a defensible stricter call is not a miss."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m6-rubric', 'ai301-hrbp-m6', 'rubric', '{"promptVersion":"ai301-hrbp-m6-inventory-and-standard-v1","moduleId":"ai301-hrbp-m6","minWords":250,"maxWords":350,"submitLabel":"Your inventory, standard, and write-up","intro":"Paste the system inventory, your three vendor questions, the one-page documentation standard, and the 250–350 word write-up. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading a learner submission for AI 301 · The Specialist, HRBP track. Module 6 applied activity, ''Inventory and standard'': every AI system touching their population that screens, scores, ranks, filters or characterizes a person — including features switched on inside existing tools (ATS ranking, survey-platform insights, HRIS features) — with what each decides, the deployer named, and bias-audit status where known. ''Don''t know'' is an explicitly valid and informative entry and a completed inventory full of honest unknowns is the intended outcome; penalize confident guesses, not admitted gaps. Then three written vendor questions for their highest-risk system, phrased so a vendor could answer and the answer would change something. Then a one-page ER documentation standard: what AI may do, what it may never do (credibility determinations, conclusions about what happened, characterizations of motive or truthfulness), what gets recorded about production, and who signs off — written so a colleague could follow it without them. This module is not legal advice and the learner should not be graded as though they were producing legal analysis; grade the quality of the questions and the clarity of the standard. Grade the delta, never prediction accuracy.","opening":[{"key":"unawarePct","label":"Predicted — % of HR pros in regulated states unaware of their state''s law","hint":"Whole percent.","placeholder":"e.g. 30","min":0,"max":100}],"calibration":[{"key":"unawarePctActual","label":"Actual — the figure the module reports","hint":"And were you in it?","placeholder":"e.g. 57","min":0,"max":100,"actualFor":"unawarePct"}],"dimensions":[{"name":"The inventory found the quiet ones","criteria":"Real systems from their actual stack, including embedded features nobody classified as decision systems — the ATS ranking, the survey platform''s insights, HRIS scoring. Honest ''don''t know'' entries score above confident guesses. An inventory that surfaces something the learner hadn''t thought of that way is the success condition."},{"name":"The vendor questions would produce answers","criteria":"Specific enough for a vendor to answer and consequential enough that the answer changes something. ''Is your AI fair?'' scores low. ''Has this been bias-audited, by whom, and may we see it?'' and ''which of our jurisdictions have you assessed it against?'' score high. Silence as an anticipated answer is a sophisticated observation."},{"name":"The standard is followable","criteria":"Names what AI may do in ER documentation, what it may never do, what gets recorded about how a document was produced, and who signs off — concrete enough that a colleague could apply it without the author present. Aspirational language (''use AI responsibly'') fails this dimension."},{"name":"The position and the delta","criteria":"A committed position on the claim that engages its real counter-argument — that inventory and vendor diligence belong to HR technology, procurement and legal, and an HRBP absorbing it does it part-time without the mandate to act. Plus the prediction compared and the honest note on whether they were in the unaware majority."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m6-knowledge_check', 'ai301-hrbp-m6', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-12","questions":[{"id":"q1","prompt":"What does the module identify as the first practical problem with the state-law patchwork? `[V]`","options":["The penalties are severe enough to threaten mid-size employers","Awareness — a majority of HR professionals in regulated states don''t know their state has such a law, so the first question is which regimes apply rather than whether you comply","The statutes conflict with each other in ways that make compliance impossible","Enforcement is inconsistent across jurisdictions"],"correctIndex":1,"explanation":"You cannot comply with a regime you don''t know covers you, which is why the module''s homework starts with inventory and jurisdiction rather than with policy."},{"id":"q2","prompt":"Which EU AI Act obligations are already in force rather than deferred to December 2027? `[V]`","options":["All high-risk employment obligations","Bias auditing and candidate notice","The AI literacy obligation and the prohibition on emotion recognition in the workplace","None — the entire regime was postponed under the Digital Omnibus"],"correctIndex":2,"explanation":"The high-risk employment duties moved; those two did not. And the emotion-recognition provision is a prohibition rather than a risk to manage — relevant the moment a vendor offers sentiment inference from interview video."},{"id":"q3","prompt":"Under the agent theory in Mobley v. Workday `[V]`, what changed most for an employer?","options":["Employers became solely liable for vendor tool outputs","Vendors became solely liable, insulating employers","\"That''s the vendor''s problem\" and \"we only make the software\" both weaken — a tool performing a function you''d otherwise perform may carry your obligations","Nothing yet, since the case remains unresolved"],"correctIndex":2,"explanation":"The court allowed the agent theory to proceed on the basis that customers had delegated the function of rejecting or advancing candidates. D is the tempting answer — the case is ongoing — but procurement behaviour should change on the theory surviving, not on final judgment."},{"id":"q4","prompt":"Why does the discovery fight over algorithmic code matter to a practitioner?","options":["It will produce a public standard for algorithmic transparency","Because \"we don''t know how it works and the vendor won''t tell us\" becomes a position to defend rather than a shield — which makes validation evidence a pre-signature requirement","Because employers can now compel vendors to disclose code on request","Because it establishes that proprietary models are exempt from disclosure"],"correctIndex":1,"explanation":"The practical translation is procurement leverage: ask before signature, in writing. Afterwards you have no leverage and possibly an obligation."},{"id":"q5","prompt":"Which use of AI in ER documentation does the module single out as underused and entirely safe?","options":["Drafting the summary from raw interview notes","Flagging inconsistencies between witness accounts","The completeness pass — \"what did I fail to ask that a thorough investigator would have covered?\"","Suggesting appropriate disciplinary outcomes based on precedent"],"correctIndex":2,"explanation":"It audits your coverage rather than evaluating anyone, and it catches the omission that becomes a problem much later. B edges toward comparing accounts, which approaches credibility; D is squarely over the line."},{"id":"q6","prompt":"Where does AI assistance in ER documentation stop absolutely?","options":["At any use involving employee names","At credibility determinations, conclusions about what happened, and characterizations of a person''s motive or truthfulness","At documents that may become part of a legal proceeding","At investigations involving protected characteristics"],"correctIndex":1,"explanation":"101 M7''s line in its highest-stakes location — and unlike a hiring screen, there is a named individual with a specific consequence attached. A is over-broad (M4''s redaction handles names); C would prohibit most ER documentation entirely."},{"id":"q7","prompt":"What is the module''s one-line provenance discipline?","options":["Never use AI on documents that might enter discovery","Disclose AI use to the employee who is the subject of the document","If you couldn''t defend a sentence''s origin, rewrite it","Retain all AI conversation logs for the statutory retention period"],"correctIndex":2,"explanation":"And the module notes it isn''t really about AI — a document whose production you can''t describe was already weak. The supporting practices (record that AI assisted, keep the source material, don''t let model phrasing become a finding) all serve it."},{"id":"q8","prompt":"What makes \"are we compliant with AI law?\" the wrong question for counsel?","options":["It requires legal expertise the HRBP doesn''t have","It has no answer — the useful version names the specific systems, what each decides, and asks which jurisdictions regulate them this year","Counsel cannot advise on AI matters without specialist certification","Compliance questions should go to the vendor first"],"correctIndex":1,"explanation":"General questions get shrugs; specific lists get answers. Producing that list is exactly what the inventory and the three vendor questions are for."}]}', '2026-08-12');
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-calibration-prompt-before-you-start-10', 'ai301-hrbp-m7', 10, 'calibration_prompt', 'stable', '## Calibration prompt — before you start

*The last prediction of the course.*

**What percentage of HR leaders do you think believe their managers have the skills to use AI
effectively?** Whole percent.

Then, in the activity, you''ll gather every prediction you made across these seven modules and
look at the pattern — because this track scores the delta, not the score, and the pattern is the
thing worth knowing about yourself.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-module-brief-20', 'ai301-hrbp-m7', 20, 'prose', 'stable', '## Module brief

Everything so far in this track has made *you* better. This module is about the multiplier —
because an HRBP supports somewhere between twenty and two hundred managers, and each of them is
already using AI, mostly badly, mostly on work that lands on your desk afterwards.

That gives you two jobs, and most people only think about the first.

**The reactive job** is happening now: the performance review that says nothing because a model
wrote it from three bullet points, the manager who pasted a complaint into a consumer chatbot,
the PIP citing a policy that doesn''t exist. You are the person who catches these, and how you
handle the catch determines whether you see the next one or whether it just goes underground.

**The proactive job** is the leverage: building the small number of assets that make manager AI
use better by default. That''s the play with real scale — but it is also where a lot of confident
nonsense lives, because the evidence on AI-delivered manager development is much less flattering
than the market suggests, and one finding in it converts a procurement question into a judgment
call that is unambiguously yours.

That finding is the last idea in this course, and it is the one worth carrying out.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-learning-objectives-30', 'ai301-hrbp-m7', 30, 'callout', 'stable', '## Learning objectives

By the end of this module you should be able to:

1. State the actual demand picture for manager AI capability, from data.
2. Handle a manager''s AI misuse in a way that improves practice rather than driving it
   underground.
3. Describe what the evidence says about AI-delivered coaching, and what it doesn''t say.
4. Explain why allocating human support is an equity decision with your name on it.
5. Read your own calibration record across the course and say what moved.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-lesson-1-the-demand-is-not-in-question-40', 'ai301-hrbp-m7', 40, 'prose', 'volatile', '## Lesson 1 · The demand is not in question [V]

Two numbers settle whether this is worth your time.

**Only about 8% of HR leaders believe their managers have the skills to use AI effectively.**

**And only about 14% of organizations provide managers any support integrating it into their
daily work.**

Those figures come from surveys of just over a hundred HR leaders, which is a small sample and
worth saying — Module 3 taught you to ask. But the gap they describe is so wide that it would
survive being substantially wrong in either direction, and it matches what you already see: your
managers are using these tools daily with no guidance whatsoever, and the output is arriving at
your desk.

The strategic read is that this is one of the few genuinely unoccupied spaces in the
organization. Nobody owns manager AI capability. IT owns tools, L&D owns curriculum, and neither
owns *how a manager should use AI in a performance conversation* — which is a People question
that happens to be an AI question, which is precisely your intersection.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-lesson-2-catching-it-in-the-wild-50', 'ai301-hrbp-m7', 50, 'prose', 'stable', '## Lesson 2 · Catching it in the wild

Before you build anything, you have to handle what''s already happening. Three cases you will
recognize, and the moves that work.

**The review that says nothing.** A manager submits a performance review of fluent, generic
prose: "consistently demonstrates strong collaboration and delivers high-quality work." Nothing
in it could only be true of this person. That is 101 M6''s confident gap — the model filled space
where the manager''s observations should have been, because the manager gave it three bullet
points and asked for a review.

*The move:* don''t attack the AI use. Ask for the specifics — *"give me two examples of the
collaboration you''re describing and one thing they should do differently next quarter."* If the
manager has them, the tool was used badly and the fix is a better brief. If they don''t, **the
problem was never the AI** — they hadn''t been paying attention, and the model let them hide it.
That distinction is the whole diagnosis, and only asking for specifics reveals it.

**The pasted complaint.** A manager tells you they ran an employee''s grievance through a consumer
chatbot to "get a second opinion." A 101 M4 tier violation, under an agreement that may permit
training on inputs, with a named individual in it.

*The move:* handle it as an incident, not a betrayal — and this is where 101 M8''s blame-safe
principle earns its place. **An organization that punishes the manager who tells you trains
everyone else to stop telling you.** Establish what was shared, tell them plainly why it matters
and what to do instead, and make sure the next manager finds it easier to ask you first than to
guess. The manager who reported it is not your problem; the four who didn''t are.

**The fabricated citation.** A PIP or a policy explanation citing something that doesn''t exist.
Highest stakes of the three because it goes to an employee with consequences attached.

*The move:* correct it immediately, then make the rule general and checkable — *every policy or
legal reference in a document going to an employee gets traced to the source before it ships.*
That is a rule a manager can follow and you can audit. "Be careful with AI" is not.

The through-line: **your reaction to the first case determines the visibility of the next
twenty.** Managers who feel caught hide; managers who feel helped ask. And you cannot fix what
you cannot see.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-lesson-3-what-the-evidence-says-about-ai-60', 'ai301-hrbp-m7', 60, 'prose', 'volatile', '## Lesson 3 · What the evidence says about AI coaching [V]

Now the proactive side — where the market is loudest and the evidence is thinnest.

A randomized controlled comparison of human and AI chatbot coaching, with 114 coachees who were
mostly middle and senior managers in a single global corporation, found **substantial effects for
human coaching across goal attainment and wellbeing outcomes — and no equivalent effect for the
AI condition.** Attrition in the AI arm was dramatically higher; some participants asked to
switch to a human.

The detail that should carry the most weight: **one of the authors also co-authored the earlier
study that helped launch the AI-coaching category.** This is not one camp contradicting another.
It is a researcher publishing a result that complicates their own earlier finding — which is the
strongest form of evidence available and the rarest.

And the honest nuance, because overclaiming in the other direction would be the same error: this
is one study, in one organization, with a chatbot of a particular design. Narrowly scoped bots
aimed at a single measurable outcome have performed better in prior work than broad "AI coach"
products — the earlier goal-attainment research found roughly comparable results on goals
specifically, while showing little for resilience and wellbeing. **Narrow and measurable works
better than broad and relational.** That is a usable design principle, not a prohibition.

Which lets you say something precise in a procurement conversation instead of something vague:
*"the evidence supports narrow, outcome-specific tools and does not support broad AI coaching as
a substitute for human development — show me which one you''re selling."*', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-try-70', 'ai301-hrbp-m7', 70, 'try_this', 'stable', '### Try this — 3 minutes
Take the last AI-for-managers product you were pitched. Was it narrow and outcome-specific, or
broad and relational? Then check the claim it made about effectiveness against Module 3''s three
questions: what''s the evidence, what''s the sample, what would falsify it?', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-lesson-4-allocation-is-an-equity-decisio-80', 'ai301-hrbp-m7', 80, 'prose', 'stable', '## Lesson 4 · Allocation is an equity decision

Here is the finding that ends this course.

In that same research, outcomes were predicted most strongly not by the coaching modality but by
**the coachee''s starting self-efficacy and hope.** People who arrived already believing they could
change, did. People who arrived without that belief got less — and got least from the
unsupervised bot.

Follow it to its conclusion. **The employees who most need development are the ones an
unsupervised AI tool serves worst.** Which means that when your organization deploys an AI
coaching product to "democratize access to development," the actual effect is that the confident
get help and the struggling get a chatbot.

That is not a technology problem. It is a distribution decision, and distribution decisions about
who gets scarce human support are decisions about people — which puts them squarely inside the
line 101 M7 drew and this entire track has been circling.

So: **deciding who gets a human is your call, and it is an equity call.** Not procurement''s,
because they''re evaluating a product. Not IT''s, because they''re evaluating a platform. Yours,
because you are the person in the organization whose job is what happens to people at the
bottom of a distribution.

The practical version, and it is a short list:

- **Scarce human coaching goes toward lower starting self-efficacy, not toward the highest
  potential.** That inverts how most organizations allocate development, which is the point.
- **AI tools serve the confident and the already-capable well.** That is a legitimate use, and
  saying so honestly protects the argument for the other half.
- **Never let "we gave everyone access" stand as evidence of equitable development.** Equal access
  to a tool that works unequally is not equity; it is the appearance of it, and you are the person
  who has to say so.

And one caveat to keep us honest, because this course holds itself to its own standard: the
difficult-conversation rehearsal category — including techniques in Module 4 of this track — is
crowded with vendors, and essentially every effectiveness number in it traces back to one of them.
**We hold our own recommendations to the standard we hold theirs.** Module 4''s technique is
argued from craft and mechanism, not from an efficacy study, and you should treat it accordingly.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-exercise-embed-85', 'ai301-hrbp-m7', 85, 'exercise', 'stable', '{"type": "sorting", "title": "Calibration exercise \u2014 Bot, human, or neither", "intro": "Ten minutes, ten manager-support needs. Sort each: a narrow AI tool serves this well, this needs a human, or neither should be deployed here at all.\n\nCommit every card before the reveal. The principle being tested is Lesson 3''s \u2014 narrow and measurable beats broad and relational \u2014 and Lesson 4''s, that who gets a human is an equity decision."}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-key-takeaways-90', 'ai301-hrbp-m7', 90, 'takeaways', 'stable', '## Key takeaways

- **The demand is real and unoccupied** `[V]`: ~8% of HR leaders think their managers can use AI
  effectively; ~14% of organizations offer any support. Nobody owns manager AI capability, and it
  sits at your intersection.
- **Your reaction to the first misuse determines the visibility of the next twenty.** Handle it as
  an incident, not a betrayal — the manager who told you isn''t the problem; the four who didn''t
  are.
- **Ask for the specifics.** A generic AI-written review either means a bad brief or means the
  manager wasn''t paying attention. Only asking reveals which — and the second isn''t an AI problem.
- **Make rules checkable.** "Every policy or legal reference traced to source before it ships"
  can be followed and audited. "Be careful with AI" cannot.
- **The coaching evidence** `[V]`: an RCT of 114 mostly-senior managers found substantial effects
  for human coaching and none for the AI arm, with far higher attrition — published by authors
  including one who helped launch the category. Narrow and measurable beats broad and relational.
- **Outcomes track starting self-efficacy and hope — so the people who most need development are
  served worst by an unsupervised bot.** Allocating human support is therefore an equity decision,
  and it is yours. "We gave everyone access" is not evidence of equitable development.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-activity-link-95', 'ai301-hrbp-m7', 95, 'exercise', 'stable', '{"type": "activity_link", "title": "Applied activity \u2014 One asset, one manager (course close)", "blurb": "One page built for a real recurring manager failure and tested with one real manager \u2014 what they actually did with it, not whether they liked it. Then the reckoning: every prediction across seven modules, the direction of your misses, and what you believe now that you didn''t in Module 1.", "estMinutes": "30"}', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-take-a-position-100', 'ai301-hrbp-m7', 100, 'callout', 'stable', '## Take a position

**The claim:** *"Deploying an AI coaching tool organization-wide without deciding who still gets a
human is a decision to give the least support to the people who need the most — whether or not
anyone intended it."*

The strongest counter-argument is one of scale and counterfactual: **for most organizations the
alternative to an AI coach isn''t a human coach, it''s nothing.** Coaching has always been rationed
to executives; a tool that reaches everyone imperfectly may still lift the floor for people who
previously got zero. On that view, insisting on human allocation risks defending an inequity that
already existed. Your position has to survive that argument, because it is a good one.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-sources-and-attribution-110', 'ai301-hrbp-m7', 110, 'prose', 'stable', '## Sources and attribution

- **Gartner** — approximately 8% of HR leaders believing managers have the skills to use AI
  effectively, and approximately 14% of organizations providing managers support integrating
  GenAI (surveys of ~114 HR leaders; small samples, noted in-lesson). **[V]**
- **de Haan, Terblanche & Nowack**, *Human Resource Development International* (2026) — the
  randomized controlled comparison of human and AI chatbot coaching, N=114, predominantly middle
  and senior managers in one global corporation; and **Terblanche et al. (2022)** on
  goal-attainment-specific chatbot coaching, co-authored by one of the same researchers. **[V]**
- The allocation-as-equity-decision argument, the three misuse cases and their moves, and the
  self-applied scepticism about Module 4 are original to this course.
- Builds on 101 M6 (confident gaps), 101 M7 (decisions about people), 101 M8 (blame-safe
  reporting), and Module 4 of this track.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-activity-applied-activity-one-asset-one-manager-t-10', 'ai301-hrbp-m7-activity', 10, 'prose', 'stable', '## Applied activity — "One asset, one manager" *(the course close)*

**Time:** 30 minutes · **Submit:** the asset, what happened, and a 300–400 word close ·
**Graded against the rubric below.** This is the last thing you''ll make in this track.

### Part 1 — Build and test (20 min)

**Step 1 — Pick the recurring failure.** One thing your managers get wrong with AI, repeatedly.
Use Lesson 2''s cases or your own.

**Step 2 — Build one asset.** A single page: a prompt template, a checklist, a two-example
before/after, a short rule with the reasoning attached. **One page.** The constraint matters —
managers do not read more than that, and an asset nobody reads has no leverage.

**Step 3 — Test it with one real manager.** Give it to them, ask them to use it once, and find
out **what they actually did with it** — not whether they liked it. Liking is not use.

### Part 2 — The reckoning (10 min)

Gather every prediction you made across the seven modules — the no-plans share, your presence and
contested-judgment split, your botsitting hours, unanticipated objections, cost per regretted
departure, the unaware share, and the manager-capability figure at the top of this module.

Then answer the question this whole track has been building toward: **in which direction did you
systematically miss, and what does that say about how you were reading this technology when you
started?** Over-crediting AI''s reach, under-crediting it, or scattered.

And the one that matters most: **what do you believe now that you didn''t believe in Module 1?**
Name something specific enough that you couldn''t have written it before taking this track. "AI is
a powerful tool with risks" is not an answer to this question.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-micro-core', 'ai301-hrbp-m7-micro', 10, 'prose', 'stable', '## Module 7 in two minutes

**You support twenty to two hundred managers, and every one of them is already using AI badly on work that lands on your desk.** Two jobs follow. The reactive one is happening now — the review that says nothing, the pasted complaint, the fabricated citation — and **your reaction to the first case determines the visibility of the next twenty.** Managers who feel caught hide; managers who feel helped ask.

**The diagnostic move on a generic AI-written review:** ask for two examples and one thing to do differently. If the manager has them, the brief was bad. If they don''t, the problem was never AI — they weren''t paying attention and the model let them hide it.

**The proactive job is where the evidence bites** `[V]`. An RCT of 114 mostly-senior managers found substantial effects for human coaching and none for the AI arm, with far higher attrition — published by authors including one who co-authored the earlier study that launched the category, which is self-correction rather than one camp contradicting another. Narrow and measurable beats broad and relational.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-micro-rule', 'ai301-hrbp-m7-micro', 20, 'callout', 'stable', '### The rule to carry

Outcomes track starting self-efficacy and hope — so the people who most need development are served worst by an unsupervised bot. **Who gets a human is an equity decision, and it''s yours.** "We gave everyone access" is not evidence of equitable development.', NULL, '2026-08-12', NULL);
INSERT INTO fd_content_block (id, module_id, ordinal, kind, layer, body, depends_on, reviewed_at, variant) VALUES ('ai301-hrbp-m7-micro-close', 'ai301-hrbp-m7-micro', 30, 'prose', 'stable', '**The full module adds** the three misuse cases with the moves that keep them visible, the bot/human/neither sort — including the card that turns the module''s own finding into a screen it forbids — and the course close: one page built for a real manager failure and tested on a real manager, plus the reckoning across every prediction you made in seven modules. The last question is the one that matters: what do you believe now that you didn''t in Module 1?', NULL, '2026-08-12', NULL);
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m7-sorting', 'ai301-hrbp-m7', 'sorting', '{"reviewedAt":"2026-08-12","buckets":[{"id":"neither","label":"Neither","hint":"Don''t deploy anything here","rank":0,"pct":10},{"id":"human","label":"Needs a human","hint":"Scarce support belongs here","rank":1,"pct":40},{"id":"bot","label":"Narrow AI tool","hint":"Measurable, bounded, works","rank":2,"pct":85}],"tasks":[{"id":"t1","text":"Helping a manager write clearer, more specific goals for their team","key":"bot","reasoning":"Narrow, measurable, bounded — the profile the goal-attainment research actually supports. The output is checkable by the manager and the stakes of a mediocre goal are low and recoverable."},{"id":"t2","text":"Supporting a first-time manager who doubts they should have taken the job","key":"human","reasoning":"Low starting self-efficacy is precisely the condition under which an unsupervised bot performs worst — and this is the person the equity argument is about. If your scarce human coaching is going anywhere, it goes here."},{"id":"t3","text":"A checklist for running a structured one-to-one","key":"bot","reasoning":"Not coaching at all — an asset. Bounded, reusable, and exactly the kind of one-page thing the module''s activity has you build. No relational component to lose."},{"id":"t4","text":"Rehearsing a difficult conversation before the manager has it","key":"bot","reasoning":"Module 4''s technique, and it works on mechanism — bounded scenario, the manager retains the judgment. Note the module''s own caveat: this category is vendor-dominated and its efficacy numbers come from sellers, so the argument here is craft, not evidence.","also":["human"]},{"id":"t5","text":"Deciding whether a manager should be moved out of people leadership","key":"neither","reasoning":"A decision about a person with consequences attached. 101 M7''s line — no tool, narrow or broad, and a coaching product is not the right instrument for a fitness judgment either."},{"id":"t6","text":"An org-wide AI coach rolled out to ''democratize access to development''","key":"neither","reasoning":"The exact deployment Lesson 4 warns about: the confident get help, the struggling get a chatbot, and the organization records equity it didn''t achieve. Not never-any-tool — never *this* framing, without an explicit decision about who still gets a human.","also":["bot"]},{"id":"t7","text":"Helping a manager understand why their team''s engagement scores dropped","key":"human","reasoning":"Contested interpretation about identifiable people on a small population — Module 5''s small-numbers trap and Module 2''s room quadrant at once. A tool will produce a confident explanation, which is the danger."},{"id":"t8","text":"Practising the mechanics of giving specific behavioural feedback","key":"bot","reasoning":"Skill drill with a right answer shape — narrow and measurable. The manager can tell whether their feedback got more specific, which is what makes the loop work without a human in it."},{"id":"t9","text":"A manager processing their own distress after conducting three redundancies","key":"human","reasoning":"Relational and unmeasurable — the broad category where the RCT found nothing and attrition was highest. Some participants in that study asked to switch to a human; this is why."},{"id":"t10","text":"Screening managers by self-efficacy to decide who receives human coaching","key":"neither","reasoning":"The dangerous near-miss, and the sharpest card in the set. Lesson 4''s finding should *inform your judgment* about allocation — it must not become a psychological screen applied to people to ration a resource. That is a decision about people made by an instrument, which is where this course started."}],"pattern":"Narrow and measurable beats broad and relational — and who gets the human is a judgment you make, never a screen you run.","postscript":"The bot cards share a shape: bounded task, checkable output, judgment retained by the manager. The human cards share the opposite: relational, unmeasurable, or landing on someone whose starting confidence is low — which is where the evidence says a bot serves worst. Card 10 is the one worth sitting with: it takes the module''s own finding and turns it into exactly the kind of instrument 101 M7 forbids. A true insight can still be misapplied, and recognizing that is the last thing this course teaches."}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m7-rubric', 'ai301-hrbp-m7', 'rubric', '{"promptVersion":"ai301-hrbp-m7-one-asset-one-manager-v1","moduleId":"ai301-hrbp-m7","minWords":300,"maxWords":400,"submitLabel":"Your asset, what happened, and the reckoning","intro":"Paste the one-page asset, an account of what the manager actually did with it, and the 300–400 word close including the calibration reckoning across all seven modules. This is the last submission in the track. Resubmission is free and unlimited — the score is a mirror, not a gate.","activityContext":"You are grading the CLOSING submission of AI 301 · The Specialist, HRBP track. Two parts. Part 1: a one-page asset built for a real recurring manager AI failure, tested with one real manager, with an account of what they ACTUALLY DID with it — not whether they liked it, since liking is not use. The one-page constraint is deliberate and a longer asset should be marked down: managers don''t read more, and an unread asset has no leverage. Part 2 is the reckoning across the whole track: the learner gathers every prediction they made (no-plans share, presence/contested split, botsitting hours, unanticipated objections, cost per regretted departure, unaware share, manager-capability figure), names the DIRECTION of their systematic miss — over-crediting AI''s reach, under-crediting it, or scattered — and answers what they believe now that they didn''t in Module 1, specifically enough that it could not have been written before the track. Generic closings (''AI is a powerful tool with risks'') fail that question outright. This track scores the delta, not the score: grade the honesty and specificity of the account of change, never the accuracy of any prediction. A learner who completed only some modules should be graded on the pattern in what they did complete.","opening":[{"key":"managerSkillPct","label":"Predicted — % of HR leaders who think managers can use AI effectively","hint":"The last prediction of the course. Whole percent.","placeholder":"e.g. 25","min":0,"max":100}],"calibration":[{"key":"managerSkillPctActual","label":"Actual — the figure the module reports","hint":"Then gather the other six and read the pattern.","placeholder":"e.g. 8","min":0,"max":100,"actualFor":"managerSkillPct"}],"dimensions":[{"name":"The asset is one page and aimed at a real failure","criteria":"A specific recurring manager failure, and an asset a busy manager would actually read — one page, concrete, with the reasoning attached rather than assumed. Length beyond a page is a real deduction here, not a stylistic note: the constraint is the design."},{"name":"It met a real manager","criteria":"Tested with an actual person, with an account of what they did with it. ''They said it was helpful'' scores low; ''they used it for two reviews and ignored the third section'' scores high. A finding that the asset was ignored, honestly reported, scores well — that is data about the asset, not a failure of the submission."},{"name":"The reckoning is honest about direction","criteria":"Predictions gathered across the modules completed, with the systematic direction named — over-crediting AI''s reach, under-crediting it, or genuinely scattered — and a real attempt to explain why their reading leaned that way. Accuracy is never graded; a learner who missed badly in a consistent direction and can account for it should score at the top."},{"name":"What changed, specifically","criteria":"The final question is the heaviest thing in the track. The learner must name something they believe now that they didn''t in Module 1, specific enough that it could not have been written beforehand. Generic closings fail this dimension outright, regardless of the quality of everything else. Also grades the position on the allocation claim, including its strong counter-argument that for most organizations the alternative to an AI coach is nothing at all."}]}', '2026-08-12');
INSERT INTO fd_exercise (id, module_id, kind, payload_json, reviewed_at) VALUES ('ai301-hrbp-m7-knowledge_check', 'ai301-hrbp-m7', 'knowledge_check', '{"title":"Knowledge check — 8 questions","note":"Unlocks after the applied activity is submitted. Retakes are free and unlimited.","reviewedAt":"2026-08-12","questions":[{"id":"q1","prompt":"What do the demand figures establish? `[V]`","options":["That managers are resistant to using AI in their work","That roughly 8% of HR leaders think managers can use AI effectively while ~14% of organizations give any support — an unoccupied space that sits at the HRBP''s intersection","That manager AI training should be owned by L&D","That AI tools are too complex for non-technical managers"],"correctIndex":1,"explanation":"The gap is wide enough to survive being substantially wrong in either direction. And nobody owns it: IT owns tools, L&D owns curriculum, neither owns how a manager should use AI in a performance conversation."},{"id":"q2","prompt":"A manager submits a fluent, generic AI-written performance review. What should you ask?","options":["Whether they used AI to write it","For two examples of what they described and one thing the employee should do differently","Them to rewrite it without AI assistance","For the prompt they used, so you can improve it"],"correctIndex":1,"explanation":"It''s the diagnostic. If they have the specifics, the tool was briefed badly and the fix is easy. If they don''t, the problem was never AI — they weren''t paying attention and the model let them hide it. A and C treat the tool as the fault and never reach the diagnosis."},{"id":"q3","prompt":"A manager tells you they pasted an employee grievance into a consumer chatbot. Why does the module say handle it as an incident rather than a betrayal?","options":["Because the data exposure is minor in practice","Because punishing the manager who told you trains everyone else to stop telling you — the four who didn''t report are the actual problem","Because consumer tools are not covered by most organizational policies","Because the manager could not reasonably have known"],"correctIndex":1,"explanation":"101 M8''s blame-safe principle, applied to someone else''s mistake. You cannot fix what you cannot see, and your reaction to the first case sets the visibility of the next twenty."},{"id":"q4","prompt":"Which rule for managers is the module''s model of a good one?","options":["\"Use AI responsibly and with good judgment\"","\"Don''t use AI for anything involving employees\"","\"Every policy or legal reference in a document going to an employee gets traced to source before it ships\"","\"Check all AI output carefully before using it\""],"correctIndex":2,"explanation":"A manager can follow it and you can audit it. A and D are aspirations with no observable behaviour attached; B is unenforceable and would be routed around within a month."},{"id":"q5","prompt":"What does the coaching RCT actually show? `[V]`","options":["That AI coaching is ineffective for all purposes","That human coaching produced substantial effects across goal attainment and wellbeing while the AI arm did not, with far higher attrition — in one study of 114 mostly-senior managers","That AI coaching matches human coaching on goals but not wellbeing","That coaching in general has weak evidential support"],"correctIndex":1,"explanation":"Stated with its scope, because overclaiming in the sceptical direction is the same error as overclaiming in the enthusiastic one. C describes the earlier goal-attainment research, which is a real and different finding — narrow and measurable performs better than broad and relational."},{"id":"q6","prompt":"Why does the module emphasize that one author co-authored the earlier, more favourable study?","options":["It suggests the researchers changed their commercial position","Because a researcher publishing a result that complicates their own earlier finding is the strongest and rarest form of evidence available","Because it means the two studies used identical methods","Because it undermines the credibility of both studies"],"correctIndex":1,"explanation":"It is not one camp contradicting another. It is self-correction, which is exactly the intellectual honesty this course asks of the learner — and worth naming for that reason as much as for the finding."},{"id":"q7","prompt":"Outcomes were predicted most strongly by the coachee''s starting self-efficacy and hope. What follows?","options":["That development budgets should target high-potential employees, who will benefit most","That AI coaching should be reserved for senior populations","That the people who most need development are served worst by an unsupervised bot — making the allocation of scarce human support an equity decision","That self-efficacy should be screened before assigning any development resource"],"correctIndex":2,"explanation":"And it inverts how most organizations allocate development. D is the dangerous near-miss: screening people on a psychological attribute to allocate resources is precisely the kind of decision 101 M7 warns about — the finding informs your judgment, it doesn''t become a filter."},{"id":"q8","prompt":"Why does the module apply its scepticism to Module 4''s own technique?","options":["Because adversarial rehearsal has been shown ineffective","Because the rehearsal category is vendor-dominated and its effectiveness numbers trace to sellers — so this course holds its own recommendations to the standard it holds theirs, and Module 4 is argued from craft rather than an efficacy study","Because Module 4''s technique requires tools most organizations lack","To satisfy disclosure requirements for training material"],"correctIndex":1,"explanation":"A course teaching claim teardown that exempted itself would fail its own standard. The honest position is that Module 4''s argument is mechanistic, not empirical, and the learner should weigh it accordingly."}]}', '2026-08-12');
